L["hide the prompt for a while -- 15 minutes unless you say"] = "masquer le panneau un moment -- 15 minutes sauf indication contraire"
L["preview the prompt with a mock candidate"] = "afficher un aperçu du panneau avec un joueur fictif"
L["the favour ledger: who buffed you, what you gave back, and who you buffed"] = "le registre des faveurs : qui vous a buffé, ce que vous avez rendu, et qui vous avez buffé"
L["what this addon does, and the one thing it needs from you"] = "ce que fait cet addon, et la seule chose qu'il attend de vous"
L["make a /click macro for your action bar"] = "créer une macro /click pour votre barre d'action"
L["unlock the prompt so it can be dragged"] = "déverrouiller le panneau pour pouvoir le déplacer"
L["lock it again -- an unlocked prompt never casts"] = "le verrouiller de nouveau -- un panneau déverrouillé ne lance jamais rien"
L["list who is never offered anything, or put somebody on that list"] = "lister ceux à qui rien n'est jamais proposé, ou ajouter quelqu'un à cette liste"
L["take somebody off the never-offer list"] = "retirer quelqu'un de la liste d'exclusion"
L["switch handing your target back after buffing on or off"] = "activer ou désactiver le rétablissement de votre cible après avoir buffé"
L["switch the chat lines about who buffed you on or off"] = "activer ou désactiver les messages de discussion indiquant qui vous a buffé"
L["copy these settings as one line of text"] = "copier ces paramètres en une seule ligne de texte"
L["use settings somebody exported, or undo the last import"] = "utiliser des paramètres exportés par quelqu'un, ou annuler la dernière importation"
L["what your class and this build allow"] = "ce que votre classe et cette version permettent"
L["the last few things that broke"] = "les dernières erreurs survenues"
L["tools for testing the addon on this client: the click log, try, look and forms"] = "outils pour tester l'addon sur ce client : le journal des clics, try, look et forms"
L["log what the button does when clicked"] = "consigner ce que fait le bouton à chaque clic"
L["run any macro text from the prompt"] = "exécuter n'importe quel texte de macro depuis le panneau"
L["dump every API answer for a unit"] = "afficher toutes les réponses de l'API pour une unité"
L["example macros to try"] = "exemples de macros à essayer"
L["Manners commands:"] = "Commandes de Manners :"
L["|cffffd100/mnr|r works in place of |cffffd100/manners|r in all of them."] = "|cffffd100/mnr|r peut remplacer |cffffd100/manners|r dans toutes ces commandes."
L["|cffff8080own buffs: last scan not believed (%s)|r -- %d read, baseline %d"] = "|cffff8080vos améliorations : dernière analyse non retenue (%s)|r -- %d lues, référence %d"
L["|cffffd100own buffs: baseline not settled|r -- %d read, waiting for a second scan to agree"] = "|cffffd100vos améliorations : référence pas encore établie|r -- %d lues, en attente d'une deuxième analyse concordante"
L["own buffs: %d read, baseline %d"] = "vos améliorations : %d lues, référence %d"
L["%d changes to your auras this session, read in %d walks"] = "%d changements de vos auras cette session, lus en %d passages"
L["thank with an emote: |cff00ff00on|r"] = "remerciement par une emote : |cff00ff00activé|r"
L["thank with an emote: |cffff0000off|r"] = "remerciement par une emote : |cffff0000désactivé|r"
L["last thanked: |cffffffff%s|r, %ds ago (the game answered %s)"] = "dernier remerciement : |cffffffff%s|r, il y a %d s (réponse du jeu : %s)"
L["last not thanked: |cffffffff%s|r, %ds ago (%s)"] = "dernier remerciement omis : |cffffffff%s|r, il y a %d s (%s)"
L["try cleared -- the normal cast takes effect when this fight ends; until then a press runs the macro already on the button."] = "try effacé -- le sort normal reprendra à la fin de ce combat ; d'ici là, un appui exécute la macro déjà sur le bouton."
L["try cleared -- back to the normal cast."] = "try effacé -- retour au sort normal."
L["try armed: |cff80ff80%s|r"] = "try armé : |cff80ff80%s|r"
L["|cffff8080not armed for now:|r %s."] = "|cffff8080non armé pour l'instant :|r %s."
L["expands to: |cffffffff%s|r"] = "donne : |cffffffff%s|r"
L["%d characters -- %d over the %d a macro body holds. The client will cut it, and what runs is not what is printed above."] = "%d caractères -- %d de plus que les %d que peut contenir une macro. Le client la coupera, et ce qui s'exécute n'est pas ce qui est affiché ci-dessus."
L["It takes effect when this fight ends; until then a press runs the macro already on the button. |cffffd100/manners try|r with nothing clears it."] = "Cela prendra effet à la fin de ce combat ; d'ici là, un appui exécute la macro déjà sur le bouton. |cffffd100/manners try|r sans argument l'efface."
L["The prompt arms it once they have one. |cffffd100/manners try|r with nothing clears it."] = "Le panneau l'armera dès qu'il en aura un. |cffffd100/manners try|r sans argument l'efface."
L["Click the prompt to run it. |cffffd100/manners try|r with nothing clears it."] = "Cliquez sur le panneau pour l'exécuter. |cffffd100/manners try|r sans argument l'efface."
L["Targeting forms, for /manners try:"] = "Formes de ciblage, pour /manners try :"
L["(on yourself)"] = "(sur vous-même)"
L["Tokens: |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name} is what a debt is filed under, {aim} is what a targeting line wants. Use \\n for a new line."] = "Balises : |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name} est le nom sous lequel une dette est enregistrée, {aim} est ce qu'attend une ligne de ciblage. Utilisez \\n pour un retour à la ligne."
L["the favour ledger did not load -- reinstalling Manners should bring it back."] = "le registre des faveurs ne s'est pas chargé -- réinstaller Manners devrait le rétablir."
L["unlocked -- it can be dragged once this fight ends; until then a press still casts what the fight froze. Then |cffffd100/manners lock|r."] = "déverrouillé -- vous pourrez le déplacer à la fin de ce combat ; d'ici là, un appui lance toujours ce que le combat a figé. Ensuite, |cffffd100/manners lock|r."
L["unlocked -- it can be dragged once this fight ends; nothing is armed meanwhile. Then |cffffd100/manners lock|r."] = "déverrouillé -- vous pourrez le déplacer à la fin de ce combat ; d'ici là, rien n'est armé. Ensuite, |cffffd100/manners lock|r."
L["unlocked -- drag the prompt, then |cffffd100/manners lock|r."] = "déverrouillé -- déplacez le panneau, puis |cffffd100/manners lock|r."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- |cffffd100/manners on|r first."] = "déverrouillé, mais l'addon est |cffff8080désactivé|r, donc il n'y a aucun panneau à déplacer -- d'abord |cffffd100/manners on|r."
L["locked."] = "verrouillé."
L["hand your target back after buffing: |cff00ff00on|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "rétablissement de votre cible après avoir buffé : |cff00ff00activé|r -- prend effet à la fin de ce combat ; d'ici là, un appui exécute la macro déjà sur le bouton."
L["hand your target back after buffing: |cffff0000off|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "rétablissement de votre cible après avoir buffé : |cffff0000désactivé|r -- prend effet à la fin de ce combat ; d'ici là, un appui exécute la macro déjà sur le bouton."
L["hand your target back after buffing: |cff00ff00on|r"] = "rétablissement de votre cible après avoir buffé : |cff00ff00activé|r"
L["hand your target back after buffing: |cffff0000off|r"] = "rétablissement de votre cible après avoir buffé : |cffff0000désactivé|r"
L["click logging: |cff00ff00on|r"] = "journal des clics : |cff00ff00activé|r"
L["click logging: |cffff0000off|r"] = "journal des clics : |cffff0000désactivé|r"
L["verbose: |cff00ff00on|r -- a line in your own chat when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed"] = "mode détaillé : |cff00ff00activé|r -- une ligne dans votre propre fenêtre de discussion quand quelqu'un vous buffe, quand une faveur est comptée comme rendue, et quand un clic échoue, est passé ou laisse une faveur encore due"
L["verbose: |cffff0000off|r"] = "mode détaillé : |cffff0000désactivé|r"
L["enabled."] = "activé."
L["disabled."] = "désactivé."
L["nobody is on your never-offer list. Shift-right-click the prompt to put whoever it is showing on it."] = "personne n'est sur votre liste d'exclusion. Faites un Maj-clic droit sur le panneau pour y ajouter le joueur affiché."
L["never offered anything unless they buff you: %s"] = "rien ne leur est proposé, sauf s'ils vous buffent : %s"
L["say who: |cffffd100/manners allow Name|r. |cffffd100/manners never|r lists everybody on the list."] = "précisez qui : |cffffd100/manners allow Name|r. |cffffd100/manners never|r affiche toute la liste."
L["|cffffffff%s|r can be offered again."] = "|cffffffff%s|r peut de nouveau être proposé."
L["nobody called %s is on your never-offer list."] = "personne du nom de %s n'est sur votre liste d'exclusion."
L["snooze takes a number of minutes from 1 to %d, or off -- for example |cffffd100/manners snooze 15|r or |cffffd100/manners snooze 1h|r."] = "snooze attend un nombre de minutes entre 1 et %d, ou off -- par exemple |cffffd100/manners snooze 15|r ou |cffffd100/manners snooze 1h|r."
L["your settings are in the box under |cffffd100Share as text|r on the Profiles tab of the options -- click in it, select all and copy."] = "vos paramètres sont dans le champ sous |cffffd100Partager en texte|r, dans l'onglet Profils des options -- cliquez dedans, sélectionnez tout et copiez."
L["this string is too long to be imported back -- a very long phrase box under What I say is the usual cause. Shorten it if you want to share these settings."] = "cette chaîne est trop longue pour être réimportée -- la cause habituelle est un champ de phrases très long dans l'onglet Ce que je dis. Raccourcissez-le si vous voulez partager ces paramètres."
L["paste the settings string into the box under |cffffd100Share as text|r on the Profiles tab, or type |cffffd100/manners import|r followed by it."] = "collez la chaîne de paramètres dans le champ sous |cffffd100Partager en texte|r, dans l'onglet Profils, ou tapez |cffffd100/manners import|r suivi de la chaîne."
L["type |cffffd100/manners import|r followed by a settings string."] = "tapez |cffffd100/manners import|r suivi d'une chaîne de paramètres."
L["Tools for testing Manners on this client:"] = "Outils pour tester Manners sur ce client :"
L["nothing has broken this session."] = "aucune erreur pendant cette session."
L["|cffffd100the last %d of %d|r |cff808080(%d kept)|r:"] = "|cffffd100les %d dernières erreurs sur %d|r |cff808080(%d conservées)|r :"
L["|cffffd100the last %d of %d|r:"] = "|cffffd100les %d dernières erreurs sur %d|r :"
L["Flavour.lua did not load -- check the toc's file list"] = "Flavour.lua ne s'est pas chargé -- vérifiez la liste des fichiers du toc"
L["your own buff: not offered -- %s is switched off."] = "votre propre amélioration : non proposée -- l'option %s est désactivée."
L["switched OFF on this profile -- nothing is recorded or offered; /manners on"] = "DÉSACTIVÉ sur ce profil -- rien n'est enregistré ni proposé ; /manners on"
L["|cffff4040this client has never heard of %s|r -- Manners has the wrong spell ids for %s on %s. Please report this line."] = "|cffff4040ce client ne connaît pas %s|r -- Manners a de mauvais identifiants de sort pour %s sur %s. Merci de signaler cette ligne."
L["owes returning: |cffffffff%s|r (%ds left, buffed you %ds ago)"] = "à rendre : |cffffffff%s|r (encore %d s, vous a buffé il y a %d s)"
L["not watching for favours -- Manners is switched off."] = "pas de surveillance des faveurs -- Manners est désactivé."
L["Favours are not recorded while \"People who buff me\" is off, on the Who to buff tab."] = "Les faveurs ne sont pas enregistrées tant que l'option « Ceux qui me buffent » est désactivée, dans l'onglet Qui buffer."
L["not watching for favours -- |cffffd100People who buff me|r is switched off."] = "pas de surveillance des faveurs -- l'option |cffffd100Ceux qui me buffent|r est désactivée."
L["nobody has buffed you recently."] = "personne ne vous a buffé récemment."
L["your own buff: offered to you when you are missing it."] = "votre propre amélioration : proposée quand elle vous manque."
L["your own buff: nothing you cast goes on yourself alone."] = "votre propre amélioration : aucun de vos sorts ne vise que vous."
L["prompt is UNLOCKED -- it will not buff anyone until you /manners lock"] = "panneau DÉVERROUILLÉ -- il ne buffera personne tant que vous n'aurez pas tapé /manners lock"
L["|cffffd100snoozed until %s|r -- no prompt until then; /manners snooze off ends it"] = "|cffffd100en pause jusqu'à %s|r -- aucun panneau d'ici là ; /manners snooze off y met fin"
L["|cffffd100mounted|r -- Not while mounted keeps the prompt away until you get off"] = "|cffffd100sur une monture|r -- « Pas sur une monture » masque le panneau jusqu'à ce que vous descendiez de monture"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only your own buff and people who buffed you or asked are offered"] = "|cffffd100économie de mana|r -- jusqu'à ce que votre mana remonte à %d %%, seuls votre propre amélioration et ceux qui vous ont buffé ou vous l'ont demandé sont proposés"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only people who buffed you or asked are offered"] = "|cffffd100économie de mana|r -- jusqu'à ce que votre mana remonte à %d %%, seuls ceux qui vous ont buffé ou vous l'ont demandé sont proposés"
L["|cffffd100ready check|r -- your party or raid comes first until the pull"] = "|cffffd100appel|r -- votre groupe ou votre raid passe en premier jusqu'au pull"
L["|cffffd100raid groups|r -- in a raid, only groups %s are offered unasked"] = "|cffffd100groupes de raid|r -- en raid, seuls les groupes %s sont proposés spontanément"
L["|cffffd100raid groups|r -- every group is unticked, so in a raid nobody is offered unasked"] = "|cffffd100groupes de raid|r -- aucun groupe n'est coché, donc en raid personne n'est proposé spontanément"
L["|cffff8080/manners try is armed:|r %s -- clear it with a bare /manners try"] = "|cffff8080/manners try est armé :|r %s -- effacez-le avec /manners try sans argument"
L["queue now: %d"] = "file d'attente actuelle : %d"
L["queue if switched on: %d"] = "file d'attente si activé : %d"
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners help|r lists them all."] = "la commande |cffffd100/manners %s|r n'existe pas -- vouliez-vous dire |cffffd100/manners %s|r ? |cffffd100/manners help|r les liste toutes."
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners dev|r lists the testing tools."] = "la commande |cffffd100/manners %s|r n'existe pas -- vouliez-vous dire |cffffd100/manners %s|r ? |cffffd100/manners dev|r liste les outils de test."
L["Thank ye kindly, {name}! First round's on me when we're back at the forge."] = "Merci bien, {name} ! La première tournée est pour moi, de retour à la forge."
L["Much obliged, {name}. Ye've a friend in the mountain now."] = "Mille mercis, {name}. Z'avez un ami dans la montagne, maint'nant."
L["Thank ye, {name}! I'd have been fine without it, mind. But thank ye."] = "Merci, {name} ! J'aurais tenu sans, remarquez. Mais merci."
L["Bless ye, {name}! I'd hug ye, but ye'd be needin' a healer after."] = "Merci, {name} ! Une accolade ? Non, z'auriez besoin d'un soigneur après."
L["Paid back already, {name}. Quicker than I've ever settled a bar tab."] = "Déjà remboursé, {name}. J'ai jamais réglé une ardoise aussi vite."
L["I'll tell this at the Thunderbrew like ye saved me life, {name}. Thank ye!"] = "Chez Tonnebière, j'dirai qu'vous m'avez sauvé la vie, {name}. Merci !"
L["Grand, {name}! I'd carve ye a statue, but this is quicker."] = "Chapeau, {name} ! J'vous taillerais bien une statue, mais ça va plus vite."
L["The Titans made us of stone, {name}, but that still touched me. Thank ye."] = "Les Titans nous ont taillés dans la pierre, {name}, et pourtant, ça m'a touché. Merci."
L["Thank ye, {name}. Back at ye, before me pride notices I needed it."] = "Merci, {name}. J'vous l'rends, avant qu'ma fierté voie qu'j'en avais besoin."
L["Thank ye, {name}. Muradin says a debt left unpaid rusts. Here, before it does."] = "Merci, {name}. Muradin dit qu'une dette impayée rouille. Tenez, tant qu'elle brille."
L["Thank ye, {name}. I'd give ye a ride on me ram, but he bites strangers. And me."] = "Merci, {name}. Mon bélier vous porterait bien, mais il mord les inconnus. Et moi."
L["The Explorers' League'll ask where ye dug up such manners, {name}. Thanks!"] = "La Ligue des explorateurs voudra savoir où z'avez déterré ces manières, {name}. Merci !"
L["Thank ye, {name}. Me beard's on end. That's dwarven fer 'deeply touched'."] = "Merci, {name}. Ma barbe se hérisse. En nain, ça veut dire « très touché »."
L["Mined half o' Khaz Modan, {name}. Never struck a vein that rich. Yer cut."] = "Creusé la moitié d'Khaz Modan, {name}. Jamais vu un filon pareil. Vot' part."
L["Like a Kharanos hearth in a Dun Morogh blizzard, that, {name}. Thank ye."] = "Comme un bon feu à Kharanos en plein blizzard de Dun Morogh, {name}. Merci."
L["Came back to ye like a Wildhammer's stormhammer, {name}. Less painful, mind."] = "Ça vous r'vient comme le marteau d'un Marteau-hardi, {name}. En moins douloureux."
L["Come to Ironforge, {name}. Me mam'll feed ye till ye can't stand. Thank ye!"] = "Passez à Forgefer, {name}. M'man vous gavera jusqu'à c'que vous rouliez. Merci !"
L["Checked it fer gunpowder out o' habit, {name}. Clean as a whistle. Here's yers!"] = "Par habitude, j'ai vérifié qu'y avait pas d'poudre, {name}. Nickel. Voilà l'vôtre !"
L["Aye, {name}, ye only had to ask. Hold still now, like a good anvil."] = "Pour sûr, {name}, suffisait d'demander. Bougez plus, comme une bonne enclume."
L["Say no more, {name}. Stone and steel, here it comes."] = "Pas un mot d'plus, {name}. Par la pierre et l'acier, ça vient !"
L["Ask a dwarf fer help, {name}, and ye'll get it. Loudly."] = "Demandez d'l'aide à un nain, {name} : vous l'aurez. Et vous l'entendrez."
L["Right, {name}. Brace yerself; I do everything like I'm swingin' a hammer."] = "Bon, {name}. Accrochez-vous : j'fais tout comme si j'maniais l'marteau."
L["Aye, {name}, and a story about it ye didn't ask fer. Where to begin..."] = "Pour sûr, {name}, avec une histoire qu'vous m'avez pas d'mandée. Par où commencer..."
L["One {buff}, pulled fresh like a proper pint, {name}."] = "{buff} à la pression, {name}. Comme une vraie pinte."
L["Done, {name}. Dwarven work: over-built, under-priced and guaranteed."] = "C'est fait, {name}. Ouvrage nain : surdimensionné, sous-facturé et garanti."
L["Easy, {name}. Last favour I did was fix a gnome's tank. Cost me both eyebrows."] = "Facile, {name}. Dernier service rendu : le char d'un gnome. J'y ai laissé les sourcils."
L["Aye, {name}. Mountain kings never refuse. I'm more a foothill, but same rule."] = "Pour sûr, {name}. Un roi d'la montagne refuse jamais. J'suis plutôt colline, même règle."
L["Tempered and quenched, {name}. Mind, it's still hot."] = "Forgé et trempé, {name}. Attention, c'est encore chaud."
L["Done afore ye finished, {name}. Dwarves hear 'please' through solid rock."] = "Déjà fait, {name}. Un nain entend « s'il vous plaît » à travers la roche."
L["Aye, {name}. In Dun Morogh ye help quick, or ye both freeze standin' there."] = "Pour sûr, {name}. À Dun Morogh, on aide vite, sinon on gèle tous les deux sur place."
L["Aye, {name}. Ye'll feel it in yer boots first. That's how ye know it's dwarven."] = "Pour sûr, {name}. Ça s'sent d'abord dans les bottes. C'est signé nain."
L["Aye, {name}. Say no, and ye'd ask a gnome, and then I'd feel responsible."] = "Pour sûr, {name}. Si j'dis non, vous d'manderez à un gnome, et j'm'en voudrais."
L["Here, {name}, a wee somethin' to keep ye on yer feet. Wee, like me."] = "Tenez, {name}, un p'tit quelque chose pour vous garder d'aplomb. P'tit, comme moi."
L["Off ye go, {name}, steady as the mountain."] = "En route, {name}, et solide comme la montagne."
L["Here, {name}. Ale's for after; this is for before."] = "Tenez, {name}. La bière, c'est pour après ; ça, c'est pour avant."
L["Magni turned to diamond fer the cause, {name}. This is the cheaper option."] = "Magni s'est changé en diamant pour la cause, {name}. Ça, c'est l'option pas chère."
L["A dwarf's got yer back, {name}. Well, yer knees. Close enough."] = "Un nain vous épaule, {name}. Enfin, à hauteur de genou. C'est presque pareil."
L["If a trogg bothers ye, {name}, tell it a dwarf sent ye. Then run."] = "Si un trogg vous embête, {name}, dites-lui qu'un nain vous envoie. Puis courez."
L["If it wears off, {name}, give it a good thump. That's how we fix everything."] = "Si ça s'dissipe, {name}, tapez d'ssus. Chez nous, on répare tout comme ça."
L["Take this, {name}. I'd give ye some stubbornness too, but I'm usin' all mine."] = "Prenez ça, {name}. J'vous donnerais bien d'mon entêtement, mais j'en ai pas d'trop."
L["Mind the wendigos, {name}: big, hairy and grumpy. Like me, but hungrier."] = "Gare aux wendigos, {name} : gros, poilus, grognons. Comme moi, en plus affamés."
L["Take this, {name}. Me grandad fought three wars with a pickaxe and this."] = "Prenez ça, {name}. Mon grand-père a fait trois guerres avec une pioche et ça."
L["Dwarven make, {name}. Drop it off Thandol Span and it'd still work. Don't."] = "Du travail nain, {name}. Tombé du Viaduc de Thandol, ça marcherait encore. Essayez pas."
L["Stonewrought Dam holds back all o' Loch Modan, {name}. This'll hold ye an hour."] = "Le barrage retient tout l'Loch Modan, {name}. Ça, ça vous tiendra une heure."
L["Won't keep yer boots dry in the Wetlands, {name}. Nothin' does. The rest, aye."] = "Ça gardera pas vos bottes au sec dans les Paluns, {name}. Rien n'y arrive. Le reste, si."
L["Old miner's rule, {name}: never go down a hole without a lamp, a mate and this."] = "Règle de mineur, {name} : jamais d'descente sans lampe, sans copain, et sans ça."
L["Brann Bronzebeard went explorin' with less, {name}, and wrote three books."] = "Brann Barbe-de-bronze explorait avec moins qu'ça, {name}. Et il a écrit trois livres."
L["Mountaineers swear by it, {name}. Ye'll climb no better, but land softer."] = "Les montagnards jurent que par ça, {name}. Ça aide pas à grimper, mais à retomber."
L["Ironforge's gates have never fallen, {name}. Neither should ye. Take this."] = "Les portes d'Forgefer sont jamais tombées, {name}. Faites pareil. Tenez."
L["Me cousins down Blackrock way would've set it alight first, {name}. Fer luck."] = "Mes cousins du côté d'Rochenoire y auraient mis l'feu d'abord, {name}. Pour la chance."
L["Stone and hammer keep ye, cousin {name}!"] = "Pierre et marteau vous gardent, cousin {name} !"
L["Three Hammers, one round, cousin {name}!"] = "Trois Marteaux, une tournée, cousin {name} !"
L["Yer cousin's cousin married mine, {name}, I'd wager. It's a small mountain."] = "J'parie qu'le cousin d'vot' cousin a épousé l'mien, {name}. La montagne est petite."
L["Two dwarves together, {name}. Pity whatever's standin' in our way."] = "Deux nains ensemble, {name}. Plaignons c'qui s'mettra en travers d'not' chemin."
L["Bronzebeard, Wildhammer, Dark Iron, Earthen, {name}: one family, nobody agrees."] = "Barbe-de-bronze, Marteau-hardi, Sombrefer, terrestres, {name} : une famille, zéro accord."
L["Between the pair of us, {name}, we could out-stubborn a mountain."] = "À nous deux, {name}, on aurait une montagne à l'usure."
L["Me grandmother'd climb out of her tomb if I did any less fer kin, {name}."] = "Ma grand-mère sortirait d'sa tombe si j'en faisais moins pour la famille, {name}."
L["The Titans carved us both from the same rock, {name}. Explains the headaches."] = "Les Titans nous ont taillés dans la même roche, {name}. Ça explique nos têtes dures."
L["Proud o' ye, {name}. Don't let it go to yer head; no room under the helmet."] = "Fier de vous, {name}. Que ça vous monte pas à la tête : y a plus d'place sous l'casque."
L["Stand behind me, {name}. Aye, I know. Crouch a bit."] = "Derrière moi, {name}. Oui, j'sais. Baissez-vous un peu."
L["Right, {name}: I take the front, ye take the loot, and we argue after."] = "Bon, {name} : j'prends l'avant, vous prenez l'butin, et on s'dispute après."
L["If I start singin', {name}, the fight's gone well. Or very badly."] = "Si j'me mets à chanter, {name}, c'est qu'le combat s'passe bien. Ou très mal."
L["Dwarves never leave a mate behind, {name}. Nor a keg. Mates first, mind."] = "Un nain abandonne jamais un copain, {name}. Ni un tonneau. Les copains d'abord, hein."
L["Beards out, {name}! Them without beards, look fierce. It's nearly as good."] = "Barbes en avant, {name} ! Les imberbes, prenez l'air féroce. C'est presque aussi bien."
L["Knocked on the nearest rock, {name}. Solid. No cave-ins fer us today."] = "D'autres touchent du bois, {name}. Moi, la roche : pas d'éboulement aujourd'hui."
L["No fires near me pack, {name}. It's mostly gunpowder. And a sandwich."] = "Pas d'feu près d'mon sac, {name}. C'est surtout d'la poudre. Et un sandwich."
L["Dwarves don't retreat, {name}. Our legs aren't built fer it. So forward it is."] = "Un nain recule pas, {name}. Nos jambes sont pas faites pour. Alors, en avant."
L["Stay close, {name}. If it goes dark, follow the cursin'. That'll be me."] = "Restez près d'moi, {name}. S'il fait noir, suivez les jurons. Ce s'ra moi."
L["Dwarves always know which way is down, {name}. Up's yer problem."] = "Un nain sait toujours où est le bas, {name}. Le haut, c'est vot' problème."
L["Anythin' made o' stone, {name}, let me talk to it first. Might be a cousin."] = "Tout c'qui est en pierre, {name}, laissez-moi lui parler d'abord. C'est p't'êt' un cousin."
L["If the ceilin' creaks, {name}, I'll tell ye. If I go quiet, run."] = "Si l'plafond craque, {name}, j'vous l'dirai. Si j'me tais, courez."
L["Mornin', {name}! Too early for ale. Almost. Have this first."] = "B'jour, {name} ! Trop tôt pour une bière. Presque. Prenez d'abord ça."
L["Up with the forge fires, {name}! A dwarf's day starts with a hammer and this."] = "Debout avec les feux d'la forge, {name} ! Une journée d'nain commence au marteau. Et avec ça."
L["Early, {name}? Nonsense. The mine's been open two hours. Here."] = "Tôt, {name} ? Balivernes. La mine est ouverte depuis deux heures. Tenez."
L["Mornin', {name}. Me beard's still asleep. The rest o' me is ready."] = "B'jour, {name}. Ma barbe dort encore. Le reste est prêt."
L["Mornin', {name}. Porridge, a pipe and this. The other two are mine."] = "B'jour, {name}. Bouillie, pipe, et ça. Les deux premiers, c'est pour moi."
L["The rams had me up at dawn, {name}. Headbutted the door till I came out. Here."] = "Les béliers m'ont réveillé à l'aube, {name}. À coups d'tête dans la porte. Tenez."
L["Mornin', {name}. Ears still ringin' from last night's singin'. Here."] = "B'jour, {name}. J'ai encore les chants d'hier soir dans les oreilles. Tenez."
L["My thanks, {name}. Let me return the kindness before a bard gets it wrong."] = "Merci, {name}. Je vous rends la politesse avant qu'un barde ne déforme l'histoire."
L["Kindly done, {name}. Let no one say we forget a friend."] = "Bien aimable, {name}. Qu'on ne dise pas que nous oublions nos amis."
L["Thank you, {name}. I'd knight you, but apparently I 'need permission'."] = "Merci, {name}. Je vous adouberais bien, mais il paraît qu'il me faut une « autorisation »."
L["Repaid on the spot, {name}. In Stormwind that'd take three forms and a stamp."] = "Rendu sur-le-champ, {name}. À Hurlevent, il faudrait trois formulaires et un tampon."
L["Thanks, {name}. I'd pay in gold, but Stormwind still owes the stonemasons."] = "Merci, {name}. Je paierais bien en or, mais Hurlevent doit encore de l'argent aux maçons."
L["Much obliged, {name}. Mother said always return a kindness. And the dish."] = "Bien obligé, {name}. Ma mère disait : on rend toujours la politesse. Et le plat."
L["Thank you, {name}. Consider the scales balanced, by royal decree. Mine."] = "Merci, {name}. Nous voilà quittes, par décret royal. Le mien."
L["You shame me, {name}; I should have thought of it first. Allow me."] = "Vous me faites honte, {name} ; j'aurais dû y penser avant vous. Permettez."
L["Heartier than Westfall Stew, {name}, and I've wept over that stew. Thank you."] = "Mieux que le ragoût de la Marche de l'Ouest, {name}, et ce ragoût m'a fait pleurer. Merci."
L["Thank you, {name}. I'll tell Marshal Dughan. He won't care, but I'll tell him."] = "Merci, {name}. J'en parlerai au maréchal Dughan. Il s'en moquera, mais je lui dirai."
L["Job's done, {name}! My grandad built half of Stormwind saying that. Thanks."] = "Travail terminé, {name} ! Mon grand-père a bâti la moitié de Hurlevent en disant ça. Merci."
L["Lakeshire will finish its bridge before I forget this, {name}. So, never."] = "Comté-du-Lac finira son pont avant que j'oublie ça, {name}. Autant dire jamais."
L["Kul Tirans say a kindness goes back on the next tide, {name}. There it goes."] = "Chez les Kultirassiens, un bienfait repart à la marée suivante, {name}. Le voilà parti."
L["Thank you, {name}. Northshire's monks would be proud. Of you. They know me."] = "Merci, {name}. Les moines de Comté-du-Nord seraient fiers. De vous. Ils me connaissent."
L["Not since Mum packed my Deadmines lunch, {name}, have I felt so looked after."] = "Jamais été si chouchouté depuis le casse-croûte de maman pour les Mortemines, {name}."
L["Into my memoirs, {name}. Chapter nine: 'Everyone Was Lovely'. Thank you."] = "Dans mes mémoires, {name}. Chapitre neuf : « Des gens adorables ». Merci."
L["I'll toast you at the Pig and Whistle, {name}. Then the pig. Then the whistle."] = "Je trinquerai à vous au Cochon et Sifflet, {name}. Puis au cochon. Puis au sifflet."
L["Of course, {name}. Hold still and look heroic; it helps the bards."] = "Bien sûr, {name}. Ne bougez pas et prenez l'air héroïque ; ça aide les bardes."
L["Right away, {name}. Keep your shield high."] = "Tout de suite, {name}. Gardez le bouclier haut."
L["More work? Gladly, {name}. It beats the lumber mill."] = "Encore du travail ? Volontiers, {name}. Ça change de la scierie."
L["Of course, {name}. Humans excel at helping and overpromising. This is helping."] = "Bien sûr, {name}. Les humains excellent à aider et à trop promettre. Ici, j'aide."
L["Certainly, {name}. Humans are quick learners; I learned this one yesterday."] = "Certainement, {name}. Les humains apprennent vite : ce sort, je l'ai appris hier."
L["Hold still, {name}, like a statue in the Valley of Heroes. You'd fit right in."] = "Ne bougez plus, {name}, comme une statue de la Vallée des Héros. Vous y seriez à votre place."
L["Right away, {name}. The Light helps those who ask. So do I, and I'm quicker."] = "Tout de suite, {name}. La Lumière aide ceux qui demandent. Moi aussi, et plus vite."
L["Sailors' rule, {name}: somebody calls for help, you row. Here."] = "Règle de marin, {name} : quelqu'un appelle à l'aide, on rame. Tenez."
L["Of course, {name}. Stand up straight; my old sergeant is watching, somewhere."] = "Bien sûr, {name}. Tenez-vous droit ; mon vieux sergent nous regarde, quelque part."
L["Of course, {name}. A polite request is rarer than a quiet night in Duskwood."] = "Bien sûr, {name}. Une demande polie est plus rare qu'une nuit calme au Bois de la Pénombre."
L["Right away, {name}. I'll play the Archbishop; you pretend to be impressed."] = "Tout de suite, {name}. Je fais l'archevêque ; vous, faites semblant d'être impressionné."
L["Step into the light, {name}. Not the Light; I just like to see my aim."] = "Venez dans la lumière, {name}. Pas la Lumière : je veux juste voir où je vise."
L["Stormwind rose from rubble, {name}. I can manage one {buff}."] = "On a rebâti Hurlevent sur des gravats, {name}. {buff}, je peux gérer."
L["Of course, {name}. Last one I did was a Westfall scarecrow. Long story."] = "Bien sûr, {name}. Le dernier, c'était un épouvantail de la Marche de l'Ouest. Passons."
L["Aye, {name}. Kul Tiran terms: a handshake, and I spare you the shanty."] = "Paré, {name}. Tarif kultirassien : une poignée de main, et pas de chanson de marin."
L["The road ahead is long, {name}. This won't shorten it, but it'll help."] = "La route est longue, {name}. Ceci ne la raccourcira pas, mais ça aidera."
L["Fair winds and following seas, {name}."] = "Bon vent et bonne mer, {name}."
L["Take this, {name}. Elves have centuries to be generous; I've got fifty years."] = "Prenez ceci, {name}. Les elfes ont des siècles pour être généreux ; moi, j'ai cinquante ans."
L["A little something, {name}. Don't tell the guards; they'll all want one."] = "Un petit quelque chose, {name}. N'en dites rien aux gardes, ils en voudront tous."
L["Here, {name}. If a kobold asks, you don't have a candle."] = "Tenez, {name}. Si un kobold demande, vous n'avez pas de bougie."
L["For you, {name}. A human gift: well meant, hastily made, surprisingly sturdy."] = "Pour vous, {name}. Un cadeau humain : bien intentionné, vite fait, étonnamment solide."
L["Mind the murlocs, {name}. Take this; I've seen what they do to a picnic."] = "Gare aux murlocs, {name}. Prenez ceci ; j'ai vu ce qu'ils font d'un pique-nique."
L["Every road needs a hero, {name}. Today it's me, apparently. Take this."] = "Chaque route a besoin d'un héros, {name}. Aujourd'hui, c'est moi, apparemment. Prenez."
L["Stay out of Duskwood after dark, {name}. It's always dark. Take this."] = "Évitez le Bois de la Pénombre la nuit, {name}. C'est toujours la nuit. Prenez ceci."
L["Redridge gnolls take anything not nailed down, {name}. This is nailed down."] = "Les gnolls des Carmines volent tout ce qui n'est pas cloué, {name}. Ceci est cloué."
L["If you meet Hogger, {name}, take this and a friend. Mostly the friend."] = "Si vous croisez Lardeur, {name}, prenez ceci et un ami. Surtout l'ami."
L["The Light and a good pair of boots, {name}. Now you've got one of them."] = "La Lumière et une bonne paire de bottes, {name}. Vous avez désormais l'une des deux."
L["Every hero in Stormwind began with a kindness and a borrowed sword, {name}."] = "Tout héros de Hurlevent a commencé par une bonté et une épée empruntée, {name}."
L["Here, {name}. The Defias can't steal this one. They've tried everything else."] = "Tenez, {name}. Les Défias ne peuvent pas voler ça. Ils ont essayé tout le reste."
L["Uther blessed strangers on the road, {name}. I've less hammer, same idea."] = "Uther bénissait les inconnus sur la route, {name}. J'ai moins de marteau, même idée."
L["Take this, {name}. It's a tradition. I just started it, but it's a tradition."] = "Prenez ceci, {name}. C'est une tradition. Je viens de la lancer, mais c'est une tradition."
L["The wolves in Elwynn look friendly, {name}. They are not. Take this."] = "Les loups d'Elwynn ont l'air gentils, {name}. Ils ne le sont pas. Prenez ceci."
L["Arathor's children stand together, {name}."] = "Les enfants d'Arathor restent unis, {name}."
L["A fellow human, {name}! Quick, let's found a kingdom before lunch."] = "Un autre humain, {name} ! Vite, fondons un royaume avant le déjeuner."
L["Stormwind or Boralus, {name}, we'll both complain about the weather."] = "Hurlevent ou Boralus, {name}, on se plaindra tous les deux de la météo."
L["Human to human, {name}: no, I don't know why everything happens to us either."] = "D'humain à humain, {name} : non, moi non plus, je ne sais pas pourquoi tout nous tombe dessus."
L["Short lives, long to-do lists, {name}. We humans must help each other along."] = "Vie courte, longue liste de choses à faire, {name}. Entre humains, on s'entraide."
L["Stormwind stone or Kul Tiran oak, {name}, we outlast everyone's expectations."] = "Pierre de Hurlevent ou chêne de Kul Tiras, {name}, on dure plus que prévu."
L["Humans stick together, {name}. Everyone else is taller, older or furrier."] = "Serrons-nous les coudes, {name}. Les autres sont plus grands, plus vieux ou plus poilus."
L["Our lot built half the world on bread, stubbornness and bad luck, {name}."] = "Notre peuple a bâti la moitié du monde avec pain, entêtement et poisse, {name}."
L["Don't tell the dwarves, {name}, but it was us humans who invented the tavern."] = "Ne le dites pas aux nains, {name}, mais la taverne, c'est nous qui l'avons inventée."
L["Keep close, {name}. Humans have always won by outnumbering things."] = "Restez près de moi, {name}. Les humains ont toujours gagné par le nombre."
L["Stay in formation, {name}. We haven't got one, but stay in it anyway."] = "Gardez la formation, {name}. On n'en a pas, mais gardez-la quand même."
L["I'll draw up a plan, {name}, and then we can all ignore it together."] = "Je vais dresser un plan, {name}, et on pourra tous l'ignorer ensemble."
L["Every hero in the songs had friends, {name}. Nobody sings about them. I will."] = "Tous les héros des chansons avaient des amis, {name}. Personne ne les chante. Moi, si."
L["Shields up, {name}. Stormwind taught me to march; nobody taught me to stop."] = "Boucliers levés, {name}. Hurlevent m'a appris à marcher ; personne, à m'arrêter."
L["If this goes badly, {name}, we regroup at the nearest inn. Human tactics."] = "Si ça tourne mal, {name}, on se regroupe à l'auberge la plus proche. Tactique humaine."
L["I've made us a flag, {name}. It's a handkerchief on a stick, but it's ours."] = "Je nous ai fait un drapeau, {name}. C'est un mouchoir sur un bâton, mais c'est le nôtre."
L["Keep a torch lit, {name}. Humans can't see in the dark, and we hate it."] = "Gardez une torche, {name}. Les humains ne voient pas dans le noir, et on déteste ça."
L["Watch my back, {name}; I'll watch yours. The Light has the rest. Better view."] = "Couvrez-moi, {name}, je vous couvre. La Lumière couvre le reste : elle voit de plus haut."
L["Humans always rise to the occasion, {name}. Usually after tripping over it."] = "Les humains sont toujours à la hauteur, {name}. Après s'être pris les pieds dans le tapis."
L["Do this well, {name}. Some elf will be telling the story for a thousand years."] = "Faites-le bien, {name}. Un elfe va raconter l'histoire pendant mille ans."
L["Farmers, sailors, bakers, {name}: every army Stormwind ever raised. Onward!"] = "Fermiers, marins, boulangers, {name} : toutes les armées de Hurlevent. En avant !"
L["Ishnu-alah, {name}. Returned the same day, which for a kaldorei is rushing."] = "Ishnu-alah, {name}. Rendu le jour même : pour un kaldorei, c'est de la précipitation."
L["Thank you, {name}. Elune smiles on the generous."] = "Merci, {name}. Élune sourit aux cœurs généreux."
L["Thank you, {name}. Even the wisps glow brighter, and they're hard to impress."] = "Merci, {name}. Même les feux follets brillent plus fort, et ils sont durs à impressionner."
L["Elune saw that, {name}. She sees everything, so I had best return it."] = "Élune a vu ça, {name}. Elle voit tout, alors je ferais bien de vous le rendre."
L["Thank you, {name}. Returned before I nap for a century or two."] = "Merci, {name}. Je vous le rends avant ma sieste d'un siècle ou deux."
L["Thank you, {name}. The Ancients will hear of this. They're dreadful gossips."] = "Merci, {name}. Les Anciens en entendront parler. Ce sont de vraies commères."
L["Thank you, {name}. I'll tell the Sentinels to stop aiming at you."] = "Merci, {name}. Je dirai aux Sentinelles d'arrêter de vous viser."
L["My people never hurry, {name}. For you, an exception."] = "Mon peuple ne se presse jamais, {name}. Pour vous, une exception."
L["Ande'thoras-ethil, {name}. May your troubles be diminished, as mine just were."] = "Ande'thoras-ethil, {name}. Que vos soucis s'allègent, comme les miens à l'instant."
L["We gave up immortality at Hyjal, {name}. Kindness has been worth double since."] = "Nous avons renoncé à l'immortalité sur Hyjal, {name}. Depuis, la bonté vaut double."
L["My ears went a darker purple, {name}. On a kaldorei, that means I'm touched."] = "Mes oreilles ont viré au violet foncé, {name}. Chez les kaldorei, c'est signe d'émotion."
L["Azshara's court never gave a thing away, {name}. You've outdone a queen."] = "La cour d'Azshara ne donnait jamais rien, {name}. Vous avez surpassé une reine."
L["The owls turned their heads for that, {name}. All the way round. High praise."] = "Les chouettes ont tourné la tête, {name}. Tout le tour. Un bel hommage."
L["I outlived the Sundering, {name}. I'll not outlive a debt to you. Here."] = "J'ai survécu à la Fracture, {name}. Une dette envers vous ne durera pas autant. Tenez."
L["All those centuries of memories, {name}, and this one goes near the front."] = "Des siècles de souvenirs, {name}, et celui-ci passe presque en tête."
L["I'll tell the moon about you tonight, {name}. She likes a good story."] = "Je parlerai de vous à la lune ce soir, {name}. Elle aime les belles histoires."
L["Gladly, {name}. Be still, and let the moonlight find you."] = "Avec plaisir, {name}. Restez immobile, que le clair de lune vous trouve."
L["Of course, {name}. Elune's blessings are meant to be shared."] = "Bien sûr, {name}. Les bénédictions d'Élune sont faites pour être partagées."
L["At last, {name}! I've waited ten thousand years for someone to ask."] = "Enfin, {name} ! J'attends qu'on me le demande depuis dix mille ans."
L["No riddle, no omen from Elune, {name}. Just a plain yes, for once."] = "Ni énigme ni présage d'Élune, {name}. Juste un oui, pour une fois."
L["Of course, {name}. Ask in Darnassian next time and I'll add a bow."] = "Bien sûr, {name}. Demandez en darnassien la prochaine fois, et j'ajoute une révérence."
L["Elune already said yes, {name}. I'm merely catching up."] = "Élune a déjà dit oui, {name}. Je ne fais que suivre."
L["Of course, {name}. Stand still and pretend you're a tree. It helps."] = "Bien sûr, {name}. Ne bougez pas, faites l'arbre. Ça aide."
L["Step into the light, {name}. The last kaldorei I did this for Shadowmelded."] = "En pleine lumière, {name}. Le dernier kaldorei que j'ai servi s'est camouflé dans l'ombre."
L["Certainly, {name}. Ask a kaldorei anything, except how old we are."] = "Certainement, {name}. Demandez tout à un kaldorei, sauf son âge."
L["In Darnassus, {name}, this takes a moonwell and a priestess. Out here, just me."] = "À Darnassus, {name}, il faut un puits de lune et une prêtresse. Ici, juste moi."
L["The last army to ask me for help was fighting demons, {name}. You're politer."] = "La dernière armée à me demander de l'aide combattait des démons, {name}. Vous êtes plus poli."
L["Gladly, {name}. Consider it on loan from Elune. She's never once collected."] = "Avec plaisir, {name}. Un prêt d'Élune. Elle n'a jamais rien réclamé."
L["One moment, {name}. My hair is older than most kingdoms, and it tangles."] = "Un instant, {name}. Mes cheveux ont l'âge de bien des royaumes, et ils s'emmêlent."
L["Darnassian has nine words for 'yes', {name}. I'll spare you eight of them."] = "Le darnassien a neuf mots pour dire « oui », {name}. Je vous épargne les huit autres."
L["Of course, {name}. The Sentinels would want a password. I'll accept 'please'."] = "Bien sûr, {name}. Les Sentinelles exigeraient un mot de passe. Moi, le mot magique suffit."
L["Elune-adore, {name}. Walk softly; the trees are light sleepers."] = "Elune-adore, {name}. Marchez doucement : les arbres ont le sommeil léger."
L["May the forest shelter you, {name}, wherever you roam."] = "Que la forêt vous abrite, {name}, où que vous alliez."
L["A gift from the shadows, {name}. No, don't look. You won't find me."] = "Un présent venu des ombres, {name}. Non, ne cherchez pas. Vous ne me trouverez pas."
L["Elune lights your path, {name}. I'm merely holding the lantern."] = "Élune éclaire votre chemin, {name}. Moi, je tiens juste la lanterne."
L["The owls pointed you out, {name}. They have strong opinions. Here."] = "Les chouettes vous ont désigné, {name}. Elles ont des avis tranchés. Tenez."
L["Tyrande would insist, {name}, and nobody argues with Tyrande."] = "Tyrande insisterait, {name}, et personne ne discute avec Tyrande."
L["Take this, {name}. The last one went to a hippogryph. It was less grateful."] = "Prenez ceci, {name}. Le dernier est allé à un hippogriffe. Il était moins reconnaissant."
L["Mind the wildlife, {name}. Half of it is a druid, and all of it is watching."] = "Attention à la faune, {name}. La moitié, ce sont des druides, et tous vous observent."
L["Walk with Elune, {name}. If she's busy, walk with this."] = "Marchez avec Élune, {name}. Si elle est occupée, avec ceci."
L["Mind the satyrs, {name}. They were Highborne once. You can tell by the sneer."] = "Gare aux satyres, {name}. Ce sont d'anciens Bien-nés. Ça se voit à leur air hautain."
L["I've watched you from the treeline a while, {name}. Supportively. Here."] = "Je vous observe de la lisière depuis un moment, {name}. Avec bienveillance. Tenez."
L["Most furbolgs are friendly, {name}. This is for the other ones."] = "La plupart des furbolgs sont amicaux, {name}. Ceci, c'est pour les autres."
L["Moonwell water would be better, {name}, but it travels badly. This doesn't."] = "L'eau d'un puits de lune serait mieux, {name}, mais elle voyage mal. Ceci, non."
L["A gift from Teldrassil, {name}. It's a long way down; I nearly dropped it."] = "Un présent de Teldrassil, {name}. La descente est longue ; j'ai failli le lâcher."
L["I'd stay to chat, {name}, but kaldorei chats run to the next full moon. Here."] = "Je bavarderais bien, {name}, mais un bavardage kaldorei dure jusqu'à la pleine lune. Tenez."
L["Bandu thoribas, {name}: prepare to fight. There. Now you're prepared."] = "Bandu thoribas, {name} : préparez-vous au combat. Voilà. Vous êtes préparé."
L["From the kaldorei, the moon and a very old tree, {name}. Mostly from me."] = "De la part des kaldorei, de la lune et d'un très vieil arbre, {name}. Surtout de moi."
L["Ishnu-alah, {name}. Elune keeps her children close."] = "Ishnu-alah, {name}. Élune veille sur ses enfants."
L["Of course I saw you, {name}. It takes a kaldorei to spot a kaldorei."] = "Bien sûr que je vous ai vu, {name}. Il faut un kaldorei pour repérer un kaldorei."
L["One kaldorei to another, {name}: we lost a tree, never each other."] = "Entre kaldorei, {name} : nous avons perdu un arbre, jamais les nôtres."
L["A kaldorei never leaves kin in the dark, {name}. Unless it's for cover."] = "Un kaldorei ne laisse jamais les siens dans l'ombre, {name}. Sauf pour les cacher."
L["Two kaldorei, {name}, and still no helmet made that fits either pair of ears."] = "Deux kaldorei, {name}, et toujours aucun casque fait pour nos oreilles."
L["Sentinel, druid or simply stubborn, {name}? I'm all three on a good night."] = "Sentinelle, druide ou juste têtu, {name} ? Moi, les trois, les bons soirs."
L["Between us, {name}, twenty thousand years of telling everyone 'we tried that'."] = "À nous deux, {name}, vingt mille ans à répéter « on a déjà essayé »."
L["Let's Shadowmeld together sometime, {name}, and see who notices."] = "Camouflons-nous dans l'ombre ensemble, {name}. On verra qui remarque."
L["Our shan'do sleeps in the Dream, {name}. Let's make his waking worth it."] = "Notre shan'do dort dans le Rêve, {name}. Faisons que son réveil en vaille la peine."
L["Our people are thin on the ground, {name}, and very thick in the trees."] = "Notre peuple se fait rare au sol, {name}, mais foisonne dans les arbres."
L["Quick one, {name}? By kaldorei reckoning we'll be done before we start."] = "Un petit tour rapide, {name} ? À l'échelle kaldorei, on aura fini avant d'avoir commencé."
L["I'll be the one you can't see, {name}. That's not a mistake; that's the plan."] = "Vous ne me verrez pas, {name}. Ce n'est pas une erreur, c'est le plan."
L["Elune watches the whole party, {name}. I'm just the one who waves at her."] = "Élune veille sur tout le groupe, {name}. Moi, je lui fais juste coucou."
L["Ten thousand years of companions, {name}. You lot rank rather high."] = "Dix mille ans de compagnons, {name}. Vous êtes plutôt bien classés."
L["Stay close, {name}. We kaldorei misplaced two World Trees. Not you, though."] = "Restez près de moi, {name}. Nous avons égaré deux Arbres-Monde ; vous, jamais."
L["If I fall, {name}, don't fret. I'll float about as a wisp, looking wise."] = "Si je tombe, {name}, pas d'inquiétude. Je flotterai en feu follet, l'air sage."
L["I fought beside Neltharion once, {name}. You're already a better ally."] = "J'ai combattu aux côtés de Neltharion, {name}. Vous êtes déjà un meilleur allié."
L["Follow me, {name}. I know these paths. They were a forest last time, mind."] = "Suivez-moi, {name}. Je connais ces sentiers. La dernière fois, c'était une forêt."
L["Should we fail, {name}, I'll remember you fondly for several thousand years."] = "En cas d'échec, {name}, je penserai à vous avec tendresse pendant des millénaires."
L["I've watched heroes charge in blind for millennia, {name}. Let's try eyes open."] = "Des millénaires que je vois des héros charger à l'aveugle, {name}. Essayons les yeux ouverts."
L["If anyone asks, {name}, we were always this good. I'll swear to it for ages."] = "Si on vous demande, {name}, on a toujours été aussi bons. J'en jurerai pendant des siècles."
L["I'll take first watch, {name}. And second. A kaldorei barely notices a night."] = "Premier tour de garde pour moi, {name}. Et le second. Un kaldorei remarque à peine une nuit."
L["The moon's up, {name}. For a kaldorei, this is the middle of the morning."] = "La lune est levée, {name}. Pour un kaldorei, c'est le milieu de la matinée."
L["Everyone sensible is asleep, {name}. Elune and I prefer it this way."] = "Les gens raisonnables dorment, {name}. Élune et moi préférons ça."
L["Moonlight suits you, {name}. This is merely a second layer."] = "Le clair de lune vous va bien, {name}. Ceci n'est qu'une seconde couche."
L["Dark at last, {name}. Now I see perfectly and everything else has to guess."] = "Enfin la nuit, {name}. Je vois parfaitement, et tout le reste doit deviner."
L["Same stars I saw ten thousand years ago, {name}. They've aged better than me."] = "Les mêmes étoiles qu'il y a dix mille ans, {name}. Elles ont mieux vieilli que moi."
L["Moonrise, {name}. Every kaldorei just woke up a little, and got a little smug."] = "La lune se lève, {name}. Chaque kaldorei s'éveille un peu, et devient un peu suffisant."
L["Morning, {name}. My people slept through these for millennia. I'm adapting."] = "Bonjour, {name}. Les miens ont passé des millénaires à dormir le matin. Je m'adapte."
L["Dawn, {name}. Elune's gone to bed, so I'm covering for her."] = "L'aube, {name}. Élune est partie se coucher, alors je la remplace."
L["The sun's up, {name}, and so, reluctantly, am I."] = "Le soleil est levé, {name}, et moi aussi, à contrecœur."
L["Too bright, {name}. I'll squint through this one; Elune forgives squinting."] = "Trop de lumière, {name}. Je plisserai les yeux ; Élune pardonne les yeux plissés."
L["Daybreak, {name}: the one hour a night elf is easy to spot. Quick, take this."] = "L'aube, {name} : la seule heure où l'on repère facilement un elfe de la nuit. Vite, prenez."
L["Up early, {name}? I'm up late. Let's meet in the middle, with this."] = "Levé tôt, {name} ? Moi, couché tard. Retrouvons-nous au milieu, avec ceci."
L["The shadows remember kindness, {name}. So do I."] = "Les ombres se souviennent de la bonté, {name}. Moi aussi."
L["My thanks, {name}. The ren'dorei do not forget a kindness."] = "Merci, {name}. Les ren'dorei n'oublient jamais un bienfait."
L["Thank you, {name}. The voices approve of you, which is frankly alarming."] = "Merci, {name}. Les voix vous approuvent, ce qui est franchement alarmant."
L["Thank you, {name}. Few give gifts to someone who glows this ominously."] = "Merci, {name}. On offre rarement des cadeaux à quelqu'un qui luit aussi sinistrement."
L["Kindness is rare in the Void, {name}. I'll return yours before it notices."] = "La bonté est rare dans le Vide, {name}. Je vous rends la vôtre avant qu'il s'en aperçoive."
L["Silvermoon threw us out, {name}. People like you make it hard to mind."] = "Lune-d'argent nous a chassés, {name}. Avec des gens comme vous, on n'y pense même plus."
L["Returned in full, {name}. It may be slightly purple. That's normal."] = "Rendu en intégralité, {name}. C'est peut-être un peu violet. C'est normal."
L["The Void only takes, {name}. I, however, give back."] = "Le Vide ne fait que prendre, {name}. Moi, je rends."
L["Thank you, {name}. The whispers went quiet. That's how I know it was sincere."] = "Merci, {name}. Les murmures se sont tus. C'est ainsi que je sais que c'était sincère."
L["Thank you, {name}. I'd smile, but people say it's unsettling. So: imagine one."] = "Merci, {name}. Je sourirais bien, mais il paraît que c'est inquiétant. Imaginez-en un."
L["Returned, {name}: cold hands, warm intentions. That's us in a sentence."] = "Rendu, {name} : mains froides, intentions chaleureuses. C'est tout nous."
L["Returned, {name}. You may hear it twice; my spells echo now."] = "Rendu, {name}. Rendu... Pardon, mes sorts ont de l'écho."
L["The Void offered me forbidden knowledge, {name}. Yours was the nicer gift."] = "Le Vide m'a offert un savoir interdit, {name}. Votre cadeau était plus gentil."
L["Alleria says the Void can be mastered, {name}. Kindness, I find, is easier."] = "Selon Alleria, le Vide se maîtrise, {name}. La bonté, je trouve, c'est plus facile."
L["Much obliged, {name}. Most people give us a wide berth. You gave me this."] = "Bien obligé, {name}. D'habitude, on nous tient à distance. Vous, vous m'avez tendu ceci."
L["Thank you, {name}. My shadow bowed as well. It never does. You've impressed it."] = "Merci, {name}. Mon ombre aussi s'est inclinée. Elle qui ne s'incline jamais."
L["As you wish, {name}. The shadows answer kindly today."] = "Comme vous voudrez, {name}. Les ombres sont clémentes aujourd'hui."
L["Consider it done, {name}. The Void obeys us, not the other way round."] = "C'est comme si c'était fait, {name}. Le Vide nous obéit, pas l'inverse."
L["Certainly, {name}. The whispers said no, so it's an easy yes."] = "Certainement, {name}. Les murmures ont dit non, donc c'est oui sans hésiter."
L["Of course, {name}. One {buff}, lightly seasoned with the Void."] = "Bien sûr, {name}. {buff}, avec une pincée de Vide."
L["Of course, {name}. Hold still; the shadows are shy with strangers."] = "Bien sûr, {name}. Ne bougez pas, les ombres sont timides avec les inconnus."
L["Gladly, {name}. Ren'dorei manners: the Void waits its turn."] = "Avec plaisir, {name}. Politesse ren'dorei : le Vide attend son tour."
L["Asked so nicely, {name}? The Void never says please. Here."] = "Demandé si gentiment, {name} ? Le Vide ne dit jamais s'il vous plaît. Tenez."
L["Of course, {name}. Stand in the light, please; the Void gets ideas in corners."] = "Bien sûr, {name}. Mettez-vous dans la lumière ; dans les coins, le Vide se fait des idées."
L["Of course, {name}. The Void asked why. I said 'manners'. It's still puzzled."] = "Bien sûr, {name}. Le Vide a demandé pourquoi. J'ai dit « politesse ». Il cherche encore."
L["Gladly, {name}. Nobody asks us for anything but 'please stop whispering'."] = "Avec plaisir, {name}. D'habitude, on nous demande juste d'arrêter de murmurer."
L["Happy to, {name}. Just let me finish arguing with myself. There. I won."] = "Volontiers, {name}. Je finis de me disputer avec moi-même. Voilà. J'ai gagné."
L["Certainly, {name}. I could rift over there first, but that feels showy."] = "Certainement, {name}. J'aurais pu venir par une faille, mais ça fait m'as-tu-vu."
L["Asking questions got us exiled, {name}. Answering one is quite safe, I'm told."] = "Poser des questions nous a valu l'exil, {name}. Y répondre est sans danger, paraît-il."
L["Of course, {name}. A slight chill and a faint chorus are both perfectly normal."] = "Bien sûr, {name}. Un léger frisson et un chœur lointain, c'est parfaitement normal."
L["A touch of shadow for you, {name}. Quite safe. Mostly."] = "Une touche d'ombre pour vous, {name}. Sans danger. En principe."
L["Walk carefully in the dark places, {name}."] = "Prudence dans les lieux obscurs, {name}."
L["A little something from the Telogrus Rift, {name}. It's cleaner than it sounds."] = "Un petit souvenir de la Faille de Telogrus, {name}. C'est plus propre qu'on ne le croit."
L["Take this, {name}. Any tentacles you see are purely decorative."] = "Prenez ceci, {name}. Les tentacules éventuels sont purement décoratifs."
L["The shadows asked after you, {name}. I told them to mind their manners."] = "Les ombres ont demandé de vos nouvelles, {name}. Je leur ai dit de bien se tenir."
L["Here, {name}. We walked into the Void so you wouldn't have to."] = "Tenez, {name}. Nous avons plongé dans le Vide pour vous l'éviter."
L["I checked your shadow, {name}. Nothing lurking. Take this anyway."] = "J'ai vérifié votre ombre, {name}. Rien ne s'y cache. Prenez ceci quand même."
L["Umbric sends his regards, {name}. He doesn't, but he would."] = "Umbric vous salue, {name}. Enfin, non, mais il le ferait."
L["Take this, {name}. It may whisper a compliment. Pretend you didn't hear."] = "Prenez ceci, {name}. Si ça murmure un compliment, faites mine de rien."
L["Here, {name}. Looks sinister, works beautifully. Rather like me."] = "Tenez, {name}. L'air sinistre, mais ça marche à merveille. Un peu comme moi."
L["Take this, {name}. The Void had worse in mind for you. I intercepted."] = "Prenez ceci, {name}. Le Vide vous réservait pire. J'ai intercepté."
L["If something in the dark whispers your name, {name}, relax. That was me. Here."] = "Si quelque chose murmure votre nom dans le noir, {name}, détendez-vous. C'était moi. Tenez."
L["Here, {name}. We ren'dorei don't often get to be the nice surprise."] = "Tenez, {name}. Il est rare que les ren'dorei soient la bonne surprise."
L["I left Quel'Thalas with only a knack for the dark, {name}. Here's the knack."] = "J'ai quitté Quel'Thalas avec un seul don, celui de l'ombre, {name}. Je vous en fais don."
L["Here, {name}. Don't thank the shadows; they'll only want something. Thank me."] = "Tenez, {name}. Remerciez-moi, pas les ombres : elles voudraient quelque chose."
L["I owe a kindness for every ominous look I've given, {name}. I'm badly behind."] = "Je dois une gentillesse pour chaque regard sinistre lancé, {name}. J'ai un sacré retard."
L["We ren'dorei look after our own, {name}."] = "Nous, ren'dorei, veillons sur les nôtres, {name}."
L["Silvermoon's loss, {name}. We're doing splendidly without it."] = "Tant pis pour Lune-d'argent, {name}. Nous nous portons à merveille sans elle."
L["Your whispers and mine should really meet sometime, {name}."] = "Vos murmures et les miens devraient vraiment se rencontrer un jour, {name}."
L["Two ren'dorei in one place, {name}. Quick, look brooding. It's expected."] = "Deux ren'dorei au même endroit, {name}. Vite, prenons l'air ténébreux. On l'attend de nous."
L["Nobody else understands the hair, {name}. It was blond once. I think."] = "Personne ne comprend nos cheveux, {name}. Ils ont été blonds. Je crois."
L["Telogrus felt like home in the end, {name}. A very draughty, very dark home."] = "Telogrus a fini par ressembler à un foyer, {name}. Très sombre, plein de courants d'air."
L["Ren'dorei to ren'dorei, {name}: what's yours whispering? Mine's on about soup."] = "Entre ren'dorei, {name} : que disent vos murmures ? Les miens parlent de soupe."
L["Stay close, {name}. The whispers are much quieter in company."] = "Restez près de moi, {name}. En compagnie, les murmures se taisent."
L["If the shadows start giving orders, {name}, ignore them. I usually do."] = "Si les ombres se mettent à donner des ordres, {name}, ignorez-les. C'est ce que je fais."
L["Keep an eye on my shadow, {name}. It wanders off when there's a fight."] = "Surveillez mon ombre, {name}. Elle file dès qu'il y a un combat."
L["If I start glowing purple, {name}, carry on. It only means I'm keen."] = "Si je me mets à luire en violet, {name}, continuez. C'est juste de l'enthousiasme."
L["We ren'dorei make fine companions, {name}. We bring our own dark to hide in."] = "Les ren'dorei sont de bons compagnons, {name}. On apporte notre propre ombre pour s'y cacher."
L["If I seem to talk to nobody, {name}, I'm fine. If nobody talks back, worry."] = "Si je parle dans le vide, {name}, ça va. Si le Vide ne répond pas, inquiétez-vous."
L["I'll open a rift if it goes wrong, {name}. Only for me, sadly. But I'll wave."] = "Si ça tourne mal, {name}, j'ouvre une faille. Pour moi seul, hélas. Mais je ferai coucou."
L["Try to enjoy this, {name}. We ren'dorei rarely get invited anywhere twice."] = "Profitez-en, {name}. On invite rarement les ren'dorei deux fois."
L["Keep the lanterns lit, {name}. I don't need them; the shadows behave better."] = "Gardez les lanternes allumées, {name}. Pas pour moi : les ombres se tiennent mieux."
L["Keep an eye on the corners, {name}. I'll keep an eye on what's in them."] = "Surveillez les coins, {name}. Moi, je surveille ce qu'il y a dedans."
L["The Void promised me power, {name}. It never mentioned company this good."] = "Le Vide m'a promis le pouvoir, {name}. Il n'a jamais parlé d'aussi bonne compagnie."
L["If you hear whispers mid-fight, {name}, they're cheering. For us, I think."] = "Des murmures en plein combat, {name} ? Ils nous encouragent. Enfin, je crois."
L["Should anything eldritch turn up, {name}, let me talk to it. I speak a little."] = "Si une horreur indicible se présente, {name}, laissez-moi lui parler. Je baragouine un peu."
L["Night suits the ren'dorei, {name}. We match the decor."] = "La nuit va bien aux ren'dorei, {name}. Nous sommes assortis au décor."
L["The shadows are longest now, {name}, and in a very generous mood."] = "Les ombres n'ont jamais été si longues, {name}, ni d'humeur si généreuse."
L["Late, {name}? The whispers love a late hour. Lately, so do I."] = "Tard, {name} ? Les murmures adorent les heures tardives. Moi aussi, sur le tard."
L["Midnight, {name}. The one hour my shadow and I agree on anything."] = "Minuit, {name}. La seule heure où mon ombre et moi sommes d'accord."
L["Stars out, {name}. I've seen what's between them, and I prefer the stars."] = "Les étoiles, {name}. J'ai vu ce qu'il y a entre elles ; je préfère les étoiles."
L["Thanks, {name}! Kindness received, catalogued and returned!"] = "Merci, {name} ! Gentillesse reçue, cataloguée et retournée !"
L["Reciprocity engaged! Much obliged, {name}."] = "Réciprocité enclenchée ! Mille mercis, {name}."
L["By my calculations, {name}, you're owed exactly one {buff}."] = "D'après mes calculs, {name}, je vous dois {buff}. Pile."
L["Thanks, {name}! I'd build you a thank-you machine, but it'd explode."] = "Merci, {name} ! Je vous ferais bien une machine à remercier, mais elle exploserait."
L["Thank you, {name}! This calls for a celebration. Stand back, I'll build one."] = "Merci, {name} ! Ça mérite une fête. Reculez, je vais en construire une."
L["You're too kind, {name}! Returning the favour took only four schematics."] = "Trop aimable, {name} ! Vous rendre la politesse n'a demandé que quatre schémas."
L["Drat, {name}! I was going to invent gratitude, but you beat me to it."] = "Zut, {name} ! J'allais inventer la gratitude, mais vous m'avez devancé."
L["Oh, {name}, how kind! My heart's doing that whirring thing again."] = "Oh, {name}, comme c'est gentil ! Mon cœur refait son petit bruit de rouage."
L["Noted in my lab journal, {name}, page four hundred: 'people are lovely'."] = "Noté dans mon carnet de labo, {name}, page quatre cents : « les gens sont adorables »."
L["Splendid, {name}! Returning it at once, before I'm tempted to improve it."] = "Formidable, {name} ! Je vous le rends vite, avant d'être tenté de le perfectionner."
L["Thanks, {name}! Kindness is a reversible reaction. I checked. Here's yours."] = "Merci, {name} ! La gentillesse est une réaction réversible. J'ai vérifié. Voilà la vôtre."
L["My mechanostrider would salute you, {name}, but it only knows falling over."] = "Mon mécanotrotteur vous saluerait bien, {name}, mais il ne sait que tomber."
L["My transporter would've sent this to Gadgetzan, {name}. Hand-delivered instead!"] = "Mon transporteur aurait envoyé ça à Gadgetzan, {name}. Livré en main propre, du coup !"
L["Oh, thank you, {name}! I haven't felt this good since before the troggs."] = "Oh, merci, {name} ! Je ne m'étais pas senti aussi bien depuis avant les troggs."
L["I'll name my next invention after you, {name}! It's a very small cannon."] = "Ma prochaine invention portera votre nom, {name} ! C'est un tout petit canon."
L["Thanks, {name}! Mind the whistle; that's just my gratitude valve venting."] = "Merci, {name} ! Ce sifflement ? Ma soupape de gratitude qui dégaze."
L["You're on my list of favourite people, {name}! It's short. Mostly clockwork."] = "Vous êtes sur ma liste de chouchous, {name} ! Elle est courte. Surtout des automates."
L["Request received, {name}! Processing... done!"] = "Requête reçue, {name} ! Traitement en cours... terminé !"
L["One upgrade, coming right up, {name}! Stand still for calibration."] = "Une mise à niveau, tout de suite, {name} ! Ne bougez plus, calibrage en cours."
L["Of course, {name}! I built a machine for this. It's in pieces, so: by hand."] = "Bien sûr, {name} ! J'ai une machine pour ça. Elle est en pièces, donc : à la main."
L["Certainly, {name}! Stand on the X. There's no X. Stand anywhere."] = "Bien sûr, {name} ! Sur la croix. Il n'y a pas de croix. Où vous voulez."
L["Right away, {name}! Goggles on. Not for you, I just like them."] = "Tout de suite, {name} ! Lunettes en place. Pas pour vous, je les aime bien."
L["{buff}, {name}? Simple in theory AND practice. Suspicious!"] = "{buff}, {name} ? Simple en théorie ET en pratique. Louche !"
L["Happy to, {name}! Keep hands, feet and eyebrows well clear."] = "Avec joie, {name} ! Gardez mains, pieds et sourcils à bonne distance."
L["Right away, {name}! Stand back three paces. Four. Five. There, perfect."] = "Tout de suite, {name} ! Reculez de trois pas. Quatre. Cinq. Voilà, parfait."
L["Happy to, {name}! It beats sorting springs by size. Though that's fun too."] = "Avec joie, {name} ! Mieux que trier des ressorts. Quoique, c'est amusant aussi."
L["Excellent request, {name}! No moving parts. I'll try to add some next time."] = "Excellente demande, {name} ! Aucune pièce mobile. J'en ajouterai la prochaine fois."
L["Standard model or deluxe, {name}? They're the same. Deluxe sounds nicer."] = "Modèle standard ou de luxe, {name} ? C'est le même. « De luxe » sonne mieux."
L["Coming up, {name}! Fresh off the workbench, still warm, only slightly smoking."] = "Ça arrive, {name} ! Tout juste sorti de l'établi, encore chaud, à peine fumant."
L["Approved, {name}! Stamped, signed and filed under 'obviously'."] = "Approuvé, {name} ! Tamponné, signé et classé à « évidemment »."
L["Of course, {name}! Adjust the gyromatic... no, wait, that's the squirrel's."] = "Bien sûr, {name} ! J'ajuste le gyromatique... non, attendez, c'est celui de l'écureuil."
L["Gnomes never refuse a problem, {name}. Occasionally we cause them. Here!"] = "Les gnomes ne refusent jamais un problème, {name}. Parfois, on les crée. Tenez !"
L["Hold still, {name}, this is perfectly safe. Probably!"] = "Ne bougez pas, {name}, c'est parfaitement sûr. Probablement !"
L["Science says you need this, {name}. Who am I to argue?"] = "D'après la science, il vous faut ça, {name}. Qui suis-je pour discuter ?"
L["A small upgrade for you, {name}. No cogs required."] = "Une petite mise à niveau pour vous, {name}. Aucun rouage requis."
L["Take it, {name}, I've a spare. I've three spares of everything."] = "Prenez, {name}, j'en ai un de rechange. J'ai trois rechanges de tout."
L["Try this, {name}! Version one had legs. Version two is much better."] = "Essayez ça, {name} ! La version un avait des jambes. La version deux est bien mieux."
L["The High Tinker says share our genius, {name}. Here's a sample!"] = "Le Grand Artisan dit de partager notre génie, {name}. Voici un échantillon !"
L["Gnomeregan Forever, {name}! This lasts rather less, but it's free."] = "Gnomeregan pour toujours, {name} ! Ceci dure un peu moins, mais c'est gratuit."
L["I'm small, {name}, but my gifts come full-sized. Here!"] = "Je n'ai pas la taille, {name}, mais mes cadeaux, si. Tenez !"
L["Don't worry, {name}! It worked on the chicken, and the chicken's thrilled."] = "Pas d'inquiétude, {name} ! Ça a marché sur le poulet, et le poulet est ravi."
L["Field test, {name}! You're the lucky volunteer. Everyone's a volunteer, really."] = "Essai sur le terrain, {name} ! Bravo, vous êtes volontaire. D'office, comme tout le monde."
L["One size fits all, {name}, gnome to tauren. I measured. The tauren was patient."] = "Taille unique, {name}, du gnome au tauren. J'ai mesuré. Le tauren a été patient."
L["Take this, {name}! Unlike my Net-o-Matic, it never lands on me."] = "Prenez, {name} ! Mon lance-filet me retombe dessus. Ceci, jamais."
L["The Gnomish Army Knife does twelve things badly, {name}. This does one well."] = "Mon couteau gnome multifonction fait douze choses mal, {name}. Ceci en fait une bien."
L["Guarantee void if exposed to troggs, dragonfire or enthusiasm, {name}. Enjoy!"] = "Garantie annulée en cas de troggs, de feu de dragon ou d'enthousiasme, {name}. Profitez !"
L["Nothing up my sleeves, {name}! Well, a spanner and two fuses. Nothing sinister."] = "Rien dans les mains, rien dans les poches, {name} ! Enfin, une clé et deux fusibles."
L["Here, {name}! It's small, but so is a keystone, and look what those hold up."] = "Tenez, {name} ! C'est petit, mais une clé de voûte aussi, et voyez ce qu'elle soutient."
L["I'd explain how it works, {name}, but that takes three days and a chalkboard."] = "Je vous expliquerais le principe, {name}, mais il faut trois jours et un tableau noir."
L["If you hear ticking, {name}, that's my pocket watch. Almost certainly."] = "Si vous entendez un tic-tac, {name}, c'est ma montre. Très probablement."
L["For Gnomeregan, {name}! Always nice to talk to somebody at eye level."] = "Pour Gnomeregan, {name} ! Enfin quelqu'un à ma hauteur !"
L["A fellow gnome, {name}! I'll hold the schematic; you hold the bucket."] = "Un autre gnome, {name} ! Je tiens le schéma, vous tenez le seau."
L["Flesh or cogs, {name}, we're all gnomes. Some of us just need oiling."] = "Chair ou rouages, {name}, on est tous gnomes. Certains ont juste besoin d'huile."
L["One gnome to another, {name}: you did turn the reactor off, didn't you?"] = "Entre gnomes, {name} : vous avez bien éteint le réacteur, hein ?"
L["Two gnomes, {name}! Stacked up, we're very nearly a night elf."] = "Deux gnomes, {name} ! L'un sur l'autre, on fait presque un elfe de la nuit."
L["You check my sums, {name}, I check yours, and we're both quietly offended."] = "Vous vérifiez mes calculs, {name}, je vérifie les vôtres, et on se vexe en silence."
L["You still owe me a sprocket, {name}. Every gnome owes me a sprocket."] = "Vous me devez toujours un pignon, {name}. Tous les gnomes me doivent un pignon."
L["One day, {name}, we'll walk back into Gnomeregan together. With the lights on."] = "Un jour, {name}, on retournera ensemble à Gnomeregan. Et on rallumera la lumière."
L["Between gnomes, {name}: we both know it'll explode, and we both want to watch."] = "Entre gnomes, {name} : on sait que ça va exploser, et on veut tous les deux voir ça."
L["Shall we build something huge, {name}? Just to see the tall folk's faces?"] = "Et si on construisait un truc énorme, {name} ? Juste pour voir la tête des grands ?"
L["Party-wide calibration complete, {name}! Nobody touch anything shiny."] = "Calibrage du groupe terminé, {name} ! Personne ne touche à ce qui brille."
L["I've run the numbers, {name}: with you here, we win. I rounded up."] = "J'ai fait les calculs, {name} : avec vous, on gagne. J'ai arrondi au-dessus."
L["If I shout 'duck', {name}, don't look for a duck. That went badly last time."] = "Si je crie « Gare ! », {name}, ne cherchez pas de train. Ça a déjà mal fini."
L["Formation, {name}: tall folk at the front, me somewhere safe and clever."] = "Formation, {name} : les grands devant, moi dans un coin sûr et ingénieux."
L["Everyone gets one, {name}! Standardised parts are the secret of a good machine."] = "Un pour chacun, {name} ! Les pièces standard, c'est le secret d'une bonne machine."
L["My plan, {name}: step one, survive. Step two is still in development."] = "Mon plan, {name} : étape un, survivre. L'étape deux est encore à l'étude."
L["Don't panic, {name}. Whatever goes wrong, I'll have a gadget for it. Next week."] = "Pas de panique, {name}. Quoi qu'il arrive, j'aurai un gadget pour ça. La semaine prochaine."
L["If I vanish, {name}, check under the nearest boot. Politely, please."] = "Si je disparais, {name}, regardez sous la botte la plus proche. Poliment."
L["When this is over, {name}, I want samples. Of everything. The big one first."] = "Après ça, {name}, je veux des échantillons. De tout. Du gros en premier."
L["Every explosion today, {name}, is on purpose. I'll decide which ones later."] = "Chaque explosion aujourd'hui, {name}, est voulue. Je déciderai lesquelles plus tard."
L["Group trial under way, {name}! No control group. Everybody gets the good stuff."] = "Essai de groupe en cours, {name} ! Pas de groupe témoin. Personne n'a le placebo."
L["If we get separated, {name}, follow the smoke. It'll be me."] = "Si on est séparés, {name}, suivez la fumée. Ce sera moi."
L["Everyone keep their fingers, {name}. I've counted. I'll count again after."] = "Gardez tous vos doigts, {name}. Je les ai comptés. Je recompterai après."
L["Morning, {name}! Up since three. The toaster needed a new engine."] = "Bonjour, {name} ! Debout depuis 3 h : il fallait un moteur neuf au grille-pain."
L["Good morning, {name}! The coffee's brewing itself. It learned how. Worrying."] = "Bonjour, {name} ! Le café se fait tout seul. Il a appris. C'est inquiétant."
L["Early start, {name}! Best ideas come before breakfast. So do the explosions."] = "Debout tôt, {name} ! Les meilleures idées viennent avant le petit-déjeuner. Les explosions aussi."
L["Morning, {name}! My alarm clock went off at six. Exploded, I mean. Effective!"] = "Bonjour, {name} ! Mon réveil a sonné à 6 h. Enfin, explosé. Très efficace !"
L["Up early, {name}? I dreamt of a better sprocket and couldn't wait. Here!"] = "Déjà debout, {name} ? J'ai rêvé d'un meilleur pignon, impossible d'attendre. Tenez !"
L["Morning, {name}! The sun's a bit dim today. I've been meaning to fix that."] = "Bonjour, {name} ! Le soleil est un peu faiblard. Il faudrait que je le répare."
L["The Light rewards kindness, {name}. I'm simply its fastest courier."] = "La Lumière récompense la bonté, {name}. Je suis juste son coursier le plus rapide."
L["Archenon poros, {name}. Your gift is returned."] = "Archenon poros, {name}. Votre présent vous est rendu."
L["Thanks, {name}. I'd offer a lift in the Exodar, but you've seen how it lands."] = "Merci, {name}. Je vous offrirais bien un tour dans l'Exodar, mais vous avez vu son atterrissage."
L["A gift freely given, {name}. The naaru hum a little louder. Returned."] = "Un don sincère, {name}. Les naaru vibrent un peu plus fort. Je vous le rends."
L["Kindly done, {name}. On Argus we'd have carved that in crystal. Here."] = "Bien aimable, {name}. Sur Argus, on l'aurait gravé dans le cristal. Tenez."
L["Across a dozen worlds, {name}, kindness is the one tongue I never had to learn."] = "D'un monde à l'autre, {name}, la bonté est la seule langue que je n'ai pas eu à apprendre."
L["What a kindness, {name}. It almost makes up for the Legion. Almost."] = "Quelle bonté, {name}. De quoi presque oublier la Légion. Presque."
L["Thank you, {name}. I'd say it in Draenei, but that takes eleven minutes."] = "Merci, {name}. Je vous le dirais bien en draeneï, mais ça prend onze minutes."
L["Thank you, {name}. The Exodar crashed; my manners didn't. Here."] = "Merci, {name}. L'Exodar s'est écrasé ; mes bonnes manières, non. Tenez."
L["Sargeras once offered my people gifts, {name}. We ran. Yours, I'll keep."] = "Sargeras nous a offert des dons, {name}. Nous avons fui. Le vôtre, je le garde."
L["Thank you, {name}. I've fled demons across the stars, but never from a debt."] = "Merci, {name}. J'ai fui les démons à travers les étoiles, mais jamais une dette."
L["Thank you, {name}. I'll add you to my prayers. The list goes back to Argus."] = "Merci, {name}. Je vous ajoute à mes prières. La liste remonte jusqu'à Argus."
L["The Legion took a world from us, {name}. Folk like you keep giving bits back."] = "La Légion nous a pris un monde, {name}. Des gens comme vous nous en rendent des bouts."
L["You gave first, {name}. A prophet would call it an omen. I call it manners."] = "Vous avez donné le premier, {name}. Un prophète y verrait un signe ; moi, de la politesse."
L["With the Light's compliments, {name}. It asked me to add 'nicely done'."] = "Avec les compliments de la Lumière, {name}. Elle me charge d'ajouter « bien joué »."
L["Of course, {name}. The naaru guide your steps; this puts a spring in them."] = "Bien sûr, {name}. Les naaru guident vos pas ; ceci leur donne du ressort."
L["Gladly, {name}. The Light answers those who ask."] = "Avec plaisir, {name}. La Lumière répond à qui l'appelle."
L["Velen foresaw you asking, {name}. I foresaw saying yes."] = "Velen avait prévu votre demande, {name}. Moi, j'avais prévu de dire oui."
L["The Light is not rationed, {name}. Take as much as you like."] = "La Lumière n'est pas rationnée, {name}. Servez-vous."
L["Of course, {name}. I've outrun the Burning Legion; I can manage this."] = "Bien sûr, {name}. J'ai semé la Légion ardente ; je peux bien gérer ça."
L["At once, {name}. Hooves planted, crystals humming, here it comes."] = "Tout de suite, {name}. Sabots plantés, cristaux vibrants, ça arrive."
L["Gladly, {name}. I followed a talking crystal across the stars. This is easy."] = "Avec plaisir, {name}. J'ai suivi un cristal qui parle à travers les étoiles. Ceci est facile."
L["Certainly, {name}. Velen taught us patience. Luckily, this takes none."] = "Bien sûr, {name}. Velen nous a appris la patience. Par chance, ceci n'en demande pas."
L["Gladly, {name}. The naaru never say no. They say 'hmmm', but it means yes."] = "Volontiers, {name}. Un naaru ne dit jamais non. Il dit « hmmm », et ça veut dire oui."
L["On the Exodar this took three crystals and a prayer, {name}. Here: the prayer."] = "Sur l'Exodar, il fallait trois cristaux et une prière, {name}. Voici la prière."
L["Of course, {name}. I only refuse demons, and they so rarely say please."] = "Bien sûr, {name}. Je ne refuse qu'aux démons, et ils sont si rarement polis."
L["Gladly, {name}. We were refugees long enough to know what asking costs."] = "Avec plaisir, {name}. Réfugiés si longtemps, nous savons ce que coûte une demande."
L["Of course, {name}. My people crossed the stars looking for friends. Found one."] = "Bien sûr, {name}. Mon peuple a traversé les étoiles pour trouver des amis. En voilà un."
L["Ask a draenei, {name}: one yes, one blessing, possibly a history lesson."] = "Demandez à un draeneï, {name} : un oui, une bénédiction, voire un cours d'histoire."
L["The Light is with you, {name}. Go in peace, or at least go prepared."] = "La Lumière est avec vous, {name}. Allez en paix, ou au moins bien préparé."
L["Walk in the Light, {name}. May it shelter you always."] = "Marchez dans la Lumière, {name}. Qu'elle vous protège toujours."
L["Take this, {name}. My people always travel Light."] = "Prenez ceci, {name}. Mon peuple voyage toujours éclairé."
L["Take this, {name}. The Legion is always coming. I'd know."] = "Prenez ceci, {name}. La Légion revient toujours. J'en sais quelque chose."
L["I'm out of miracles today, {name}. Will {buff} do?"] = "Plus de miracles en stock aujourd'hui, {name}. {buff}, ça ira ?"
L["For the road, {name}. Mine has been twenty-five thousand years long."] = "Pour la route, {name}. La mienne dure depuis vingt-cinq mille ans."
L["Blessed by a naaru, {name}. Well, I stood near one. It still counts."] = "Béni par un naaru, {name}. Enfin, j'étais à côté. Ça compte quand même."
L["Take this, {name}. It glows a bit. Everything we own does."] = "Prenez ceci, {name}. Ça brille un peu. Tout ce qu'on possède brille."
L["Here, {name}. We draenei pack for the end of the world. We've had the practice."] = "Tenez, {name}. Nous autres draeneï faisons nos bagages pour la fin du monde. L'habitude."
L["Take this, {name}. I've stayed a step ahead of demons for ages. Now you're two."] = "Prenez ceci, {name}. J'ai toujours eu un pas d'avance sur les démons. Vous en avez deux."
L["The naaru shine on all, {name}. They're dreadful at aiming. I'm helping."] = "Les naaru brillent pour tous, {name}. Mais ils visent très mal. Je les aide."
L["A stranger shared bread with me on Azuremyst, {name}. I'm still paying it back."] = "Un inconnu a partagé son pain avec moi sur Brume-Azur, {name}. Je le rembourse encore."
L["Velen sees a thousand futures, {name}. I see one: you, better prepared. Here."] = "Velen voit mille avenirs, {name}. Moi, un seul : vous, mieux préparé. Tenez."
L["Don't drink from the streams on Bloodmyst, {name}. Do take this."] = "Ne buvez pas l'eau des ruisseaux de Brume-Sang, {name}. Mais prenez ceci."
L["Eredar magic from before the fall, {name}. We only kept the good kind. Here."] = "Magie érédar d'avant la chute, {name}. Nous n'avons gardé que la bonne. Tenez."
L["Archenon poros, {name}! The children of Argus look after one another."] = "Archenon poros, {name} ! Les enfants d'Argus veillent les uns sur les autres."
L["Home is wherever two draenei meet, {name}. Today, it's here."] = "Deux draeneï réunis, c'est un foyer, {name}. Aujourd'hui, c'est ici."
L["Horns high, {name}. Two draenei, and nobody's mentioned the Legion. Progress."] = "Cornes hautes, {name}. Deux draeneï, et personne n'a parlé de la Légion. On progresse."
L["Tails up, {name}. Argus would be proud of what we've made of exile."] = "Queue haute, {name}. Argus serait fier de ce que nous avons fait de l'exil."
L["Two draenei, {name}, and between us nearly fifty thousand years of worrying."] = "Deux draeneï, {name}, et à nous deux près de cinquante mille ans d'inquiétude."
L["Horns, hooves and hope, {name}. The Legion never found a cure for any of them."] = "Cornes, sabots et espoir, {name}. La Légion n'a jamais trouvé de remède à aucun."
L["Children of Velen, {name}: exiled, hopeful and dreadfully polite."] = "Enfants de Velen, {name} : exilés, pleins d'espoir et terriblement polis."
L["Third world's the charm, {name}. We draenei are owed one that stays put."] = "Jamais deux sans trois, {name}. Mais ce monde-ci, nous comptons le garder."
L["Stay near, {name}. I lost a world once; I'm keeping hold of this party."] = "Restez près de moi, {name}. J'ai déjà perdu un monde ; ce groupe, je le garde."
L["Twenty-five thousand years on the run, {name}. Walking with friends is nicer."] = "Vingt-cinq mille ans de fuite, {name}. Marcher entre amis, c'est plus agréable."
L["The naaru would call this a fellowship, {name}. I call it good luck."] = "Les naaru appelleraient ça une confrérie, {name}. Moi, j'appelle ça de la chance."
L["I've watched worlds end, {name}. Whatever's ahead of us hardly worries me."] = "J'ai vu des mondes finir, {name}. Ce qui nous attend ne m'inquiète guère."
L["Stay together, {name}. The Light finds us easier when we're all in one place."] = "Restons groupés, {name}. La Lumière nous trouve mieux quand on est tous ensemble."
L["Stay close, {name}. We draenei are very good at leaving places in a hurry."] = "Restez près de moi, {name}. Les draeneï sont très doués pour partir en catastrophe."
L["We draenei take the long view, {name}. From up here, this fight is very short."] = "Nous autres draeneï voyons loin, {name}. De là-haut, ce combat paraît bien court."
L["Let me go first, {name}. Anything watching will see a very tall optimist."] = "Laissez-moi passer devant, {name}. Qui nous guette verra un très grand optimiste."
L["We draenei follow prophets, {name}. Today I'll settle for following you."] = "Les draeneï suivent les prophètes, {name}. Aujourd'hui, je me contenterai de vous."
L["The Exodar carried thousands, {name}, and this little party still feels safer."] = "L'Exodar en portait des milliers, {name}, et ce petit groupe me semble plus sûr."
L["Shoulder to shoulder, {name}. Mine's a bit higher, but the principle holds."] = "Épaule contre épaule, {name}. La mienne est un peu plus haute, mais le principe tient."
L["A prayer for the party, {name}. The short one. The long one ends next age."] = "Une prière pour le groupe, {name}. La courte. La longue finit à la prochaine ère."
L["Much obliged, {name}. Gilneas never forgets a kindness, and nor does my nose."] = "Je vous suis redevable, {name}. Gilnéas n'oublie jamais un bienfait, et mon flair non plus."
L["Thank you, {name}. You have my gratitude, and my best howl."] = "Merci, {name}. Vous avez ma gratitude, et mon plus beau hurlement."
L["Thank you, {name}. If worgen had tails, mine would be wagging."] = "Merci, {name}. Si les worgens avaient une queue, la mienne remuerait."
L["You've made a friend for life, {name}. Loyalty is rather our thing."] = "Vous vous êtes fait un ami pour la vie, {name}. La loyauté, c'est un peu notre truc."
L["The beast in me wants to growl, {name}. The Gilnean in me insists on thanks."] = "La bête en moi veut grogner, {name}. Le Gilnéen en moi tient à vous remercier."
L["Much appreciated, {name}. I'd shake your hand, but, claws. Here instead."] = "Merci beaucoup, {name}. Je vous serrerais bien la main, mais... les griffes. Tenez plutôt ça."
L["We walled ourselves off for years, {name}. You make that look silly."] = "Des années cachés derrière un mur, {name}. Grâce à vous, ça paraît bien bête."
L["Obliged, {name}. You've earned a spot by the fire. The good spot."] = "Bien obligé, {name}. Vous avez gagné une place au coin du feu. La bonne place."
L["Thank you, {name}. In return, I'll never chase your mount. Well, rarely."] = "Merci, {name}. En retour, je ne courrai jamais après votre monture. Enfin, rarement."
L["Returned, {name}, with a stiff upper lip. The lower one shows teeth; ignore it."] = "Je vous le rends, {name}, avec le sourire. Il montre un peu les crocs, ignorez ça."
L["Thank you, {name}. I'd tip my hat, but it doesn't fit over the ears these days."] = "Merci, {name}. Je vous tirerais mon chapeau, mais il ne passe plus sur mes oreilles."
L["Thank you, {name}. Most folk just scratch my ears and hope for the best."] = "Merci, {name}. D'habitude, on me gratte les oreilles en espérant que ça suffise."
L["Returned, {name}. A Gilnean pays debts; a worgen pays them at a sprint."] = "Je vous le rends, {name}. Un Gilnéen paie ses dettes ; un worgen les paie au galop."
L["Spoiled twice today, {name}, and the first time was a biscuit. Thank you."] = "Gâté deux fois aujourd'hui, {name}, et la première, c'était un biscuit. Merci."
L["Certainly, {name}. Hold still, I don't bite. Much."] = "Certainement, {name}. Du calme, je ne mords pas. Pas trop."
L["Right you are, {name}. Stand steady now."] = "Bien entendu, {name}. Restez tranquille."
L["Right away, {name}. Stay, now. I've always wanted to say that."] = "Tout de suite, {name}. Pas bouger ! J'ai toujours rêvé de dire ça."
L["Gladly, {name}. Rain or shine, and in Gilneas it's rain."] = "Avec plaisir, {name}, qu'il pleuve ou non. À Gilnéas, il pleut."
L["Certainly, {name}. I'll try not to shed on you."] = "Bien sûr, {name}. J'éviterai de muer sur vous."
L["Say no more, {name}. These ears heard you before you'd decided to ask."] = "Pas un mot de plus, {name}. Ces oreilles vous entendaient avant que vous demandiez."
L["Of course, {name}. You asked nicer than the last fellow who threw me a stick."] = "Bien sûr, {name}. Vous avez demandé plus poliment que le dernier qui m'a lancé un bâton."
L["Glad to, {name}. Few people ask a seven-foot wolf for favours. I love it."] = "Volontiers, {name}. On demande rarement un service à un loup de deux mètres. J'adore."
L["Certainly, {name}. I'll stay in this form. The other one causes a scene."] = "Certainement, {name}. Je reste sous cette forme. L'autre fait toujours scandale."
L["Tea first? No? Straight to business, {name}. How very un-Gilnean. Here."] = "Un thé d'abord ? Non ? Droit au but, {name}. Si peu gilnéen. Tenez."
L["Of course, {name}. Excuse the damp. Nothing smells quite like a wet worgen."] = "Bien sûr, {name}. Excusez l'humidité. Le chien mouillé, à côté, sent la rose."
L["Of course, {name}. I'll try not to sniff. I will fail, but I'll try."] = "Bien sûr, {name}. J'essaierai de ne pas renifler. J'échouerai, mais j'essaierai."
L["Of course, {name}. Anything but a bath."] = "Bien sûr, {name}. Tout sauf un bain."
L["Stay off the moors after dark, {name}. Take this."] = "Évitez la lande à la nuit tombée, {name}. Prenez ceci."
L["Keep your wits about you, {name}. Something is always hunting."] = "Restez vigilant, {name}. Il y a toujours quelque chose en chasse."
L["I'd have brought this sooner, {name}, but I stopped to chase something."] = "Je vous l'aurais apporté plus tôt, {name}, mais il a fallu que je coure après quelque chose."
L["For you, {name}. No, I don't want a treat. Well. Perhaps a small one."] = "Pour vous, {name}. Non, je ne veux pas de friandise. Enfin... peut-être une petite."
L["Gilneans always offer, {name}. The claws are just part of the outfit."] = "Les Gilnéens offrent toujours, {name}. Les griffes font juste partie de la tenue."
L["An old Gilnean remedy, {name}. Good for colds, gloom and most curses. Not mine."] = "Un vieux remède gilnéen, {name}. Contre le rhume, le spleen et les malédictions. Sauf la mienne."
L["Run with this, {name}. Trust me, I know about running."] = "Courez avec ça, {name}. Croyez-moi, la course, je connais."
L["Fetched this for you, {name}. Don't make a thing of it."] = "Je vous l'ai rapporté, {name}. N'en faites pas toute une histoire."
L["Here, {name}. That's why I was following you. Honestly. I'll stop now."] = "Tenez, {name}. Voilà pourquoi je vous suivais. Vraiment. J'arrête, promis."
L["For you, {name}. Not everything that prowls was as well raised as I was."] = "Pour vous, {name}. Tout ce qui rôde n'a pas été aussi bien élevé que moi."
L["From a Gilnean of good family, {name}. The fur is new; the manners are old."] = "D'un Gilnéen de bonne famille, {name}. Le poil est neuf ; les manières, anciennes."
L["I thought of this in a dream, {name}. I was also chasing a rabbit. Here."] = "J'y ai pensé en rêve, {name}. Je chassais aussi un lapin. Tenez."
L["Liam would have cried 'For Gilneas!', {name}. I'll just say: for you."] = "Liam aurait crié « Pour Gilnéas ! », {name}. Moi, je dirai juste : pour vous."
L["Tal'doren's druids taught me to leash the beast, {name}. Now it fetches. Here."] = "Les druides de Tal'doren m'ont appris à dresser la bête, {name}. Elle rapporte. Tenez."
L["Be careful out there, {name}. Take it from someone who was bitten once."] = "Soyez prudent, {name}. Croyez-en quelqu'un qui s'est déjà fait mordre."
L["Here, {name}. I'd leave it on your doorstep, but that frightens people."] = "Tenez, {name}. Je l'aurais laissé sur votre paillasson, mais ça fait peur aux gens."
L["Take this, {name}. I'd offer my coat, but it's attached."] = "Tenez, {name}. Je vous prêterais mon manteau, mais il ne s'enlève pas."
L["Here, {name}. Chin up, hackles down. Words to live by."] = "Tenez, {name}. Tête haute, crocs rangés. Une belle devise."
L["The curse binds us, {name}, but Gilneas binds us tighter."] = "La malédiction nous lie, {name}, mais Gilnéas nous lie plus encore."
L["No need to explain the ears to you, {name}."] = "Pas besoin de vous expliquer les oreilles, {name}."
L["Fur, fog and rain, {name}. Only a Gilnean understands all three."] = "Fourrure, brouillard et pluie, {name}. Seul un Gilnéen comprend les trois."
L["Pack looks after pack, {name}. Always has."] = "La meute veille sur la meute, {name}. Depuis toujours."
L["Do you shed this badly too, {name}? Between us we could knit a third worgen."] = "Vous muez autant que moi, {name} ? À nous deux, on tricoterait un troisième worgen."
L["Two worgen, {name}. Somewhere, a cat's having a very bad day."] = "Deux worgens, {name}. Quelque part, un chat passe une très mauvaise journée."
L["Honestly, {name}, do you ever forget which form you left home in?"] = "Franchement, {name}, il vous arrive d'oublier sous quelle forme vous êtes sorti ?"
L["Gilnean to Gilnean, {name}: the finest-mannered wolves in all Azeroth."] = "Entre Gilnéens, {name} : les loups les mieux élevés de tout Azeroth."
L["Pack rules, {name}: nobody wanders off, and nobody mentions the fleas."] = "Règles de la meute, {name} : personne ne s'éloigne, et personne ne parle des puces."
L["A pack again, {name}. I hadn't known how much I'd missed one."] = "Une meute, de nouveau, {name}. Je ne savais pas à quel point ça m'avait manqué."
L["I'll catch the scent of trouble first, {name}. It's the one perk of the curse."] = "Je flairerai les ennuis avant tout le monde, {name}. Le seul avantage de la malédiction."
L["If I howl, {name}, it's a battle cry. Probably. Don't look at me like that."] = "Si je hurle, {name}, c'est un cri de guerre. Sans doute. Ne me regardez pas comme ça."
L["Lead on, {name}. I'll trot. It's undignified, but it's much quicker."] = "Passez devant, {name}. Je trottine. Pas très digne, mais bien plus rapide."
L["If I stop and stare at a wall, {name}, something's behind it. Or it's a wall."] = "Si je fixe un mur, {name}, c'est qu'il y a quelque chose derrière. Ou que c'est un mur."
L["Years on the Greymane Wall, {name}. Holding a line with you is a holiday."] = "Des années sur le mur de Grisetête, {name}. Tenir la ligne avec vous, c'est des vacances."
L["After this, {name}, a proper cup of tea. Before this, a proper mauling."] = "Après, {name}, une bonne tasse de thé. Avant, une bonne raclée."
L["If I limp back, {name}, I'll make big sad eyes. Don't fuss. I'm fine."] = "Si je boite au retour, {name}, j'aurai des yeux de chien battu. Ignorez. Ça va."
L["Short rest? I'll curl up, {name}, after three turns. The turns aren't optional."] = "Une pause ? Je me roule en boule, {name}, après trois tours. Les tours sont obligatoires."
L["Stay together, {name}. I was a lone wolf once. Dreadful pay, nobody talks."] = "Restons groupés, {name}. J'ai été loup solitaire. Mal payé, personne à qui parler."
L["Night again, {name}. I'm at my best and my worst. This is the best part."] = "Encore la nuit, {name}. Le meilleur et le pire de moi-même. Ceci, c'est le meilleur."
L["Look at that moon, {name}. Don't mind me; I'm not howling. Much."] = "Regardez cette lune, {name}. Ne faites pas attention, je ne hurle pas. Presque pas."
L["Gilneas at night was fog and footsteps, {name}. These days I'm the footsteps."] = "Gilnéas la nuit, c'était brouillard et bruits de pas, {name}. Désormais, les pas, c'est moi."
L["Curfew in Gilneas was sundown, {name}. For good reason, as it turned out."] = "À Gilnéas, le couvre-feu tombait au crépuscule, {name}. Et pour cause, finalement."
L["Something out there keeps rustling, {name}. I'm not going to look. I'm looking."] = "Quelque chose bruisse là-dehors, {name}. Je ne vais pas regarder. Je regarde."
L["Past dark, {name}: ears up, nose working, manners on. Two out of three will do."] = "La nuit, {name} : oreilles dressées, truffe en éveil, politesse. Deux sur trois, ça ira."
L["Morning, {name}. I'd have been up sooner, but the rug by the fire was so warm."] = "Bonjour, {name}. Le tapis près du feu était si chaud, j'ai eu du mal à le quitter."
L["Smells like rain this morning, {name}. Everything in Gilneas smelled like rain."] = "Ça sent la pluie ce matin, {name}. À Gilnéas, tout sentait la pluie."
L["Up already, {name}? I've chased two rabbits. For exercise. Purely."] = "Déjà debout, {name} ? J'ai chassé deux lapins. Pour l'exercice. Uniquement."
L["Morning, {name}. Tea, toast, a shave. The shave takes rather longer now."] = "Bonjour, {name}. Thé, toasts, rasage. Le rasage prend nettement plus longtemps."
L["Morning, {name}. The birds woke me, so I woke the birds. It seemed only fair."] = "Bonjour, {name}. Les oiseaux m'ont réveillé, je les ai réveillés. De bonne guerre."
L["Morning, {name}. The squirrels are taunting me. Quickly, before I'm distracted."] = "Bonjour, {name}. Les écureuils me narguent. Vite, avant que je sois distrait."
L["Throm-ka, {name}! Honour is repaid."] = "Throm-ka, {name} ! Je paie ma dette d'honneur."
L["You give freely, {name}. I return the favour."] = "Vous donnez sans compter, {name}. À mon tour."
L["Orcs keep their thanks short, {name}. Thanks."] = "Les orcs remercient en peu de mots, {name}. Merci."
L["Orcs return every blow twice, {name}. The kind ones too."] = "Les orcs rendent chaque coup deux fois, {name}. Même les coups de main."
L["You helped me, I help you. Orc poetry, {name}. It doesn't rhyme."] = "Vous m'aidez, je vous aide. Poésie orque, {name}. Ça ne rime pas."
L["In the old days I'd have repaid you with a boar, {name}. This keeps better."] = "Autrefois, je vous aurais remboursé avec un sanglier, {name}. Ceci se conserve mieux."
L["Owing somebody itches worse than Durotar sand, {name}. There. Itch gone."] = "Devoir quelque chose gratte plus que le sable de Durotar, {name}. Voilà. Ça ne gratte plus."
L["Strong stuff, {name}. I could wrestle a kodo now. So can you."] = "Du costaud, {name}. Je pourrais lutter contre un kodo, maintenant. Vous aussi."
L["Ambushed by kindness, {name}. No orc trains for that. Returned in full."] = "Une embuscade de gentillesse, {name}. Aucun orc n'y est préparé. Je riposte."
L["Honour is a debt, {name}. Orcs pay on the spot, before we forget what for."] = "L'honneur est une dette, {name}. Un orc paie sur-le-champ, avant d'oublier pourquoi."
L["An orc remembers a kindness like a scar, {name}: fondly, and for good."] = "Un orc garde un bienfait comme une cicatrice, {name} : avec tendresse, et à vie."
L["I'd give you my axe, {name}, but we're not that close yet. Take this."] = "Je vous donnerais bien ma hache, {name}, mais on n'est pas encore intimes. Prenez ça."
L["Thanks, {name}. My wolf growled at you. That's how he says it."] = "Merci, {name}. Mon loup a grogné contre vous. C'est sa façon de dire merci."
L["I've had gifts from shamans, chieftains and one lost kodo, {name}. Yours wins."] = "Des chamans, des chefs et un kodo perdu m'ont fait des cadeaux, {name}. Le vôtre gagne."
L["We once took strength from demons, {name}. Yours comes on far better terms."] = "Jadis, nous avons pris la force des démons, {name}. La vôtre coûte bien moins cher."
L["The spirits saw that, {name}. My shaman says they approve. Of you, anyway."] = "Les esprits ont vu ça, {name}. Mon chaman dit qu'ils approuvent. Vous, du moins."
L["I'll carve that on my axe handle, {name}. Next to the notches. Thank you."] = "Je graverai ça sur le manche de ma hache, {name}. À côté des encoches. Merci."
L["A kindness, {name}? Hm. My face is doing something. I think it's a smile."] = "Une gentillesse, {name} ? Hm. Mon visage fait quelque chose. Un sourire, je crois."
L["In my clan a gift gets a bigger one back, {name}. Don't make me escalate."] = "Dans mon clan, un cadeau appelle un plus gros, {name}. Ne me forcez pas à surenchérir."
L["Dabu, {name}. It is done."] = "Dabu, {name}. C'est fait."
L["Hold still, {name}. Strength for the fight ahead."] = "Ne bougez pas, {name}. De la force pour la bataille à venir."
L["Ask an orc for help and you get it, {name}. Ask for subtlety and you wait."] = "Demandez de l'aide à un orc, vous l'avez, {name}. Demandez de la subtilité, vous attendez."
L["Help, yes. Hugging, no. Hold still, {name}."] = "De l'aide, oui. Des câlins, non. Ne bougez pas, {name}."
L["You want {buff}? You have {buff}, {name}. Next."] = "Vous voulez {buff} ? Vous avez {buff}, {name}. Suivant."
L["Don't flinch, {name}. My helping face looks exactly like my fighting face."] = "Ne tressaillez pas, {name}. Quand j'aide, j'ai la même tête que quand je cogne."
L["Short question, short answer, {name}: yes."] = "Question courte, réponse courte, {name} : oui."
L["Work complete, {name}. I started out as a peon; the words never leave you."] = "Travail terminé, {name}. J'ai débuté comme péon ; ces mots-là ne vous lâchent jamais."
L["A challenge, {name}? Oh, a request. Close enough. I accept either way."] = "Un défi, {name} ? Ah, une demande. C'est pareil. J'accepte dans les deux cas."
L["Yes, {name}. I was sharpening my axe, but it'll keep. It always keeps."] = "Oui, {name}. J'affûtais ma hache, mais ça peut attendre. Ça attend toujours."
L["In the Valley of Honor this would cost you a duel, {name}. For you, a nod."] = "Dans la vallée de l'Honneur, ça coûte un duel, {name}. Pour vous : un signe de tête."
L["Now, {name}? Now. Orcs never learned the word 'later'."] = "Maintenant, {name} ? Maintenant. Les orcs ne connaissent pas « plus tard »."
L["One {buff}, {name}. Orc style: fast, direct, a bit too hard."] = "Voilà {buff}, {name}. À la mode orque : vite, direct, un peu trop fort."
L["Stand still, {name}. I aim this like a throwing axe, and I rarely miss."] = "Ne bougez pas, {name}. Je vise comme avec une hache de lancer, et je rate rarement."
L["Lok'tar, {name}. It means 'victory'. Today it also means 'yes'."] = "Lok'tar, {name}. Ça signifie « victoire ». Aujourd'hui, aussi « oui »."
L["Lok'tar ogar, {name}! Take this into battle. A tavern brawl also counts."] = "Lok'tar ogar, {name} ! Emportez ça au combat. Une bagarre de taverne, ça compte."
L["Blood and thunder, {name}! Go and earn your glory."] = "Sang et tonnerre, {name} ! Allez vous couvrir de gloire."
L["Among orcs, {name}, making you stronger is how we say we like you."] = "Chez les orcs, {name}, vous rendre plus fort, c'est dire qu'on vous aime bien."
L["An orc giving gifts unasked? Tell no one, {name}. It ruins the image."] = "Un orc qui offre sans qu'on demande ? N'en dites rien, {name}. Ça ruine l'image."
L["I was told to be more diplomatic, {name}. This is me being diplomatic."] = "On m'a dit d'être plus diplomate, {name}. Voilà. Ça, c'est de la diplomatie."
L["Go hit something for me, {name}. Or set it on fire. Orcs aren't fussy."] = "Frappez quelque chose pour moi, {name}. Ou brûlez-le. Les orcs ne sont pas difficiles."
L["Don't thank me, {name}. Just win, and do it loudly."] = "Ne me remerciez pas, {name}. Gagnez, c'est tout, et bruyamment."
L["I'd make a speech, {name}, but it's mostly shouting. Just take it."] = "Je ferais bien un discours, {name}, mais c'est surtout des cris. Prenez, c'est tout."
L["You looked like you needed an orc, {name}. Everybody does, sooner or later."] = "Vous aviez l'air d'avoir besoin d'un orc, {name}. Comme tout le monde, tôt ou tard."
L["'Strike first,' Grom always said, {name}. So: here, before you could ask."] = "« Frappe le premier », disait Grom, {name}. Alors tenez, avant que vous demandiez."
L["Take it, {name}. A grunt who walks past a comrade gets a talking-to. From me."] = "Prenez, {name}. Un grunt qui ignore un camarade se fait sermonner. Par moi."
L["Frostwolves share the hunt, {name}. I caught nothing today, so share this."] = "Les Loups-de-givre partagent la chasse, {name}. Bredouille aujourd'hui, je partage ça."
L["Walk the Durotar way, {name}: head up, sun on your neck, scorpid underfoot."] = "Marchez comme à Durotar, {name} : tête haute, soleil dans le cou, scorpide sous le pied."
L["Here, {name}. The spirits love generosity. My axe says nothing; it sulks."] = "Tenez, {name}. Les esprits aiment la générosité. Ma hache ne dit rien ; elle boude."
L["Orcs give two things freely, {name}: advice and this. Skip the advice."] = "Un orc offre deux choses, {name} : des conseils et ceci. Oubliez les conseils."
L["The Barrens don't end, {name}. They just get more zhevra. Take this."] = "Les Tarides ne finissent jamais, {name}. Il y a juste plus de zhévras. Prenez ça."
L["Strength for your arm, {name}. The honour, I see, you brought yourself."] = "De la force pour votre bras, {name}. L'honneur, je vois que vous l'avez apporté."
L["My wolf wanted you to have his bone, {name}. I talked him down to this."] = "Mon loup voulait vous donner son os, {name}. Je l'ai convaincu de vous offrir ça."
L["Throm-ka, {name}! The blood of the clans runs strong in you."] = "Throm-ka, {name} ! Le sang des clans bat fort dans vos veines."
L["An orc, {name}! Finally, somebody who shouts at my volume."] = "Un orc, {name} ! Enfin quelqu'un qui crie aussi fort que moi."
L["Frostwolf, Warsong or Blackrock, {name}, we all argue like family."] = "Loup-de-givre, Chanteguerre ou Rochenoire, {name}, on se dispute tous comme en famille."
L["Between orcs no words are needed, {name}. Good. I was out of them."] = "Entre orcs, pas besoin de mots, {name}. Tant mieux, je n'en ai plus."
L["Green skin or brown, {name}, it's the same stubborn blood."] = "Peau verte ou brune, {name}, c'est le même sang têtu."
L["Two orcs, {name}, and nobody's shouted yet. The shamans will call it an omen."] = "Deux orcs, {name}, et personne n'a encore crié. Les chamans y verront un présage."
L["Our clans probably feuded once, {name}. Everybody's did. Let's call it settled."] = "Nos clans se sont sûrement fait la guerre, {name}. Comme tous. Disons que c'est réglé."
L["Between orcs, {name}, 'victory or death' is just how we say 'see you later'."] = "Entre orcs, {name}, « la victoire ou la mort », ça veut juste dire « à plus tard »."
L["Your tusks and mine have seen worse days, {name}. This is a better one."] = "Vos défenses et les miennes ont vu pire, {name}. Aujourd'hui, c'est mieux."
L["The plan, {name}: we hit it. Questions? No? Good plan."] = "Le plan, {name} : on frappe. Des questions ? Non ? Bon plan."
L["A true warband, {name}. Loud, angry, and all on the same side for once."] = "Une vraie bande de guerre, {name}. Bruyante, en colère, et pour une fois, tous du même côté."
L["Stay with the warband, {name}. Strength in numbers. And in axes."] = "Restez avec la bande, {name}. La force est dans le nombre. Et dans les haches."
L["If you fall, {name}, I carry you out. Complaining the whole way, but I carry."] = "Si vous tombez, {name}, je vous porte dehors. En râlant tout du long, mais je vous porte."
L["Fight well, {name}, and tonight you share our fire. And our boasting."] = "Battez-vous bien, {name}, et ce soir, vous partagerez notre feu. Et nos vantardises."
L["Nobody runs, {name}. Walking briskly away is allowed. Barely."] = "Personne ne fuit, {name}. S'éloigner d'un pas vif est permis. De justesse."
L["I'll go first, {name}. I have the thickest skull here, and I'm proud of it."] = "Je passe devant, {name}. J'ai le crâne le plus épais ici, et j'en suis fier."
L["When the war drums start, {name}, charge. We have no drums. I'll hum."] = "Aux tambours de guerre, {name}, chargez. On n'a pas de tambours. Je fredonnerai."
L["Watch my back, {name}. The front I can see; that's the part I hit."] = "Surveillez mes arrières, {name}. L'avant, je le vois ; c'est là que je frappe."
L["One clan today, {name}: the Clan of Whoever Showed Up. Finest there is."] = "Un seul clan aujourd'hui, {name} : le clan de Ceux-qui-sont-venus. Le meilleur."
L["Anything big comes through that door, {name}, it's mine. Anything bigger, ours."] = "Si un gros passe cette porte, {name}, il est à moi. Un plus gros, à nous."
L["Scars are stories, {name}. Let's all come out of this with short ones."] = "Les cicatrices sont des histoires, {name}. Tâchons d'en sortir avec des courtes."
L["Old chieftains had war councils, {name}. We have me pointing at things."] = "Jadis, les chefs tenaient conseil de guerre, {name}. Nous, on a moi qui montre du doigt."
L["If I charge early, {name}, it isn't impatience. It's tradition."] = "Si je charge trop tôt, {name}, ce n'est pas de l'impatience. C'est la tradition."
L["Thank you, {name}. It would warm my heart, if it still beat."] = "Merci, {name}. Ça me réchaufferait le cœur, s'il battait encore."
L["Such warmth, for one so cold? Returned in full, {name}."] = "Tant de chaleur pour un être si froid ? Je vous la rends, {name}."
L["Thank you, {name}. I'd blush, but the blood stopped reaching my face."] = "Merci, {name}. Je rougirais bien, mais le sang n'arrive plus jusqu'à mon visage."
L["My undying gratitude, {name}. For once, the phrase is accurate."] = "Mon éternelle reconnaissance, {name}. Pour une fois, l'expression est exacte."
L["Most kind, {name}. You've lifted me from 'deceased' to 'mildly deceased'."] = "Trop aimable, {name}. Vous m'avez fait passer de « décédé » à « légèrement décédé »."
L["You've added years to my life, {name}. Shame it already ended."] = "Vous avez ajouté des années à ma vie, {name}. Dommage qu'elle soit déjà finie."
L["I felt that, {name}, and I don't feel much these days. Here, feel this."] = "J'ai senti ça, {name}, et je ne sens plus grand-chose. À vous de sentir ceci."
L["I'd shake your hand, {name}, but I'm not sure mine is still attached."] = "Je vous serrerais bien la main, {name}, mais la mienne ne tient plus très bien."
L["Thank you, {name}. I'd send a bat with a proper note, but they eat the notes."] = "Merci, {name}. Je vous enverrais un mot par chauve-souris, mais elles mangent les mots."
L["You've spoiled me, {name}. The pleasant kind of spoiled, for once."] = "Vous m'avez gâté, {name}. Pour une fois, ça ne veut pas dire pourri."
L["The last gift I got was the plague, {name}. Yours is a big improvement."] = "Mon dernier cadeau, c'était la peste, {name}. Le vôtre est bien mieux."
L["Thank you, {name}. Nothing this fresh has touched me since Lordaeron fell."] = "Merci, {name}. Rien d'aussi frais ne m'a touché depuis la chute de Lordaeron."
L["Sylvanas says we repay every debt, {name}. She rarely means the nice ones."] = "Sylvanas dit qu'on paie toutes nos dettes, {name}. Rarement les agréables."
L["My posture's improved, {name}. It's been slumping since the Third War. Thanks."] = "Je me tiens plus droit, {name}. Je m'affaissais depuis la Troisième Guerre. Merci."
L["Repaid at once, {name}. We Forsaken never carry debts. They rot."] = "Rendu aussitôt, {name}. Un Réprouvé ne garde pas ses dettes. Elles pourrissent."
L["Thank you, {name}. Unpaid debts in Undercity end up in the canal. Not yours."] = "Merci, {name}. À Fossoyeuse, les dettes impayées finissent dans le canal. Pas la vôtre."
L["Thank you, {name}. I'll keep this somewhere safe. My ribcage has room."] = "Merci, {name}. Je garde ça en lieu sûr. Ma cage thoracique a de la place."
L["Thank you, {name}. I'd bake you something, but everything I touch goes off."] = "Merci, {name}. Je vous ferais un gâteau, mais tout ce que je touche tourne au vinaigre."
L["I'll mention you to the Dark Lady, {name}. She won't care, but I will."] = "Je parlerai de vous à la Dame noire, {name}. Elle s'en moquera, mais pas moi."
L["Kindness returned, {name}. Even the flies around me look impressed."] = "Gentillesse rendue, {name}. Même mes mouches ont l'air impressionnées."
L["In all my years with the Scourge, nobody once said this, {name}. Thank you."] = "Pendant toutes mes années dans le Fléau, personne ne m'a dit ceci, {name} : merci."
L["I'll drink to you tonight, {name}. It all leaks out, but it's the thought."] = "Je boirai à votre santé ce soir, {name}. Tout fuit, mais c'est l'intention qui compte."
L["The Dark Lady says trust no gift, {name}. I'll risk it, and send one back."] = "La Dame noire se méfie des cadeaux, {name}. Moi, je prends le risque, et j'en rends un."
L["Thank you, {name}. You've made my list of reasons to keep going. It's short."] = "Merci, {name}. Vous voilà sur ma liste de raisons de continuer. Elle est courte."
L["Thank you, {name}. No contract, no fine print. Varimathras should take notes."] = "Merci, {name}. Ni contrat ni petites lignes. Varimathras devrait en prendre de la graine."
L["Grave dirt and gratitude, {name}: all I own. You'll prefer the gratitude."] = "Terre de tombe et gratitude, {name} : c'est tout ce que j'ai. Prenez la gratitude."
L["Thank you, {name}. Eternity drags; this was the best bit of the decade."] = "Merci, {name}. L'éternité, c'est long ; c'était le meilleur moment de la décennie."
L["Faranell would want notes on that reaction, {name}. I'll just return it."] = "Faranell voudrait étudier cette réaction, {name}. Moi, je vous la rends."
L["Thank you, {name}. Lordaeron had manners once. Glad somebody kept them."] = "Merci, {name}. Lordaeron avait des manières, jadis. Content que vous les ayez gardées."
L["The Deathguard would salute you, {name}, but it's hard on their arms. Thanks."] = "La Garde de la mort vous saluerait, {name}, mais leurs bras risquent de tomber. Merci."
L["I'd have Lordaeron's bells rung for you, {name}, but they only do funerals now."] = "Les cloches de Lordaeron sonneraient pour vous, {name}, mais elles ne sonnent plus que le glas."
L["Thank you, {name}. Next time I'm in Brill, I'll name a pumpkin after you."] = "Merci, {name}. À Brill, je donnerai votre nom à une citrouille."
L["Thank you, {name}. My afterlife had rather let itself go. You've tidied it up."] = "Merci, {name}. Mon au-delà se laissait aller. Vous y avez mis de l'ordre."
L["Certainly, {name}. Try not to die. It's overrated."] = "Certainement, {name}. Évitez de mourir. C'est surfait."
L["You need only ask, {name}. The dead are patient."] = "Vous n'avez qu'à demander, {name}. Les morts sont patients."
L["Ask the dead for a favour, {name}. We rarely have other plans."] = "Demandez un service aux morts, {name}. Nous avons rarement d'autres projets."
L["Certainly, {name}. Stand clear; I'd hate to drop anything on you."] = "Bien sûr, {name}. Écartez-vous ; je m'en voudrais de perdre un morceau sur vous."
L["A moment, {name}. Rigor mortis is hard on the casting hand."] = "Un instant, {name}. La rigidité cadavérique gêne l'incantation."
L["Nice to be asked for something, {name}, besides the way to the graveyard."] = "Ça fait plaisir qu'on me demande autre chose, {name}, que le chemin du cimetière."
L["Gladly, {name}. It takes my mind off the smell. Mine, I mean."] = "Volontiers, {name}. Ça me distrait de l'odeur. La mienne, je veux dire."
L["Certainly, {name}. Hold still. My aim drifts when my eye does."] = "Bien sûr, {name}. Ne bougez pas : je vise mal quand mon œil se balade."
L["In Undercity nobody says please, {name}. Mostly they gurgle. Here you are."] = "À Fossoyeuse, nul ne dit s'il vous plaît, {name}. On y gargouille. Tenez."
L["Just {buff}, {name}? The apothecaries always want a sample too."] = "Juste {buff}, {name} ? Les apothicaires prélèvent aussi un échantillon."
L["I always rise when called, {name}. Unfortunate history. Here you are."] = "Quand on m'appelle, je me relève, {name}. Fâcheux antécédent. Tenez."
L["Anything for you, {name}. Within reason, and what's left of mine."] = "Tout pour vous, {name}. Dans les limites de la raison, ou de ce qu'il en reste."
L["Of course, {name}. I'd say 'over my dead body', but that's been tried."] = "Bien sûr, {name}. « Plutôt mourir », dirais-je, mais c'est déjà fait."
L["Right away, {name}. The dead don't dawdle. We shamble with purpose."] = "Tout de suite, {name}. Les morts ne traînent pas : ils se traînent. Nuance."
L["Of course, {name}. Free will is a gift. I spend mine on things like this."] = "Bien sûr, {name}. Le libre arbitre est un don. Je dépense le mien ainsi."
L["Coming up, {name}. Quicker than a bat out of Undercity, and it doesn't bite."] = "Ça vient, {name}. Plus vif qu'une chauve-souris de Fossoyeuse, et moins mordant."
L["Of course, {name}. After a winter in the Plaguelands, this counts as a holiday."] = "Bien sûr, {name}. Après un hiver aux Maleterres, ça fait figure de vacances."
L["{buff}, {name}? Sorry, my good ear's in my other pocket."] = "{buff}, {name} ? Pardon, ma bonne oreille est dans mon autre poche."
L["Of course, {name}. No sleep, no meals, no plans. I'm extremely available."] = "Bien sûr, {name}. Ni sommeil, ni repas, ni projets : je suis très disponible."
L["I'm dying to help, {name}. Figure of speech. I've done the real one."] = "Je meurs d'envie de vous aider, {name}. Au figuré. Au propre, c'est déjà fait."
L["Stay among the living a little longer, {name}."] = "Restez encore un peu parmi les vivants, {name}."
L["Take this, {name}. The grave can wait."] = "Prenez ceci, {name}. La tombe attendra."
L["I was a physician in Lordaeron, {name}. Old habits die harder than I did."] = "J'étais médecin à Lordaeron, {name}. Les vieilles habitudes ont la vie plus dure que moi."
L["No charge, {name}. The apothecaries would have made you sign something."] = "Gratuit, {name}. Les apothicaires vous auraient fait signer quelque chose."
L["A gift from the grave, {name}. Don't worry, I washed it."] = "Un présent d'outre-tombe, {name}. Rassurez-vous, je l'ai lavé."
L["Every body needs a little help, {name}. Mine mostly needs stitches."] = "Tout le monde a besoin d'un coup de main, {name}. Moi, surtout de recoudre la mienne."
L["I've seen where heroes end up, {name}. I live there. Take this."] = "J'ai vu où finissent les héros, {name}. J'y habite. Prenez ceci."
L["Take this, {name}. I learned the hard way you can't take it with you."] = "Prenez ceci, {name}. J'ai appris à mes dépens qu'on ne l'emporte pas dans la tombe."
L["Take this, {name}. It's the only thing I own that isn't slightly damp."] = "Prenez ceci, {name}. Mon seul bien qui ne soit pas légèrement humide."
L["Hold on to yourself, {name}. Trust me, the pieces are hard to find later."] = "Restez entier, {name}. Croyez-moi, les morceaux sont durs à retrouver."
L["Take this, {name}. The Plaguelands are full of people who didn't."] = "Prenez ceci, {name}. Les Maleterres sont pleines de gens qui ont refusé."
L["A small kindness, {name}. My bat got the last one, and it never said thanks."] = "Une attention, {name}. La dernière est allée à ma chauve-souris. Pas un merci."
L["Tirisfal fog gets into everything, {name}. So does this, but pleasantly."] = "La brume de Tirisfal s'insinue partout, {name}. Ceci aussi, en plus agréable."
L["Here, {name}. I kept it cool for you. I keep everything cool. Can't help it."] = "Tenez, {name}. Gardé au frais. Chez moi, tout est au frais. Je n'y peux rien."
L["I've outlived everyone I knew, {name}. I'd rather not outlive you. Take this."] = "J'ai survécu à tous mes proches, {name}. Je préfère ne pas vous survivre. Tenez."
L["Pardon me, {name}. I'm told I lurk. I'm trying to lurk helpfully."] = "Pardon, {name}. On me dit que je rôde. J'essaie de rôder utilement."
L["Out of my own pocket, {name}. What's left of the pocket, anyway."] = "De ma poche, {name}. Enfin, de ce qu'il en reste."
L["I've already had the worst day there is, {name}. Let's spare you yours."] = "J'ai déjà vécu le pire jour qui soit, {name}. Épargnons-vous le vôtre."
L["Wind's off the Plaguelands, {name}. Take this, and breathe through your mouth."] = "Le vent vient des Maleterres, {name}. Prenez ceci, et respirez par la bouche."
L["The crows have been watching you, {name}. Let's disappoint them."] = "Les corbeaux vous observent, {name}. Décevons-les."
L["Here, {name}. Tirisfal grows nothing but pumpkins and grudges. This is neither."] = "Tenez, {name}. Tirisfal ne produit que citrouilles et rancœurs. Ceci fait exception."
L["Take this, {name}. The only thing in Undercity that needn't be boiled first."] = "Prenez ceci, {name}. Seule chose à Fossoyeuse qu'on n'a pas à faire bouillir."
L["Eternity is long, {name}, and I've spent a fair bit of it practising this."] = "L'éternité, c'est long, {name}, surtout vers la fin. J'ai eu le temps de m'exercer."
L["For the road, {name}. Undercity-made, so do keep it away from open flame."] = "Pour la route, {name}. Fabriqué à Fossoyeuse, alors tenez-le loin des flammes."
L["Take this, {name}. It's odourless, which I'm told makes it my best feature."] = "Prenez ceci, {name}. C'est inodore ; il paraît que c'est ce que j'ai de mieux."
L["Forsaken are famously patient, {name}. I just couldn't wait to give you this."] = "Les Réprouvés sont réputés patients, {name}. Mais ça, je n'ai pas pu attendre."
L["No strings attached, {name}. I cut mine when the Lich King lost his grip."] = "Aucune ficelle, {name}. J'ai coupé les miennes quand le roi-liche a lâché prise."
L["Fresh from Tirisfal, {name}. Well, fresh for Tirisfal."] = "Tout frais de Tirisfal, {name}. Enfin, frais pour Tirisfal."
L["Take this, {name}. I was saving it, but I'm bad at keeping things. Look at me."] = "Prenez ceci, {name}. Je le gardais, mais je conserve mal. Moi le premier."
L["We Forsaken must look after each other, {name}."] = "Nous, Réprouvés, devons nous serrer les coudes, {name}."
L["Between us corpses, {name}, you're remarkably well preserved."] = "Entre cadavres, {name}, vous êtes remarquablement bien conservé."
L["Lose a finger, {name}, and I've a spare. Forsaken share."] = "Un doigt en moins, {name} ? J'en ai un en rab. Les Réprouvés partagent."
L["Is your jaw clicking too, {name}, or is that just me?"] = "Votre mâchoire claque aussi, {name}, ou c'est juste moi ?"
L["Victory for Sylvanas, {name}. A small one this time, but it's ours."] = "Victoire pour Sylvanas, {name}. Une petite, cette fois, mais elle est à nous."
L["Brill or Deathknell, {name}? We all woke up somewhere. I got the damp crypt."] = "Brill ou le Glas, {name} ? On s'est tous réveillés quelque part. Moi, crypte humide."
L["When the Scourge comes calling, {name}, we won't be home. Not ever again."] = "Si le Fléau sonne à la porte, {name}, nous n'y serons pas. Plus jamais."
L["The Bulwark still holds, {name}, and so do we. Held together, but holding."] = "Le Rempart tient toujours, {name}, et nous aussi. Rafistolés, mais debout."
L["Lordaeron raised us twice, {name}: once as children, once as Forsaken."] = "Lordaeron nous a élevés, {name}, puis relevés. Enfants, puis Réprouvés."
L["Somewhere in Northrend, {name}, the Lich King is sulking about us. Good."] = "Quelque part en Norfendre, {name}, le roi-liche nous boude. Tant mieux."
L["The Dark Lady needs us whole, {name}. Near enough will do."] = "La Dame noire nous veut entiers, {name}. À peu près, ça ira."
L["You smell of Tirisfal, {name}. From one of us, that's a compliment."] = "Vous sentez le Tirisfal, {name}. Entre nous, c'est un compliment."
L["We've both got forever, {name}. Let's not spend it all waiting for the lift."] = "Nous avons l'éternité, {name}. Ne la passons pas à attendre l'ascenseur."
L["One Forsaken to another, {name}: the sewer shortcut is not a shortcut."] = "Entre Réprouvés, {name} : le raccourci par les égouts n'en est pas un."
L["If the Deathguard ask, {name}, we're on patrol. A very, very slow patrol."] = "Si la Garde de la mort demande, {name}, on est en patrouille. Très, très lente."
L["Our kind don't get many kindnesses, {name}. Let's keep them in the family."] = "Les nôtres reçoivent peu de gentillesses, {name}. Gardons-les en famille."
L["The bats in the Trade Quarter know us both by now, {name}. That's fame, nearly."] = "Les chauves-souris de Fossoyeuse nous connaissent, {name}. C'est presque la gloire."
L["Keep the faith, {name}. In each other, I mean. It answers more often."] = "Gardez la foi, {name}. En nous, j'entends. Nous répondons plus souvent."
L["The dead look after the dead, {name}. The living could learn a thing or two."] = "Les morts veillent sur les morts, {name}. Les vivants ont des leçons à prendre."
L["We've both seen the inside of a grave, {name}. Dreadful service. No view."] = "On a tous deux connu la tombe, {name}. Service déplorable. Aucune vue."
L["Stay alive, {name}. Undercity's housing list is already very long."] = "Restez en vie, {name}. Fossoyeuse affiche déjà complet."
L["If I fall down, {name}, give it a minute. Old habit."] = "Si je tombe, {name}, laissez-moi une minute. Vieille habitude."
L["I'll take the front, {name}. What's the worst that could happen? Again?"] = "Je passe devant, {name}. Au pire, quoi ? Je meurs ? Encore ?"
L["Keep upwind of me, {name}. It's better for morale."] = "Restez du bon côté du vent, {name}. C'est meilleur pour le moral."
L["The last party I joined, {name}, I woke up in a crypt. Let's improve on that."] = "Mon dernier groupe, {name} ? Réveil dans une crypte. Faisons mieux."
L["Anything that bites, {name}, point it at me. There's nothing left worth eating."] = "Tout ce qui mord, {name}, envoyez-le-moi. Il n'y a plus rien à manger."
L["Spare the heals for the others, {name}. I run on spite and embalming fluid."] = "Gardez les soins pour les autres, {name}. Je carbure à la rancune et au formol."
L["If this goes badly, {name}, don't worry. I know the way back. Intimately."] = "Si ça tourne mal, {name}, je connais le chemin du retour. Intimement."
L["I've fought the Scourge from both sides, {name}. This side's better company."] = "J'ai connu le Fléau des deux côtés, {name}. Celui-ci est mieux fréquenté."
L["Stay close, {name}. I'm the one who won't scream at the ghouls. Old neighbours."] = "Restez près de moi, {name}. Je ne crierai pas devant les goules. D'anciens voisins."
L["I've walked the Plaguelands at night, {name}. This is a stroll by comparison."] = "J'ai arpenté les Maleterres de nuit, {name}. Ici, c'est une promenade de santé."
L["The corpse at the back is me, {name}. Please don't loot it."] = "Le cadavre au fond, c'est moi, {name}. Ne dépouillez pas ma dépouille."
L["Stay together, {name}. It's easier than putting somebody back together."] = "Restez groupés, {name}. C'est plus simple que de recoller quelqu'un."
L["Don't wait for me, {name}. I shamble, but I shamble forever. I'll catch up."] = "Ne m'attendez pas, {name}. Je me traîne, mais pour l'éternité. Je vous rattraperai."
L["Keep the torches clear of me, {name}. I'm old, dry and very flammable."] = "Éloignez les torches de moi, {name}. Je suis vieux, sec et très inflammable."
L["Don't check me for a pulse after, {name}. It only worries people."] = "Ne prenez pas mon pouls après, {name}. Ça inquiète toujours les gens."
L["Mind the green puddles, {name}. I've seen what they do. I'm what they do."] = "Attention aux flaques vertes, {name}. J'ai vu ce qu'elles font. C'est moi."
L["Send anything scary to me, {name}. I've been dead; it's got nothing."] = "Envoyez-moi ce qui fait peur, {name}. J'ai été mort ; ça ne fait pas le poids."
L["Stick together, {name}. The apothecaries pay well for strays."] = "Ne vous éloignez pas, {name}. Les apothicaires paient bien les égarés."
L["If this ends underwater, {name}, don't mind me. Breathing's optional now."] = "Si ça finit sous l'eau, {name}, pas de souci pour moi : respirer est facultatif."
L["The Dark Lady trusts no one, {name}. I've made an exception for this party."] = "La Dame noire ne se fie à personne, {name}. Pour ce groupe, je fais une exception."
L["When we win, {name}, drinks at the Gallows' End in Brill. My treat. Your risk."] = "Si on gagne, {name}, verre à la taverne de Brill. Je régale. À vos risques et périls."
L["Don't mind the bats, {name}. They follow me everywhere. They think I'm a cave."] = "Les chauves-souris me suivent partout, {name}. Elles me prennent pour une grotte."
L["I'll watch the rear, {name}. Nothing sneaks up on someone who can't blink."] = "Je surveille nos arrières, {name}. On ne surprend pas qui ne cligne plus des yeux."
L["Any blood on the floor after, {name}, it isn't mine. I stopped carrying any."] = "Du sang par terre après, {name} ? Pas le mien. Je n'en ai plus sur moi."
L["The dead keep terrible hours, {name}. Nice to have company for once."] = "Les morts ont des horaires affreux, {name}. Pour une fois, j'ai de la compagnie."
L["Midnight, {name}: the best hour to be up and about when you shouldn't be."] = "Minuit, {name} : la meilleure heure pour être debout quand on ne devrait pas l'être."
L["The living are all asleep, {name}. We Forsaken call this the quiet shift."] = "Les vivants dorment tous, {name}. Chez les Réprouvés, on appelle ça la garde tranquille."
L["Late, {name}? In Undercity, this is lunchtime."] = "Tard, {name} ? À Fossoyeuse, c'est l'heure du déjeuner."
L["This is the hour the Scourge used to walk, {name}. Now it's ours."] = "À cette heure-ci, le Fléau rôdait, {name}. Désormais, elle est à nous."
L["Night, {name}. The one time nobody can tell I'm pale."] = "Nuit noire, {name}. Enfin, personne ne remarque ma pâleur."
L["Dark as the Undercity, {name}. Finally, some proper lighting."] = "Noir comme à Fossoyeuse, {name}. Enfin un éclairage correct."
L["Fog, moonlight and a hint of mildew, {name}. Proper Tirisfal weather."] = "Brume, clair de lune et un soupçon de moisi, {name}. Un vrai temps de Tirisfal."
L["The banshees start singing about now, {name}. Relax. They're only practising."] = "C'est l'heure où les banshees chantent, {name}. Du calme : elles répètent."
L["Stars over Tirisfal, {name}. The one thing up there that never rotted."] = "Étoiles sur Tirisfal, {name}. Seule chose là-haut qui n'ait jamais pourri."
L["Past midnight, {name}. The graveyards are quiet. The good ones, anyway."] = "Minuit passé, {name}. Les cimetières sont calmes. Les bons, du moins."
L["An owl just saw me and left, {name}. They're sensible birds."] = "Un hibou m'a vu et a filé, {name}. C'est un oiseau sage."
L["Morning already, {name}? I've been up all night. And all of last decade."] = "Déjà le matin, {name} ? J'ai veillé toute la nuit. Et toute la dernière décennie."
L["The sun's up, {name}. I'll stand in the shade, if you don't mind. Things peel."] = "Le soleil est levé, {name}. Je vais rester à l'ombre, si ça ne vous dérange pas. Ça pèle."
L["Early start, {name}. The dead never sleep in. Or at all, really."] = "Debout tôt, {name}. Les morts ne dorment jamais tard. Ni tôt, d'ailleurs."
L["Sunrise, {name}. My least favourite colour. I'm off to find some shade."] = "Lever du soleil, {name}. Ma pire couleur. Je cours me mettre à l'ombre."
L["Dawn over Tirisfal, {name}: grey, then slightly less grey. Glorious."] = "L'aube sur Tirisfal, {name} : gris, puis un peu moins gris. Splendide."
L["Morning, {name}. The Gallows' End porridge moved again. Have this instead."] = "Bonjour, {name}. La bouillie de la taverne a encore bougé. Prenez plutôt ceci."
L["The roosters in Brill still crow, {name}. Nobody's had the heart to tell them."] = "Les coqs de Brill chantent encore, {name}. Personne n'a eu le cœur de les prévenir."
L["Morning, {name}. The Deathguard change shifts now. They just turn round."] = "Bonjour, {name}. Relève de la Garde de la mort : ils font demi-tour, c'est tout."
L["Take the lift slowly, {name}. The last man who rushed it is still coming down."] = "Prenez l'ascenseur sans hâte, {name}. Le dernier pressé descend encore."
L["Undercity has it all, {name}: a bank, an inn, and opinions in the sewers."] = "Fossoyeuse a tout, {name} : banque, auberge, et des égouts qui ont un avis."
L["Even the rats bow to the Dark Lady here, {name}. Take this before one asks."] = "Même les rats saluent la Dame noire ici, {name}. Vite, avant qu'un rat ne le réclame."
L["Mind the canal, {name}. It's green for a reason, and the reason isn't moss."] = "Attention au canal, {name}. Il est vert pour une raison, et ce n'est pas la mousse."
L["Undercity's lovely this time of year, {name}. It's always this time of year."] = "Fossoyeuse est charmante en cette saison, {name}. C'est toujours cette saison."
L["We moved into Lordaeron's cellar, {name}, and kept the good silver."] = "On a pris la cave de Lordaeron, {name}, et gardé la belle argenterie."
L["The Royal Quarter's that way, {name}. Bow low; the banshees keep score."] = "Le quartier royal est par là, {name}. Inclinez-vous bien : les banshees notent."
L["The bat handler swears they're friendly, {name}. Take this before you test it."] = "Le maître des chauves-souris les jure dociles, {name}. Prenez ceci avant de vérifier."
L["Magic Quarter's that way, {name}. The glowing puddles aren't for drinking."] = "Quartier de la Magie par là, {name}. Les flaques qui luisent ne se boivent pas."
L["The throne room's just upstairs, {name}. Nobody sits in it. Bad memories."] = "La salle du trône est là-haut, {name}. Le trône reste vide. Mauvais souvenirs."
L["Most folk greet a Forsaken with holy water, {name}. You're a welcome change."] = "La plupart accueillent un Réprouvé à l'eau bénite, {name}. Vous changez agréablement."
L["Few stop for a Forsaken, {name}. You did, and I noticed. Thank you."] = "Peu s'arrêtent pour un Réprouvé, {name}. Vous, si, et je l'ai remarqué. Merci."
L["Contrary to rumour, {name}, not everything a Forsaken hands out is a plague."] = "Contrairement à la rumeur, {name}, un Réprouvé ne distribue pas que la peste."
L["Forsaken can't be charmed, {name}, they say. Asking nicely works, though."] = "On dit qu'on ne charme pas un Réprouvé, {name}. La politesse, en revanche, ça marche."
L["Take this instead of small talk, {name}. Mine tends to unsettle people."] = "Prenez ceci au lieu d'un brin de causette, {name}. La mienne met mal à l'aise."
L["They say the Forsaken have no friends, {name}. I'm recruiting."] = "On dit que les Réprouvés n'ont pas d'amis, {name}. Je recrute."
L["Take this, {name}. If anyone asks, the Forsaken were perfectly charming."] = "Prenez ceci, {name}. Si on demande, les Réprouvés ont été parfaitement charmants."
L["Stay alive, {name}. I've tried the alternative, and I can't recommend it."] = "Restez en vie, {name}. J'ai essayé l'alternative, je ne la recommande pas."
L["The Earth Mother saw your kindness, {name}. She nudged me. Quite hard."] = "La Terre-Mère a vu votre bonté, {name}. Elle m'a donné un coup de coude. Plutôt fort."
L["Thank you, {name}. May the winds guide you."] = "Merci, {name}. Que les vents vous guident."
L["Thank you, {name}. I'm deeply moved, and it takes a lot to move a tauren."] = "Merci, {name}. Ça m'ébranle, et il en faut beaucoup pour ébranler un tauren."
L["It's a long way up to a tauren's heart, {name}. You found it."] = "Le chemin est long jusqu'au cœur d'un tauren, {name}. Vous l'avez trouvé."
L["I felt that from horn to hoof, {name}. Returned, hoof to horn."] = "Senti des cornes aux sabots, {name}. Rendu des sabots aux cornes."
L["A gift given is a seed planted, {name}. Here is the harvest."] = "Un don est une graine semée, {name}. Voici la récolte."
L["That deserves a feast, {name}. The feast can wait; {buff} can't."] = "Ça mérite un festin, {name}. Le festin peut attendre ; {buff}, non."
L["Thank you, {name}. Should you ever need a wall to hide behind, I'm free."] = "Merci, {name}. S'il vous faut un jour un mur pour vous abriter, je suis libre."
L["I'd dance for joy, {name}, but last time Bloodhoof lost a roof. This instead."] = "Je danserais de joie, {name}, mais Sabot-de-Sang y a perdu un toit. Plutôt ceci."
L["Returned faster than a wind rider, {name}, and with much less screeching."] = "Rendu plus vite qu'un coursier du vent, {name}, et avec beaucoup moins de cris."
L["Returned, {name}. The quilboar never learned to give back, and look at them."] = "Je vous le rends, {name}. Les hurans n'ont jamais appris à rendre. Voyez où ils en sont."
L["Thank you, {name}. My ancestors are all nodding. It's a great deal of nodding."] = "Merci, {name}. Tous mes ancêtres hochent la tête. Ça fait beaucoup de hochements."
L["In Mulgore we return a gift before the grass under it grows back, {name}."] = "À Mulgore, on rend un don avant que l'herbe dessous ait repoussé, {name}."
L["Thank you, {name}. I'll name my next kodo calf after you. They're lovely."] = "Merci, {name}. Mon prochain petit kodo portera votre nom. Ils sont adorables."
L["Kindness is rarer than shade in the Barrens, {name}. Here's some back."] = "La bonté est plus rare que l'ombre dans les Tarides, {name}. En voici en retour."
L["I'll carve this on a totem, {name}. Tauren carve slowly; expect it by spring."] = "Je graverai ça sur un totem, {name}. Lentement : ce sera prêt au printemps."
L["Folk give directions by me, {name}: 'left at the tauren.' You gave me a gift."] = "On me prend pour repère, {name} : « à gauche au tauren ». Vous, vous m'offrez un cadeau."
L["Cairne taught us to honour every kindness, {name}. I'd been hoping for one."] = "Cairne nous a appris à honorer chaque bonté, {name}. J'en espérais justement une."
L["Of course, {name}. Stand tall and be at peace. I'll handle the tall part."] = "Bien sûr, {name}. Tenez-vous droit et soyez en paix. La hauteur, je m'en charge."
L["Ask and it is given, {name}. The herd shares what it has."] = "Demandez et vous recevrez, {name}. Le troupeau partage ce qu'il a."
L["Of course, {name}. Stand back a pace; I do this with my whole body."] = "Bien sûr, {name}. Reculez d'un pas ; je fais ça avec tout mon corps."
L["Gladly, {name}. Mind the tail."] = "Volontiers, {name}. Gare à la queue."
L["The Earth Mother gives freely, {name}, and so do her largest children."] = "La Terre-Mère donne sans compter, {name}, et ses plus grands enfants aussi."
L["Gladly, {name}. Tauren are slow to anger and quick to help. Quick-ish."] = "Avec plaisir, {name}. Les taurens sont lents à la colère, prompts à aider. Enfin, prompts..."
L["Refuse you, {name}? My ancestors would never let me hear the end of it."] = "Vous refuser, {name} ? Mes ancêtres me le reprocheraient pour l'éternité."
L["Of course, {name}. A tauren says yes the way the plains grow grass: easily."] = "Bien sûr, {name}. Chez un tauren, le oui pousse comme l'herbe des plaines."
L["Of course, {name}. One moment; my hands are big and the spell is small."] = "Bien sûr, {name}. Un instant ; j'ai de grosses mains et le sort est petit."
L["After a season herding kodo, {name}, a polite request is a holiday. Here."] = "Après une saison de kodos, {name}, une demande polie, c'est les vacances. Tenez."
L["The Earth Mother says share, {name}. My stomach says lunch. She outranks it."] = "La Terre-Mère dit partager, {name}. Mon ventre dit manger. Elle a le dernier mot."
L["Of course, {name}. You get the help and a tauren proverb. Proverb: hold still."] = "Bien sûr, {name}. L'aide, plus un proverbe tauren. Proverbe : ne bougez pas."
L["Spirits of the plains, lend me a hand. ...Ah, I have two. Here, {name}."] = "Esprits des plaines, prêtez-moi une main. ...Ah, j'en ai deux. Tenez, {name}."
L["Magatha would want a favour for it, {name}. Baine would just say yes. So: yes."] = "Magatha voudrait une faveur en échange, {name}. Baine dirait oui. Donc : oui."
L["Hold still, {name}. I've practised on kodo, and they're far less polite."] = "Ne bougez pas, {name}. Je me suis exercé sur des kodos. Bien moins polis."
L["Of course, {name}. A shu'halo never refuses a traveller. Or a second helping."] = "Bien sûr, {name}. Un shu'halo ne refuse jamais un voyageur. Ni une seconde part."
L["Walk with the Earth Mother, {name}. She's everywhere, so you can't get lost."] = "Marchez avec la Terre-Mère, {name}. Elle est partout, alors impossible de vous perdre."
L["May An'she light your path, {name}."] = "Qu'An'she illumine votre chemin, {name}."
L["You looked like you could use a friend, {name}. I'm a very big one."] = "Vous aviez l'air d'avoir besoin d'une épaule, {name}. J'en ai deux, très larges."
L["Take this, {name}. The Earth Mother would scold me if I walked past."] = "Prenez ceci, {name}. La Terre-Mère me gronderait si je passais sans m'arrêter."
L["Tread lightly, {name}. Take it from someone who never has."] = "Marchez d'un pas léger, {name}. Parole de quelqu'un qui n'a jamais su."
L["The wind said you'd pass this way, {name}. The wind is a terrible gossip."] = "Le vent m'a dit que vous passeriez par là, {name}. Le vent est une vraie commère."
L["Take this, {name}. I'd lend you my kodo too, but he's less generous than me."] = "Prenez ceci, {name}. Je vous prêterais bien mon kodo, mais il est moins généreux que moi."
L["The shu'halo say carry what you can for others, {name}. I can carry a lot."] = "Les shu'halo disent de porter ce qu'on peut pour les autres, {name}. Je peux porter beaucoup."
L["Take this, {name}. If the centaur trouble you, say Thunder Bluff sends regards."] = "Tenez, {name}. Aux centaures gênants : bons baisers des Pitons-du-Tonnerre."
L["Here, {name}. Plainstriders run from me for no reason at all. You needn't."] = "Tenez, {name}. Les trotteurs des plaines me fuient, allez savoir pourquoi. Pas vous."
L["For you, {name}. Visit Mulgore sometime. The grass is soft and nobody hurries."] = "Pour vous, {name}. Venez à Mulgore un jour. L'herbe est douce et personne ne se presse."
L["Here, {name}. Grandmother blessed travellers and fed them. I'm out of bread."] = "Tenez, {name}. Grand-mère bénissait et nourrissait les voyageurs. Je n'ai plus de pain."
L["The spirits asked me to mind you, {name}. I said yes before they'd finished."] = "Les esprits m'ont confié votre garde, {name}. J'ai dit oui avant qu'ils finissent."
L["Here, {name}. Better a gift than a war stomp. Both leave an impression."] = "Tenez, {name}. Mieux vaut un cadeau qu'un Choc martial. Les deux marquent."
L["Here, {name}. Tauren leave the world a little better, and a little trampled."] = "Tenez, {name}. Les taurens laissent le monde un peu meilleur, et un peu piétiné."
L["You look weary, {name}. The Earth Mother would offer a nap. I offer this."] = "Vous semblez las, {name}. La Terre-Mère vous offrirait une sieste. Moi, ceci."
L["Sunwalkers call it a blessing, hunters luck, {name}. Tauren call it manners."] = "Les Marche-soleil disent bénédiction, les chasseurs chance, {name}. Nous, politesse."
L["Take this, {name}. If a harpy screeches at you, screech back. They hate that."] = "Tenez, {name}. Si une harpie vous hurle dessus, hurlez en retour. Elles détestent."
L["Here, {name}. A tauren blessing: sturdy, slow to fade, smells faintly of sage."] = "Tenez, {name}. Une bénédiction tauren : solide, tenace, avec un léger parfum de sauge."
L["The Earth Mother watches over us both, {name}."] = "La Terre-Mère veille sur nous deux, {name}."
L["Somebody warn the doorframes, {name}. There are two of us now."] = "Prévenez les chambranles, {name}. Nous sommes deux, maintenant."
L["Plains or peaks, {name}, a shu'halo heart is a big one."] = "Plaines ou sommets, {name}, un cœur shu'halo est un grand cœur."
L["Horns and helmets, {name}. Only another tauren knows the pain."] = "Cornes et casques, {name}. Seul un autre tauren connaît la douleur."
L["Rain on fur takes a week to dry, {name}. Only another tauren ever believes me."] = "Une fourrure mouillée met une semaine à sécher, {name}. Seul un tauren me croit."
L["Between tauren, {name}: Thunder Bluff's lifts were built by somebody smaller."] = "Entre taurens, {name} : les ascenseurs des Pitons-du-Tonnerre ? Conçus pour plus petit."
L["Our ancestors watch us both, {name}. Let's give them something nice to see."] = "Nos ancêtres nous regardent tous deux, {name}. Offrons-leur un beau spectacle."
L["From Mulgore to Highmountain, {name}, the herd always finds itself."] = "De Mulgore à Haut-Roc, {name}, le troupeau se retrouve toujours."
L["Get behind me, {name}. There's room back there for the whole party."] = "Mettez-vous derrière moi, {name}. Il y a de la place pour tout le groupe."
L["The herd moves together, {name}. Mind my hooves; the herd has learned to."] = "Le troupeau avance ensemble, {name}. Attention à mes sabots ; le troupeau a appris."
L["Low ceilings ahead, {name}? I'll be the first to find out. Take this."] = "Des plafonds bas en vue, {name} ? C'est moi qui le saurai en premier. Prenez ceci."
L["I'm slow to anger, {name}, but I hold a grudge for the whole party."] = "La colère me vient lentement, {name}, mais ma rancune couvre tout le groupe."
L["Need a wall to hide behind, {name}? I'm most of one. Come on."] = "Besoin d'un mur pour vous cacher, {name} ? J'en suis presque un. Venez."
L["When I war stomp, {name}, everybody sit down. It saves you falling over."] = "Quand je lance Choc martial, {name}, asseyez-vous. Ça vous évite de tomber."
L["Everyone fed? Everyone blessed? Good, {name}. Tauren never lead a hungry herd."] = "Tous nourris ? Tous bénis ? Bien, {name}. Un tauren ne mène pas un troupeau affamé."
L["Tauren don't swim, {name}, we wade. If it's deep, you're riding on me."] = "Un tauren ne nage pas, {name}, il patauge. Si c'est profond, grimpez sur moi."
L["Stay close, {name}. My ancestors walk with us. They're quieter than you lot."] = "Restez groupés, {name}. Mes ancêtres marchent avec nous. En silence, eux."
L["If I fall, {name}, don't try to carry me. Drag me. Fondly."] = "Si je tombe, {name}, ne me portez pas. Traînez-moi. Tendrement."
L["We move like a stampede, {name}: all together, and sorry about the flowers."] = "On avance comme une cavalcade, {name} : tous ensemble, et pardon aux fleurs."
L["Nobody walks alone at the rear, {name}. That's where I'll be, looming kindly."] = "Personne ne ferme la marche seul, {name}. J'y serai, bienveillant de toute ma hauteur."
L["Tell me when to charge, {name}. Tauren are slow to start, and slower to stop."] = "Dites-moi quand charger, {name}. Un tauren est lent à démarrer, et plus lent à s'arrêter."
L["Nobody wander, {name}. The last party that did in the Barrens is still walking."] = "Ne vous égarez pas, {name}. Le dernier groupe égaré dans les Tarides marche encore."
L["An'she rises, {name}, and so do we. Slower, in my case."] = "An'she se lève, {name}, et nous aussi. Plus lentement, dans mon cas."
L["The sun is An'she's eye, {name}. He's watching, so let's look busy."] = "Le soleil est l'œil d'An'she, {name}. Il nous regarde, alors ayons l'air occupés."
L["Morning, {name}. The kodo are up, the grass is wet, and this is yours."] = "Bonjour, {name}. Les kodos sont levés, l'herbe est mouillée, et ceci est pour vous."
L["Morning, {name}. I've greeted the sun, the wind and two plainstriders. Now you."] = "Bonjour, {name}. J'ai salué le soleil, le vent et deux trotteurs des plaines. À vous."
L["Morning, {name}. Dew on the grass, dew on my fur. I'll be damp till noon."] = "Bonjour, {name}. Rosée sur l'herbe, rosée sur ma fourrure. Humide jusqu'à midi."
L["Early, {name}. That mist over Mulgore at dawn? Mostly kodo breath."] = "Tôt, {name}. La brume de Mulgore à l'aube ? Surtout de l'haleine de kodo."
L["Mu'sha keeps the night watch, {name}. I'll tell her to keep an eye on you."] = "Mu'sha monte la garde la nuit, {name}. Je lui dirai de garder un œil sur vous."
L["The moon's out, {name}. Mu'sha sees you, and she approves. I asked."] = "La lune est sortie, {name}. Mu'sha vous voit, et elle approuve. J'ai demandé."
L["Late, {name}. The kodo are asleep, and they snore like thunder. Take this."] = "Il est tard, {name}. Les kodos dorment et ronflent comme le tonnerre. Prenez ceci."
L["Stars out, {name}. Each one's an ancestor, they say. That one's winking at you."] = "Étoiles au ciel, {name}. Chacune est un ancêtre, dit-on. Celle-ci vous fait de l'œil."
L["Late, {name}. Mulgore is so quiet at night you can hear the grass argue."] = "Il est tard, {name}. Mulgore est si calme la nuit qu'on entend l'herbe se disputer."
L["Quiet now, {name}. At this hour, even my hooves try to tiptoe."] = "Chut, {name}. À cette heure, même mes sabots vont sur la pointe des pieds."
L["Ya be too kind, {name}! Dis one be from me."] = "Trop gentil, {name} ! Et çui-là, il vient d'moi."
L["Thanks, mon! Da spirits smile on ya, {name}."] = "Merci, l'ami ! Les esprits, ils vous sourient, {name}."
L["Ya gave me good mojo, {name}. Now ya get some back, extra spicy."] = "Vous m'avez donné du bon mojo, {name}. Maint'nant, vous en r'cevez, extra épicé."
L["Bwonsamdi gonna be real disappointed, {name}. Thanks, mon."] = "Bwonsamdi, il va être bien déçu, {name}. Merci, l'ami."
L["Dat be some fine work, {name}. Almost as fine as me. Almost."] = "Du beau travail, ça, {name}. Presque aussi beau qu'moi. Presque."
L["A troll can grow back a hand, {name}. Can't grow back honour. Here."] = "Un troll, ça fait repousser une main, {name}. Pas l'honneur. Tenez."
L["Ya just made a troll smile, {name}, and we got a lot of teeth."] = "Vous v'nez d'faire sourire un troll, {name}, et on a beaucoup d'dents."
L["Da loa keep a tally, {name}, and now ya on da good side of it."] = "Les loa, ils tiennent les comptes, {name}, et maint'nant, vous êtes du bon côté."
L["Ya beat me to it, {name}! Darkspear hate bein' second. Now we even."] = "Devancé, {name} ! Un Sombrelance, ça déteste être second. On est quittes."
L["I owe ya now, {name}, and trolls only like owin' da loa. Settled."] = "J'vous dois, {name}, et un troll, ça aime devoir qu'aux loa. Voilà, réglé."
L["I be tellin' da whole Echo Isles 'bout ya, {name}. All dey talk 'bout is crabs."] = "J'vais parler d'vous à toutes les îles de l'Écho, {name}. Là-bas, on parle que d'crabes."
L["My hair just stood up taller, {name}. Didn't know it could. Thanks, mon."] = "Mes ch'veux, ils s'dressent encore plus haut, {name}. J'savais pas. Merci, l'ami."
L["Da spirits say 'give it back', {name}. Da spirits nag, but dey right."] = "Les esprits disent « rends-le », {name}. Ça rouspète, mais ça a raison."
L["Mojo for mojo, {name}: oldest trade in da jungle. Second oldest be bananas."] = "Mojo contre mojo, {name} : l'plus vieux troc d'la jungle. Juste avant les bananes."
L["Vol'jin said repay kindness quick, {name}. He said a lot. Dat one stuck."] = "Vol'jin disait d'rendre vite les bontés, {name}. Il disait beaucoup. Ça, c'est resté."
L["Dat deserve a dance, {name}. Lucky ya, ya get {buff} instead."] = "Ça mérite une danse, {name}. Coup d'chance, ce s'ra {buff} à la place."
L["Jungle rule, {name}: what ya give come back, usually wit' teeth. Dis one don't."] = "Loi d'la jungle, {name} : c'qu'on donne revient, souvent avec des dents. Lui, non."
L["A gift for a troll? Careful, {name}. We follow nice folk home."] = "Un cadeau à un troll ? Gare, {name}. On suit les gentils chez eux."
L["Sure ting, {name}. Hold still; da mojo don't like a movin' target."] = "Bien sûr, {name}. Bougez plus, là ; le mojo, il aime pas les cibles qui bougent."
L["No worries, {name}. Da loa got ya covered."] = "Pas d'souci, {name}. Les loa, ils vous couvrent."
L["Stay away from da voodoo, {name}. ...Except dis voodoo. Dis one fine."] = "Restez loin du vaudou, {name}. ...Sauf c'vaudou-là. Lui, il est bien."
L["Close ya eyes, {name}. Da mojo be shy when people watch."] = "Fermez les yeux, {name}. Le mojo, il est timide quand on l'regarde."
L["Ya don't gotta ask twice, {name}. Ya barely gotta ask once."] = "Pas b'soin d'demander deux fois, {name}. Même une, c'est presque trop."
L["Sure, {name}. Bein' a troll be mostly swagger. Da rest be dis."] = "Bien sûr, {name}. Être un troll, c'est surtout d'la frime. Le reste, c'est ça."
L["Ya asked real polite, {name}. Polite get da good stuff."] = "Vous avez d'mandé bien poliment, {name}. Les polis, ils ont l'bon truc."
L["Ya came to da right troll, {name}. Da wrong troll be over dere, fishin'."] = "Vous êtes tombé sur l'bon troll, {name}. L'mauvais, il est là-bas, à pêcher."
L["Yes, {name}. Da loa owe me a favour, and I be spendin' it on you."] = "Oui, {name}. Les loa, ils m'doivent une faveur, et j'la dépense pour vous."
L["No problem, {name}. Got a pouch fulla mojo. Don't touch da other pouch."] = "Pas d'problème, {name}. J'ai une sacoche pleine d'mojo. Touchez pas à l'autre."
L["Anyting for ya, {name}. Well, not my hair. Da hair be sacred."] = "Tout pour vous, {name}. Sauf mes ch'veux. Les ch'veux, c'est sacré."
L["Troll magic, {name}, served hot. Blow on it first."] = "Magie troll, {name}, servie bien chaude. Soufflez d'ssus avant."
L["Right away, {name}. In Zandalar dis need a priest, a pyramid and a week."] = "Tout d'suite, {name}. À Zandalar, ça d'mande un prêtre, une pyramide et une s'maine."
L["Easy one, {name}. Hard one be gettin' a raptor to sit still."] = "Facile, {name}. L'difficile, c'est d'faire tenir un raptor tranquille."
L["Troll rule, {name}: never make a friend beg or a raptor wait. Here."] = "Règle troll, {name} : un ami supplie pas, un raptor attend pas. Tenez."
L["Hold still, {name}. Last one who wiggled got da spell and a new haircut."] = "Bougez plus, {name}. L'dernier qui gigotait a eu l'sort, plus une coupe."
L["Da loa be watchin' over ya, {name}. Dey real nosy like dat."] = "Les loa, ils veillent sur vous, {name}. Des vrais fouineurs, ceux-là."
L["Stay sharp out dere, {name}. Take dis wit' ya."] = "Faites gaffe dehors, {name}. Prenez ça avec vous."
L["Ya look like somebody who appreciate quality, {name}. Here: quality."] = "Vous avez l'air d'aimer la qualité, {name}. Tenez : d'la qualité."
L["Take dis, {name}. Walk like ya own da jungle. I do."] = "Prenez ça, {name}. Marchez comme si la jungle était à vous. Moi, c'est l'cas."
L["Everybody need mojo, {name}. I make so much I gotta give it away."] = "Tout l'monde a besoin d'mojo, {name}. J'en fais tellement qu'faut que j'le donne."
L["A little somethin' for ya, {name}. Don't ask where da loa got it."] = "Un p'tit quelque chose pour vous, {name}. D'mandez pas où les loa l'ont trouvé."
L["Go on, {name}. Anyting try to eat ya now gonna get indigestion."] = "Allez, {name}. Ce qui vous mange maint'nant, il aura une indigestion."
L["Ya lookin' dangerous now, {name}. Almost troll-level dangerous."] = "Vous v'là dangereux, {name}. Presque autant qu'un troll."
L["Somethin' for ya, {name}. No, ya don't owe da loa nothin'. Probably."] = "Un p'tit truc pour vous, {name}. Non, vous d'vez rien aux loa. En principe."
L["Raptors out dere got bigger teeth den me, {name}. Now dey got a problem."] = "Les raptors ont d'plus grandes dents qu'moi, {name}. Là, ils ont un problème."
L["Troll hospitality, {name}: ya get mojo, ya get a smile, ya don't get my fish."] = "Hospitalité troll, {name} : du mojo, un sourire, mais pas touche à mon poisson."
L["Walk wit' mojo, {name}. Everybody else just be walkin'."] = "Avec l'mojo, ça marche, {name}. Les autres, ils font qu'marcher."
L["Free mojo, {name}! Quick, before da witch doctor find out I give it away."] = "Mojo gratuit, {name} ! Vite, avant qu'le sorcier-docteur voie que j'le donne."
L["Da loa said give dis to da next good soul, {name}. Ya da next good soul."] = "Les loa ont dit d'donner ça à la prochaine bonne âme, {name}. Ça tombe sur vous."
L["Here, {name}. Hakkar never shared, and look what happen to him."] = "Tenez, {name}. Hakkar partageait jamais. Voyez c'qui lui est arrivé."
L["Jungle got two kinds of folk, {name}: da ready and da lunch. Now ya ready."] = "La jungle, {name}, c'est les prêts ou les plats. Vous v'là prêt."
L["Easy, {name}. Dis mojo tickle goin' in. Don't laugh; it get offended."] = "Doucement, {name}. C'mojo, il chatouille en entrant. Riez pas ; il s'vexe."
L["'Nobody badduh dan me,' Zul'jin said, {name}. Dis let ya argue da point."] = "« Personne plus méchant qu'moi », disait Zul'jin, {name}. Avec ça, contredisez-le."
L["Hey, {name}! Always good to see family, mon."] = "Hé, {name} ! C'est toujours bon d'voir la famille, ça."
L["Da rest of Azeroth stand up straight, {name}. We got more style."] = "Le reste d'Azeroth, il s'tient tout droit, {name}. Nous, on a plus d'style."
L["Hey, {name}, ya tusks be lookin' sharp. Mine too, obviously."] = "Hé, {name}, belles défenses, bien affûtées. Les miennes aussi, évidemment."
L["Every troll be family, {name}. Even da ones who still owe me gold."] = "Tous les trolls, c'est la famille, {name}. Même ceux qui m'doivent encore d'l'or."
L["Island or pyramid, {name}, a troll be a troll. Zandalari just wear more gold."] = "Île ou pyramide, {name}, un troll reste un troll. Les Zandalari sont juste plus dorés."
L["Two trolls, {name}. Da room just got taller and a lot more relaxed."] = "Deux trolls, {name}. L'plafond vient d'baisser, et l'ambiance d'se détendre."
L["Da loa can't tell us apart, {name}. Dat be why dey bless us both. Cheaper."] = "Les loa nous confondent, {name}, alors ils nous bénissent. Deux pour l'prix d'un."
L["Troll to troll, {name}: nobody else know how hard it be to buy boots."] = "Entre trolls, {name} : personne sait comme c'est dur d'trouver des bottes."
L["Our ancestors had empires, {name}. We got each other. Fair trade, I say."] = "Nos ancêtres avaient des empires, {name}. Nous, la famille. Pas un mauvais troc."
L["Stay close, {name}. Trolls regenerate; da rest of ya gotta be careful."] = "Restez près d'moi, {name}. Les trolls, ça régénère ; vous autres, faites attention."
L["Dis crew got style, {name}. Now it got mojo too."] = "C'groupe a du style, {name}. Et maint'nant, du mojo."
L["We go in together, {name}, we come out together. Dat be da whole plan, mon."] = "On entre ensemble, {name}, on sort ensemble. C'est tout l'plan, l'ami."
L["Nobody fallin' today, {name}. Bwonsamdi can wait for da next group."] = "Personne tombe aujourd'hui, {name}. Bwonsamdi, il attendra l'groupe suivant."
L["Keep ya head down, {name}. I keep mine up. Somebody gotta look good."] = "Baissez la tête, {name}. Moi, j'la garde haute. Faut bien qu'quelqu'un ait la classe."
L["Raptor formation, {name}: fast, loud, and nobody look back."] = "Formation raptor, {name} : vite, fort, et personne se r'tourne."
L["Big snake show up, {name}, don't run. Ya run, it chase. Stand behind me."] = "Gros serpent, {name} ? Courez pas. Vous courez, il chasse. Derrière moi."
L["Anybody need more mojo, {name}, just shout. Not too loud; da loa nappin'."] = "Besoin d'plus d'mojo, {name}, criez. Pas trop fort ; les loa font la sieste."
L["We gonna be a story at Sen'jin, {name}. Let's make it one wit' a happy endin'."] = "On s'ra une histoire qu'on raconte à Sen'jin, {name}. Une qui finit bien, hein."
L["Stick close, {name}. My tusks be sharp, but dey can't be everywhere."] = "Restez près, {name}. Mes défenses piquent, mais elles sont pas partout."
L["Nobody panic, {name}. Panic be bad mojo. Swagger be good mojo."] = "Pas d'panique, {name}. Panique, mauvais mojo. Frime, bon mojo."
L["See a big idol wit' glowin' eyes, {name}? Don't touch it. Trust me on dis."] = "Une grosse idole aux yeux qui brillent, {name} ? Touchez pas. Croyez-moi."
L["Night be da best time for mojo, {name}. Nobody see where it come from."] = "La nuit, c'est l'meilleur moment pour l'mojo, {name}. Personne voit d'où il vient."
L["Da jungle wake up at night, {name}. So do I. Here, dis one fresh."] = "La jungle, elle s'réveille la nuit, {name}. Moi aussi. Tenez, c'lui-là, il est frais."
L["Moon be high, {name}, spirits be restless. Dis keep dem off ya."] = "La lune est haute, {name}, les esprits s'agitent. Ça, ça les tient loin d'vous."
L["Hir'eek, da bat loa, keep late hours too, {name}. Dis from da both of us."] = "Hir'eek, le loa chauve-souris, veille tard aussi, {name}. Ça vient d'nous deux."
L["Dis late, {name}, only trolls and trouble be awake. I be da nice one."] = "Si tard, {name}, y a qu'les trolls et les tracas d'debout. J'suis pas un tracas."
L["Stars be out, {name}. Every one a loa, my granny say. Dat a lotta watchers."] = "Les étoiles brillent, {name}. Chacune un loa, dit mémé. Ça en fait, des curieux."
L["Such courtesy does you credit, {name}. Nearly as much as it does me."] = "Tant de courtoisie vous honore, {name}. Presque autant qu'elle m'honore."
L["How gracious, {name}. Allow me to return the favour."] = "Quelle grâce, {name}. Souffrez que je vous rende la politesse."
L["Thank you, {name}. I haven't felt this radiant since... well, this morning."] = "Merci, {name}. Je n'avais pas eu un tel éclat depuis... ma foi, ce matin."
L["Kind of you, {name}. We sin'dorei never turn down free magic. Ask anyone."] = "Merci, {name}. Nous, sin'dorei, ne refusons jamais la magie gratuite. Notoirement."
L["Exquisite, {name}. I would know; I only accept the exquisite."] = "Exquis, {name}. Je m'y connais : je n'accepte que l'exquis."
L["Lovely, {name}. I'll be insufferable about this all day. More than usual."] = "Charmant, {name}. Je vais être insupportable toute la journée. Plus que d'habitude."
L["Thank you, {name}. It even goes with my gold trim. You have an eye."] = "Merci, {name}. C'est même assorti à mes dorures. Vous avez l'œil."
L["Returned in kind, {name}. A prettier kind, admittedly. I can't help it."] = "Rendu à l'identique, {name}. En plus joli, je l'admets. C'est plus fort que moi."
L["Thank you, {name}. Visit Silvermoon; I'll show you all of it but Murder Row."] = "Merci, {name}. À Lune-d'argent, je vous ferai tout visiter, sauf l'allée du Meurtre."
L["Returned, {name}. Unlike Kael'thas, I give things back."] = "Rendu, {name}. Moi, au moins, je rends. Pas comme Kael'thas."
L["Thank you, {name}. I felt that to the tips of my ears, and that's a long way."] = "Merci, {name}. Je l'ai senti jusqu'au bout des oreilles, et c'est loin."
L["Thank you, {name}. That was so kind my eyes nearly changed colour again."] = "Merci, {name}. Si gentil que mes yeux ont failli changer de couleur. Encore."
L["A gift, unasked? Farstriders would call that an ambush. A lovely one, {name}."] = "Un cadeau surprise ? Pour les Pérégrins, c'est une embuscade. Charmante, {name}."
L["Better than a mana crystal, {name}, and I've given those up. Mostly. Thank you."] = "Mieux qu'un cristal de mana, {name}, et j'ai décroché. Presque. Merci."
L["Quick of you, {name}. Elves live for centuries, and you still beat me to it."] = "Rapide, {name}. J'ai des siècles devant moi, et vous m'avez pris de vitesse."
L["Charming, {name}. I don't say it lightly. I say it constantly, but not lightly."] = "Charmant, {name}. Je ne le dis pas à la légère. Souvent, mais jamais à la légère."
L["Thank you, {name}. I'll mention you at court. Well, at a very exclusive picnic."] = "Merci, {name}. Je parlerai de vous à la cour. Enfin, à un pique-nique très select."
L["Thank you, {name}. You've been added to my list of people who deserve me."] = "Merci, {name}. Vous voilà sur ma liste des gens qui me méritent."
L["Unasked kindness, {name}! Somebody tell Rommath; he'll want to study it."] = "Une bonté spontanée, {name} ! Prévenez Rommath ; il voudra l'étudier."
L["Naturally, {name}. Only the finest for you."] = "Naturellement, {name}. Rien que le meilleur pour vous."
L["For you, {name}? Of course. The sun gives freely."] = "Pour vous, {name} ? Bien sûr. Le soleil donne sans compter."
L["Patience, {name}. Radiance can't be rushed, only admired."] = "Patience, {name}. L'éclat ne se presse pas ; il s'admire."
L["Of course, {name}. {buff}, delivered with impeccable posture."] = "Bien sûr, {name}. {buff}, avec un maintien impeccable."
L["You asked nicely, {name}. In Silvermoon that counts for everything."] = "Vous avez demandé poliment, {name}. À Lune-d'argent, c'est tout ce qui compte."
L["One moment, {name}. I never cast anything without checking my hair."] = "Un instant, {name}. Je ne lance jamais rien sans vérifier ma coiffure."
L["At once, {name}. Keeping someone waiting is so terribly unfashionable."] = "Tout de suite, {name}. Faire attendre, c'est si terriblement démodé."
L["Certainly, {name}. Stand back a step; my sleeves are enchanted and very wide."] = "Bien sûr, {name}. Reculez d'un pas ; mes manches sont enchantées, et amples."
L["Magisters would bill you, {name}. Blood Knights would lecture. I merely glow."] = "Les magistères facturent, {name}. Les chevaliers de sang sermonnent. Moi, je brille."
L["At once, {name}. If it goes well, tell everyone. If not, blame the robe."] = "Aussitôt, {name}. Réussi ? Dites-le à tous. Raté ? Accusez la robe."
L["At once, {name}. The dragonhawk can wait; it's used to waiting while I dress."] = "Aussitôt, {name}. Le faucon-dragon attendra : il a l'habitude, avec mes essayages."
L["Gladly, {name}. We once took the Light from a naaru. Asking is so much nicer."] = "Volontiers, {name}. Nous avons pris la Lumière d'un naaru ; demander, c'est plus chic."
L["Three centuries of casting, {name}, and you're the first to say please."] = "Trois siècles de sorts, {name}, et vous êtes le premier à dire s'il vous plaît."
L["Gladly, {name}. Silvermoon's brooms sweep themselves, so my hands are free."] = "Volontiers, {name}. Nos balais balaient tout seuls, alors j'ai les mains libres."
L["Of course, {name}. Arcane Torrent is for the rude. You asked nicely."] = "Bien sûr, {name}. Les malpolis ont droit au Torrent arcanique. Vous, à ceci."
L["Anar'alah belore, {name}. May the sun guide you, and light your good side."] = "Anar'alah belore, {name}. Que le soleil vous guide, et éclaire votre meilleur profil."
L["Shorel'aran, {name}. Fight with elegance."] = "Shorel'aran, {name}. Combattez avec élégance."
L["Take this, {name}. Whatever happens out there is merely a setback."] = "Prenez ceci, {name}. Quoi qu'il arrive là-bas, ce ne sera qu'un simple contretemps."
L["Everyone deserves to shine, {name}. Only a little less than me, of course."] = "Tout le monde mérite de briller, {name}. Juste un peu moins que moi, bien sûr."
L["The sun is with you, {name}. I simply held the door for it."] = "Le soleil est avec vous, {name}. Je lui ai simplement tenu la porte."
L["Go on, {name}, take it. The Sunwell's back; we can afford to be generous."] = "Allez, {name}, prenez. Le Puits de soleil est de retour ; nous pouvons être généreux."
L["For you, {name}: {buff}, lightly scented with Silvermoon."] = "Pour vous, {name} : {buff}, au parfum de Lune-d'argent."
L["Here, {name}. Hand-cast in Silvermoon, so do try not to scuff it."] = "Tenez, {name}. Fait main à Lune-d'argent, alors tâchez de ne pas l'abîmer."
L["A little Sunwell for you, {name}. It's been through a lot; treat it kindly."] = "Un peu de Puits de soleil pour vous, {name}. Il en a vu, alors ménagez-le."
L["Be prepared, {name}. We weren't, once, and now we have a scar for a road."] = "Soyez paré, {name}. Nous ne l'étions pas : depuis, une balafre nous sert de route."
L["Here, {name}. I only give to the worthy. How convenient that you walked by."] = "Tenez, {name}. Je ne donne qu'aux dignes. Comme vous tombez bien."
L["Take this, {name}. It's been in my family for moments."] = "Prenez ceci, {name}. Un héritage de famille. Depuis ce matin."
L["We sin'dorei have lost much, {name}. Never our generosity. Or our cheekbones."] = "Les sin'dorei ont beaucoup perdu, {name}. Pas leur générosité. Ni leurs pommettes."
L["Take this, {name}. Should a mana wyrm follow you, it's only jealous."] = "Prenez ceci, {name}. Si un wyrm de mana vous suit, il est juste jaloux."
L["Seven thousand years to perfect generosity, {name}. We started last week."] = "Sept mille ans pour parfaire la générosité, {name}. Nous avons commencé mardi."
L["Take this, {name}. It came through the Undercity orb, so it's slightly dizzy."] = "Prenez ceci, {name}. Arrivé par l'orbe de Fossoyeuse, il a encore le tournis."
L["For you, {name}. It matches everything. I checked, obviously."] = "Pour vous, {name}. Ça va avec tout. J'ai vérifié, évidemment."
L["If a ghoul stops you, {name}, say Silvermoon's still standing. They hate that."] = "Une goule vous arrête, {name} ? Dites que Lune-d'argent tient bon. Ça les agace."
L["The Sunwell shines for us both, {name}."] = "Le Puits de soleil brille pour nous deux, {name}."
L["Two sin'dorei in one place, {name}. The day just got twice as elegant."] = "Deux sin'dorei au même endroit, {name}. La journée devient deux fois plus élégante."
L["You too, {name}? Two sin'dorei, one mirror. We'll have to take turns."] = "Vous aussi, {name} ? Deux sin'dorei, un seul miroir. Il faudra se relayer."
L["Like the phoenix, {name}: we keep rising, and we look good doing it."] = "Comme le phénix, {name} : nous renaissons sans cesse, et avec style."
L["Between sin'dorei, {name}: yes, the Horde is loud. Yes, we're used to it now."] = "Entre sin'dorei, {name} : oui, la Horde est bruyante. Oui, nous nous y faisons."
L["Sin'dorei to sin'dorei, {name}: shall we pretend neither of us had a fel phase?"] = "De sin'dorei à sin'dorei, {name} : oublions nos périodes gangrenées respectives ?"
L["Sunstrider or Farstrider, {name}, we all stride beautifully."] = "Haut-Soleil ou Pérégrin, {name}, nous avons tous fière allure."
L["We both remember Quel'Thalas before the Scourge, {name}. Let's earn the after."] = "Nous avons connu Quel'Thalas avant le Fléau, {name}. Méritons l'après."
L["Do keep pace, {name}. We have a reputation for arriving beautifully."] = "Gardez le rythme, {name}. Nous avons la réputation d'arriver avec grâce."
L["Stand where the light is good, {name}. If we must fight, we'll look splendid."] = "Placez-vous dans la bonne lumière, {name}. S'il faut se battre, soyons splendides."
L["A party at last, {name}. I did dress for one."] = "Enfin un groupe, {name}. J'avais compris « soirée », d'où la tenue."
L["The sun shines on all of us, {name}. Mostly on me, but it shares."] = "Le soleil brille pour nous tous, {name}. Surtout pour moi, mais il partage."
L["One for you, {name}, and one for the party's image, which I've taken on myself."] = "Un pour vous, {name}, et un pour l'image du groupe, dont je m'occupe personnellement."
L["If I fall, {name}, arrange me attractively. The rest I leave to the healer."] = "Si je tombe, {name}, disposez-moi avec goût. Pour le reste, voyez le soigneur."
L["Nobody touch the enchanted relics, {name}. Well, I may. I've had training."] = "Qu'on ne touche pas aux reliques enchantées, {name}. Sauf moi : j'ai une formation."
L["Every expedition needs a ranger, {name}. I'm not one, but I have the boots."] = "Toute expédition veut un rôdeur, {name}. Je n'en suis pas, mais j'ai les bottes."
L["We fight together, {name}, then tell it beautifully. I'll handle the telling."] = "Combattons ensemble, {name}, puis racontons-le joliment. Le récit, c'est moi."
L["The healer is to be thanked and the tank adored, {name}. Me, admired. Carry on."] = "Remerciez le soigneur, adorez le tank, {name}. Moi, admirez-moi. Continuez."
L["If this goes badly, {name}, we blame the Scourge. It's traditional."] = "Si ça tourne mal, {name}, on accuse le Fléau. C'est la tradition."
L["Mana potions are for emergencies, {name}. I've had eleven emergencies today."] = "Les potions de mana, c'est pour les urgences, {name}. J'en ai eu onze aujourd'hui."
L["We walked out of the ashes once, {name}. We'll walk out of whatever's ahead."] = "Nous sommes sortis des cendres, {name}. Nous sortirons bien de ce qui vient."
L["The sun has risen, {name}, and so have I. We coordinate."] = "Le soleil s'est levé, {name}, et moi aussi. Nous nous coordonnons."
L["Dawn over Quel'Thalas is lovelier, {name}, but this will do. Just."] = "L'aube est plus belle sur Quel'Thalas, {name}, mais celle-ci ira. De justesse."
L["Morning light, {name}. The most flattering hour. For both of us, naturally."] = "La lumière du matin, {name}. L'heure la plus flatteuse. Pour nous deux, naturellement."
L["Breakfast in Eversong is fruit, tea and arcane, {name}. Skip to the arcane."] = "Le petit-déjeuner elfique : fruits, thé et arcanes, {name}. Passons aux arcanes."
L["Dawn, {name}. Red and gold across the sky. Somebody's been copying us."] = "L'aube, {name}. Du rouge et de l'or dans le ciel. Quelqu'un nous copie."
L["Morning, {name}. Only Silvermoon's arcane guardians are up this early. And me."] = "Bonjour, {name}. À cette heure, seuls les gardiens arcaniques veillent. Et moi."
L["Your generosity is noted, {name}. In triplicate. Suramar remembers its friends."] = "Votre générosité est notée, {name}. En trois exemplaires. Suramar n'oublie pas ses amis."
L["Most gracious, {name}. Allow me to repay you in kind."] = "Fort aimable, {name}. Permettez que je vous rende la pareille."
L["Thank you, {name}. Ten thousand years under a dome; I'm still practising that."] = "Merci, {name}. Dix mille ans sous un dôme ; je m'y exerce encore."
L["A gift with no favour owed? The court would faint. Thank you, {name}."] = "Un présent sans rien devoir en retour ? La cour s'évanouirait. Merci, {name}."
L["Returned, {name}. We keep careful accounts of kindness. And of slights."] = "Rendu, {name}. Nous tenons le compte des bontés. Et des affronts."
L["I'll mention you to First Arcanist Thalyssra, {name}. Favourably, even."] = "Je parlerai de vous à la Première arcaniste Thalyssra, {name}. En bien, même."
L["Most kind, {name}. In Suramar we'd hold a banquet. Consider it held."] = "Fort aimable, {name}. À Suramar, nous donnerions un banquet. Considérez qu'il a eu lieu."
L["I'd send a formal letter of thanks, {name}, but this seemed quicker."] = "Une lettre de remerciement officielle, {name} ? Ceci va plus vite."
L["In Elisande's court a gift hid a knife, {name}. Yours hides none. Thank you."] = "À la cour d'Elisande, un cadeau cachait un poignard, {name}. Le vôtre, non. Merci."
L["Thank you, {name}. My manasaber approves of you, and she approves of no one."] = "Merci, {name}. Ma monture vous approuve, et elle n'approuve personne."
L["Exquisite, {name}. Once I'd have said 'adequate'. The world has humbled me."] = "Exquis, {name}. Jadis, j'aurais dit « convenable ». Le monde m'a rendu humble."
L["You fed a mind that once went hungry, {name}. We never forget those who do."] = "Vous avez nourri un esprit jadis affamé, {name}. Nous ne l'oublions jamais."
L["Centuries of court etiquette, {name}, and 'thank you' still outperforms it all."] = "Des siècles d'étiquette, {name}, et rien ne vaut toujours un simple « merci »."
L["Thank you, {name}. You're invited to the next masquerade. Masks mandatory."] = "Merci, {name}. Vous êtes invité au prochain bal masqué. Masque obligatoire."
L["Thank you, {name}. Oculeth would open a portal to say so. I'll simply cast."] = "Merci, {name}. Oculeth ouvrirait un portail pour le dire. Je me contente d'un sort."
L["Of course, {name}. A little arcane polish, just for you."] = "Bien sûr, {name}. Un peu de vernis arcanique, rien que pour vous."
L["A reasonable request, {name}. Granted."] = "Requête raisonnable, {name}. Accordée."
L["Certainly, {name}. The short version; the long one takes a lunar cycle."] = "Certainement, {name}. Version courte ; la longue prend un cycle lunaire."
L["A request, how refreshing. The court only ever made demands. Here, {name}."] = "Une requête, quelle fraîcheur. La cour ne connaissait que les exigences. Tenez, {name}."
L["Done, {name}, and free. Elisande would have charged you a favour for it."] = "Fait, {name}, et gratuitement. Elisande vous aurait réclamé une faveur en échange."
L["There, {name}. No need to bow. A small nod would be lovely, though."] = "Voilà, {name}. Inutile de vous incliner. Un signe de tête serait charmant, cela dit."
L["Of course, {name}. I've perfected this since before most cities had walls."] = "Bien sûr, {name}. Je maîtrise ce sort depuis avant l'invention des remparts."
L["Granted, {name}. I'd ask a favour back, but I'm trying to be less Suramar."] = "Accordé, {name}. J'exigerais bien une faveur, mais j'essaie d'être moins Suramar."
L["Certainly, {name}. Forgive the flourish. We can't cast plainly; we've tried."] = "Bien sûr, {name}. Pardonnez les fioritures ; la sobriété, nous avons essayé."
L["At once, {name}. Elisande once stopped time. I only need a second."] = "Aussitôt, {name}. Elisande arrêtait le temps. Moi, une seconde me suffit."
L["Of course, {name}. The ley lines here are shallow, but I'll make do."] = "Bien sûr, {name}. Les lignes telluriques sont bien maigres ici, mais soit."
L["Very well, {name}. Stand in the moonlight. Or by that lamp. Lamps will do."] = "Soit, {name}. Mettez-vous au clair de lune. Ou sous cette lampe. Ça ira."
L["Naturally, {name}. Suramar had a spell for everything. I remember several."] = "Bien sûr, {name}. Suramar avait un sort pour tout. J'en ai retenu plusieurs."
L["Take this, {name}. Arcane gifts are wasted on the idle."] = "Prenez ceci, {name}. Les dons des arcanes sont perdus pour les oisifs."
L["A spark of Suramar's arcana for you, {name}. Use it wisely."] = "Une étincelle des arcanes de Suramar pour vous, {name}. Faites-en bon usage."
L["I've gone without magic once, {name}. I don't recommend it. Take this."] = "J'ai déjà vécu sans magie, {name}. Je ne le recommande pas. Prenez ceci."
L["The world outside the dome is so large, {name}. And so under-enchanted. Here."] = "Le monde hors du dôme est si vaste, {name}. Et si peu enchanté. Tenez."
L["Arcwine is traditional, {name}, but {buff} travels better."] = "Le vin arcanique est la tradition, {name}, mais {buff} voyage mieux."
L["Do take this, {name}. It's rude to refuse Suramar's hospitality. Very rude."] = "Prenez donc ceci, {name}. Refuser l'hospitalité de Suramar est impoli. Très impoli."
L["Here, {name}. I'm told this is how outsiders say hello. Charming custom."] = "Tenez, {name}. On m'a dit que c'est ainsi que les étrangers se saluent. Charmante coutume."
L["Take this, {name}. Magic hoarded is magic spoiled, as Suramar learned."] = "Prenez ceci, {name}. Magie amassée, magie gâchée : Suramar l'a appris."
L["Once, I'd have made you bow for this, {name}. We've all grown."] = "Jadis, vous auriez dû vous incliner, {name}. Nous avons tous grandi."
L["The Kirin Tor do this too, {name}, bless them. Quite nicely, for newcomers."] = "Le Kirin Tor fait ça aussi, {name}, ces braves. Pas mal, pour des novices."
L["A gift from under the dome, {name}. Kept fresh for a very, very long time."] = "Un cadeau de sous le dôme, {name}. Conservé au frais très, très longtemps."
L["Enjoy this, {name}. I used to cast it on nobility. You're an improvement."] = "Profitez-en, {name}. Je le lançais jadis sur la noblesse. Vous êtes un progrès."
L["I packed for the outside world like a gala, {name}. Four capes. Take this."] = "J'ai fait mes malles comme pour un gala, {name}. Quatre capes. Prenez ceci."
L["Here, {name}. Suramar work: overdesigned, overdecorated, and flawless."] = "Tenez, {name}. Façon Suramar : trop pensé, trop orné, et sans défaut."
L["Here, {name}. In Suramar this came with a string quartet. Do hum something."] = "Tenez, {name}. À Suramar, un quatuor à cordes l'accompagnait. Fredonnez donc."
L["Suramar's children shine together again, {name}."] = "Les enfants de Suramar brillent à nouveau ensemble, {name}."
L["Shal'dorei, {name}! You packed arcwine? Outsider wine is just... grapes."] = "Shal'dorei, {name} ! Vous avez du vin arcanique ? Ici, le vin, c'est... du raisin."
L["Suramar's own, {name}. Try not to be too impressed by the rest of the world."] = "De Suramar, vous aussi, {name} ? Ne vous laissez pas trop impressionner par le reste du monde."
L["We survived the Legion and the withering, {name}. The rest is small talk."] = "Nous avons survécu à la Légion et au flétrissement, {name}. Le reste n'est que bavardage."
L["Our tailors made it out of Suramar too, {name}. Thank the stars."] = "Nos couturiers aussi ont fui Suramar, {name}. Loués soient les astres."
L["We both remember going hungry, {name}. Never again, for either of us."] = "Nous avons connu la faim, {name}, vous et moi. Plus jamais."
L["Out from under the dome, {name}. Is the sky still this big for you too?"] = "Sortis du dôme, {name}. Le ciel vous paraît-il encore si grand, à vous aussi ?"
L["Two shal'dorei in one place, {name}. The locals will assume it's a gala."] = "Deux shal'dorei au même endroit, {name}. Les gens du coin vont croire à un gala."
L["An expedition, {name}! In Suramar this needed six permits and a masquerade."] = "Une expédition, {name} ! À Suramar, il aurait fallu six permis et un bal masqué."
L["The dome kept us safe, {name}. Now we must make do with one another. Gladly."] = "Le dôme nous protégeait, {name}. Maintenant, comptons les uns sur les autres. Avec plaisir."
L["Arcane for everyone, {name}. The court would call it waste. I call it company."] = "De l'arcane pour tout le monde, {name}. La cour appellerait ça du gaspillage. Moi, de la compagnie."
L["Do follow my lead, {name}. I've had ten thousand years of walking in step."] = "Suivez-moi, {name}. J'ai eu dix mille ans pour apprendre à marcher au pas."
L["In a party one shares one's magic, {name}. How novel. I rather like it."] = "En groupe, on partage sa magie, {name}. Quelle nouveauté. J'aime assez."
L["An outing is like a masquerade, {name}: smile, keep moving, watch for knives."] = "Une sortie, c'est comme un bal masqué, {name} : souriez, bougez, gare aux poignards."
L["Stay in the light of my spells, {name}. It's the most flattering in the party."] = "Restez dans la lumière de mes sorts, {name}. C'est la plus flatteuse du groupe."
L["After Elisande's court, {name}, a party of five is a holiday. Nobody plots."] = "Après la cour d'Elisande, {name}, un groupe, c'est les vacances. Aucun complot."
L["Lost? Follow the one who glows, {name}. That's me. It's always me."] = "Perdu ? Suivez ce qui brille, {name}. C'est moi. C'est toujours moi."
L["If I start lecturing on ley lines, {name}, do interrupt. Politely."] = "Si je disserte sur les lignes telluriques, {name}, coupez-moi. Poliment."
L["I watched my people wither, {name}. I won't watch friends fade. Nobody falls."] = "J'ai vu mon peuple dépérir, {name}. Pas mes amis. Personne ne tombera."
L["Tell me if I'm being grand, {name}. I lose track. It's the millennia."] = "Dites-moi si j'en fais trop, {name}. Je perds le fil. Les millénaires."
L["Night at last, {name}. Add a few thousand lanterns and it's nearly Suramar."] = "Enfin la nuit, {name}. Ajoutez quelques milliers de lanternes et c'est presque Suramar."
L["Under the dome it was always night, {name}. I feel quite at home."] = "Sous le dôme, il faisait toujours nuit, {name}. Je me sens chez moi."
L["The stars are out, {name}. We had better ones in Suramar. These will do."] = "Voici les étoiles, {name}. Celles de Suramar étaient plus belles. Ça ira."
L["Nightborne, {name}, and here's the night. At last I'm dressed for the hour."] = "Sacrenuit, {name}, et voici la nuit. Enfin une tenue de circonstance."
L["At this hour, {name}, Suramar was only just getting dressed for dinner."] = "À cette heure, {name}, Suramar commençait à peine à s'habiller pour dîner."
L["Daylight, {name}. Ten thousand years under a dome, and it still startles me."] = "La lumière du jour, {name}. Dix mille ans sous un dôme, et elle me surprend encore."
L["An early hour, {name}. The court never rose before noon. I'm reforming."] = "Une heure bien matinale, {name}. La cour ne se levait jamais avant midi. Je me réforme."
L["Morning, {name}. The sun here is so very... unenchanted. Take this instead."] = "Bonjour, {name}. Le soleil ici est si... désenchanté. Prenez plutôt ceci."
L["Morning, {name}. We warded Suramar against every threat but the sun."] = "Bonjour, {name}. Suramar était protégée de tout, sauf du soleil."
L["Dawn, {name}: when the court's gossip went to bed. Here's mine: you look well."] = "Aube, {name} : fin des ragots de cour. Un dernier : vous avez bonne mine."
L["A favour for a favour, {name}! Pleasure doing business."] = "Donnant-donnant, {name} ! Un plaisir de faire affaire."
L["Thanks, {name}! Consider your account settled in full."] = "Merci, {name} ! Votre compte est soldé, rubis sur l'ongle."
L["Aw, {name}. I'd invoice you, but I'm feeling sentimental. It'll pass."] = "Oh, {name}. J'vous facturerais bien, mais je suis d'humeur sentimentale. Ça passera."
L["Thanks, {name}! I checked it for fine print. There wasn't any. Weird!"] = "Merci, {name} ! J'ai cherché les petites lignes. Y en avait pas. Bizarre !"
L["Returned with interest, {name}. Minus the interest. Don't get used to it."] = "Rendu avec intérêts, {name}. Moins les intérêts. Vous y habituez pas."
L["Much obliged, {name}! You've just been upgraded to preferred customer."] = "Bien obligé, {name} ! Vous venez de passer client privilégié."
L["I'd name a rocket after you, {name}, but my rockets never last long. Thanks!"] = "Je donnerais bien votre nom à une fusée, {name}, mais mes fusées durent jamais longtemps. Merci !"
L["I'd have charged fifty gold for that, {name}. Let's call us even."] = "J'vous aurais fait payer cinquante pièces d'or, {name}. Disons qu'on est quittes."
L["Gave first, {name}? Bold business model. I'll match it. Don't tell Undermine."] = "Donner en premier, {name} ? Modèle audacieux. Je m'aligne. Pas un mot à Terremine."
L["A deal where both sides profit, {name}! I'd heard of those. Never seen one."] = "Un marché gagnant-gagnant, {name} ! J'en avais entendu parler. Jamais vu."
L["First free gift since Kezan blew up, {name}. Returning it before I price it."] = "Premier cadeau depuis que Kezan a sauté, {name}. J'le rends avant d'l'étiqueter."
L["Thanks, {name}! I appraised it at priceless. Here's one appraised the same."] = "Merci, {name} ! Estimation : inestimable. Voilà le mien, estimé pareil."
L["Kindness in, kindness out, {name}. Best returns since the kaja'mite boom."] = "Bonté investie, bonté rendue, {name}. Du jamais vu depuis le boom du kaja'mite."
L["Even trade, {name}? My accountant just fainted. He does that around fair deals."] = "Échange équitable, {name} ? Mon comptable s'est évanoui. L'honnêteté lui fait ça."
L["Thanks, {name}! I'd shake on it, but I count my fingers after. Habit, not you."] = "Merci, {name} ! Tope là. Après, j'recompte mes doigts. L'habitude, rien d'perso."
L["No haggling at all? Thanks, {name}. I feel cheated. In a nice way."] = "Même pas d'marchandage ? Merci, {name}. C'est d'l'arnaque. Mais sympa."
L["You got it, {name}! Time is money, friend!"] = "Ça marche, {name} ! Le temps, c'est de l'argent, l'ami !"
L["Deal, {name}! I'll put it on your tab. Kidding!"] = "Marché conclu, {name} ! Je le mets sur votre ardoise. J'rigole !"
L["Right away, {name}! Satisfaction guaranteed or your {buff} back."] = "Tout de suite, {name} ! Satisfait ou remboursé, {buff} compris."
L["{buff}, {name}! Tips optional. Encouraged. Optional."] = "{buff}, {name} ! Pourboire facultatif. Encouragé. Facultatif."
L["Fast, cheap or good, {name}? Today you get all three. Don't spread it around."] = "Rapide, pas cher ou bien fait, {name} ? Aujourd'hui, les trois. Le répétez pas."
L["Sure thing, {name}! No explosions this time, I promise. Mostly promise."] = "Tout de suite, {name} ! Pas d'explosion cette fois, promis. Presque promis."
L["For you, {name}? No charge. Put that in writing and I'll deny it."] = "Pour vous, {name} ? Gratuit. Mettez ça par écrit et je nierai tout."
L["Sure, {name}! Quote's zero gold. Lowest I've ever quoted. It stings a little."] = "Bien sûr, {name} ! Devis : zéro pièce d'or. Mon plus bas. Ça pique un peu."
L["Coming up, {name}! Full warranty included. Valid until it wears off."] = "Ça arrive, {name} ! Garantie totale. Valable tant que ça dure."
L["Sure, {name}! Sign here, initial there... joking. Mostly. Hold still."] = "Bien sûr, {name} ! Signez ici, paraphez là... j'rigole. En partie. Bougez pas."
L["Free of charge, {name}. If anybody from Bilgewater asks, you paid double."] = "Gratuit, {name}. Si Baille-Fonds demande, vous avez payé le double."
L["Gadgetzan's got the water trade, {name}. I've got this. Better margins."] = "Gadgetzan a le commerce de l'eau, {name}. Moi, j'ai ça. Meilleures marges."
L["Kezan standard, {name}: fast, loud, and done before you read the terms."] = "Norme Kezan, {name} : vite, bruyant, fini avant la lecture des conditions."
L["Order received, {name}! Delivery instant, wrapping optional, refunds imaginary."] = "Commande reçue, {name} ! Livré illico, emballage facultatif, remboursement fictif."
L["This one's on the house, {name}. Don't tell the Trade Prince."] = "C'est offert par la maison, {name}. N'en dites rien au Prince marchand."
L["Top-shelf stuff, zero fees, {name}. Today only!"] = "Qualité supérieure, zéro frais, {name}. Aujourd'hui seulement !"
L["Free sample, {name}! If you like it, you know where to find me."] = "Échantillon gratuit, {name} ! Si ça vous plaît, vous savez où me trouver."
L["Here, {name}. If anything explodes near you today, that was unrelated."] = "Tenez, {name}. Si quelque chose explose près de vous aujourd'hui, j'y suis pour rien."
L["Goodwill's an asset, {name}. Here's some {buff} for my books."] = "La bienveillance, c'est un actif, {name}. Voilà {buff} pour mes comptes."
L["Take this, {name}. Safety first! Or third. It's on the list somewhere."] = "Prenez ça, {name}. La sécurité d'abord ! Ou en troisième. C'est sur la liste, quelque part."
L["Cast in record time, {name}! The record's mine. I set it just now."] = "Lancé en un temps record, {name} ! Le record est à moi. Je viens de l'établir."
L["Kaja'Cola gives you ideas, {name}. This does the rest. Take it!"] = "Le Kaja'Cola, ça donne des idées, {name}. Ceci fait le reste. Prenez !"
L["Limited-time offer, {name}! Limited mostly by how long it lasts."] = "Offre à durée limitée, {name} ! Limitée surtout par sa durée."
L["Free trial, {name}! No obligation. Well, a small emotional one."] = "Essai gratuit, {name} ! Sans engagement. Enfin, juste affectif."
L["Here, {name}. Patent pending. Try it out and tell your rich friends."] = "Tenez, {name}. Brevet en instance. Essayez et parlez-en à vos amis riches."
L["Consider this an investment, {name}. In you. I expect heroic returns."] = "C'est un investissement, {name}. En vous. J'attends des dividendes héroïques."
L["Take it, {name}! My last shipment sank off Kezan, so everything's clearance."] = "Prenez, {name} ! Ma cargaison a sombré au large de Kezan. Tout doit disparaître !"
L["The Venture Company charges for this, {name}. I'm the competition. Here."] = "La KapitalRisk fait payer ça, {name}. Moi, je suis la concurrence. Tenez."
L["Every goblin has a soft spot, {name}. Mine's small and guarded. You found it."] = "Tout gobelin a un faible, {name}. Le mien est petit, gardé, et vous l'avez trouvé."
L["Take this, {name}. It's the only thing I own with no lien on it."] = "Prenez ça, {name}. Le seul truc que j'ai qui soit pas hypothéqué."
L["You'll be rich someday, {name}. I can tell. Remember who gave you this."] = "Vous serez riche, {name}. Ça s'voit. Souvenez-vous d'qui vous a donné ça."
L["Anything for a fellow entrepreneur, {name}!"] = "Tout pour un collègue entrepreneur, {name} !"
L["Kezan's finest, together again, {name}. Keep a hand on your coin purse."] = "La crème de Kezan, réunie, {name}. Gardez une main sur votre bourse."
L["Fellow goblin, {name}? Then you know this is a very, very rare discount."] = "Un collègue gobelin, {name} ? Alors vous savez que c'est une remise très, très rare."
L["Goblins look after goblins, {name}. It's cheaper than hiring guards."] = "Les gobelins s'entraident, {name}. C'est moins cher que d'engager des gardes."
L["Kezan's gone, {name}, but the hustle made it out. Look at us."] = "Kezan a sauté, {name}, mais la débrouille a survécu. R'gardez-nous."
L["Between goblins, {name}, this never happened. I have a reputation."] = "Entre gobelins, {name}, ça n'a jamais eu lieu. J'ai une réputation."
L["Bilgewater or Steamwheedle, {name}, we always float to the top. Like oil."] = "Baille-Fonds ou Gentepression, {name}, on surnage toujours. Comme l'huile."
L["Remember the volcano, {name}? We sold tickets to it. Proud times."] = "Souvenez-vous du volcan, {name} : on vendait des billets. La belle époque."
L["Group rate, {name}! Everybody here gets it half off. Of free."] = "Tarif de groupe, {name} ! Tout le monde ici a moitié prix. Sur du gratuit."
L["Nobody dies on my contract, {name}. The paperwork's a nightmare."] = "Personne meurt sous mon contrat, {name}. La paperasse, c'est l'enfer."
L["We split the loot even, {name}. I'll do the maths. Trust me."] = "Butin à parts égales, {name}. Les calculs, c'est moi. Faites-moi confiance."
L["Team-building, {name}! You make everybody stronger, and they all owe you."] = "Team-building, {name} ! Vous rendez tout le monde plus fort, et tout le monde vous doit."
L["Stick together, {name}. Mercenaries cost gold; friends only cost this."] = "Restons groupés, {name}. Les mercenaires coûtent de l'or ; les amis, juste ça."
L["Everybody's covered, {name}. Not insured, mind. Covered. Different price."] = "Tout le monde est couvert, {name}. Pas assuré, hein. Couvert. Pas le même tarif."
L["I read the risk report on this outing, {name}. Short read. It just says 'no'."] = "J'ai lu l'étude de risques, {name}. Vite lu : y a juste écrit « non »."
L["Nobody touches the big red lever, {name}. There's always a big red lever."] = "Personne touche au gros levier rouge, {name}. Y a toujours un gros levier rouge."
L["If this goes south, {name}, I've got a rocket. Seats one. I'm working on it."] = "Si ça tourne mal, {name}, j'ai une fusée. Une place. J'y travaille."
L["We're a company now, {name}. I'm treasurer. The vote was unanimous. Mine."] = "On est une entreprise, {name}. Les finances, c'est moi. Vote unanime. Le mien."
L["Stay alive, {name}. Nobody's found a way to sell resurrections yet. I'm trying."] = "Restez en vie, {name}. Vendre des résurrections, personne sait faire. Pas encore."
L["Stay close, {name}. I've already sold the story of this trip. Make it good."] = "Restez près, {name}. J'ai déjà vendu le récit d'la sortie. Faut qu'il soit bon."
L["Early bird gets the gold, {name}! Here's a freebie. Don't tell the other birds."] = "L'or appartient à ceux qui se lèvent tôt, {name} ! Un cadeau. Le dites pas aux autres lève-tôt."
L["Morning, {name}! Markets open in an hour. Until then, I'm feeling generous."] = "Bonjour, {name} ! Les marchés ouvrent dans une heure. D'ici là, je suis d'humeur généreuse."
L["Up early, {name}? Smart. Time is money, and it's cheapest in the morning."] = "Déjà debout, {name} ? Malin. Le temps, c'est de l'argent, et le matin, il est moins cher."
L["Up early, {name}? Me too. Rich goblins sleep in. I'm working on it."] = "Debout tôt, {name} ? Moi aussi. Les riches font la grasse mat'. J'y travaille."
L["Fresh day, fresh ledger, {name}. You're the first entry. The good column."] = "Nouveau jour, nouveaux comptes, {name}. Première ligne : vous. Au crédit."
L["Thank you, {name}! The caravan always repays a kindness. Usually in string."] = "Merci, {name} ! La caravane rend toujours un bienfait. En général, en ficelle."
L["How kind, {name}! You're on the caravan's good list now."] = "Comme c'est gentil, {name} ! Vous voilà dans les petits papiers de la caravane."
L["Oh, I'll keep this, {name}! I keep everything. Here's one for you."] = "Oh, je garde ça, {name} ! Je garde tout. Tenez, en voilà un pour vous."
L["Thanks, {name}! Here's yours back. Well, a new one. Hardly used."] = "Merci, {name} ! Je vous rends le vôtre. Enfin, un neuf. À peine servi."
L["My ears just went straight up, {name}. That means I'm very pleased."] = "Mes oreilles viennent de se dresser, {name}. Ça veut dire que je suis aux anges."
L["By tonight's campfire, {name}, this story will have a sandworm in it. Thanks!"] = "Au feu de camp ce soir, {name}, cette histoire aura un ver des sables. Merci !"
L["I'd gift-wrap yours, {name}, but all my wrapping is somebody's old map."] = "J'emballerais bien le vôtre, {name}, mais tout mon papier cadeau, c'est la carte d'un autre."
L["The alpacas saw that, {name}. They'll tell everyone how nice you are. Thanks!"] = "Les alpagas ont vu ça, {name}. Ils vont dire à tout le monde combien vous êtes gentil. Merci !"
L["Thank you, {name}! I'd give you my best button, but this is better. Slightly."] = "Merci, {name} ! J'aurais donné mon plus beau bouton, mais ceci est mieux. De peu."
L["Ooh, a present! Swapsies, {name}. Here's mine. No takebacks."] = "Oh, un cadeau ! Échange, {name} : voilà le mien. Donné, c'est donné !"
L["Thanks, {name}! That goes in the good pouch. Not the rock pouch. The good one."] = "Merci, {name} ! Ça va dans la bonne pochette. Pas celle à cailloux. La bonne."
L["In Vol'dun that would've cost a whole waterskin, {name}. Thank you!"] = "À Vol'dun, ça aurait coûté une outre entière, {name}. Merci !"
L["Thanks, {name}! Your name goes on the wagon. Between the alpaca and the dent."] = "Merci, {name} ! Votre nom ira sur le chariot. Entre l'alpaga et la bosse."
L["Kindness is the one thing the desert never buried, {name}. Thank you."] = "La bonté, le désert ne l'a jamais ensevelie, {name}. Merci."
L["Rakera says repay quick, {name}, before you forget which pocket it's in. Here!"] = "Rakera dit de rendre vite, {name}, avant d'oublier dans quelle poche c'est. Tenez !"
L["Nobody's given me anything I didn't dig up first, {name}. Thank you!"] = "Tout ce qu'on m'a donné, je l'avais déterré avant, {name}. Sauf ça. Merci !"
L["Of course, {name}! Shake the sand out and hold still."] = "Bien sûr, {name} ! Secouez le sable et ne bougez plus."
L["Coming right up, {name}! Caravan service, no waiting."] = "Ça arrive, {name} ! Service caravane, sans attente."
L["Sure, {name}! Let me dig it out... rope, rocks, a nice rock... here it is!"] = "Bien sûr, {name} ! Je le cherche... corde, cailloux, un joli caillou... le voilà !"
L["Hold on, {name}! Tail's in the way, one moment... there!"] = "Attendez, {name} ! La queue me gêne, un instant... voilà !"
L["One {buff}, {name}! Only slightly sandy."] = "{buff}, {name} ! Avec à peine un peu de sable."
L["Ask a vulpera and you'll get something, {name}. Usually odd. Not today!"] = "Demandez à un vulpérin, {name}, vous aurez quelque chose. Souvent bizarre. Pas aujourd'hui !"
L["Yours, {name}! Vulpera love giving things. Almost as much as finding them."] = "C'est à vous, {name} ! Les vulpérins adorent donner. Presque autant que trouver."
L["Here, {name}! Patched it up myself. Holds better than it looks."] = "Tenez, {name} ! Rafistolé moi-même. Ça tient mieux qu'on croit."
L["Sure, {name}! Stand upwind. Sandstorm last week; I'm still shedding it."] = "Bien sûr, {name} ! Restez au vent. Tempête de sable mardi ; j'en perds encore."
L["YES! Sorry, {name}, too loud? The desert's very big. You have to shout in it."] = "OUI ! Pardon, {name}, trop fort ? Le désert est très grand. Faut crier dedans."
L["Of course, {name}. Caravan rule: nobody asks twice for water or for help."] = "Bien sûr, {name}. Loi des caravanes : eau ou aide, on ne demande pas deux fois."
L["On it, {name}! Small spell, big fox, bigger ears. Wait. Other way round."] = "J'y vais, {name} ! Petit sort, grand renard, immenses oreilles. Non, l'inverse."
L["For you, {name}? Easy! Easier than getting sand out of an alpaca."] = "Pour vous, {name} ? Facile ! Plus facile que d'désensabler un alpaga."
L["Every traveller needs something for the road, {name}. I checked: not a rock."] = "Tout voyageur a besoin de quoi tenir la route, {name}. J'ai vérifié : ce n'est pas un caillou."
L["Keep this, {name}. The desert is long and the water is short."] = "Gardez ça, {name}. Le désert est long et l'eau est rare."
L["Found this lying around, {name}. Kidding! It's fresh. Take it!"] = "Trouvé ça par terre, {name}. Je plaisante ! C'est tout frais. Prenez !"
L["Here, {name}. Best thing in my pack, and I've got a lot of pack."] = "Tenez, {name}. Le meilleur truc de mon sac, et j'ai beaucoup de sac."
L["In the dunes you share your shade and your spells, {name}. Here."] = "Dans les dunes, on partage son ombre et ses sorts, {name}. Tenez."
L["Some {buff} for you, {name}. I'd haggle, but you look busy."] = "{buff} pour vous, {name}. Je marchanderais bien, mais vous avez l'air occupé."
L["A gift from the whole caravan, {name}! They'll never know."] = "Un cadeau de toute la caravane, {name} ! Ils n'en sauront jamais rien."
L["For the road, {name}. Roads are the best part. Roads, and snacks."] = "Pour la route, {name}. Les routes, c'est le meilleur. Les routes, et les en-cas."
L["Here, {name}! I swapped a hat for a thing, and the thing for this. Good trade!"] = "Tenez, {name} ! Un chapeau contre un truc, le truc contre ça. Bonne affaire !"
L["Nobody walks past anybody in the dunes, {name}. Bad luck, and rude. Here."] = "Dans les dunes, on n'ignore personne, {name}. Ça porte malheur, et c'est malpoli."
L["My nose says trouble's ahead of you, {name}. Take this. My nose is never wrong."] = "Mon flair sent des ennuis devant vous, {name}. Prenez ça. Il ne se trompe jamais."
L["Too many spells in my pack, {name}. They jingle. Take one, please."] = "Trop de sorts dans mon sac, {name}. Ça tinte. Prenez-en un, pitié."
L["If you find anything shiny later, {name}, you know where my ears are. Here!"] = "Si vous trouvez un truc qui brille, {name}, vous savez où sont mes oreilles. Tenez !"
L["Wait, {name}! You nearly left without this. Deserts eat people who do that."] = "Attendez, {name} ! Vous partiez sans ça. Le désert mange les gens qui font ça."
L["Stew's not ready yet, {name}, so this is the starter."] = "Le ragoût n'est pas prêt, {name}, alors voici l'entrée."
L["A fellow wanderer! The caravan is never far, {name}."] = "Un compagnon d'errance ! La caravane n'est jamais loin, {name}."
L["Ears up, {name}! Always nice to share a spell with a fellow fox."] = "Oreilles dressées, {name} ! Un sort entre renards, c'est toujours un plaisir."
L["One vulpera to another, {name}: I've three spare spoons if you need one."] = "Entre vulpérins, {name} : j'ai trois cuillères de rechange si besoin."
L["Vol'dun raised us both, {name}. Sand in the fur, luck in the pack."] = "Vol'dun nous a élevés, {name}. Sable dans la fourrure, chance dans le sac."
L["Ears to ears, {name}: between us we've heard everything said in this place."] = "Entre nos quatre oreilles, {name}, on a entendu tout ce qui s'est dit ici."
L["Remember the caravan fires, {name}? Everybody sang badly. It was perfect."] = "Les feux de caravane, {name} ! Tout le monde chantait faux. C'était parfait."
L["Vol'dun's far behind us, {name}. Half of it followed us here in our fur."] = "Vol'dun est loin, {name}. Enfin, la moitié nous a suivis dans la fourrure."
L["Caravan rules, {name}: stay together, share the water, nobody sells the alpaca."] = "Règles de la caravane, {name} : on reste ensemble, on partage l'eau, personne ne vend l'alpaga."
L["Anything shiny in there, {name}, I saw it first. Caravan law."] = "Tout ce qui brille là-dedans, {name}, je l'ai vu en premier. Loi de la caravane."
L["One for the party, {name}! A caravan's only as fast as its slowest alpaca."] = "Un pour le groupe, {name} ! Une caravane ne va pas plus vite que son alpaga le plus lent."
L["Keep your pack shut, {name}. I don't mean to take things. They follow me."] = "Gardez votre sac fermé, {name}. Je ne fais pas exprès de prendre des choses. Elles me suivent."
L["Lost in a city, {name}, never in a cave. Caves are just houses with no rent."] = "On se perd en ville, {name}, jamais dans une grotte. Une grotte, c'est une maison sans loyer."
L["I'm small, {name}, so I'll check the tiny tunnels. You lot take the big ones."] = "Petite taille, petits tunnels, {name} : je m'en charge. Vous autres, les grands."
L["Shout if you need anything, {name}. I've probably got it. It's probably dented."] = "Criez si besoin, {name}. Je l'ai sûrement. Sûrement cabossé."
L["I'll walk at the back and pick up whatever we drop, {name}. Finders keepers."] = "Je ferme la marche et je ramasse ce qui tombe, {name}. Qui trouve garde."
L["A caravan with no wagon, {name}! Very fast. Very light. Nowhere to nap."] = "Une caravane sans chariot, {name} ! Très rapide. Très légère. Zéro sieste."
L["Scouted ahead, {name}. By nose. Smells of danger and very old cheese."] = "Reconnaissance au flair, {name} : ça sent le danger, et un fromage très avancé."
L["Everybody fed? Everybody watered? Good. Now this, {name}. Caravan order."] = "Nourris ? Abreuvés ? Bien. Maintenant ceci, {name}. Ordre de caravane."
L["We vulpera travel by night, {name}. Cool sand, sleepy scorpids."] = "Nous, vulpérins, voyageons de nuit, {name}. Sable frais, scorpides endormis."
L["Desert nights get cold, {name}. Here, something warm-ish."] = "Les nuits du désert sont froides, {name}. Tenez, un truc presque chaud."
L["Stars out, {name}. Every one's a signpost if you know how to read it. I don't."] = "Les étoiles sont sorties, {name}. Chacune est un panneau, si on sait la lire. Moi, non."
L["Good hour for foxes, {name}. The ears work best when everything's quiet."] = "L'heure des renards, {name}. Quand tout se tait, les oreilles se régalent."
L["Past dark and I'm just waking up, {name}. In the dunes, noon's for napping."] = "La nuit tombe, je me lève, {name}. Dans les dunes, midi, c'est pour la sieste."
L["I'll curl up in my tail later, {name}. Best blanket I own. First, this."] = "Plus tard, en boule dans ma queue, {name}. Ma meilleure couette. D'abord, ceci."
L["A kindness returned is a kindness doubled, {name}."] = "Un bienfait rendu est un bienfait doublé, {name}."
L["Thank you, {name}. You have restored my balance."] = "Merci, {name}. Vous avez rétabli mon équilibre."
L["Somewhere, a Sha just went hungry. Thank you, {name}."] = "Quelque part, un sha vient de rester sur sa faim. Merci, {name}."
L["Thank you, {name}. Aysa would bow, Ji would cheer. I will do both, badly."] = "Merci, {name}. Aysa s'inclinerait, Ji applaudirait. Je vais faire les deux, mal."
L["Thank you, {name}. I will think of you at my next meal, and the one after."] = "Merci, {name}. Je penserai à vous à mon prochain repas, et au suivant."
L["Chen always said: never refuse a gift. Or a drink. Thank you, {name}."] = "Chen disait toujours : ne refuse jamais un cadeau. Ni un verre. Merci, {name}."
L["I was about to nap, {name}, but this is better. Slightly. Thank you."] = "J'allais faire la sieste, {name}, mais ceci est mieux. Un peu. Merci."
L["A hozen would have thrown something, {name}. I was raised better. Thank you."] = "Un hozen aurait jeté quelque chose, {name}. On m'a mieux élevé que ça. Merci."
L["That was very pandaren of you, {name}. All that's missing is a dumpling."] = "C'était très pandaren de votre part, {name}. Il ne manque qu'un ravioli."
L["At Halfhill that earns a prize turnip, {name}. I left mine at home. Thank you."] = "À Micolline, ça mérite un navet primé, {name}. Le mien est resté à la ferme. Merci."
L["Grandmother kept a jar of kindnesses, {name}. Yours goes in; this comes out."] = "Grand-mère avait un bocal à bontés, {name}. La vôtre y entre, ceci en sort."
L["Thank you, {name}. In the Jade Forest my door is open, and my pantry more so."] = "Merci, {name}. Dans la forêt de Jade, ma porte est ouverte, et ma table encore plus."
L["You move like the Shado-Pan, {name}. I never saw that coming. Thank you."] = "Vous bougez comme un Pandashan, {name}. Je ne l'ai pas vu venir. Merci."
L["Like rain on a rice paddy, {name}. The paddy never says thank you. I do."] = "Comme la pluie sur la rizière, {name}. La rizière ne dit jamais merci. Moi, si."
L["Thank you, {name}. Li Li would put this in her travel journal. With drawings."] = "Merci, {name}. Li Li mettrait ça dans son carnet de voyage. Avec des dessins."
L["Thank you, {name}. The August Celestials are busy, so I thank you for all four."] = "Merci, {name}. Les Astres vénérables sont occupés ; je vous remercie pour les quatre."
L["Stormstout ale knocks a pandaren flat, {name}. So did that. Thank you."] = "La bière Brune-d'Orage met un pandaren au tapis, {name}. Vous aussi. Merci."
L["Now we are square, {name}. The first time anyone has called a pandaren square."] = "Nous voilà quittes, c'est carré, {name}. Une première, pour un pandaren."
L["Of course, {name}. Patience, and it is done. Patience is the slow part."] = "Bien sûr, {name}. Un peu de patience, et c'est fait. La patience, c'est le plus long."
L["With pleasure, {name}. A kind deed is never wasted."] = "Avec plaisir, {name}. Une bonne action n'est jamais perdue."
L["At once, {name}. Quick for a pandaren, which is not saying much."] = "Tout de suite, {name}. Vite pour un pandaren, donc pas très vite."
L["Master Shang Xi said: help whoever asks, {name}. He also said: duck."] = "Maître Shang Xi disait : aide qui te le demande, {name}. Il disait aussi : baisse-toi."
L["A Tushui master would make you meditate first, {name}. I will skip that part."] = "Un maître Tushui vous ferait méditer d'abord, {name}. Je vais sauter cette étape."
L["Anything for you, {name}. Except the last dumpling. Let us not be silly."] = "Tout pour vous, {name}. Sauf le dernier ravioli. Ne soyons pas ridicules."
L["One {buff}, {name}, brewed strong. The recipe stays a secret."] = "{buff}, {name}, cuvée spéciale. La recette reste secrète."
L["Stand like a crane, {name}: one leg, calm face. Two legs is also fine."] = "Posture de la grue, {name} : une jambe, visage serein. Deux jambes, ça va aussi."
L["We never refuse a request, {name}. Only second helpings. No, not those either."] = "Un pandaren ne refuse jamais rien, {name}. Sauf de se resservir. Non, ça non plus."
L["The last to ask me for help, {name}, was an island-sized turtle. You're easier."] = "Dernière demande reçue, {name} : une tortue grande comme une île. Vous, c'est plus simple."
L["Pandaren help like we cook, {name}: slowly, generously, and far too much of it."] = "Nous aidons comme nous cuisinons, {name} : lentement, généreusement, et bien trop."
L["Certainly, {name}. Let me put down my bowl. ...There. That was the hard part."] = "Certainement, {name}. Je pose mon bol. ...Voilà. C'était le plus dur."
L["Yes, {name}. Grandfather said never make guests ask twice. He said it twice."] = "Oui, {name}. Grand-père disait : ne jamais faire redemander un invité. Il le redisait."
L["Hold still, {name}. I am calm, you are calm, the spell is calm. Nobody panic."] = "Ne bougez plus, {name}. Moi, calme. Vous, calme. Le sort, calme. Pas de panique."
L["Take this, {name}. And perhaps a cup of tea afterward?"] = "Prenez ceci, {name}. Et peut-être une tasse de thé ensuite ?"
L["Balance in all things, {name}. Now go with a light heart."] = "L'équilibre en toute chose, {name}. Allez, le cœur léger."
L["Take this, {name}. A grummle would sell it to you for a luckydo."] = "Prenez ceci, {name}. Un grummel vous le vendrait contre un porte-bonheur."
L["The jinyu say the waters foretold this, {name}. They say that a lot."] = "Les jinyu disent que les eaux l'avaient prédit, {name}. Ils disent ça souvent."
L["The Huojin say act first. The Tushui say think first. I say: here, {name}."] = "Les Huojin disent : agis d'abord. Les Tushui : réfléchis d'abord. Moi : tenez, {name}."
L["A pandaren stood up to give you this, {name}. Treasure it."] = "Un pandaren s'est levé pour vous donner ça, {name}. Chérissez-le."
L["Fight like a monk, {name}: calm, quick, and then a long lunch."] = "Battez-vous comme un moine, {name} : calme, vif, et ensuite un long déjeuner."
L["Go gently, {name}. The turtle got where it was going and never hurried once."] = "Rien ne sert de courir, {name}. La tortue est arrivée sans jamais se presser."
L["You looked like you needed a hug, {name}. This is next best, and less furry."] = "Vous aviez besoin d'un câlin, {name}. Voilà presque aussi bien, en moins poilu."
L["If a fight finds you, {name}, roll away. Rolling is very underrated."] = "Un combat vous tombe dessus, {name} ? Roulade. C'est très sous-estimé."
L["For you, {name}. It is warm, round and full of good intentions. Like me."] = "Pour vous, {name}. C'est chaud, rond et plein de bonnes intentions. Comme moi."
L["Take this, {name}. My kite is stuck in a tree, so I have time for good deeds."] = "Tenez, {name}. Cerf-volant coincé dans un arbre, alors je fais le bien en attendant."
L["I carried this from Pandaria, {name}. Also a keg. The keg is mine."] = "J'ai rapporté ça de Pandarie, {name}. Et un fût. Le fût, il est à moi."
L["The virmen stole my carrots, {name}, but this they will never get. Here."] = "Un virmen a volé mes carottes, {name}, mais ceci, jamais. Tenez."
L["On the Wandering Isle, {name}, strangers get soup. This travels better."] = "Sur l'île Vagabonde, {name}, l'étranger a droit à la soupe. Ceci voyage mieux."
L["Pandaren look soft, {name}. So does a sack of rice, until it lands on you."] = "On nous croit mous, {name}. Comme un sac de riz, avant qu'il vous tombe dessus."
L["Chi-Ji says there is always hope, {name}. I say there is always a spare. Here."] = "Pour Chi-Ji, il y a toujours de l'espoir, {name}. Pour moi, toujours du rab. Tenez."
L["We must share a brew when the road allows, {name}!"] = "Il faudra partager une bière quand la route le permettra, {name} !"
L["Shen-zin Su would be proud of us both, {name}. Or asleep. Hard to tell."] = "Shen-zin Su serait fier de nous deux, {name}. Ou endormi. Difficile à dire."
L["Two pandaren together, {name}. Somewhere, an innkeeper just felt a chill."] = "Deux pandarens ensemble, {name}. Quelque part, un aubergiste vient de frissonner."
L["Liu Lang would approve, {name}: two of us, both a long way from home."] = "Liu Lang approuverait, {name} : nous deux, bien loin de chez nous."
L["Tushui or Huojin, {name}, we both left the turtle, and we both miss the food."] = "Tushui ou Huojin, {name}, nous avons quitté la tortue, et sa cuisine nous manque."
L["One pandaren to another, {name}: the brews out here are thin. Share mine later."] = "Entre pandarens, {name} : ici, la bière est de l'eau. On partagera la mienne."
L["We both smell of rice wine and road dust, {name}. The smell of home."] = "Vin de riz et poussière de la route, {name} : on sent tous deux la maison."
L["Pandaren look after pandaren, {name}. Mostly by feeding them. This comes first."] = "Un pandaren veille sur les siens, {name}. Surtout en les nourrissant. Ceci en entrée."
L["A fight, then a meal, {name}. That is the correct order. Never the reverse."] = "Un combat, puis un repas, {name}. C'est l'ordre correct. Jamais l'inverse."
L["Stay together, {name}, like dumplings in a steamer. Warm, and ready."] = "Restons ensemble, {name}, comme des raviolis dans un panier vapeur. Au chaud, et prêts."
L["We move as one, {name}. Slowly, perhaps, but as one."] = "On avance comme un seul homme, {name}. Lentement, mais comme un seul."
L["Balance, {name}: one fights, one heals, and one carries the snacks. Me."] = "Équilibre, {name} : l'un combat, l'autre soigne, et le troisième porte les en-cas. Moi."
L["If we fall, {name}, we fall together, and then we nap. Let us not."] = "Si nous tombons, {name}, nous tombons ensemble, et puis on fait la sieste. Évitons."
L["Stay behind me, {name}. I am soft, but I am very wide."] = "Derrière moi, {name}. Peu de muscle, beaucoup de largeur."
L["If we win, {name}, I will cook. If we lose, I will also cook, but sadly."] = "Si on gagne, {name}, je cuisine. Si on perd, je cuisine aussi, mais tristement."
L["Everyone breathe, {name}. In, and out. Now hit things, calmly."] = "Respirez, {name}. Inspirez, expirez. Et maintenant, frappez. Calmement."
L["Keep up, {name}. I am in a hurry. It happens to pandaren about once a decade."] = "Suivez, {name}, j'ai hâte. Chez un pandaren, ça arrive tous les dix ans."
L["A party is like a brew, {name}: odd ingredients, wonderful together. Mostly."] = "Un groupe, c'est une bière, {name} : drôles d'ingrédients, bon mélange. En général."
L["If I fall, {name}, roll me somewhere safe. Carrying me is not an option."] = "Si je tombe, {name}, roulez-moi à l'abri. Me porter n'est pas une option."
L["Pandaren fight like water, {name}: calm, patient, and then suddenly everywhere."] = "Un pandaren se bat comme l'eau, {name} : calme, patient, puis soudain partout."
L["Up before the tea, {name}? Brave. Here, instead of the tea."] = "Debout avant le thé, {name} ? Courageux. Tenez, à la place du thé."
L["Morning, {name}. First this, then breakfast, then the second breakfast."] = "Bonjour, {name}. D'abord ceci, puis le petit-déjeuner, puis le second petit-déjeuner."
L["A new day, {name}, and nobody has spilled anything yet. Let us begin gently."] = "Un nouveau jour, {name}, et personne n'a encore rien renversé. Commençons doucement."
L["Halfhill's farmers have been up for hours, {name}. I have been up for minutes."] = "À Micolline, on est debout depuis des heures, {name}. Moi, depuis des minutes."
L["Morning mist, {name}. It looked just like home. Then a kobold walked by."] = "Brume matinale, {name}. On se serait cru chez nous. Puis un kobold est passé."
L["Good morning, {name}. My stomach woke first and has been giving orders since."] = "Bonjour, {name}. Mon estomac s'est réveillé le premier et donne des ordres depuis."
L["Past my first nap, {name}, and before my second. Quickly, while I'm awake."] = "Après ma première sieste, {name}, et avant la deuxième. Vite, pendant que j'ai les yeux ouverts."
L["Late, {name}. The brewmasters are asleep. The brews, I suspect, are not."] = "Il est tard, {name}. Les maîtres brasseurs dorment. Les brassins, eux, travaillent encore."
L["Midnight snack time, {name}. This is the appetiser."] = "Casse-croûte de minuit, {name}. Ceci, c'est l'amuse-bouche."
L["Dark already, {name}? Back home, Grandfather's stories would just be starting."] = "Déjà nuit, {name} ? Chez nous, les histoires de Grand-père commenceraient à peine."
L["The moon is round and full tonight, {name}. We have a great deal in common."] = "La lune est ronde et pleine ce soir, {name}. Nous avons beaucoup en commun."
L["Your kindness is noted, {name}. Dragons do not forget."] = "Votre bonté est notée, {name}. Les dragons n'oublient pas."
L["Thank you, {name}. Returned on swift wings."] = "Merci, {name}. Je vous la rends à tire-d'aile."
L["Wings, fire and scales, {name}, and still you thought I needed help. Touching."] = "Ailes, feu et écailles, {name}, et vous pensiez encore que j'avais besoin d'aide. Touchant."
L["I would bow, {name}, but last time my wings cleared a table. Thank you."] = "Je m'inclinerais bien, {name}, mais la dernière fois, mes ailes ont vidé une table. Merci."
L["That goes straight into my hoard, {name}. Kind deeds are the only gold I keep."] = "Ça va droit dans mon trésor, {name}. Les bonnes actions sont le seul or que je garde."
L["I was made to be a weapon, {name}. I much prefer this part. Thank you."] = "On a fait de moi une arme, {name}. Je préfère de loin ce rôle-ci. Merci."
L["Thank you, {name}. Wrathion would have made a speech of it. I will not."] = "Merci, {name}. Wrathion en aurait fait un discours. Moi, non."
L["Returned with a little fire in it, {name}. Only a little. I am practising."] = "Je vous le rends avec une pointe de feu, {name}. Juste une pointe. Je m'entraîne."
L["A mortal gift, {name}: small, brief and kind. I am learning to like all three."] = "Un cadeau de mortel, {name} : petit, bref et gentil. J'apprends à aimer les trois."
L["Thank you, {name}. Mortal customs are new to me. Do I pay you? No? Then this."] = "Merci, {name}. Je découvre les usages des mortels. Je vous paie ? Non ? Alors ceci."
L["Thank you, {name}. I have scales where most have feelings. That got through."] = "Merci, {name}. J'ai des écailles là où d'autres ont des sentiments. Ça a percé."
L["You're on my list of favourite mortals, {name}. It was empty until today."] = "Vous voici sur ma liste de mortels préférés, {name}. Elle était vide jusqu'ici."
L["The red in me is grateful, {name}. The black in me is suspicious. The red wins."] = "Mon côté rouge vous remercie, {name}. Mon côté noir se méfie. Le rouge l'emporte."
L["Thank you, {name}. My wings would clap, but wings don't do that. I checked."] = "Merci, {name}. Mes ailes applaudiraient, mais ça ne marche pas. J'ai essayé."
L["A dragon's thanks comes with a roar, {name}. I will spare the neighbours."] = "Un dragon remercie d'un rugissement, {name}. Je vais épargner les voisins."
L["Very well, {name}. Stand still, I would hate to singe you."] = "Très bien, {name}. Ne bougez pas, je m'en voudrais de vous roussir."
L["Granted, {name}. A dragon keeps its word."] = "Accordé, {name}. Un dragon tient parole."
L["Certainly, {name}. Stand clear of the tail."] = "Certainement, {name}. Écartez-vous de la queue."
L["Of course, {name}. Is this still how it is done? I was asleep for a while."] = "Bien sûr, {name}. Est-ce encore ainsi que l'on procède ? J'ai fait une longue sieste."
L["Gladly, {name}. All five dragonflights are in me, and all five say yes."] = "Volontiers, {name}. Les cinq vols draconiques sont en moi, et tous disent oui."
L["Right away, {name}. Dragon-sized help, in a conveniently smaller form."] = "Tout de suite, {name}. Une aide digne d'un dragon, en format de poche."
L["Of course, {name}. Neltharion only gave orders. A request is much nicer."] = "Bien sûr, {name}. Neltharion ne savait qu'ordonner. Une demande, c'est plus aimable."
L["Right away, {name}. Stand back a little; I am still learning how big I am."] = "Tout de suite, {name}. Reculez un peu : je découvre encore mon gabarit."
L["Certainly, {name}. Hold still. I have excellent aim and very little practice."] = "Certainement, {name}. Ne bougez pas. Visée excellente, entraînement quasi nul."
L["Of course, {name}. Dragons usually demand tribute. I'm waiving it, this once."] = "Bien sûr, {name}. Un dragon exige un tribut, d'habitude. Pour cette fois, c'est offert."
L["Of course, {name}. Please don't scream. Mortals often do. It's the horns."] = "Bien sûr, {name}. Ne hurlez pas, les mortels le font souvent. À cause des cornes."
L["My breath is fire, {name}, so we will do this the other way."] = "Mon souffle est de feu, {name}, alors on va faire autrement."
L["Gladly, {name}. In my day... no. I promised to stop saying 'in my day'. Here."] = "Volontiers, {name}. De mon temps... Non, j'ai juré d'arrêter ça. Voilà."
L["A small magic, {name}, but I cast it with enormous dignity."] = "Une petite magie, {name}, mais lancée avec une immense dignité."
L["Take this, {name}. Even a dragon needs allies. Especially one this size."] = "Prenez ceci, {name}. Même un dragon a besoin d'alliés. Surtout de ce gabarit."
L["A gift from the Dragon Isles, {name}. Fly well."] = "Un présent des Îles aux Dragons, {name}. Bon vol."
L["Alexstrasza says every life is precious, {name}. I am starting with yours."] = "Alexstrasza dit que chaque vie est précieuse, {name}. Je commence par la vôtre."
L["I slept through ten thousand years of good deeds, {name}. Catching up now."] = "J'ai dormi pendant dix mille ans de bonnes actions, {name}. Je rattrape mon retard."
L["Tell them a dragon did this, {name}. It sounds far grander than it was."] = "Dites que c'est l'œuvre d'un dragon, {name}. C'est plus grandiose que la réalité."
L["Scalecommander's orders, {name}. I am not a Scalecommander, but still."] = "Ordre du Squammandant, {name}. Je ne suis pas Squammandant, mais tout de même."
L["Take this, {name}. Ancient dragon magic, only slightly out of date."] = "Prenez ceci, {name}. Magie draconique antique, à peine périmée."
L["A dragon giving, {name}, not taking. I am trying something new."] = "Un dragon qui donne, {name}, au lieu d'amasser. J'innove."
L["In visage form I look harmless, {name}. So did Lady Prestor. I really am."] = "Sous ce visage, j'ai l'air sans danger, {name}. Dame Prestor aussi. Moi, c'est vrai."
L["A gift from above, {name}. I landed specially. It took two tries."] = "Un cadeau tombé du ciel, {name}. J'ai atterri exprès. En deux essais."
L["Here, {name}. Every dragon should guard something. I have chosen you, for now."] = "Tenez, {name}. Tout dragon garde un trésor. Pour l'instant, c'est vous."
L["Take this, {name}. It's from five dragonflights, so it clashes with everything."] = "Prenez ceci, {name}. Cinq vols draconiques dedans : ça jure avec tout."
L["I'd fly you there myself, {name}, but I'm told that is 'kidnapping'. Take this."] = "Je vous y porterais bien, {name}, mais on appelle ça un « enlèvement ». Tenez."
L["Dragons gifted the world at its dawn, {name}. Mine is smaller, and later."] = "Les dragons ont comblé le monde naissant, {name}. Moi, en plus petit, et en retard."
L["A little essence for you, {name}. It is what I'm made of, so handle it gently."] = "Un peu d'essence pour vous, {name}. C'est ce qui me compose : maniez-la avec soin."
L["Take this, {name}. It will feel warm. Most things do, after I touch them."] = "Prenez ceci, {name}. Ce sera chaud. Comme presque tout ce que je touche."
L["The Forbidden Reach feels far behind us now, {name}."] = "Les Confins Interdits semblent bien loin derrière nous, {name}."
L["Two dracthyr in one place, {name}. Mind the wings; there is not room for four."] = "Deux dracthyrs ici, {name}. Gare aux ailes : pas de place pour quatre."
L["Remember when the whole world was new to us, {name}? It still is, mostly."] = "Vous rappelez-vous quand tout nous était nouveau, {name} ? Presque tout l'est encore."
L["In visage form nobody can tell, {name}. Between us: we look better in scales."] = "En forme anthropique, nul ne devine, {name}. Entre nous, les écailles nous vont mieux."
L["Made for war, {name}, and look at us: sharing. Somebody's plans went wrong."] = "Créés pour la guerre, {name}, et voilà qu'on partage. Un certain plan a mal tourné."
L["Visage or scales, {name}, I would know one of us anywhere. It is the posture."] = "Visage ou écailles, {name}, je reconnais les nôtres partout. C'est la posture."
L["Mortals always ask us the same thing, {name}: will we fly them. Still no."] = "Les mortels veulent tous la même chose, {name} : un tour en vol. Toujours non."
L["Between two dracthyr, {name}: the horns never get any easier with hats."] = "Entre dracthyrs, {name} : avec des cornes, les chapeaux, c'est toujours l'enfer."
L["Tell me when to breathe fire, {name}. And, please, when not to."] = "Dites-moi quand cracher du feu, {name}. Et surtout, quand ne pas le faire."
L["I woke in a cave full of strangers, {name}. This is far better company."] = "Mon réveil ? Une grotte pleine d'inconnus, {name}. Ici, la compagnie est bien meilleure."
L["Neltharion made us to fight alone, {name}. We have improved on him."] = "Neltharion nous a créés pour combattre seuls, {name}. Nous avons fait mieux que lui."
L["Stay clear of my tail, {name}. It hasn't yet learned whose side it's on."] = "Écartez-vous de ma queue, {name}. Elle ne sait pas encore dans quel camp elle est."
L["A flight of our own, {name}. So this is what the dragons meant."] = "Notre propre vol, {name}. Voilà donc ce que voulaient dire les dragons."
L["If I say 'take cover', {name}, I mean behind my wings. They are good for that."] = "Si je dis « à couvert », {name}, c'est derrière mes ailes. Elles sont faites pour ça."
L["Stand beside me, {name}, never in front. I cannot aim my breath politely."] = "À côté de moi, {name}, jamais devant. Mon souffle ignore la politesse."
L["Leave the big ones to me, {name}. Well, the ones smaller than me. That is most."] = "Laissez-moi les gros, {name}. Enfin, ceux plus petits que moi. Soit presque tous."
L["Stay close, {name}. I can glide us all down from anywhere. Up is your problem."] = "Restez près, {name}. La descente en planant, c'est moi. La montée, c'est vous."
L["Keep moving, {name}. A dragon in a hurry is grand. One waiting is just big."] = "Avançons, {name}. Un dragon en marche, c'est grandiose. À l'arrêt, c'est juste gros."
L["Tell me the plan slowly, {name}. I was made for battles, not for plans."] = "Le plan, lentement, {name}. Les batailles, je connais. Les plans, moins."
L["Mortals live so briefly, {name}. Let us not make today any shorter."] = "Les mortels vivent si peu, {name}. N'écourtons pas la journée."
L["It is good to see one of our own, {name}."] = "Quel plaisir de voir l'un des nôtres, {name}."
L["Our people are few, {name}. That makes each of us count."] = "Nous sommes peu nombreux, {name}. Chacun de nous compte d'autant plus."
L["Thank you, {name}. The Alliance looks after its own, and today that's me."] = "Merci, {name}. L'Alliance veille sur les siens, et aujourd'hui, c'est moi."
L["Kindness answered, {name}. For the Alliance!"] = "Bonté rendue, {name}. Pour l'Alliance !"
L["Stormwind has a statue for every hero, {name}. I'm putting in a word for yours."] = "Hurlevent a une statue pour chaque héros, {name}. Je glisserai un mot pour la vôtre."
L["The Alliance way, {name}: you help me, I help you, a dwarf buys the drinks."] = "La méthode de l'Alliance, {name} : vous m'aidez, je vous aide, un nain paie la tournée."
L["Genn would growl, Muradin would hug, {name}. I'll just return it."] = "Genn grognerait, Muradin vous étreindrait, {name}. Moi, je rends la politesse."
L["If the Alliance gave medals for manners, {name}, you'd need a second tabard."] = "Si l'Alliance décorait la politesse, {name}, il vous faudrait un second tabard."
L["Returned in full, {name}. An ally who gives first is worth a whole garrison."] = "Je vous rends la pareille, {name}. Un allié qui donne le premier vaut tout un fief."
L["Thank you, {name}. I'll mention you in my letter home. Mother reads them aloud."] = "Merci, {name}. Je parlerai de vous dans ma lettre. Mère les lit à voix haute."
L["The Lion's Pride will hear of this, {name}. At length. Thank you."] = "La Fierté du lion en entendra parler, {name}. Longuement. Merci."
L["The Alliance at its finest, {name}: nobody asked, somebody helped. Thanks."] = "Le meilleur de l'Alliance, {name} : personne ne demande, quelqu'un aide. Merci."
L["I'll tell everyone on the Deeprun Tram, {name}. It's a long tram. Thank you."] = "Je le raconterai à tout le tram des profondeurs, {name}. C'est un long tram. Merci."
L["Most gallant, {name}. If I had a lion on my tabard, it would be purring."] = "Très galant, {name}. Si j'avais un lion sur mon tabard, il ronronnerait."
L["Our kings bicker, {name}, but their people get on splendidly. Thank you."] = "Nos rois se chamaillent, {name}, leurs peuples s'entendent à merveille. Merci."
L["The Alliance was forged by folk keeping their word, {name}. Here's mine."] = "L'Alliance a été forgée par des gens de parole, {name}. Voici la mienne."
L["Of course, {name}. Allies help each other. It's practically in the name."] = "Naturellement, {name}. Entre alliés, on s'entraide. C'est presque dans le nom."
L["At once, {name}. The Alliance does not leave a friend wanting."] = "Sur-le-champ, {name}. L'Alliance n'abandonne pas un ami dans le besoin."
L["Of course, {name}. It's in the Alliance charter. Somewhere near the back."] = "Bien sûr, {name}. C'est dans la charte de l'Alliance. Quelque part vers la fin."
L["By order of the Alliance, {name}: one {buff}, effective at once."] = "Par ordre de l'Alliance, {name} : {buff}, avec effet immédiat."
L["Anything for an ally, {name}. Within reason. This is well within reason."] = "Tout pour un allié, {name}. Dans la limite du raisonnable. Et ceci l'est largement."
L["Right away, {name}. SI:7 knew you would ask. I only just found out."] = "Tout de suite, {name}. Le SI:7 savait que vous demanderiez. Moi, je l'apprends."
L["Straight away, {name}. The Alliance marches on requests like yours. And bread."] = "Tout de suite, {name}. L'Alliance marche aux demandes comme la vôtre. Et au pain."
L["Yes, {name}. From Stormwind to Ironforge, 'please' opens every gate."] = "Oui, {name}. De Hurlevent à Forgefer, la politesse ouvre toutes les portes."
L["Right away, {name}. I've worn the blue all day hoping somebody would ask."] = "Tout de suite, {name}. En bleu toute la journée, j'attendais qu'on me le demande."
L["Hold still, {name}. I learned this faster than the Alliance anthem."] = "Ne bougez pas, {name}. J'ai appris ça plus vite que l'hymne de l'Alliance."
L["Of course, {name}. Armies win wars; small favours win allies. Here's one."] = "Bien sûr, {name}. Une armée gagne des guerres ; un petit geste, des alliés. Voilà."
L["For the Alliance, {name}! Stay strong out there. Stronger, now."] = "Pour l'Alliance, {name} ! Restez fort là-dehors. Plus fort, désormais."
L["Onward, {name}. The Alliance is with you."] = "En avant, {name}. L'Alliance est avec vous."
L["Take this, {name}. Had a gnome made it, it would come with twelve levers."] = "Prenez ceci, {name}. Si un gnome l'avait fabriqué, il aurait douze leviers."
L["Compliments of the Alliance, {name}. We've done these since the Second War."] = "Avec les compliments de l'Alliance, {name}. On fait ça depuis la Deuxième Guerre."
L["Chin up, {name}. Somewhere in Stormwind, a bard is writing about this."] = "Haut les cœurs, {name}. Quelque part à Hurlevent, un barde écrit déjà là-dessus."
L["Every ally counts, {name}. I counted, actually. You're my favourite so far."] = "Chaque allié compte, {name}. J'ai compté. Vous êtes mon préféré, pour l'instant."
L["Anduin would want me to share, {name}, and I'd hate to disappoint him."] = "Anduin voudrait que je partage, {name}, et je m'en voudrais de le décevoir."
L["Take this, {name}. Stormwind's walls can't follow you, so this will have to."] = "Tenez, {name}. Les murs de Hurlevent ne vous suivront pas ; ceci, si."
L["Here, {name}. The gryphons get you there; this gets you back."] = "Tenez, {name}. Les griffons vous y emmènent ; ceci vous en ramène."
L["Alliance rule, {name}: keep your word, your walls, your friends. Here, friend."] = "Règle de l'Alliance, {name} : on garde sa parole, ses murs, ses amis. Tenez, l'ami."
L["Every ally deserves a lion at their back, {name}. I'm the nearest lion."] = "Chaque allié mérite un lion dans son dos, {name}. Le plus proche, c'est moi."
L["A gift from the Alliance, {name}. Signed, sealed and hand-delivered."] = "Un cadeau de l'Alliance, {name}. Signé, scellé et remis en main propre."
L["The Alliance never forgets the brave, {name}. Give it something to remember."] = "L'Alliance n'oublie jamais les braves, {name}. Donnez-lui de quoi se souvenir."
L["Together we stand, {name}. For the Alliance!"] = "Unis, nous tiendrons, {name}. Pour l'Alliance !"
L["Right, {name}: shields up, heads down, and nobody charges before the plan does."] = "Bien, {name} : boucliers levés, têtes baissées, et personne ne charge avant le plan."
L["The finest company the Alliance ever fielded, {name}. Or at least the nearest."] = "La plus belle compagnie jamais alignée par l'Alliance, {name}. Ou du moins la plus proche."
L["Together, {name}, we're practically a regiment. A small, well-dressed regiment."] = "Ensemble, {name}, nous sommes presque un régiment. Un petit régiment très élégant."
L["Watch each other's backs, {name}. The Alliance was built by people who did."] = "Veillez les uns sur les autres, {name}. C'est ainsi qu'on a bâti l'Alliance."
L["Shields together, {name}. The Alliance never won anything in single file."] = "Boucliers serrés, {name}. L'Alliance n'a jamais rien gagné en file indienne."
L["If this goes in the history books, {name}, let's be a chapter, not a footnote."] = "Si l'Histoire en parle, {name}, soyons un chapitre, pas une note en bas de page."
L["Whoever carries the banner, {name}, gets painted looking noble. Volunteers?"] = "Le porte-étendard, {name}, finit en portrait, l'air noble. Des volontaires ?"
L["Dwarven nerve, elven patience, human stubbornness, {name}: the Alliance recipe."] = "Cran de nain, patience d'elfe, entêtement humain, {name} : la recette de l'Alliance."
L["Keep the lion roaring, {name}. Softly, mind. We're sneaking."] = "Que le lion rugisse, {name}. Tout bas, par contre. On se faufile."
L["Strength and honour, {name}. And kindness, it turns out. Repaid in full."] = "Force et honneur, {name}. Et bonté aussi, il faut croire. Rendue en entier."
L["The Horde takes care of its own, {name}."] = "La Horde prend soin des siens, {name}."
L["Strength given, strength returned, {name}. That's all of Horde diplomacy."] = "Force donnée, force rendue, {name}. C'est toute la diplomatie de la Horde."
L["I'd carve your name on Orgrimmar's gates, {name}, but they're full. Thanks."] = "Je graverais votre nom aux portes d'Orgrimmar, {name}, mais c'est complet. Merci."
L["Gallywix would've sent you an invoice, {name}. I'm sending this instead."] = "Gallywix vous aurait envoyé une facture, {name}. Moi, je vous envoie ceci."
L["You did not have to do that, {name}. That is why the Horde remembers it."] = "Rien ne vous y obligeait, {name}. C'est pour ça que la Horde s'en souvient."
L["In the Horde we do not say thank you twice, {name}. So: once, and meant."] = "Dans la Horde, on ne dit pas merci deux fois, {name}. Donc : une fois, et sincère."
L["In the Horde a debt is carried like an axe, {name}: openly, and not for long."] = "Dans la Horde, une dette se porte comme une hache, {name} : en vue, et pas longtemps."
L["The gate grunts will hear of you, {name}. They'll grunt. It means respect."] = "Je le dirai aux grunts de la porte, {name}. Ils grogneront. C'est du respect."
L["The Horde keeps two lists, {name}: grudges and favours. Yours is the short one."] = "La Horde tient deux listes, {name} : rancunes et faveurs. Vous êtes sur la courte."
L["Honour says repay you, {name}. Manners say smile. I'm working on the smile."] = "L'honneur dit de rendre, {name}. La politesse, de sourire. Le sourire, j'y travaille."
L["That landed softer than any zeppelin I've ridden, {name}. Thank you."] = "Atterrissage plus doux que tous mes zeppelins, {name}. Merci."
L["Thanks, {name}, in Orcish, Zandali, Thalassian and Gutterspeak. Pick one."] = "Merci, {name}, en orc, en zandali, en thalassien et en bas-parler. Choisissez."
L["Thrall taught the Horde honour, {name}. Nobody had to teach you. Thank you."] = "Thrall a appris l'honneur à la Horde, {name}. Vous, c'était inné. Merci."
L["You gave first, {name}. In the Horde that earns first cut of the roast. Here."] = "Donné en premier, {name} : dans la Horde, ça vaut la première part du rôti. Tenez."
L["The Warchief can't thank everyone himself, {name}. He's delegated it to me."] = "Le chef de guerre ne peut remercier chacun, {name}. Il me l'a délégué."
L["Consider it done, {name}. For the Horde, and for anyone who asks nicely."] = "Considérez que c'est fait, {name}. Pour la Horde, et pour qui demande poliment."
L["You only had to ask, {name}. The Horde answers."] = "Il suffisait de demander, {name}. La Horde répond présent."
L["The Horde usually helps with axes, {name}. Today, {buff}."] = "D'habitude, la Horde aide à coups de hache, {name}. Aujourd'hui, {buff}."
L["Done, {name}. No speeches. The Horde has plenty of those already."] = "C'est fait, {name}. Pas de discours. La Horde en a déjà bien assez."
L["You asked, {name}. In Orgrimmar, that counts as a formal treaty."] = "Vous avez demandé, {name}. À Orgrimmar, ça vaut un traité en bonne et due forme."
L["Asking is no weakness, {name}. Refusing an ally would be."] = "Demander n'est pas une faiblesse, {name}. Refuser à un allié en serait une."
L["No need to bang a war drum, {name}. You asked; it's done."] = "Inutile de battre le tambour, {name}. Vous demandez, c'est fait."
L["Of course, {name}. In the Horde, 'please' outranks everyone but the Warchief."] = "Bien sûr, {name}. Dans la Horde, seul le chef de guerre passe avant « s'il vous plaît »."
L["In Orgrimmar we'd have argued about it first, {name}. Tradition. Here."] = "À Orgrimmar, on en aurait débattu d'abord, {name}. Tradition oblige. Tenez."
L["Consider it requisitioned, {name}. The quartermaster needn't hear about it."] = "C'est réquisitionné, {name}. Inutile d'en parler à l'intendant."
L["Done, {name}. If anyone asks, I scowled the whole time. I've a reputation."] = "C'est fait, {name}. Si on demande, j'ai grimacé tout du long. J'ai une réputation."
L["Of course, {name}. Horde hospitality: rough edges, full helpings."] = "Bien sûr, {name}. L'accueil de la Horde : brut de décoffrage, mais copieux."
L["The Horde came together because somebody always said yes, {name}. Yes."] = "La Horde s'est formée parce que quelqu'un a toujours dit oui, {name}. Oui."
L["For the Horde, {name}! Go with strength. I've just handed you some."] = "Pour la Horde, {name} ! Allez-y avec force. Je viens de vous en donner."
L["Go with honour, {name}. Victory awaits."] = "Partez avec honneur, {name}. La victoire vous attend."
L["Go and do something worth a song, {name}. Loud songs. The Horde likes loud."] = "Faites quelque chose qui mérite une chanson, {name}. Bruyante. La Horde aime le bruit."
L["Walk tall, {name}. The Horde always made room for those the world turned away."] = "Marchez la tête haute, {name}. La Horde a toujours accueilli ceux que le monde rejetait."
L["Take this, {name}, and a word of Horde wisdom: hit first, apologise never."] = "Prenez ceci, {name}, et une sagesse de la Horde : frapper d'abord, s'excuser jamais."
L["Victory or death, {name}. I'd prefer victory, so take this."] = "La victoire ou la mort, {name}. Je préfère la victoire, alors prenez ceci."
L["Like a mak'gora, {name}, except everybody wins. Here."] = "Comme un mak'gora, {name}, sauf que tout le monde gagne. Tenez."
L["For the Horde, {name}, and for you. The Horde's big; you're closer."] = "Pour la Horde, {name}, et pour vous. La Horde est vaste ; vous, plus proche."
L["Here, {name}. Stronger together, they say, and I've just done my half."] = "Tenez, {name}. Plus forts ensemble, dit-on, et je viens de faire ma moitié."
L["Carry this, {name}. It weighs less than a Horde banner and flies just as proud."] = "Portez ceci, {name}. Plus léger qu'une bannière de la Horde, et tout aussi fier."
L["Here, {name}. The Horde feeds its own, arms its own, and now enchants them."] = "Tenez, {name}. La Horde nourrit les siens, les arme, et désormais les enchante."
L["Take this, {name}. Whatever's out there is about to meet the Horde."] = "Prenez ceci, {name}. Ce qui rôde là-dehors va bientôt rencontrer la Horde."
L["Here, {name}. Wherever you're headed, arrive looking like the Horde sent you."] = "Tenez, {name}. Où que vous alliez, arrivez comme si la Horde vous envoyait."
L["The Crossroads never turned a traveller away, {name}. It overcharged a few."] = "La Croisée n'a jamais refusé un voyageur, {name}. Elle en a plumé quelques-uns."
L["The Horde raises you tough, {name}. This is for the days tough isn't enough."] = "La Horde vous endurcit, {name}. Ceci, pour les jours où ça ne suffit pas."
L["Take this, {name}. A Horde gift: no ribbon, no speech, no refunds."] = "Cadeau de la Horde, {name} : ni ruban, ni discours, ni repris ni échangé."
L["Stand tall, {name}. Taller than that. The Horde has tauren to keep up with."] = "Redressez-vous, {name}. Plus haut. Dans la Horde, on se mesure aux taurens."
L["Our strength is each other, {name}. For the Horde!"] = "Notre force, c'est notre union, {name}. Pour la Horde !"
L["Forward, {name}. The Horde advances together. Retreats... never, officially."] = "En avant, {name}. La Horde avance unie. Elle recule... jamais, officiellement."
L["Together we're a war band, {name}. Apart, we're just loud."] = "Ensemble, nous sommes un clan de guerre, {name}. Séparés, juste du bruit."
L["Shoulder to shoulder, {name}. Whoever charges first buys the grog."] = "Coude à coude, {name}. Le premier qui charge paie le grog."
L["Nobody gets left behind, {name}. I've counted us twice."] = "Personne ne reste en arrière, {name}. J'ai compté deux fois."
L["Rule of the warband, {name}: nobody eats until everybody's back."] = "Loi du clan, {name} : on ne mange qu'une fois tout le monde rentré."
L["Drums up, {name}. If we can't be quiet, we'll be terrifying."] = "Tambours prêts, {name}. À défaut d'être discrets, soyons terrifiants."
L["The Horde never won a thing alone, {name}. Let's not start now."] = "La Horde n'a jamais rien gagné en solo, {name}. On ne va pas commencer."
L["We fight like the Horde, {name}: all at once, and nobody waits for the signal."] = "On se bat façon Horde, {name} : tous d'un coup, et personne n'attend le signal."
L["Right, {name}. Loot shared, blame shared, glory to whoever shouts first."] = "Bon, {name}. Butin partagé, reproches partagés, gloire à qui crie le premier."
L["Look at us, {name}. The Warchief would be proud. Mildly. From a distance."] = "Regardez-nous, {name}. Le chef de guerre serait fier. Un peu. De loin."
L["Tusks, horns, long ears and bare bone, {name}. Finest warband going."] = "Défenses, cornes, longues oreilles, os à nu, {name}. Un clan de rêve."
L["The war stories get bigger after, {name}. Let's give them a head start."] = "Les récits de guerre grossissent après coup, {name}. Donnons-leur de l'avance."
L["Thank you, {name}. Good hearts turn up on every side, and apparently here."] = "Merci, {name}. Il y a de bons cœurs dans tous les camps, et visiblement ici aussi."
L["Thank you, {name}. No side, no title, just kindness. Legends start like this."] = "Merci, {name}. Ni camp, ni titre, juste de la bonté. Ainsi naissent les légendes."
L["Thank you, {name}. Kindness has no faction, which is handy, since I have none."] = "Merci, {name}. La bonté n'a pas de faction, ça tombe bien, je n'en ai pas."
L["Thank you, {name}. Whichever side gets you is getting a bargain."] = "Merci, {name}. Le camp qui vous récupérera fera une affaire."
L["Whoever claims me in the end, {name}, I'll remember you first. Thank you."] = "Quel que soit mon camp à la fin, {name}, je penserai d'abord à vous. Merci."
L["Strictly neutral, {name}, but gratitude doesn't count. Thank you."] = "Strictement neutre, {name}, mais la gratitude ne compte pas. Merci."
L["Thank you, {name}. I carry no banner, so both hands are free to return this."] = "Merci, {name}. Sans bannière, j'ai les deux mains libres pour vous le rendre."
L["The Steamwheedle stay neutral for gold, {name}. I do it for moments like this."] = "Gentepression reste neutre pour l'or, {name}. Moi, pour des instants pareils."
L["Neither side has taught me their thanks yet, {name}, so here's the plain kind."] = "Aucun camp ne m'a encore appris à remercier, {name}, alors voici un merci nature."
L["Thank you, {name}. I stand between two great banners, and still you noticed me."] = "Merci, {name}. Entre deux immenses bannières, et vous m'avez quand même vu."
L["Two sides at war, {name}, and us being lovely right in the middle. Thank you."] = "Deux camps en guerre, {name}, et nous deux, adorables, pile au milieu. Merci."
L["Gladly, {name}, whatever banner you fly. I don't even own a banner."] = "Avec plaisir, {name}, quelle que soit votre bannière. Je n'en ai même pas."
L["Certainly, {name}. I help everyone. It's the one thing I've decided."] = "Certainement, {name}. J'aide tout le monde. C'est la seule chose que j'ai décidée."
L["Everyone asks me which side I'm on, {name}. Much nicer to be asked for help."] = "On me demande sans cesse mon camp, {name}. Demander de l'aide, c'est plus agréable."
L["Of course, {name}. No war council to ask; just me, and I say yes."] = "Bien sûr, {name}. Pas de conseil de guerre à consulter : juste moi, et je dis oui."
L["Here you are, {name}. No oath, no colours, no fee."] = "Voilà, {name}. Sans serment, sans couleurs, sans frais."
L["I can't pick a side yet, {name}, but I can pick a good cause. This is one."] = "Pas encore de camp, {name}, mais je peux choisir une bonne cause. En voici une."
L["At once, {name}. I have no side to be on, so for now I am entirely on yours."] = "Aussitôt, {name}. Faute de camp, pour l'instant, je suis tout à fait du vôtre."
L["Of course, {name}. Nobody pays me to take sides, so I take requests instead."] = "Bien sûr, {name}. Nul ne me paie pour prendre parti, alors je prends les commandes."
L["Neutral does not mean unwilling, {name}. It means I help first and argue never."] = "Neutre ne veut pas dire réticent, {name}. J'aide d'abord, je ne discute jamais."
L["Friends can come from any side, {name}. Or, like me, from none in particular."] = "On trouve des amis dans tous les camps, {name}. Ou, comme moi, dans aucun en particulier."
L["Soon they'll hand us tabards, {name}. Until then, we look after each other."] = "Bientôt, on nous donnera des tabards, {name}. D'ici là, veillons les uns sur les autres."
L["I haven't chosen a side yet, {name}, so I'm being kind to both. Take this."] = "Pas encore de camp, {name}, alors je ménage la chèvre et le chou. Tenez."
L["A gift with no strings, {name}. I don't even have a faction to tie them to."] = "Un cadeau sans attaches, {name}. Je n'ai même pas de faction où m'attacher."
L["Go on, {name}. Two whole factions are waiting to argue over us."] = "Allez-y, {name}. Deux factions entières vont se battre pour nous avoir."
L["No quartermaster yet, {name}, so nobody's counting. Have plenty."] = "Pas encore d'intendant, {name}, donc personne ne compte. Servez-vous largement."
L["Take this, {name}. Neutral ground travels with me; you're standing on some."] = "Prenez ceci, {name}. Le terrain neutre voyage avec moi ; vous êtes dessus."
L["The Argent Dawn helps whoever needs it, {name}. I'm learning from the best."] = "L'Aube d'argent aide qui en a besoin, {name}. J'apprends des meilleurs."
L["Booty Bay's rule: no fighting on the docks, {name}. Mine: no refusing a gift."] = "À Baie-du-Butin, pas de bagarre sur les quais, {name}. Chez moi, pas de cadeau refusé."
L["The one thing both factions agree on, {name}. They just don't know it yet."] = "Le seul point d'accord des deux factions, {name}. Elles ne le savent pas encore."
L["This goes with any tabard, {name}. I made sure by giving it no colours at all."] = "Ça va avec tous les tabards, {name}. Pour ça, je ne lui ai donné aucune couleur."
L["For you, {name}. Neither Orgrimmar nor Stormwind sent it. It works anyway."] = "Pour vous, {name}. Ni Orgrimmar ni Hurlevent ne l'envoient. Ça marche quand même."
L["Here, {name}. I belong to no nation yet, so I practise belonging to everyone."] = "Tenez, {name}. Pas encore de patrie, alors je m'exerce à être de partout."
L["Side by side, {name}, whatever comes."] = "Côte à côte, {name}, quoi qu'il arrive."
L["No flag over this party, {name}, just us. That's plenty."] = "Aucun drapeau sur ce groupe, {name}, juste nous. C'est bien assez."
L["One day we'll pick sides, {name}. Today we pick fights, together."] = "Un jour, on prendra parti, {name}. Aujourd'hui, on prend part au combat. Ensemble."
L["Whatever side the rest of the world is on, {name}, I'm on this party's."] = "Quel que soit le camp du reste du monde, {name}, moi, je suis du côté de ce groupe."
L["Neutral in the war, {name}, but very partial to this group."] = "Neutre dans la guerre, {name}, mais très partial envers ce groupe."
L["They call us a neutral party, {name}. Nobody said it had to be a quiet one."] = "On nous dit groupe neutre, {name}. Personne n'a dit groupe muet."
L["Whatever we fight today, {name}, it's nothing personal. Just very thorough."] = "Quoi qu'on affronte aujourd'hui, {name}, rien de personnel. Juste très minutieux."
L["One side in this party, {name}: ours. Smallest faction on Azeroth. The best."] = "Un seul camp ici, {name} : le nôtre. Plus petite faction d'Azeroth. La meilleure."
L["No orders from any capital, {name}. We choose our road. Let's choose quickly."] = "Aucune capitale ne nous commande, {name}. On choisit notre route. Choisissons vite."
L["No war to win today, {name}, just this one fight. Much more manageable."] = "Pas de guerre à gagner aujourd'hui, {name}, juste ce combat. Bien plus gérable."
L["One good turn deserves another, {name}."] = "Un service en vaut un autre, {name}."
L["Have some {buff} in return, {name}."] = "En retour, {buff} pour vous, {name}."
L["Kindness should go both ways, {name}. Thank you."] = "La gentillesse doit être réciproque, {name}. Merci."
L["You went first, {name}, so I'll go second and we'll call it friendship."] = "Vous avez fait le premier pas, {name}, je fais le second, et on appellera ça l'amitié."
L["I'd write you a song, {name}, but {buff} is less off-key."] = "Je vous écrirais bien une chanson, {name}, mais {buff} chante plus juste."
L["A gift for a gift, {name}. At this rate we'll be unstoppable by supper."] = "Un cadeau pour un cadeau, {name}. À ce rythme, on sera invincibles avant le dîner."
L["All square, {name}. Unless you'd like to make it best of three."] = "Quittes, {name}. À moins que vous ne vouliez la revanche et la belle."
L["You started it, {name}. I'm only finishing it."] = "C'est vous qui avez commencé, {name}. Moi, je ne fais que finir."
L["That was kind, {name}. The day just got noticeably better. Here's my half."] = "C'était gentil, {name}. La journée vient de s'améliorer nettement. Voici ma moitié."
L["I was about to do that for you, {name}. Honestly. Here's proof."] = "J'allais le faire pour vous, {name}. Si, si. La preuve."
L["Thank you, {name}. I'll sleep better tonight, and I sleep in a ditch."] = "Merci, {name}. Je dormirai mieux ce soir, et je dors dans un fossé."
L["Two good things today, {name}: your kindness, and the chance to return it."] = "Deux joies aujourd'hui, {name} : votre gentillesse, et l'occasion de la rendre."
L["You had me in your debt for all of three seconds, {name}. There."] = "Je vous ai été redevable trois secondes entières, {name}. Voilà."
L["Gratitude is best served quickly, {name}. Here it is, still warm."] = "La gratitude est un plat qui se mange chaud, {name}. Tenez."
L["Well, {name}, now I have to be a better person all day. Thanks for that."] = "Bon, {name}, il va falloir que je sois exemplaire toute la journée. Merci bien."
L["Returned with a bow, {name}. A figurative one. My back isn't what it was."] = "Rendu avec une révérence, {name}. Au figuré. Mon dos n'est plus ce qu'il était."
L["Thank you, {name}. I'd hoped somebody would start. I'm hopeless at starting."] = "Merci, {name}. J'attendais que quelqu'un se lance. Moi, je ne me lance jamais."
L["Thank you, {name}. You've rescued a day I'd written off at breakfast."] = "Merci, {name}. Vous sauvez une journée fichue dès le petit-déjeuner."
L["You asked, {name}, and here it is."] = "Vous avez demandé, {name}, et voilà."
L["{buff}, coming right up, {name}."] = "{buff}, ça arrive, {name}."
L["Gladly, {name}. One moment."] = "Avec plaisir, {name}. Un instant."
L["Asked and answered, {name}. Next question?"] = "Aussitôt demandé, aussitôt fait, {name}. Question suivante ?"
L["Say the word and it's yours, {name}. You said several. Here."] = "Il suffit d'un mot, {name}. Vous en avez dit plusieurs. Tenez."
L["For you, {name}? Gladly. I was hoping someone would ask."] = "Pour vous, {name} ? Avec plaisir. J'espérais qu'on me le demande."
L["Of course, {name}. Easiest yes I'll say all day."] = "Bien sûr, {name}. Le oui le plus facile de ma journée."
L["Right away, {name}. Finally, a question I know the answer to."] = "Tout de suite, {name}. Enfin une question dont je connais la réponse."
L["Of course, {name}. Nobody asks me for anything these days. This is lovely."] = "Bien sûr, {name}. Plus personne ne me demande rien. C'est adorable."
L["Hold still, {name}. It works best on people who aren't fidgeting. So, nobody."] = "Ne bougez plus, {name}. Ça marche mieux sans gigoter. Donc jamais."
L["Here you are, {name}. I'd make you wait for effect, but that seems rude."] = "Voilà, {name}. J'aurais pu ménager mon effet, mais ce serait impoli."
L["Yes, {name}. I'd have said it sooner if you'd asked sooner."] = "Oui, {name}. Et plus tôt si vous aviez demandé plus tôt."
L["Say no more, {name}. Well, say thank you. Then no more."] = "Plus un mot, {name}. Sauf « merci ». Après, plus un mot."
L["There, {name}. Next time, don't ask; just stand near me looking hopeful."] = "Voilà, {name}. La prochaine fois, un regard plein d'espoir suffira."
L["Coming up, {name}. This is the one part of my day that goes to plan."] = "Ça arrive, {name}. Le seul moment de ma journée qui se passe comme prévu."
L["Asking nicely works, {name}. Tell everyone. The world could use the news."] = "La politesse, ça marche, {name}. Faites passer le mot : le monde en a besoin."
L["At once, {name}. Stay put, or this lands on your shadow instead."] = "Tout de suite, {name}. Ne bougez pas, ou ça tombera sur votre ombre."
L["Safe travels, {name}. {buff} packs lighter than a sword."] = "Bon voyage, {name}. {buff} pèse moins lourd qu'une épée."
L["A small blessing for the road, {name}."] = "Une petite bénédiction pour la route, {name}."
L["Go well, {name}, and come back in one piece."] = "Bonne route, {name}, et revenez en un seul morceau."
L["No reason, {name}. It just felt like a {buff} sort of day."] = "Aucune raison, {name}. C'était une journée à {buff}, voilà tout."
L["Don't mind me, {name}. Just passing, with a spare {buff}."] = "Ne faites pas attention à moi, {name}. Je passais, avec {buff} en trop."
L["Consider it a gift, {name}. I'd wrap it, but it glows through the paper."] = "C'est un cadeau, {name}. Je l'aurais emballé, mais ça brille à travers le papier."
L["Here, {name}. Pass it on when you meet someone who needs it."] = "Tenez, {name}. Faites passer quand vous croiserez quelqu'un qui en a besoin."
L["Whatever brings you here, {name}, may it go better than planned."] = "Quoi qui vous amène, {name}, que ça se passe mieux que prévu."
L["Just being neighbourly, {name}. Very, very temporary neighbours."] = "Simple politesse entre voisins, {name}. Des voisins très, très temporaires."
L["You looked about to do something brave, {name}. Here, for that."] = "Vous sembliez prêt à un exploit, {name}. Tenez, pour ça."
L["No need to stop, {name}. It works while you walk."] = "Inutile de vous arrêter, {name}. Ça marche en marchant."
L["Nothing asked, nothing owed, {name}. Nothing to do but go and be splendid."] = "Rien demandé, rien dû, {name}. Il ne vous reste qu'à être splendide."
L["Call it a wager, {name}, that you'll do something worthwhile with it."] = "Disons que c'est un pari, {name} : vous en ferez quelque chose de bien."
L["A gift from a passing stranger, {name}. The best kind, the old stories say."] = "Présent d'un inconnu de passage, {name}. Le meilleur, selon les vieux contes."
L["It's rude to pass someone without a greeting, {name}. This is mine."] = "C'est impoli de croiser quelqu'un sans le saluer, {name}. Voici mon salut."
L["I'm not following you, {name}. We're just going the same way. Here."] = "Je ne vous suis pas, {name}. On va juste dans la même direction. Tenez."
L["If today goes well, {name}, remember me. If it goes badly, I was never here."] = "Si ça se passe bien, {name}, souvenez-vous de moi. Sinon, je n'étais pas là."
L["Hold still a moment, {name}. There. Best-prepared person in sight."] = "Ne bougez pas, {name}. Voilà. La personne la mieux préparée à la ronde."
L["Everyone ready? You are now, {name}."] = "Tous prêts ? Vous l'êtes maintenant, {name}."
L["A little something for the party, {name}."] = "Un petit bonus pour le groupe, {name}."
L["Stay close, {name}. We go further together."] = "Restez près de moi, {name}. Ensemble, on va plus loin."
L["House rules, {name}: nobody dies, nobody sulks, everybody eats after."] = "Règle de la maison, {name} : on ne meurt pas, on ne boude pas, on mange après."
L["There, {name}. Now if this goes badly, it won't be my fault."] = "Voilà, {name}. Maintenant, si ça tourne mal, ce ne sera pas ma faute."
L["All set, {name}. I'd give a speech, but we'd be here all day."] = "Tout est prêt, {name}. Un discours ? On y serait encore demain."
L["Look after that, {name}. It's the only one I brought for you."] = "Prenez-en soin, {name}. C'est le seul que j'ai apporté pour vous."
L["Now we look the part, {name}. Let's go and be it."] = "L'allure, on l'a, {name}. Allons prouver qu'on en a l'étoffe."
L["Fresh {buff} all round, {name}. The rest is luck and elbows."] = "{buff} pour tout le monde, {name}. Le reste, c'est la chance et les coudes."
L["Right, {name}. If anyone has a plan, now's the time. No? Wonderful. Onward."] = "Bon, {name}. Si quelqu'un a un plan, c'est le moment. Non ? Parfait. En avant."
L["One each, {name}. Don't swap; they're fitted."] = "Un chacun, {name}. Pas d'échange : sur-mesure."
L["Whoever starts the fight, {name}, has to tell the story afterwards."] = "Qui commence le combat, {name}, devra le raconter ensuite."
L["Good friends, sharp steel, {buff}. What else is there, {name}?"] = "Bons amis, lames affûtées, {buff}. Que demander de plus, {name} ?"
L["Stay where I can see you, {name}. I can't help what I can't find."] = "Restez dans mon champ de vision, {name}. Loin des yeux, loin du soin."
L["If this ends up a legend, {name}, I want a line in it. Just the one."] = "Si on entre dans la légende, {name}, je veux une réplique. Rien qu'une."
L["Brace yourselves, {name}. And each other, if it comes to that."] = "Accrochez-vous, {name}. Et les uns aux autres, s'il le faut."
L["Chin up, {name}. Whatever's ahead has never met this lot before."] = "Haut les cœurs, {name}. L'ennemi n'a jamais vu une bande pareille."
L["Do try to stay in one piece, {name}. I'm only equipped for small repairs."] = "Tâchez de rester entier, {name}. Je ne fais que les petites réparations."
L["Well, {name}, we look ready. Let's go before we find out otherwise."] = "Eh bien, {name}, on a l'air prêts. Partons avant de découvrir le contraire."
L["If we get lost, {name}, we're exploring. Nobody ever scolded an explorer."] = "Si on se perd, {name}, on explore. Personne n'a jamais grondé un explorateur."
L["Thank you, {name}. I'd conjure a gift in return, but it would only be water."] = "Merci, {name}. Je vous invoquerais bien un cadeau, mais ce ne serait que de l'eau."
L["Much obliged, {name}. I'll write it up properly later. Several pages."] = "Mille mercis, {name}. J'en ferai un rapport en règle plus tard. Plusieurs pages."
L["Thank you, {name}. They never taught gratitude at Dalaran. I'm self-taught."] = "Merci, {name}. À Dalaran, on n'enseigne pas la gratitude. Je suis autodidacte."
L["Kind of you, {name}. I'd say it went to my head, but that's my job."] = "Très aimable, {name}. Je dirais que ça me monte à la tête, mais c'est mon métier."
L["Thank you, {name}. I nearly Counterspelled that on reflex. So glad I didn't."] = "Merci, {name}. J'ai failli y répondre par un Contresort, par réflexe. Ouf."
L["Even a frost mage would thaw at that, {name}. Thank you."] = "Même un mage de givre fondrait devant ça, {name}. Merci."
L["Thank you, {name}. Noted in my spellbook, between Frost Nova and lunch."] = "Merci, {name}. C'est noté dans mon grimoire, entre Nova de givre et déjeuner."
L["Repaid at once, {name}, before I pass a bookshop. I've lost weeks that way."] = "Rendu aussitôt, {name}, avant la prochaine librairie. J'y ai perdu des semaines."
L["Twenty years in the library, {name}, and no book mentioned people like you."] = "Vingt ans en bibliothèque, {name}, et aucun livre ne parlait de gens comme vous."
L["Arcane theory says nothing comes free, {name}. Theory was wrong. Thank you."] = "Rien n'est gratuit, dit la théorie arcanique, {name}. Elle avait tort. Merci."
L["Of course, {name}. And yes, I suppose you'll want water as well."] = "Bien sûr, {name}. Et oui, je suppose que vous voudrez de l'eau aussi."
L["As requested, {name}. Side effects may include footnotes."] = "Comme demandé, {name}. Effets secondaires possibles : notes de bas de page."
L["At once, {name}. Carefully, too; I've blinked into two walls today."] = "Tout de suite, {name}. Prudemment : mon Transfert m'a déjà envoyé dans deux murs."
L["Gladly, {name}. Knowledge should be shared. The Kirin Tor say so, reluctantly."] = "Avec plaisir, {name}. Le savoir doit être partagé. Le Kirin Tor le dit, à contrecœur."
L["Certainly, {name}. I'll cast it slowly. The hand movements are the best part."] = "Certainement, {name}. Je vais le lancer lentement. Les gestes, c'est le meilleur."
L["Of course, {name}. Think of it as homework, and I've done it for you."] = "Bien sûr, {name}. Voyez ça comme des devoirs, déjà faits pour vous."
L["Of course, {name}. Antonidas taught me this. He also taught me to duck."] = "Bien sûr, {name}. C'est Antonidas qui me l'a appris. Et à me baisser, aussi."
L["At once, {name}. Arcane, not fire. I did check. I always check. Nearly always."] = "Tout de suite, {name}. Arcanes, pas feu : vérifié. Je vérifie toujours. Presque."
L["Certainly, {name}. It's this or a lecture on ley lines, and you've been kind."] = "Bien sûr, {name}. C'est ça ou un cours sur les lignes telluriques. Je suis clément."
L["You asked a mage, {name}. The spell is instant; the explanation is not."] = "Vous avez demandé à un mage, {name}. Le sort est instantané, l'explication non."
L["I've cast this a thousand times, {name}. Nine hundred and ninety went well."] = "Je l'ai lancé mille fois, {name}. Neuf cent quatre-vingt-dix se sont bien passées."
L["Certainly, {name}. Stand still. Fidgeters have been known to end up woolly."] = "Bien sûr, {name}. Ne bougez pas. Les agités finissent parfois en mouton."
L["Here, {name}. I had a spare thought and nowhere to put it."] = "Tenez, {name}. J'avais une pensée en trop et nulle part où la ranger."
L["Take this, {name}. I'd add bread, but conjured bread tastes of nothing."] = "Prenez ceci, {name}. J'ajouterais du pain, mais le pain invoqué n'a aucun goût."
L["{buff} for you, {name}. No charge, unlike the portals."] = "{buff} pour vous, {name}. Sans frais, contrairement aux portails."
L["Here, {name}. Most folk I point at turn into sheep. Today's your lucky day."] = "Tenez, {name}. D'ordinaire, ma cible finit en mouton. Jour de chance pour vous."
L["Nothing on fire, nothing frozen, {name}. I'm branching out."] = "Rien de brûlé, rien de gelé, {name}. Je me diversifie."
L["For you, {name}. I was practising, and you happened to be the nearest head."] = "Pour vous, {name}. Je m'entraînais, et vous étiez la tête la plus proche."
L["Here, {name}. I'd have portalled it over, but you were standing right there."] = "Tenez, {name}. Je vous l'aurais envoyé par portail, mais vous étiez juste là."
L["Kings once hired Dalaran for this, {name}. You get it for nothing."] = "Jadis, des rois payaient Dalaran pour ça, {name}. Vous l'avez pour rien."
L["Take this, {name}. It wears off, unlike my last experiment."] = "Prenez, {name}. Ça se dissipe, pas comme ma dernière expérience."
L["For you, {name}: everything I learned in Dalaran, minus the essays."] = "Pour vous, {name} : tout mon savoir de Dalaran, sans les dissertations."
L["Here, {name}. Arcane magic is best shared, before it gets ideas of its own."] = "Tenez, {name}. La magie arcanique se partage, avant qu'elle n'ait des idées à elle."
L["Evocation takes an age, {name}, so I spend my mana where it counts. Here."] = "L'Évocation est longue, {name}, alors mon mana va là où il compte. Tenez."
L["Here, {name}. A mage who walks past without helping is just a very tall hat."] = "Tenez, {name}. Un mage qui passe sans aider n'est qu'un grand chapeau pointu."
L["Now that you're clever, {name}, stand between me and the angry things."] = "Vous voilà plus malin, {name}. Alors placez-vous entre moi et tout ce qui grogne."
L["For the record, {name}, I only blink away when it's tactically sound."] = "Pour mémoire, {name}, je ne me transfère au loin que par pure tactique."
L["Water's on me after, {name}. Please don't ask for it mid-fight."] = "Après, c'est ma tournée d'eau, {name}. Pas en plein combat, par pitié."
L["Minds sharpened, {name}. I'll handle the fire, the frost and the panicking."] = "Esprits aiguisés, {name}. Je m'occupe du feu, du givre et de la panique."
L["Right, {name}: if I say 'Frost Nova', run. If I say 'run', also run."] = "Si je dis « Nova de givre », {name}, courez. Si je dis « courez », courez aussi."
L["Pyroblast takes a while, {name}. Whatever interrupts it, I take personally."] = "Explosion pyrotechnique, c'est long, {name}. Qui l'interrompt me fera exploser."
L["If I ice-block, {name}, I'm not frozen with fear. I'm frozen on purpose."] = "En Bloc de glace, {name}, je ne suis pas glacé d'effroi. Je suis glacé exprès."
L["Portals home are on me after, {name}. Getting there alive is on all of us."] = "Portails du retour offerts, {name}. Rester en vie, c'est l'affaire de tous."
L["Anything you'd rather not fight, {name}, point at it. It'll be wool by teatime."] = "Montrez-moi ce qui vous déplaît, {name}. Ce sera de la laine d'ici le goûter."
L["I'll drop a Blizzard on them, {name}. You're welcome to watch, from outside it."] = "Je leur lâche un Blizzard, {name}. Libre à vous de regarder. De dehors."
L["If I start counting under my breath, {name}, that's mana, not nerves."] = "Si je compte à voix basse, {name}, c'est mon mana, pas mes nerfs."
L["If I go quiet, {name}, it's Evocation, not sulking. Usually."] = "Si je me tais, {name} : Évocation, pas bouderie. D'habitude."
L["If this goes badly, {name}, I've a teleport home. I'd never use it. Probably."] = "Si ça tourne mal, {name}, je peux me téléporter. Je ne le ferais jamais. Sans doute."
L["How thoughtful, {name}. The Light keeps accounts; I settle mine early."] = "Quelle délicatesse, {name}. La Lumière tient ses comptes ; je règle les miens d'avance."
L["Thank you, {name}. I'll put in a good word with the Light. It owes me several."] = "Merci, {name}. Je dirai du bien de vous à la Lumière. Elle me doit bien ça."
L["Thank you, {name}. A small miracle, and I didn't even have to pray for it."] = "Merci, {name}. Un petit miracle, et je n'ai même pas eu à prier."
L["Thank you, {name}. My faith in people is restored. It was only resting."] = "Merci, {name}. Ma foi dans les gens est restaurée. Elle ne faisait que se reposer."
L["Thank you, {name}. You're in tonight's prayers. Near the top."] = "Merci, {name}. Vous êtes dans mes prières ce soir. Presque en tête."
L["Healers are rarely on this end of it, {name}. I'd forgotten how nice it is."] = "Les soigneurs sont les plus mal soignés, {name}. J'avais oublié comme c'est bon."
L["Thank you, {name}. You've saved me a prayer, and I'm always one short."] = "Merci, {name}. Vous m'épargnez une prière, et il m'en manque toujours une."
L["Thank you, {name}. I'd give a sermon on generosity, but you've just given it."] = "Merci, {name}. J'allais prêcher la générosité, mais vous prêchez par l'exemple."
L["Thank you, {name}. I'll light a candle for you. Two. I'm feeling reckless."] = "Merci, {name}. Je brûlerai un cierge pour vous. Deux, même. Soyons fous."
L["Even my shadowy side is smiling, {name}. It has no face, so take my word."] = "Même ma part d'ombre sourit, {name}. Sans visage, donc croyez-moi sur parole."
L["Of course, {name}. The Light keeps no hours, and neither, sadly, do I."] = "Bien sûr, {name}. La Lumière n'a pas d'horaires, et moi non plus, hélas."
L["Straight away, {name}. Most prayers take longer; you've found a shortcut."] = "Tout de suite, {name}. Une prière prend d'habitude plus longtemps : joli raccourci."
L["Certainly, {name}. The Light shines on those who ask. I just aim it."] = "Certainement, {name}. La Lumière brille sur ceux qui demandent. Moi, je vise."
L["With pleasure, {name}. Faith moves mountains; I'm starting smaller."] = "Avec plaisir, {name}. La foi soulève des montagnes ; je commence plus petit."
L["Of course, {name}. Confessions are extra, and I'd rather not hear them."] = "Bien sûr, {name}. La confession est en option, et je préfère m'en passer."
L["Of course, {name}. Consider this sermon abridged. Very abridged. There, done."] = "Bien sûr, {name}. Voici le sermon, version abrégée. Très abrégée. Voilà, fini."
L["Certainly, {name}. A warm glow means the Light. A cold one, tell me at once."] = "Bien sûr, {name}. Lueur chaude : la Lumière. Lueur froide : prévenez-moi vite."
L["Of course, {name}. I'll pray it lasts. I'm told I have an in."] = "Bien sûr, {name}. Je prierai pour que ça dure. J'ai mes entrées là-haut."
L["Certainly, {name}. I heal, I smite, I do funerals. This is the cheerful bit."] = "Bien sûr, {name}. Je soigne, je châtie, j'enterre. Ça, c'est le côté gai."
L["Bless you, {name}. No, you didn't sneeze; I'm simply thorough."] = "À vos souhaits, {name}. Non, vous n'avez pas éternué : je les exauce."
L["Here, {name}. Think of it as a prayer that arrived early."] = "Tenez, {name}. Voyez ça comme une prière exaucée en avance."
L["The Light asked me to pass this along, {name}. I'm paraphrasing."] = "La Lumière m'a demandé de vous transmettre ceci, {name}. Je paraphrase."
L["Take this, {name}. It saves us both an awkward resurrection later."] = "Prenez ceci, {name}. Ça nous évitera une résurrection gênante plus tard."
L["Freely given, {name}. Faith costs nothing. The robes, sadly, did."] = "Donné de bon cœur, {name}. La foi ne coûte rien. La robe, si, hélas."
L["Here, {name}. Think of me as a small, walking temple. No steps to climb."] = "Tenez, {name}. Voyez-moi comme un petit temple ambulant. Sans marches à gravir."
L["A blessing for a stranger, {name}. The Light insists there's no such thing."] = "Une bénédiction pour un inconnu, {name}. La Lumière, elle, connaît tout le monde."
L["Take this, {name}. No collection plate follows. Look: empty hands."] = "Prenez ceci, {name}. Pas de quête ensuite. Regardez : mains vides."
L["Here, {name}. I'd preach, but you look like somebody with somewhere to be."] = "Tenez, {name}. Je vous ferais bien un prêche, mais vous semblez pressé."
L["I do weddings, funerals and resurrections, {name}. Mostly the last. Here."] = "Mariages, obsèques, résurrections, {name}. Surtout les résurrections. Tenez."
L["Here, {name}. I'd float over properly, but levitating in public draws a crowd."] = "Tenez, {name}. J'aurais pu venir en lévitant, mais ça attire les badauds."
L["Your turn, {name}. Now, I beg you all: make my job boring."] = "À votre tour, {name}. Et par pitié, tous : rendez mon travail ennuyeux."
L["Everyone stay near me, {name}. The Light has a limited range."] = "Restez tous près de moi, {name}. La Lumière a une portée limitée."
L["There, {name}. If anyone falls, I'll be very disappointed, then fix it."] = "Voilà, {name}. Si quelqu'un tombe, ça me décevra beaucoup, puis je réparerai."
L["Done, {name}. I'll be at the back, praying loudly."] = "C'est fait, {name}. Je serai derrière, à prier bruyamment."
L["If I scream, {name}, it's a spell, and everything runs. Please don't join in."] = "Si je hurle, {name}, c'est un sort, et tout s'enfuit. Ne suivez pas le mouvement."
L["If I Fade, {name}, I haven't gone. I've just become deeply uninteresting."] = "Si je lance Oubli, {name}, je suis toujours là. Juste parfaitement oubliable."
L["One shield each, {name}. After that, souls need a lie-down. Pace yourselves."] = "Un bouclier chacun, {name}. Après, les âmes font la sieste. Ménagez-vous."
L["Let's all come back from this the usual way, {name}: walking."] = "Revenons tous comme d'habitude, {name} : sur nos deux jambes."
L["I'll keep you alive, {name}. You keep me from having to say 'I told you so'."] = "Je vous garde en vie, {name}. Vous, épargnez-moi un « je vous l'avais dit »."
L["I prayed over this group, {name}. The Light said 'good luck'. I'll take it."] = "J'ai prié pour ce groupe, {name}. La Lumière a dit « bon courage ». C'est déjà ça."
L["Thank you, {name}. I'd purr, but I'm not in the right shape for it."] = "Merci, {name}. Je ronronnerais bien, mais je ne suis pas dans la bonne forme."
L["Thanks, {name}. My bear form sends a grateful grunt."] = "Merci, {name}. Ma forme d'ours vous adresse un grognement reconnaissant."
L["Much obliged, {name}. My cat form wants to bring you a rabbit. I've said no."] = "Mille mercis, {name}. Ma forme de félin veut vous apporter un lapin. J'ai dit non."
L["Thank you, {name}. I'll plant a tree in your honour. Give it a century."] = "Merci, {name}. Je planterai un arbre en votre honneur. Comptez un siècle."
L["Thank you, {name}. I'd send an owl with a note, but I'd have to be the owl."] = "Merci, {name}, c'est chouette. Et je m'y connais : j'en suis une, parfois."
L["Kindly done, {name}. I felt that in my roots, and I haven't any at the moment."] = "Très aimable, {name}. Ça m'a touché jusqu'aux racines, que je n'ai pas en ce moment."
L["Nature returns everything eventually, {name}. I'm quicker. Thank you."] = "La nature rend tout, tôt ou tard, {name}. Moi, c'est tôt. Merci."
L["Barkskin keeps most things out, {name}. Kindness got straight through. Thanks."] = "Mon Écorce arrête presque tout, {name}. Pas la gentillesse. Merci."
L["Thank you, {name}. As a bear this would be a hug. Be glad I'm in this shape."] = "Merci, {name}. En ours, ce serait un câlin. Heureusement pour vous, je suis bipède."
L["Certainly, {name}. Give me a moment to remember which shape has hands."] = "Certainement, {name}. Laissez-moi me rappeler quelle forme a des mains."
L["Of course, {name}. Hold still, like an oak. Oaks are wonderful at it."] = "Bien sûr, {name}. Ne bougez plus, comme un chêne. Les chênes sont doués pour ça."
L["Gladly, {name}. The wild shares everything. Well, not the bears."] = "Avec plaisir, {name}. La nature partage tout. Enfin, pas les ours."
L["Right away, {name}. Pardon the feathers; I've just come from being an owl."] = "Tout de suite, {name}. Pardon pour les plumes, j'étais encore en chouette."
L["Of course, {name}. Nature doesn't take requests, but I do."] = "Bien sûr, {name}. La nature ne prend pas de commandes. Moi, si."
L["Gladly, {name}. Ask a tree and you'll wait a year. Ask a druid and it's now."] = "Avec plaisir, {name}. Un arbre vous ferait attendre un an. Un druide, non."
L["Of course, {name}. The balance tips a little your way. Don't tell the balance."] = "Bien sûr, {name}. L'équilibre penche un peu vers vous. Chut, ne lui dites rien."
L["I'd have run over, {name}, but as a cheetah, and you'd have screamed. Here."] = "J'aurais accouru, {name}, mais en guépard, et vous auriez crié. Tenez."
L["Of course, {name}. The wild is kind to all who ask. Midges excepted."] = "Bien sûr, {name}. La nature est bonne avec qui demande. Moustiques exceptés."
L["Fresh from the Emerald Dream, {name}. Sorry if I yawn."] = "Je sors du Rêve d'émeraude, {name}. Pardon si je bâille."
L["Take this, {name}. Nature provides, and I'm its errand runner today."] = "Prenez ceci, {name}. La nature pourvoit ; aujourd'hui, c'est moi qui livre."
L["The wild calls you friend now, {name}. Handy, since most of it has teeth."] = "La nature vous tient pour ami désormais, {name}. Pratique : elle a beaucoup de dents."
L["I brought you flowers as well, {name}, but I was a stag at the time. Sorry."] = "Je vous avais aussi apporté des fleurs, {name}, mais j'étais en cerf. Pardon."
L["Here, {name}. Cenarius would want you to have it. I'm nearly sure."] = "Tenez, {name}. Cénarius voudrait que ce soit pour vous. Enfin, je crois."
L["Nature wants you to have this, {name}. I'm its hands. Today I have hands."] = "La nature veut vous offrir ceci, {name}. Je suis ses mains. Aujourd'hui, j'en ai."
L["Take this, {name}. The wild has been watching you, and it's decided you'll do."] = "Prenez ceci, {name}. La nature vous a observé : vous ferez l'affaire."
L["If a cat follows you today, {name}, it's only me checking this took."] = "Si un chat vous suit, {name}, c'est moi qui vérifie que ça a pris."
L["For you, {name}. The Moonglade sends its regards. It sends very few."] = "Pour vous, {name}. Reflet-de-Lune vous adresse ses amitiés. Il en a peu."
L["Nature is cruel, lovely and damp, {name}. This helps with two of those."] = "La nature est cruelle, belle et humide, {name}. Ceci aide pour deux des trois."
L["I tie strangers up in roots most days, {name}. This is the nicer part."] = "Je ligote souvent les inconnus de racines, {name}. Ceci est plus gentil."
L["Ready, {name}? Now, whatever happens, nobody startle the bear."] = "Prêts, {name} ? Et quoi qu'il arrive, personne ne fait peur à l'ours."
L["There, {name}. I'll be the cat, the bear or, if we must swim, the seal."] = "Voilà, {name}. Je serai le chat, l'ours ou, s'il faut nager, le phoque."
L["I've one rebirth in me, {name}. Please, nobody make me choose."] = "Je n'ai qu'une Renaissance, {name}. Par pitié, ne m'obligez pas à choisir."
L["Close ranks, {name}. The forest is watching, and it's rooting for us."] = "Serrez les rangs, {name}. La forêt nous soutient de toutes ses racines."
L["If I turn into a tree, {name}, things are going badly and I'm fixing them."] = "Si je me change en arbre, {name}, c'est que ça va mal et que je répare."
L["I've one Innervate, {name}. Whoever looks most desperate gets it. No acting."] = "Je n'ai qu'une Innervation, {name}. Elle ira au plus désespéré. Pas de comédie."
L["If I start glowing and hooting, {name}, that's moonkin. It's a serious form."] = "Si je brille et que je hulule, {name}, c'est la forme de sélénien. Très sérieuse."
L["If it gets crowded, {name}, I'll call a Hurricane. Hold on to your hats."] = "S'il y a trop de monde, {name}, j'appelle un Ouragan. Tenez bien vos chapeaux."
L["We move like a herd, {name}. A mixed herd. One of us is sometimes a bear."] = "On avance en troupeau, {name}. Un troupeau varié : l'un de nous est parfois ours."
L["Kindness, {name}? My favourite virtue. Just ahead of polishing."] = "De la bonté, {name} ? Ma vertu préférée. Juste avant l'astiquage."
L["For that, {name}, my best blessing. Not the second best. The best."] = "Pour ça, {name}, ma meilleure bénédiction. Pas la deuxième. La meilleure."
L["Virtue rewarded on the spot, {name}! I do love it when that happens."] = "Vertu récompensée sur-le-champ, {name} ! J'adore quand ça arrive."
L["Thank you, {name}. My oath says to repay kindness. I'd do it anyway."] = "Merci, {name}. Mon serment m'impose de rendre la bonté. Je le ferais de toute façon."
L["I'll judge you favourably, {name}. I judge most things harshly. Thank you."] = "Je vous jugerai favorablement, {name}. Je juge presque tout sévèrement. Merci."
L["Thank you, {name}. My aura just brightened. It does that when I'm touched."] = "Merci, {name}. Mon aura vient de s'illuminer. Ça lui arrive quand je suis touché."
L["A kindness, {name}! I'll have it engraved on my shield, beside the dents."] = "Quelle bonté, {name} ! Je la ferai graver sur mon bouclier, entre deux bosses."
L["Much obliged, {name}. My warhorse sends thanks as well. He's more reserved."] = "Mille mercis, {name}. Mon destrier vous remercie aussi. Il est plus réservé."
L["I swore to protect the good, {name}. You've just gone to the top of the list."] = "J'ai juré de protéger les justes, {name}. Vous venez de passer en tête de liste."
L["By the Light, {name}, of course! I've been hoping somebody would ask."] = "Par la Lumière, {name}, bien sûr ! J'espérais qu'on me le demande."
L["You have my blessing, {name}. Literally, this time."] = "Vous avez ma bénédiction, {name}. Au sens propre, cette fois."
L["Certainly, {name}. Kneel if you like. I won't insist. I'll be delighted."] = "Certainement, {name}. À genoux si vous voulez. Je n'insiste pas. Ça me ravirait."
L["Gladly, {name}. I never run short of blessings. Mana, now and then."] = "Avec plaisir, {name}. Je ne manque jamais de bénédictions. De mana, parfois."
L["Certainly, {name}. Hold still. My aim is righteous; my gauntlets are clumsy."] = "Bien sûr, {name}. Ne bougez pas. Mon cœur vise juste ; mes gantelets, moins."
L["Gladly, {name}. Helping is the oath. Shining while I do it is a bonus."] = "Avec plaisir, {name}. Aider, c'est mon serment. Briller, c'est en prime."
L["Of course, {name}. Stand fast, chin up, and look deserving. There. You do."] = "Bien sûr, {name}. Tenez-vous droit, menton levé, l'air méritant. Voilà. Parfait."
L["Of course, {name}. You'd be amazed how rarely anyone asks the tin can for help."] = "Bien sûr, {name}. On demande si rarement de l'aide à la boîte de conserve."
L["Of course, {name}. A moment while I pick the blessing. I do have favourites."] = "Bien sûr, {name}. Un instant, je choisis la bénédiction. J'ai mes préférées."
L["The Light asks nothing in return, {name}. I, however, accept thanks."] = "La Lumière ne demande rien en retour, {name}. Moi, j'accepte les remerciements."
L["Go with the Light, {name}. I'll be right behind you, clanking."] = "Allez dans la Lumière, {name}. Je serai juste derrière, en cliquetant."
L["The blessing's free, {name}. You've been spared the sermon. This time."] = "La bénédiction est gratuite, {name}. Le sermon vous est épargné. Pour cette fois."
L["There, {name}. It won't last forever, so be heroic while it does."] = "Voilà, {name}. Ça ne durera pas toujours : soyez héroïque tant que ça dure."
L["Stand tall, {name}. The Light walks with you, and it has excellent posture."] = "Tenez-vous droit, {name}. La Lumière marche avec vous, et elle se tient très bien."
L["Take this, {name}. I'd give you my hammer too, but it's very attached to me."] = "Prenez ceci, {name}. Mon marteau aussi, volontiers, mais il tient trop à moi."
L["Blessings are for handing out, {name}. Hoarding them is frowned upon. By me."] = "Les bénédictions, ça se distribue, {name}. Les garder pour soi est mal vu. Par moi."
L["Justice for the wicked, blessings for the rest, {name}. You're the rest."] = "Justice aux méchants, bénédiction aux autres, {name}. Vous, c'est les autres."
L["Take this, {name}. My libram says to share. It says a lot; this bit I like."] = "Prenez, {name}. Mon libram prône le partage. Il prône beaucoup ; ça, j'aime bien."
L["Chivalry isn't dead, {name}. It's in heavy armour, and it brought you this."] = "La chevalerie n'est pas morte, {name}. Elle est en plaques, et vous apporte ceci."
L["Wear it with pride, {name}. Pride's a sin, but only in large amounts."] = "Portez ça avec fierté, {name}. La fierté n'est un péché qu'à haute dose."
L["You're blessed, {name}. If I bubble later, it's strictly tactical."] = "Vous voilà béni, {name}. Si je bulle plus tard, c'est purement tactique."
L["Stand fast, {name}. We have the Light, and I have a very large hammer."] = "Tenez bon, {name}. Nous avons la Lumière, et j'ai un très gros marteau."
L["One blessing each, {name}. The Light is generous, but it insists on turns."] = "Une bénédiction chacun, {name}. La Lumière est généreuse, mais chacun son tour."
L["Splendid, {name}. Now, nobody look directly at me. I'm rather bright today."] = "Splendide, {name}. Ne me regardez pas en face : je rayonne un peu trop aujourd'hui."
L["Stay inside my aura, {name}. It's warmer than it looks."] = "Restez dans mon aura, {name}. Plus chaude qu'il n'y paraît."
L["If I stun something, {name}, hit it while it's thinking things over."] = "Si j'étourdis quelque chose, {name}, frappez-le pendant qu'il réfléchit."
L["The glowing ground is mine, {name}. Stand in it freely; it only bites them."] = "Le sol qui brille, c'est moi, {name}. Restez-y sans crainte : il ne mord qu'eux."
L["I'll judge them, {name}, and you sentence them. A very efficient court."] = "Je les juge, {name}, vous exécutez la sentence. Justice expéditive."
L["If I shout 'for the Light', {name}, it means charge. Or pray. Usually both."] = "Si je crie « Pour la Lumière », {name}, chargez. Ou priez. Souvent les deux."
L["Armour polished, hammer blessed, {name}, and my horse is sulking. We're ready."] = "Armure astiquée, marteau béni, {name}, et mon cheval boude. Nous sommes prêts."
L["Righteous Fury's up, {name}. Everything wants to hit me now. That's the idea."] = "Fureur vertueuse activée, {name}. Tout veut me frapper, maintenant. C'est le but."
L["How kind, {name}. My imp says thank you too. He's lying, but I'm not."] = "Comme c'est gentil, {name}. Mon diablotin vous remercie aussi. Il ment, mais pas moi."
L["Thank you, {name}. It's been ages since anyone gave me something uncursed."] = "Merci, {name}. Ça faisait des lustres qu'on ne m'avait rien offert de non maudit."
L["Thank you, {name}. I'll repay you with something I didn't find in a crypt."] = "Merci, {name}. En retour, quelque chose qui ne sort pas d'une crypte."
L["Most gracious, {name}. I've asked the voidwalker to stop looming at you."] = "Fort aimable, {name}. J'ai dit au marcheur du Vide de cesser de vous surplomber."
L["Thank you, {name}. I'll tell my demons about you. They'll be baffled."] = "Merci, {name}. Je parlerai de vous à mes démons. Ils n'y comprendront rien."
L["No blood, no bargain, no binding, {name}? What a strange way to trade. Thanks."] = "Ni sang, ni pacte, ni chaînes, {name} ? Drôle de marché. Merci."
L["Thank you, {name}. I'll be nicer to my felhunter tonight, in your honour."] = "Merci, {name}. En votre honneur, double ration pour mon chasseur corrompu."
L["How thoughtful, {name}. Everything I'm given, I return. Except souls. Here."] = "Trop aimable, {name}. Je rends tout ce qu'on me donne. Sauf les âmes. Tenez."
L["Of course, {name}. No soul required. This time."] = "Bien sûr, {name}. Aucune âme requise. Pour cette fois."
L["You asked a warlock for help, {name}. Bold. I like you already."] = "Vous demandez de l'aide à un démoniste, {name}. Audacieux. Vous me plaisez déjà."
L["Of course, {name}. The imp offered to help, and I said no, for all our sakes."] = "Bien sûr, {name}. Le diablotin a proposé son aide, j'ai refusé, pour notre bien à tous."
L["Certainly, {name}. Of all my spells, this is the one I can do at parties."] = "Certainement, {name}. De tous mes sorts, c'est le seul que je peux faire en soirée."
L["Gladly, {name}. A good deed on my record; the Shadow Council would be appalled."] = "Avec plaisir, {name}. Une bonne action ! Le Conseil des ombres en serait outré."
L["Of course, {name}. Please don't read the book I'm holding. For your own sake."] = "Bien sûr, {name}. Ne lisez pas le livre que je tiens, je vous prie. Pour votre bien."
L["Certainly, {name}. Feel watched? That's only the Eye of Kilrogg. Hold still."] = "Bien sûr, {name}. Vous vous sentez épié ? Juste l'Œil de Kilrogg. Ne bougez pas."
L["Of course, {name}. I only curse people who don't ask nicely. You're quite safe."] = "Bien sûr, {name}. Je ne maudis que les malpolis. Vous ne risquez rien."
L["Yes, {name}, it's the one without screaming. Hold still."] = "Oui, {name}, c'est celui sans les hurlements. Ne bougez pas."
L["Of course, {name}. Going somewhere wet? I won't ask. Warlocks never ask."] = "Bien sûr, {name}. Une sortie humide ? Je ne pose pas de questions. Jamais."
L["Here, {name}. Don't ask where it came from. Really, don't."] = "Tenez, {name}. Ne demandez pas d'où ça vient. Vraiment, ne demandez pas."
L["Fall in a lake someday, {name}, and you'll think of me fondly."] = "Tombez dans un lac un jour, {name}, et vous penserez à moi avec tendresse."
L["Breathe easy, {name}. I'd hate to lose you to anything as dull as water."] = "Respirez tranquille, {name}. Se noyer, ce serait d'un ennui mortel."
L["Here, {name}. You'll want a soulstone too, but that's a bigger conversation."] = "Tenez, {name}. Il vous faudra aussi une pierre d'âme, mais c'est une autre histoire."
L["Take this, {name}. It's the only spell of mine the priests approve of."] = "Prenez ceci, {name}. C'est le seul de mes sorts qu'approuvent les prêtres."
L["Take this, {name}. My mother still thinks I'm a mage. Let's keep it that way."] = "Prenez ceci, {name}. Ma mère me croit encore mage. Que ça reste entre nous."
L["Here, {name}. It isn't green, it doesn't whisper, and it won't follow you home."] = "Tenez, {name}. Pas vert, pas chuchoteur, et ça ne vous suivra pas chez vous."
L["Here, {name}. Dark magic, used for good. Do tell my old tutor; he'll hate it."] = "Tenez, {name}. Magie noire, bonne action. Mon ancien maître en ferait une jaunisse."
L["Random acts of kindness, {name}. I'm trying them. The imp has complained."] = "La gentillesse gratuite, {name}. J'essaie. Le diablotin a porté plainte."
L["Here, {name}. I'm not all curses and fear. Mostly, but not all."] = "Tenez, {name}. Pas que malédictions et peur. Surtout, mais pas que."
L["My grimoire has a chapter on kindness, {name}. It's short, but I've read it."] = "Mon grimoire a un chapitre sur la gentillesse, {name}. Court, mais je l'ai lu."
L["Everyone ready, {name}? Souls intact? Good. Let's keep it that way."] = "Tout le monde est prêt, {name} ? Âmes intactes ? Bien. Gardons-les ainsi."
L["Stay close, {name}. The voidwalker takes the hits; I take the credit."] = "Restez près de moi, {name}. Le marcheur du Vide prend les coups ; moi, les lauriers."
L["Swim all you like, {name}. If anyone drifts off, I'll summon them back."] = "Nagez autant que vous voudrez, {name}. Si quelqu'un dérive, je l'invoquerai."
L["Do pet the felhunter, {name}. Just take your spells off first."] = "Caressez donc le chasseur corrompu, {name}. Mais retirez d'abord vos sorts."
L["If I fear something, {name}, don't chase it. It comes back. Angrier."] = "Si je fais fuir quelque chose, {name}, laissez-le. Il revient. Plus énervé."
L["If my health drops for no reason, {name}, it's Life Tap. Sorry, healer."] = "Si ma vie baisse sans raison, {name}, c'est Connexion. Pardon, soigneur."
L["Healthstones after, {name}. For a crisis, mind, not as a snack."] = "Pierres de soins après, {name}. En cas d'urgence, pas en en-cas."
L["Keep clear when I cast Hellfire, {name}. I burn too. That's the tragic part."] = "Gare à mes Flammes infernales, {name}. Je brûle aussi. Tout le drame est là."
L["My imp is on fire, {name}, and he's on our side. Please stop dousing him."] = "Mon diablotin est en feu, {name}, mais il est avec nous. Cessez de l'arroser."
L["If something green falls from the sky, {name}, that's mine. Cheer."] = "Si un truc vert tombe du ciel, {name}, c'est à moi. Applaudissez."
L["Thank you, {name}! Sorry, was that loud? I only have the one volume."] = "Merci, {name} ! Pardon, c'était fort ? Je n'ai qu'un seul volume."
L["Much obliged, {name}. No spells to give back, but I do a very sincere shout."] = "Mille mercis, {name}. Pas de sort à rendre, mais je pousse un cri très sincère."
L["Thanks, {name}. Now I'm twice as angry. In the good way."] = "Merci, {name}. Me voilà deux fois plus en colère. Dans le bon sens."
L["Thanks, {name}. You've earned a place right behind me. Safest spot there is."] = "Merci, {name}. Vous avez gagné une place juste derrière moi. La plus sûre qui soit."
L["Thank you, {name}. Kindness makes me soft. Luckily I've plenty of armour."] = "Merci, {name}. La gentillesse me ramollit. Heureusement, j'ai de l'armure."
L["Thank you, {name}. My armourer thanks you too. I paid for his house."] = "Merci, {name}. Mon armurier vous remercie aussi. Je lui ai payé sa maison."
L["Thanks, {name}. I'd bandage something for you, but you look annoyingly fine."] = "Merci, {name}. Je vous ferais bien un bandage, mais vous êtes d'une santé agaçante."
L["Thank you, {name}. I switched to my grateful stance for that. It's rarely used."] = "Merci, {name}. Je suis passé en posture de gratitude. Elle sert peu."
L["You've given me magic, {name}. No idea where to keep it. I'll wear it. Thanks."] = "De la magie pour moi, {name} ? Je ne sais pas où la ranger. Je vais la porter. Merci."
L["Owing folk makes me restless, {name}, and restless makes me charge things."] = "Les dettes me rendent nerveux, {name}, et nerveux, je charge ce qui bouge."
L["You want a shout, {name}? I was going to shout anyway."] = "Un cri, {name} ? J'allais crier de toute façon."
L["Of course, {name}. Cover your ears; this is the only way I know how."] = "Bien sûr, {name}. Bouchez-vous les oreilles ; je ne sais pas faire autrement."
L["Right away, {name}. Stay in earshot. For me that's a generous distance."] = "Tout de suite, {name}. Restez à portée de voix. Chez moi, ça fait une belle distance."
L["Happily, {name}! Words aren't my strength. Volume is."] = "Avec joie, {name} ! Les mots, ce n'est pas mon fort. Le volume, si."
L["Right, {name}. Deep breath. Not you. Me."] = "Bon, {name}. Grande inspiration. Pas vous. Moi."
L["Happy to, {name}. First request today that didn't involve lifting something."] = "Avec joie, {name}. Première demande du jour sans rien à soulever."
L["Coming up, {name}. It's all in the diaphragm. And the anger. Mostly the anger."] = "Ça arrive, {name}. Tout est dans le diaphragme. Et la colère. Surtout la colère."
L["Of course, {name}. Most folk only ask me to stop. This is a nice change."] = "Bien sûr, {name}. D'habitude, on me demande d'arrêter. Ça change agréablement."
L["Of course, {name}. Took me years to learn. Years of yelling at trees, mostly."] = "Bien sûr, {name}. Des années d'apprentissage. À hurler sur des arbres, surtout."
L["Consider yourself shouted at, {name}. Affectionately."] = "Considérez qu'on vous a crié dessus, {name}. Affectueusement."
L["No incense, no prayers, {name}. Just me, shouting encouragingly."] = "Ni encens ni prières, {name}. Juste moi, qui hurle des encouragements."
L["Chin up, {name}! If anything bothers you, I'll charge it."] = "Haut les cœurs, {name} ! Si quelque chose vous embête, je le charge."
L["There, {name}! Anything that doesn't feel braver now wasn't listening."] = "Voilà, {name} ! Qui ne se sent pas plus courageux n'écoutait pas."
L["Here, {name}, some courage. Warriors make it by yelling. Don't ask how."] = "Tenez, {name}, du courage. Les guerriers en font en hurlant. Ne demandez pas comment."
L["Here, {name}. Something sharper than a whetstone: morale."] = "Tenez, {name}. Plus affûté qu'une pierre à aiguiser : le moral."
L["Take this, {name}. Warriors don't carry spells, so we carry each other."] = "Tenez, {name}. Les guerriers n'ont pas de sorts, alors on se serre les coudes."
L["Here, {name}. You look about to walk into something big. Walk in harder."] = "Tenez, {name}. Vous allez foncer dans un gros morceau. Foncez plus fort."
L["Here, {name}. No magic in it. Just a warrior believing in you, very firmly."] = "Tenez, {name}. Pas de magie. Juste un guerrier qui croit en vous, très fort."
L["Take this, {name}. Trainers charge for it. I charge at things. Different job."] = "Prenez ceci, {name}. Les maîtres font payer ça. Moi, je fais payer l'ennemi."
L["Here, {name}. Tell whatever you fight that a warrior vouched for you."] = "Tenez, {name}. Dites à votre adversaire qu'un guerrier répond de vous."
L["That one was for you, {name}. The next one's for whatever's in your way."] = "Celui-là était pour vous, {name}. Le suivant, pour ce qui vous barre la route."
L["Listen up, {name}! That's it. That was the whole speech."] = "Écoutez-moi, {name} ! Voilà. C'était tout le discours."
L["Where's the danger, {name}? Never mind, I'll find it. Face first."] = "Où est le danger, {name} ? Laissez, je vais le trouver. Tête la première."
L["Right, {name}! I go first, I shout loudest, and nobody touches the healer."] = "Bon, {name} ! Je passe devant, je crie le plus fort, et personne ne touche au soigneur."
L["Everybody angrier? Good. Onward, {name}, and mind my backswing."] = "Tout le monde est plus en rogne ? Bien. En avant, {name}, et gare à mon revers."
L["I need to be hit before I'm any use, {name}. Nobody panic when it happens."] = "Je ne sers à rien avant d'être frappé, {name}. Pas de panique quand ça arrive."
L["Bandages are in my pack, {name}. I tied the knots, so they're very secure."] = "Bandages dans mon sac, {name}. J'ai fait les nœuds moi-même : indénouables."
L["Right, {name}: I take the hits, you take the credit, and we split the repairs."] = "Bon, {name} : à moi les coups, à vous la gloire, et on partage les réparations."
L["If I go red and quiet, {name}, that's Berserker Rage. Red and loud, all's well."] = "Rouge et muet, {name} ? C'est la Rage berserker. Rouge et bruyant ? Tout va bien."
L["My shield's seen worse than this, {name}. So has my face. Onward."] = "Mon bouclier a vu pire, {name}. Ma figure aussi. En avant."
L["A sharper mind for you, {name}. Mine cost me an eyebrow in Dalaran."] = "Un esprit plus vif pour vous, {name}. Le mien m'a coûté un sourcil à Dalaran."
L["A clearer head for you, {name}. What you fill it with is your own affair."] = "Une tête plus claire, {name}. Ce que vous y mettez ne regarde que vous."
L["Thoughts humming, {name}? Normal. If they hum back, come and find me."] = "Vos pensées bourdonnent, {name} ? Normal. Si elles vous répondent, venez me voir."
L["A little arcane for your thoughts, {name}. Keep the change."] = "Les arcanes de l'esprit, {name} ? Je vous en rajoute un peu."
L["Brilliance, bottled, {name}. The Kirin Tor would charge you for the bottle."] = "Du génie en bouteille, {name}. Le Kirin Tor vous ferait payer la bouteille."
L["Sharper wits, {name}. Spend them on spells, locks or riddles; I won't judge."] = "Esprit affûté, {name}. Sorts, serrures ou énigmes : je ne juge pas."
L["On loan from the Violet Citadel, {name}. Late returns are fined in sheep."] = "Prêté par la citadelle Pourpre, {name}. Tout retard se paie en moutons."
L["Clever enough to spot the trap now, {name}. Avoiding it is a separate spell."] = "Assez malin pour repérer le piège, {name}. L'éviter, c'est un autre sort."
L["There, {name}. Wiser already: look, you're standing further from me."] = "Voilà, {name}. Déjà plus sage : regardez, vous vous éloignez de moi."
L["The one spell of mine that's never set anything alight, {name}. Enjoy."] = "Le seul de mes sorts qui n'a jamais rien incendié, {name}. Profitez-en."
L["A gnome's instructions make sense now, {name}. Still don't follow them."] = "Les notices gnomes sont claires, maintenant, {name}. Ne les suivez pas pour autant."
L["Fortitude, {name}: a priest's polite way of saying 'stand in front'."] = "Robustesse, {name} : la façon polie qu'a un prêtre de dire « passez devant »."
L["Every bit of stamina is one less panicked prayer from me, {name}."] = "Chaque point d'endurance, c'est une prière paniquée de moins pour moi, {name}."
L["Tougher already, {name}. Please don't take that as a dare."] = "Déjà plus robuste, {name}. Ne le prenez pas comme un défi, s'il vous plaît."
L["There are other Power Words, {name}. 'Shield', and in emergencies, 'Run'."] = "Il y a d'autres mots de pouvoir, {name}. « Bouclier » et, en cas d'urgence, « Courez »."
L["Sturdier now, {name}. Falls, bears and bad decisions all hurt a bit less."] = "Plus solide, {name}. Chutes, ours et mauvaises décisions font un peu moins mal."
L["{buff}, {name}. Three words where 'be tougher' would do."] = "{buff}, {name}. Tout ça pour dire « tenez bon »."
L["A little more of you to go round, {name}. Spend it slowly."] = "Un peu plus de vous en réserve, {name}. Ne vous dépensez pas trop vite."
L["Sturdier, {name}. Not invincible. I expect I'll be saying that again later."] = "Plus solide, {name}. Pas invincible. Je sens que je vais devoir le répéter."
L["Stubbornness, really, {name}. Dwarves are born with it; the rest of us pray."] = "De l'entêtement, en somme, {name}. Les nains naissent avec ; nous autres, on prie."
L["The only armour that never needs repairing, {name}. The smiths hate it."] = "La seule armure sans frais de réparation, {name}. Les forgerons la détestent."
L["Consider your spirits lifted, {name}. Divinely, as it happens."] = "Esprit remonté, {name}. Divinement, pour tout dire."
L["Like a good night's sleep, {name}, without all the lying down."] = "Comme une bonne nuit de sommeil, {name}, sans avoir à s'allonger."
L["A second helping of spirit, {name}. The Light always insists on seconds."] = "Une deuxième portion d'esprit, {name}. La Lumière tient à ce qu'on se resserve."
L["Keep your spirit where it is, {name}. The Spirit Healers are busy enough."] = "Gardez votre esprit là où il est, {name}. Les gardiens des âmes ont assez de travail."
L["Cheer up, {name}. That's not advice this time; it's a spell."] = "Haut les cœurs, {name}. Pas un conseil, cette fois : un sort."
L["Recover faster, {name}: from fights, from long casts and from my jokes."] = "Récupérez plus vite, {name} : des combats, des incantations et de mes blagues."
L["A deep breath's worth of calm, {name}, without having to take one."] = "Le calme d'une grande inspiration, {name}, sans avoir à inspirer."
L["The Light's own second wind, {name}. Don't waste it on arguments."] = "Le second souffle de la Lumière, {name}. Ne le gaspillez pas en disputes."
L["Proof against shadow, {name}. I know its tricks; I've borrowed a few."] = "À l'épreuve de l'Ombre, {name}. Je connais ses ruses ; j'en ai emprunté quelques-unes."
L["Should the Void call, {name}, you can now pretend you're out."] = "Si le Vide appelle, {name}, faites dire que vous n'êtes pas là."
L["For when the dark gets personal, {name}. It usually does."] = "Pour quand les ténèbres s'en prennent à vous, {name}. Ça arrive souvent."
L["The shadows will have to knock first now, {name}."] = "Les ombres devront frapper avant d'entrer, maintenant, {name}."
L["The dark still bites, {name}, but now it has to chew."] = "L'Ombre mord encore, {name}, mais il lui faut mâcher."
L["A lining against the dark, {name}. Like a cloak, only on the inside."] = "Une doublure contre les ténèbres, {name}. Comme une cape, mais à l'intérieur."
L["Curses slide right off you now, {name}. The cultists will take it personally."] = "Les malédictions glissent sur vous, {name}. Les cultistes vont mal le prendre."
L["Priests study the Shadow to guard against it, {name}. Mostly."] = "Les prêtres étudient l'Ombre pour s'en protéger, {name}. En principe."
L["For crypts, cults and Scholomance, {name}. The dark gets chatty in all three."] = "Cryptes, cultes et Scholomance, {name} : trois endroits où les ténèbres sont bavardes."
L["It won't keep off gloom, {name}. For that you want company. Here I am."] = "Contre les idées noires, ça ne peut rien, {name}. Il faut de la compagnie. Me voilà."
L["Marked by the wild, {name}. The deer will tip their antlers as you pass."] = "Vous portez la marque du fauve, {name}. Les cerfs vous salueront de leurs bois."
L["You may smell faintly of moss, {name}. That's how you know it's working."] = "Vous sentirez peut-être la mousse, {name}. C'est signe que ça marche."
L["Mark of the Wild, {name}. The wolves will still bite, but they'll feel bad."] = "Marque du fauve, {name}. Les loups mordront toujours, mais avec des remords."
L["The wild's own seal of approval, {name}. The squirrels were consulted."] = "Le sceau d'approbation de la nature, {name}. Les écureuils ont été consultés."
L["A little of the wild in you now, {name}. Resist the urge to howl."] = "Un peu de nature sauvage en vous, {name}. Résistez à l'envie de hurler."
L["Hide, claw and a thick coat, {name}. The wild packs light but thorough."] = "Cuir, griffes et fourrure épaisse, {name}. La nature voyage léger, mais n'oublie rien."
L["Cenarius signs every one of these, {name}. Well, a tree does, on his behalf."] = "Chaque marque est signée Cénarius, {name}. Enfin, par un arbre, en son nom."
L["The forest's own armour, {name}. It doesn't clank, and it smells of rain."] = "L'armure de la forêt, {name}. Elle ne cliquette pas, et elle sent la pluie."
L["A tougher hide in seconds, {name}. The oaks took centuries and are furious."] = "Un cuir plus dur en un instant, {name}. Les chênes ont mis des siècles : ils enragent."
L["It's a loan from the wild, {name}. Try not to bring it back chewed."] = "C'est un prêt de la nature, {name}. Tâchez de ne pas le rendre mâchouillé."
L["Anything that bites you now gets a mouthful, {name}."] = "Tout ce qui vous mord en aura plein la bouche, {name}."
L["Let the boar charge, {name}. It'll leave with regrets and splinters."] = "Laissez le sanglier charger, {name}. Il repartira avec des regrets et des échardes."
L["Like a rose, {name}: lovely to look at, a mistake to grab."] = "Comme une rose, {name} : superbe à voir, imprudent à cueillir."
L["Thorns, {name}. I grew them myself, so do be polite to them."] = "Épines, {name}. Je les ai fait pousser moi-même, alors soyez poli avec elles."
L["A hedge you can wear, {name}. Neatly trimmed; I'm not a barbarian."] = "Une haie à porter sur soi, {name}. Bien taillée : je ne suis pas un barbare."
L["Nature never turns the other cheek, {name}. It grows spikes on it."] = "La nature ne tend jamais l'autre joue, {name}. Elle y fait pousser des épines."
L["Raptors learn slowly, {name}. This teaches them one bite at a time."] = "Les raptors apprennent lentement, {name}. Une leçon par morsure."
L["Prickly on the outside, {name}. What's inside is your own business."] = "Piquant au-dehors, {name}. Cœur d'artichaut ou pas, c'est votre affaire."
L["Mind your cloak, {name}. Wool and brambles never did get along."] = "Gare à votre cape, {name}. Laine et ronces n'ont jamais fait bon ménage."
L["Blessing of Kings, {name}. No crown, no throne, no taxes owed."] = "Bénédiction des rois, {name}. Sans couronne, sans trône, sans impôts."
L["Long may you reign, {name}. For the next while, anyway."] = "Longue vie à votre règne, {name}. Pour les minutes à venir, en tout cas."
L["A little more of everything, {name}. Kings never did settle for less."] = "Un peu plus de tout, {name}. Les rois ne se sont jamais contentés de moins."
L["A king's blessing, {name}. Worn by better heads than mine, and some worse."] = "Une bénédiction royale, {name}. Portée par de meilleures têtes que la mienne, et de pires."
L["Every strength a little higher, {name}. Kings like to hedge their bets."] = "Tous vos atouts un peu relevés, {name}. Les rois aiment jouer sur tous les tableaux."
L["Crown not included, {name}. Everything else is, a little."] = "Couronne non incluse, {name}. Tout le reste l'est, un peu."
L["All of you, only more so, {name}. That's what they mean by the royal 'we'."] = "Vous, en mieux et en plus, {name}. C'est ça, le « nous » de majesté."
L["A blessing fit for royalty, {name}. You'll have to do your own waving."] = "Une bénédiction digne des rois, {name}. Pour saluer la foule, ce sera sans moi."
L["Stronger, cleverer, hardier, {name}. Kings had advisers for that; you have me."] = "Plus fort, plus malin, plus robuste, {name}. Les rois avaient des conseillers ; vous, moi."
L["Royal treatment, {name}, minus the courtiers and the poisoned wine."] = "Un traitement royal, {name}, sans les courtisans ni le vin empoisonné."
L["Might doesn't make right, {name}, but it does help the argument."] = "La raison du plus fort n'est pas la meilleure, {name}. Mais elle aide."
L["A firmer swing for you, {name}. The Light loves a good follow-through."] = "Un coup plus ferme pour vous, {name}. La Lumière adore un geste bien accompagné."
L["Stronger arms, {name}. Kindly point them at something that deserves it."] = "Des bras plus forts, {name}. Pointez-les vers qui le mérite, je vous prie."
L["Blessing of Might, {name}. It'll surprise you. It'll surprise them far more."] = "Bénédiction de puissance, {name}. Elle vous surprendra. Eux, bien davantage."
L["Swing away, {name}. The Light will take the credit if it goes well."] = "Frappez, {name}. La Lumière s'en attribuera le mérite si ça se passe bien."
L["Hit harder, {name}. Them, I mean. Not me. Never the paladin."] = "Frappez plus fort, {name}. Eux, je veux dire. Pas moi. Jamais le paladin."
L["More weight behind every swing, {name}. The Light calls it conviction."] = "Plus de poids dans chaque coup, {name}. La Lumière appelle ça la conviction."
L["Doors, crates and ogres will all give way easier now, {name}."] = "Portes, caisses et ogres céderont plus facilement, {name}."
L["Your weapon will feel lighter, {name}. It isn't. You're just holier."] = "Votre arme semblera plus légère, {name}. Elle ne l'est pas. Vous êtes juste plus béni."
L["The Light's own elbow grease, {name}. Put it somewhere useful."] = "L'huile de coude de la Lumière, {name}. Mettez-la là où elle servira."
L["Wisdom for you, {name}. I kept a little back for myself. Very little."] = "De la sagesse pour vous, {name}. J'en ai gardé un peu pour moi. Très peu."
L["Wisdom for your mana, {name}. The other kind still comes from bad decisions."] = "De la sagesse pour votre mana, {name}. L'autre vient toujours des erreurs."
L["Your mana creeps back on its own now, {name}, like a cat that's forgiven you."] = "Votre mana revient tout seul, {name}, comme un chat qui vous a pardonné."
L["Fewer sips between fights, {name}. The innkeepers will be heartbroken."] = "Moins de gorgées entre les combats, {name}. Les aubergistes vont avoir le cœur brisé."
L["Drink less, cast more, {name}. The Light's own budget advice."] = "Buvez moins, lancez plus, {name}. Le conseil budgétaire de la Lumière."
L["Blessing of Wisdom, {name}: the one blessing that pays for itself."] = "Bénédiction de sagesse, {name} : la seule qui se rembourse toute seule."
L["Mana, {name}, not judgement. Judgement's a separate seal, and I'm keeping it."] = "Du mana, {name}, pas du jugement. Le Jugement, c'est un autre sceau, et je le garde."
L["Wisdom usually comes with age, {name}. This comes with a paladin. Quicker."] = "La sagesse vient avec l'âge, {name}. Celle-ci vient avec un paladin. C'est plus rapide."
L["The blessing is wise, {name}. The decisions are still entirely ours."] = "La bénédiction est sage, {name}. Les décisions, elles, restent les nôtres."
L["A wise blessing for a wise choice, {name}: keeping a paladin around."] = "Sage bénédiction pour sage choix, {name} : garder un paladin sous la main."
L["A blessing of quiet, {name}. Monsters will forget whose fault it was."] = "Une bénédiction de discrétion, {name}. Les monstres oublieront à qui la faute."
L["Blessing of Salvation, {name}. You are now somebody else's problem."] = "Bénédiction de salut, {name}. Vous êtes désormais le problème de quelqu'un d'autre."
L["Saved, {name}. Not your soul, mind. Just your hide."] = "Salut, {name}. Pas celui de l'âme, attention : celui de la peau."
L["Hit hard, {name}. If anything turns round, look innocent. The Light will."] = "Frappez fort, {name}. Si ça se retourne, prenez l'air innocent. La Lumière le fera."
L["The monsters will find you forgettable now, {name}. Today, that's a compliment."] = "Les monstres vous oublieront vite, {name}. Aujourd'hui, c'est un compliment."
L["Go on, hit it, {name}. It'll blame whoever's wearing the most plate."] = "Allez-y, frappez, {name}. La bête s'en prendra à qui porte le plus de plaques."
L["The art of being in the fight, {name}, and out of the argument."] = "L'art d'être dans la mêlée, {name}, sans être dans le collimateur."
L["The Light's kindest alibi, {name}. Use it often."] = "Le plus doux alibi de la Lumière, {name}. Usez-en souvent."
L["The Light will find you easier now, {name}. Try not to squint."] = "La Lumière vous trouvera mieux, {name}. Évitez de plisser les yeux."
L["Holy Light lands harder on you now, {name}. Please don't make me prove it."] = "La Lumière sacrée vous touche plus fort, {name}. Ne m'obligez pas à le prouver."
L["You'll heal easier, {name}. The Light appreciates a willing patient."] = "Vous guérirez plus facilement, {name}. La Lumière apprécie les patients coopératifs."
L["Blessing of Light, {name}. Saving you is simpler now. Not that you'll need it."] = "Bénédiction de lumière, {name}. Vous sauver sera plus simple. Non que vous en ayez besoin."
L["The Light knows the way to you now, {name}. Let's keep its visits social."] = "La Lumière sait où vous trouver, {name}. Qu'elle s'en tienne aux visites de courtoisie."
L["A blessing that makes my job easier, {name}. Generous and lazy all at once."] = "Une bénédiction qui me facilite la tâche, {name}. Généreux et paresseux à la fois."
L["Holy Light fits you better now, {name}, like a well-cut tabard."] = "La Lumière sacrée vous va mieux, {name}, comme un tabard bien coupé."
L["Mending you just got cheaper, {name}. Not that I'd ever send a bill."] = "Vous soigner coûte moins cher, {name}. Non que je vous envoie jamais la note."
L["Block a blow now, {name}, and the Light hits back for you. It's petty."] = "Bloquez un coup, {name}, et la Lumière riposte pour vous. Elle est rancunière."
L["Every blow lands softer now, {name}. Complaints go to the Light."] = "Chaque coup vous arrive plus doucement, {name}. Les plaintes, c'est à la Lumière."
L["All the shelter of a temple, {name}, and none of the roof repairs."] = "Tout l'abri d'un temple, {name}, sans les réparations du toit."
L["Claim sanctuary, {name}. It's easier when you bring your own."] = "Réfugiez-vous au sanctuaire, {name}. Plus simple quand on l'emporte avec soi."
L["Every blow is a little less rude now, {name}. The Light teaches manners."] = "Chaque coup est un peu moins impoli, {name}. La Lumière enseigne les bonnes manières."
L["Nobody can evict you from this sanctuary, {name}. I checked the deeds."] = "Personne ne peut vous expulser de ce sanctuaire, {name}. J'ai vérifié au cadastre."
L["An ogre's club lands like a pillow now, {name}. A heavy, angry pillow."] = "La massue d'un ogre tombe comme un oreiller, {name}. Un oreiller lourd et furieux."
L["Instructions, {name}: hit things harder. There is no page two."] = "Mode d'emploi, {name} : frappez plus fort. Il n'y a pas de page deux."
L["Your sword arm is sorted, {name}. For the rest of you, see a priest."] = "Votre bras armé est réglé, {name}. Pour le reste, voyez un prêtre."
L["Battle Shout, {name}. Not a spell, really. A strongly worded suggestion."] = "Cri de guerre, {name}. Pas vraiment un sort. Une suggestion très appuyée."
L["RAAAGH! That one was for you, {name}. Everyone else just overheard."] = "RAAAGH ! Celui-là était pour vous, {name}. Les autres ont juste entendu."
L["Priests pray, mages study, {name}. I clear my throat."] = "Les prêtres prient, les mages étudient, {name}. Moi, je me racle la gorge."
L["Words matter, {name}. Mostly the loud ones."] = "Les mots comptent, {name}. Surtout les plus forts."
L["The shout lasts a few minutes, {name}. The ringing in your ears, rather longer."] = "Le cri dure quelques minutes, {name}. Le sifflement dans vos oreilles, bien plus."
L["There were words in that shout once, {name}. They slowed it down."] = "Autrefois, il y avait des mots dans ce cri, {name}. Ils le ralentissaient."
L["A little breath from the damned, {name}. They weren't using it."] = "Un peu du souffle des damnés, {name}. Ils ne s'en servaient pas."
L["Unending Breath, {name}. The fish will have so many questions."] = "Respiration interminable, {name}. Les poissons vont avoir tant de questions."
L["Stay down as long as you like, {name}. Something else is holding its breath."] = "Restez au fond tant que vous voulez, {name}. Autre chose retient son souffle pour vous."
L["Swim deep, {name}. If a murloc asks, you're only visiting."] = "Nagez profond, {name}. Si un murloc demande, vous êtes juste de passage."
L["Air from a place where air isn't strictly air, {name}. Breathe it anyway."] = "De l'air venu d'un lieu où l'air n'en est pas vraiment, {name}. Respirez-le quand même."
L["The Vile Reef awaits, {name}. Try not to find out how it earned the name."] = "Le Récif infâme vous attend, {name}. Évitez de découvrir d'où lui vient son nom."
L["Dropped something in a lake, {name}? Now's your chance."] = "Un objet tombé dans un lac, {name} ? C'est le moment."
L["No gills, {name}. I read the small print; gills were extra."] = "Pas de branchies, {name}. J'ai lu les petites lignes : c'était en option."
L["Folk will think we're duelling, {name}. Thanks for the {gift}."] = "On va croire qu'on se bat en duel, {name}. Merci pour {gift}."
L["{gift} for {buff}. No auctioneer's cut, {name}."] = "{gift} contre {buff}. Sans passer par l'hôtel des ventes, {name}."
L["Beaten to it, {name}! Your {gift} was quicker than my manners."] = "Vous avez été plus rapide, {name} ! Votre {gift} a devancé ma politesse."
L["{gift} in, {buff} out. Finest economy in all Azeroth."] = "Entrée : {gift}. Sortie : {buff}. La meilleure économie d'Azeroth."
L["{gift}, for me? All I have is this, {name}, but it's heartfelt."] = "{gift}, pour moi ? Je n'ai que ceci à offrir, {name}, mais c'est de bon cœur."
L["Your {gift} fits perfectly, {name}. Did you measure me?"] = "Votre {gift} me va parfaitement, {name}. Vous avez pris mes mesures ?"
L["A treaty in spells, {name}: {gift} for {buff}."] = "Un traité en sorts, {name} : {gift} contre {buff}."
L["{gift}! I feel taller already. Have some {buff}."] = "{gift} ! J'ai déjà pris quelques centimètres. Tenez, {buff}."
L["I was about to ask for {gift}, {name}. You read my mind."] = "J'allais justement demander {gift}, {name}. Vous lisez dans mes pensées."
L["Your {gift} still fizzes, {name}. Here's some fizz back."] = "Votre {gift} pétille encore, {name}. Voici de quoi pétiller en retour."
L["Such a kind {gift}, {name}. I'll tell the whole inn. Twice."] = "{gift}, quelle attention, {name}. Toute l'auberge le saura. Deux fois."
L["You cast {gift} first, {name}? My mother would despair of me."] = "Vous avez lancé {gift} en premier, {name} ? Ma mère désespérerait de moi."
L["I'll remember your {gift} fondly, {name}. Until it wears off."] = "Votre {gift} restera un doux souvenir, {name}. Jusqu'à la fin de l'effet."
L["{gift} for {buff}, free. Somewhere, a goblin weeps."] = "{gift} contre {buff}, gratuitement. Quelque part, un gobelin pleure."
L["Your {gift}, my {buff}. We'll be unbearable now."] = "{gift} de vous, {buff} de moi. On va être insupportables."
L["Thanks for the {gift}, {name}. I'll earn it before it fades."] = "Merci pour {gift}, {name}. Je m'en montrerai digne avant la fin de l'effet."
L["For {gift} I'd hand you both moons, {name}. This'll have to do."] = "Pour {gift}, je vous offrirais les deux lunes, {name}. Ceci devra suffire."
L["You brought {gift}, I brought {buff}. Now it's a party."] = "Vous apportez {gift}, j'apporte {buff}. Maintenant, c'est une fête."
L["{gift} means 'good luck'. {buff} means 'you too'."] = "{gift} veut dire « bonne chance ». {buff} veut dire « vous aussi »."
L["Your {gift} came first; my {buff} tries twice as hard."] = "{gift} m'a devancé ; {buff} met les bouchées doubles."
L["If anyone asks, {buff} came before {gift}. Deal?"] = "Si on vous demande, j'ai lancé {buff} avant {gift}. Marché conclu ?"
L["{gift} made my day; {buff} should make your hour."] = "{gift} a illuminé ma journée ; {buff} illuminera votre heure."
L["Saved my {buff} for someone special. Then came {gift}."] = "Je gardais {buff} pour quelqu'un de spécial. Et vous voilà, avec {gift}."
L["Your {gift} went to my head; my {buff} goes to yours."] = "{gift} me monte à la tête ; {buff}, à la vôtre."
L["{gift} on me, {buff} on you. We wear each other's work."] = "{gift} sur moi, {buff} sur vous. Chacun porte la griffe de l'autre."
L["{gift} and {buff} fade. Kindness lasts. Well, longer."] = "{gift} et {buff} se dissipent. La gentillesse reste. Enfin, plus longtemps."
L["You shared {gift}; I share {buff}. Next, snacks."] = "Vous avez partagé {gift} ; je partage {buff}. Ensuite, le goûter."
L["{gift} caught me empty-handed. Not any more: {buff}."] = "{gift} m'a pris au dépourvu. Plus maintenant : {buff}."
L["{gift}, best thing all day. {buff}, my bid for second."] = "{gift} : le clou de ma journée. {buff} : je vise la deuxième place."
L["{gift} deserves a statue. I'm no sculptor, so: {buff}."] = "{gift} mérite une statue. Je ne suis pas sculpteur, alors : {buff}."
L["{gift} for {buff}? Keep this up and we'll draw a queue."] = "{gift} contre {buff} ? À ce train-là, il va y avoir la queue."
L["{gift} was kind. {buff} is kind back, and competitive."] = "{gift}, c'était gentil. {buff} rend la pareille, et relance."
L["{gift} came like good news. {buff}, by return post."] = "{gift}, quelle bonne nouvelle ! {buff}, par retour du courrier."
L["{gift}, meet {buff}. Do get along, you two."] = "{gift}, je vous présente {buff}. Soyez sages, tous les deux."
L["Trade you {buff} for {gift}? Ah, you've already paid."] = "Je vous échange {buff} contre {gift} ? Ah, vous avez déjà payé."
L["{gift} and {buff}. The inn will say we rehearsed."] = "{gift} et {buff}. À l'auberge, on dira qu'on a répété."
L["{gift}! I just had three clever thoughts, {name}. This was one."] = "{gift} ! Je viens d'avoir trois idées brillantes, {name}. En voici une."
L["With {gift}, {name}, I finally understand my own notes. Thanks."] = "Grâce à {gift}, {name}, je comprends enfin mes propres notes. Merci."
L["Cleverer already, {name}. Clever enough to know I owe you one. Here."] = "Déjà l'esprit plus vif, {name}. Assez pour savoir que je vous en dois une. Tenez."
L["Your {gift} found me the word for this, {name}: 'thanks'."] = "Votre {gift} m'a soufflé le mot juste, {name} : « merci »."
L["{gift}! I understood a goblin contract, {name}. I'm appalled."] = "{gift} ! J'ai compris un contrat gobelin, {name}. J'en suis horrifié."
L["{gift}! I finally get last week's mage joke, {name}. Thanks."] = "{gift} ! Enfin compris la blague du mage de l'autre jour, {name}. Merci."
L["I'll use your {gift} for more than arguing, {name}. Probably."] = "Votre {gift} ne me servira pas qu'à avoir le dernier mot, {name}. Sans doute."
L["Thank you, {name}. My next spell gets three extra syllables, just to show off."] = "Merci, {name}. Mon prochain sort aura trois syllabes de plus, rien que pour frimer."
L["{gift}, {name}? I'll stand at the front for once. Briefly."] = "{gift}, {name} ? Je vais passer devant, pour une fois. Brièvement."
L["Knees, elbows and pride, {name}: all fortified. Thank you."] = "Genoux, coudes et fierté, {name} : tout est renforcé. Merci."
L["Hit me now, {name}. Actually, don't. But thank you; I'd survive it."] = "Frappez-moi, {name}. Non, en fait, ne le faites pas. Mais merci : j'y survivrais."
L["Nigh unbreakable now, {name}. Let's never test the 'nigh'. Thank you."] = "Presque incassable, {name}. Ne mettons jamais le « presque » à l'épreuve. Merci."
L["{gift}! My healer owes you a letter, {name}. I owe you this."] = "{gift} ! Mon soigneur vous doit une lettre, {name}. Moi, je vous dois ceci."
L["Every bruise I don't get today, {name}, I owe to your {gift}."] = "Chaque bleu que je n'aurai pas aujourd'hui, {name}, je le dois à votre {gift}."
L["I could lose an argument with an ogre now and live, {name}. Thank you."] = "Je pourrais perdre une dispute avec un ogre et survivre, {name}. Merci."
L["Thank you, {name}. I feel like a castle wall. A grateful one."] = "Merci, {name}. Je me sens solide comme un rempart. Un rempart reconnaissant."
L["Thank you, {name}. The next boar to charge me is in for a long afternoon."] = "Merci, {name}. Le prochain sanglier qui me charge va passer un long après-midi."
L["{gift}! My spirits are lifted, {name}. Literally, it seems."] = "{gift} ! Mon esprit s'élève, {name}. Littéralement, on dirait."
L["I feel twice as calm and half as grumpy, {name}. Thank you."] = "Deux fois plus de calme, deux fois moins de mauvaise humeur, {name}. Merci."
L["Your {gift} nearly made me sing, {name}. Take this. It's kinder."] = "Votre {gift} a failli me faire chanter, {name}. Prenez ceci. C'est plus charitable."
L["{gift}, {name}? I've forgiven three people already. Thank you."] = "{gift}, {name} ? J'ai déjà pardonné à trois personnes. Merci."
L["I was on fumes, {name}. Your {gift} was a hot meal and a hearth."] = "J'étais à sec, {name}. Votre {gift}, c'est un repas chaud au coin du feu."
L["I've stopped counting mana between fights, {name}. Thank you."] = "J'ai arrêté de compter mon mana entre les combats, {name}. Merci."
L["My spirit's topped up, {name}, and the rest of me is grateful too."] = "J'ai fait le plein d'esprit, {name}, et le reste de moi vous en remercie aussi."
L["Shadow-proof, thanks to you, {name}. The whispers are furious."] = "À l'épreuve de l'Ombre grâce à vous, {name}. Les murmures sont furieux."
L["Nothing dark gets in now, {name}. Here's something bright going the other way."] = "Plus rien d'obscur n'entre, {name}. Voici quelque chose de lumineux dans l'autre sens."
L["{gift}! Shadowfang Keep can keep its shadows, {name}. Thank you."] = "{gift} ! Le donjon d'Ombrecroc peut garder ses ombres, {name}. Merci."
L["The next shadow bolt's in for a letdown, {name}. Thank you."] = "Le prochain Trait de l'ombre va être déçu, {name}. Merci."
L["On your {gift} I'll brave Duskwood tonight, {name}. Or tomorrow."] = "Avec votre {gift}, je braverai le bois de la Pénombre ce soir, {name}. Ou demain."
L["{gift}! A squirrel just nodded at me, {name}. Here's yours."] = "{gift} ! Un écureuil vient de me saluer, {name}. À votre tour."
L["Tougher hide, sharper senses, {name}. I may have to fight the urge to forage."] = "Cuir épais, sens aiguisés, {name}. Je résiste à l'envie de ramasser des glands."
L["I feel all wild and leafy, {name}. Thank you. Sorry if I shed bark."] = "Je me sens pousser des feuilles, {name}. Merci. Pardon si je perds de l'écorce."
L["Thicker skin from your {gift}, {name}. Arrows and insults both."] = "Cuir épais grâce à votre {gift}, {name}. Flèches et insultes glissent dessus."
L["{gift}! A bird tried to nest on me, {name}. Thanks, I think."] = "{gift} ! Un oiseau a voulu nicher sur moi, {name}. Merci, je crois."
L["Half a tree now, {name}, the better half. Thanks for the {gift}."] = "Me voilà à moitié arbre, {name}, la meilleure moitié. Merci pour {gift}."
L["Thank you, {name}. I've an urge to stand in the rain and grow. I'll resist."] = "Merci, {name}. J'ai envie de rester sous la pluie à pousser. Je résiste."
L["Every bramble in the Barrens will think twice now, {name}. Thank you."] = "Les ronces des Tarides y réfléchiront à deux fois, {name}. Merci."
L["Thank you, {name}. Even my boots feel like they've put down roots."] = "Merci, {name}. Même mes bottes ont l'air d'avoir pris racine."
L["{gift}, {name}! Nobody's hugging me today. Have this instead."] = "{gift}, {name} ! Personne ne m'enlacera aujourd'hui. Prenez plutôt ceci."
L["Prickly now, thanks to you, {name}. More than usual, I mean."] = "J'ai des piquants grâce à vous, {name}. Plus que d'habitude, je veux dire."
L["Your {gift}, {name}! Let the next kobold try for my candle."] = "Votre {gift}, {name} ! Qu'un kobold essaie donc de prendre ma bougie."
L["{gift}! I'm a thicket with opinions now, {name}. Thank you."] = "{gift} ! Je suis un roncier qui a son avis sur tout, {name}. Merci."
L["Thank you, {name}. The next thing that bites me will need a moment to reflect."] = "Merci, {name}. Le prochain qui me mord aura de quoi réfléchir."
L["{gift} from you, {name}? I'll try not to found a dynasty."] = "{gift} de votre part, {name} ? J'essaierai de ne pas fonder de dynastie."
L["A little better at everything, {name}. Is this how kings feel? No wonder."] = "Tout un peu mieux, {name}. C'est ça, être roi ? Pas étonnant qu'ils y tiennent."
L["Your {gift}! My first decree, {name}: thank you."] = "Votre {gift} ! Mon premier décret, {name} : merci."
L["{gift} on a commoner, {name}? I'll try to look regal."] = "{gift} sur un roturier, {name} ? Je vais tâcher d'avoir l'air royal."
L["With your {gift} I could rule a small kingdom, {name}. Westfall."] = "Avec votre {gift}, je régnerais sur un petit royaume, {name}. La Marche de l'Ouest."
L["Thank you, {name}. I'm a little better at everything now, gratitude included."] = "Merci, {name}. Je suis un peu meilleur en tout, gratitude comprise."
L["Stronger arms already, {name}. I'll try not to hug anyone. Thank you."] = "Des bras plus forts, déjà, {name}. J'éviterai les accolades. Merci."
L["With {gift} I could lift a kodo, {name}. I won't, but thank you."] = "Avec {gift}, je soulèverais un kodo, {name}. Je m'abstiens, mais merci."
L["Your {gift} has my arms very confident, {name}. Thank you."] = "Avec votre {gift}, mes bras prennent la grosse tête, {name}. Merci."
L["{gift}! Opened a jar I've fought since Stranglethorn, {name}."] = "{gift} ! J'ai ouvert un bocal qui me résistait depuis Strangleronce, {name}."
L["Thank you, {name}. My next swing is dedicated to you. So is the dent."] = "Merci, {name}. Mon prochain coup vous est dédié. La bosse aussi."
L["{gift} from you, {name}, and my first wise act is this."] = "{gift} de votre part, {name}, et mon premier acte de sagesse, le voici."
L["Wiser already, {name}. Wise enough to know a kindness when I see one."] = "Déjà plus sage, {name}. Assez pour reconnaître une gentillesse quand j'en vois une."
L["My mana thanks you for {gift}, {name}. It's the shy one of us."] = "Mon mana vous remercie pour {gift}, {name}. C'est le timide de nous deux."
L["Your {gift} refills me faster than I spend, {name}. Nearly."] = "Votre {gift} me remplit plus vite que je ne dépense, {name}. Presque."
L["Your {gift}, {name}: mana back, and an urge to give advice."] = "Votre {gift}, {name} : du mana, et une envie de donner des conseils."
L["{gift}! The monsters forgot me at once, {name}. I won't."] = "{gift} ! Les monstres m'oublient déjà, {name}. Moi, je ne vous oublierai pas."
L["Nothing wants to fight me now, {name}. It's lovely. Thank you."] = "Plus rien ne veut se battre contre moi, {name}. C'est merveilleux. Merci."
L["{gift}! Nothing's glared at me in minutes, {name}. Thank you."] = "{gift} ! Plus rien ne m'a regardé de travers depuis des minutes, {name}. Merci."
L["{gift}! A mouse at a dragon's feast, {name}: unseen, well fed."] = "{gift} ! Une souris au festin d'un dragon, {name} : invisible et bien nourrie."
L["Thanks to {gift} I'm just a rumour in a fight, {name}."] = "Grâce à {gift}, je ne suis plus qu'une rumeur au combat, {name}."
L["The Light finds me easier now, {name}. It says thank you, and so do I."] = "La Lumière me trouve plus facilement, {name}. Elle vous remercie, et moi aussi."
L["Easier to heal now, thanks to you, {name}. My healer thanks you too."] = "Plus facile à soigner grâce à vous, {name}. Mon soigneur vous remercie aussi."
L["With your {gift}, {name}, every heal feels like a homecoming."] = "Avec votre {gift}, {name}, chaque soin a un air de retour au bercail."
L["{gift}! The Light and I are on first-name terms now, {name}."] = "{gift} ! La Lumière et moi, on se tutoie maintenant, {name}."
L["With {gift} the Light hears me first, {name}. No need to shout."] = "Avec {gift}, la Lumière m'entend en premier, {name}. Inutile de crier."
L["Blows land softer on me now, {name}. My bruises thank you, and so do I."] = "Les coups m'arrivent plus doucement, {name}. Mes bleus vous remercient, et moi aussi."
L["Every hit gentler, thanks to you, {name}. I'll make sure they notice."] = "Chaque coup plus doux grâce à vous, {name}. Je veillerai à ce qu'ils le remarquent."
L["Your {gift} softens every blow, {name}. I'm upholstered."] = "Votre {gift} amortit chaque coup, {name}. Je suis capitonné."
L["{gift}! Now the Light takes every hit personally, {name}."] = "{gift} ! La Lumière prend désormais chaque coup à titre personnel, {name}."
L["With your {gift} I'm half fortress, half chapel, {name}."] = "Avec votre {gift}, je suis mi-forteresse, mi-chapelle, {name}."
L["You shouted at me, {name}, and I've never felt so encouraged. Here."] = "Vous m'avez crié dessus, {name}, et je n'ai jamais eu autant de courage. Tenez."
L["My ears are ringing, {name}, and my arms feel twice as strong. Thank you!"] = "J'en ai les oreilles qui sifflent, {name}, et les bras deux fois plus forts. Merci !"
L["{gift}, {name}! I felt that in my teeth. In a good way."] = "{gift}, {name} ! Je l'ai senti jusque dans mes dents. En bien."
L["I'll answer your {gift} quietly, {name}. Somebody should."] = "Je réponds à votre {gift} à voix basse, {name}. Il en faut bien un."
L["Your {gift} nearly had me charging a wall, {name}. Here, calmly."] = "Votre {gift} a failli me faire charger un mur, {name}. Tenez, dans le calme."
L["All Azeroth heard your {gift}, {name}. Only I get to thank you."] = "Tout Azeroth a entendu votre {gift}, {name}. Moi seul ai le droit de vous remercier."
L["Your shout's still ringing, {name}, and so is my sword arm. Thank you."] = "Votre cri résonne encore, {name}, et mon bras armé en vibre aussi. Merci."
L["I didn't catch the words, {name}, but my arms did. Thank you!"] = "Je n'ai pas saisi les mots, {name}, mais mes bras, si. Merci !"
L["Thank you, {name}. I'll hit the next thing twice as hard and blame you."] = "Merci, {name}. Je frapperai deux fois plus fort, et ce sera votre faute."
L["I can breathe underwater, {name}! I may never need to, but thank you."] = "Je respire sous l'eau, {name} ! Ça ne servira peut-être jamais, mais merci."
L["Lungs like a murloc, thanks to you, {name}. Mrgl. Sorry. Thank you."] = "Des poumons de murloc grâce à vous, {name}. Mrgl. Pardon. Merci."
L["With {gift} I'll raid every sunken wreck, {name}. Half's yours."] = "Avec {gift}, je vais piller chaque épave, {name}. Moitié-moitié."
L["I won't ask where {gift} gets its air, {name}. Just: thanks."] = "Je ne demande pas d'où {gift} tire son air, {name}. Juste : merci."
L["With {gift} I'll cross Lordamere Lake, {name}. Underneath."] = "Avec {gift}, je traverserai le lac Lordamere, {name}. Par en dessous."
L["We have to stop meeting like this, {name}. Actually, no, we don't."] = "Il faut qu'on arrête de se croiser comme ça, {name}. En fait, non, pas du tout."
L["Again, {name}? Splendid. I've been practising since last time."] = "Encore, {name} ? Splendide. J'ai répété depuis la dernière fois."
L["You again, {name}? People will start saying we're friends."] = "Encore vous, {name} ? On va finir par dire qu'on est amis."
L["Same face, same spell, {name}. I do love a tradition."] = "Même visage, même sort, {name}. J'adore les traditions."
L["Another round, {name}? I'm keeping score, and we're both winning."] = "Une autre tournée, {name} ? Je compte les points, et on gagne tous les deux."
L["Ah, {name}! My favourite repeat customer."] = "Ah, {name} ! Mon habitué préféré."
L["Our paths keep crossing, {name}. I think the road is dropping hints."] = "Nos chemins se croisent sans cesse, {name}. La route nous fait des clins d'œil."
L["Hello again, {name}. Do stop me if you've heard this one."] = "Rebonjour, {name}. Arrêtez-moi si vous connaissez celle-là."
L["I kept some aside, {name}, in case you came back. Good instinct, mine."] = "J'en avais mis de côté, {name}, au cas où vous reviendriez. Bon instinct, le mien."
L["Back already, {name}? I'm starting to think you like me."] = "Déjà de retour, {name} ? Je commence à croire que je vous plais."
L["Again, {name}? At this rate I'll have to learn your middle name."] = "Encore, {name} ? À ce rythme, je vais devoir apprendre votre deuxième prénom."
L["Once is kindness, twice is a habit, {name}. I've never broken a habit yet."] = "Une fois, c'est gentil ; deux fois, c'est une habitude, {name}. Et jamais deux sans trois."
L["Encore, {name}. The crowd demanded it. The crowd is you."] = "Bis, {name}. Le public l'a réclamé. Le public, c'est vous."
L["One more of these, {name}, and we'll have to draw up a guild charter."] = "Encore une comme ça, {name}, et il faudra rédiger une charte de guilde."
L["I'd know your footsteps anywhere now, {name}. Handy; I'm terrible with faces."] = "Je reconnaîtrais votre pas n'importe où, {name}. Pratique : je suis nul avec les visages."
L["Us again, {name}. The world must be running out of other people."] = "Encore nous deux, {name}. Le monde doit être à court d'autres gens."
L["Last time went so well, {name}, I've changed nothing. Not even my expression."] = "La dernière fois s'est si bien passée, {name}, que je n'ai rien changé. Pas même ma tête."
L["I know where you stand now, {name}. Literally; I've aimed at it before."] = "Je sais où vous vous situez, {name}. Au sens propre : j'ai déjà visé l'endroit."
L["Oh, it's you, {name}. Good. I hate giving these to strangers."] = "Oh, c'est vous, {name}. Tant mieux. J'ai horreur d'en donner à des inconnus."
L["{name}, at this point we should just share a reagent pouch."] = "{name}, à ce stade, on devrait partager une bourse de composants."
L["Same time tomorrow, {name}? I'll bring {buff}. You bring you."] = "Même heure demain, {name} ? J'apporte {buff}. Vous, venez comme vous êtes."
L["I've lost count, {name}, and I've decided that's a compliment."] = "J'ai perdu le compte, {name}, et j'ai décidé que c'était un compliment."
L["Keep this up, {name}, and the bards will write a very dull song about us."] = "Continuez comme ça, {name}, et les bardes nous feront une chanson très ennuyeuse."
L["I could do this one in my sleep by now, {name}. I may have."] = "Je pourrais le faire en dormant, {name}. C'est peut-être déjà le cas."
L["{name}, the usual? Of course the usual. It's always the usual."] = "{name}, comme d'habitude ? Évidemment. C'est toujours comme d'habitude."
L["We ought to have a secret handshake by now, {name}. Next time, perhaps."] = "Il nous faudrait une poignée de main secrète, {name}. La prochaine fois, peut-être."
L["By now, {name}, I think we've built a small economy between us."] = "Depuis le temps, {name}, je crois qu'on a bâti une petite économie à nous deux."
L["Old friends by now, {name}. Well, old acquaintances with excellent timing."] = "De vieux amis, maintenant, {name}. Enfin, de vieilles connaissances au timing parfait."
L["Let the record show: {name} and I, undefeated at being prepared."] = "Qu'on le note : {name} et moi, invaincus quand il s'agit d'être prêts."
L["My spellbook opens to your page on its own now, {name}."] = "Mon grimoire s'ouvre tout seul à votre page, {name}."
L["If you stopped turning up, {name}, I'd report you missing to the guards."] = "Si vous cessiez de venir, {name}, je signalerais votre disparition aux gardes."
L["So much has passed between us, {name}, I've lost track of whose is whose."] = "Tant de choses ont circulé entre nous, {name}, que je ne sais plus qui a quoi."
L["We're a local landmark now, {name}. Travellers give directions by us."] = "On est devenus un point de repère, {name}. Les voyageurs s'orientent grâce à nous."
L["The innkeepers ask after you now when I come in alone, {name}."] = "Les aubergistes demandent de vos nouvelles quand j'arrive seul, {name}."
L["The guards wave us both through now, {name}. They assume we're a set."] = "Les gardes nous laissent passer tous les deux, {name}. Ils nous prennent pour un lot."
L["Folk ask which of us taught the other, {name}. I say you, to be polite."] = "On demande qui de nous deux a tout appris à l'autre, {name}. Je dis vous, par politesse."
L["I'd miss this if it stopped, {name}. So let's not stop."] = "Ça me manquerait si ça s'arrêtait, {name}. Alors, ne nous arrêtons pas."
L["Somewhere a tavern has heard all about us, {name}. Mostly from me."] = "Quelque part, une taverne sait tout de nous, {name}. Surtout par moi."
L["I hum a little when I see you coming now, {name}. Nobody else gets the hum."] = "Je fredonne un peu quand je vous vois arriver, {name}. Personne d'autre n'y a droit."
L["Safe walls, warm beds, and now {buff}. You're spoiled, {name}."] = "Des murs sûrs, des lits chauds, et maintenant {buff}. On vous gâte, {name}."
L["The guards have it covered, {name}, but I like to be thorough."] = "Les gardes veillent, {name}, mais j'aime bien faire les choses à fond."
L["Careful, {name}. Look this capable in town and folk will ask you favours."] = "Attention, {name}. Avec cet air capable en ville, on va vous demander des services."
L["Not a monster for miles, {name}. Still, one never knows about the cooking."] = "Pas un monstre à des lieues, {name}. Mais avec la cuisine, on ne sait jamais."
L["For the crowds, {name}. In town, they're the real danger."] = "Pour la foule, {name}. En ville, c'est elle le vrai danger."
L["Rest easy, {name}. I'll count that my good deed and go find a pint."] = "Reposez-vous, {name}. Ce sera ma bonne action du jour ; je vais chercher une chope."
L["Even in town, {name}, a dragon has been known to drop in. Better safe."] = "Même en ville, {name}, un dragon peut passer à l'improviste. Prudence."
L["Best do it in here, {name}. Out there, nobody stands still long enough."] = "Mieux vaut le faire ici, {name}. Dehors, personne ne reste en place assez longtemps."
L["Mind the pickpockets, {name}. This is the one thing on you they can't lift."] = "Gare aux pickpockets, {name}. Ça, au moins, ils ne pourront pas vous le faucher."
L["City rules, {name}: no blades drawn, no spells thrown. This one's allowed."] = "Règlement municipal, {name} : ni lame au clair, ni sort lancé. Celui-ci est toléré."
L["Nothing to fight here but the queue at the mailbox, {name}. Take this anyway."] = "Rien à combattre ici, sauf la file devant la boîte aux lettres, {name}. Prenez ceci quand même."
L["For the walk to the bank, {name}. It's always further than it looks."] = "Pour le trajet jusqu'à la banque, {name}. C'est toujours plus loin qu'on ne croit."
L["Put that on before the banker sees, {name}. They'll want to charge interest."] = "Mettez ça avant que le banquier le voie, {name}. Il voudrait prendre des intérêts."
L["The watch keeps the peace, {name}. I just keep you in one piece."] = "La garde maintient l'ordre, {name}. Moi, je vous maintiens en un seul morceau."
L["For the stairs, {name}. Whoever built this place never met a short way up."] = "Pour les escaliers, {name}. L'architecte d'ici ignorait le mot « raccourci »."
L["Everything else in town has a price, {name}. This slipped past the merchants."] = "Tout le reste en ville a un prix, {name}. Ceci a échappé aux marchands."
L["Buy nothing from anyone who calls you 'friend', {name}. Except me."] = "N'achetez rien à qui vous appelle « l'ami », {name}. Sauf à moi."
L["Out here everything wants to eat you, {name}. Now it'll need a bigger fork."] = "Ici, tout veut vous manger, {name}. Il lui faudra une plus grosse fourchette."
L["No guards for miles, {name}, and the boars know it. Take this."] = "Pas un garde à des lieues, {name}, et les sangliers le savent. Prenez ceci."
L["Nobody out here but us and the wildlife, {name}. Let's be the tougher half."] = "Personne ici à part nous et la faune, {name}. Soyons la moitié la plus coriace."
L["If a bear asks, {name}, you were like this when I found you."] = "Si un ours demande, {name}, vous étiez déjà comme ça quand je vous ai trouvé."
L["The wolves have been eyeing you, {name}. This should give them pause."] = "Les loups vous lorgnent, {name}. Ça devrait les faire réfléchir."
L["Wild country, {name}. Best not to meet it armed with good intentions alone."] = "Pays sauvage, {name}. Les bonnes intentions n'y suffisent pas comme arme."
L["Map, canteen, {buff}. Now you can get lost properly, {name}."] = "Carte, gourde, {buff}. Perdez-vous dans les règles de l'art, {name}."
L["Camp's a long way off, {name}. Consider this a roof you can carry."] = "Le camp est loin, {name}. Voyez ça comme un toit portatif."
L["Murlocs, raptors, bandits, rain, {name}. This handles one of those. You pick."] = "Murlocs, raptors, bandits, pluie, {name}. Ceci règle l'un des quatre. À vous de choisir."
L["Nearest inn's a day's walk, {name}. The nearest thing with teeth is closer."] = "L'auberge la plus proche est à un jour de marche, {name}. Les crocs, bien plus près."
L["Two hills and a swamp to the next town, {name}. The swamp has opinions."] = "Deux collines et un marais jusqu'à la prochaine ville, {name}. Le marais a son mot à dire."
L["Camp carefully, {name}. Every nice clearing has an owner, and it has claws."] = "Campez prudemment, {name}. Chaque jolie clairière a un propriétaire, et il a des griffes."
L["Out here the only law is the food chain, {name}. You've just moved up a rung."] = "Ici, la seule loi, c'est la chaîne alimentaire, {name}. Vous venez de monter d'un maillon."
L["Something's following you, {name}. Probably a boar. This is in case it isn't."] = "Quelque chose vous suit, {name}. Un sanglier, sans doute. Ceci, pour le cas contraire."
L["Stay on the road, {name}. The road has guards. Some of the time."] = "Restez sur la route, {name}. La route a des gardes. De temps en temps."
L["Rain's coming, {name}, and so are the wolves. One of those I can help with."] = "La pluie arrive, {name}, les loups aussi. Pour la pluie, je ne peux rien."
L["Somewhere in here a villain is rehearsing a speech, {name}. Let's interrupt."] = "Quelque part ici, un méchant répète son discours, {name}. Interrompons-le."
L["Whatever waits at the end of this place, {name}, let's make it regret it."] = "Quoi qui nous attende au bout, {name}, faisons-le-lui regretter."
L["They say nobody leaves here alive, {name}. Let's be rude and prove them wrong."] = "On dit que personne n'en sort vivant, {name}. Soyons impolis : prouvons le contraire."
L["Our host had years to prepare, {name}. We have {buff}."] = "Notre hôte a eu des années pour se préparer, {name}. Nous, on a {buff}."
L["Nobody builds a dungeon with a back door, {name}. Take this instead."] = "Aucun donjon n'a de porte de derrière, {name}. Prenez plutôt ceci."
L["Dark halls, old traps, worse tempers. At least you're ready, {name}."] = "Couloirs sombres, vieux pièges, pires caractères. Au moins, vous êtes prêt, {name}."
L["Better I hand you this now, {name}, than a eulogy later."] = "Mieux vaut ceci maintenant, {name}, qu'une oraison funèbre plus tard."
L["There's treasure in here, {name}, and something very large sat on it."] = "Il y a un trésor ici, {name}, et quelque chose de très gros assis dessus."
L["If a door slams shut behind us, {name}, that's tradition. Take this first."] = "Si la porte claque derrière nous, {name}, c'est la tradition. Ceci d'abord."
L["Mind the patrols, {name}. They walk the same loop forever and resent it."] = "Gare aux patrouilles, {name}. Toujours la même ronde, ça finit par aigrir."
L["Whoever built this place, {name}, spent it all on skulls and nothing on lamps."] = "Celui qui a bâti ces lieux, {name}, a tout dépensé en crânes, rien en lampes."
L["The last lot through here were never seen again, {name}. They lacked this."] = "Les derniers à passer ici n'ont jamais reparu, {name}. Il leur manquait ceci."
L["Check the ceiling, {name}. In places like this, something always drops in."] = "Levez les yeux, {name}. Ici, on tombe toujours sur quelqu'un. Ou l'inverse."
L["If we meet a talking skull, {name}, let me do the talking."] = "Si un crâne nous parle, {name}, laissez-moi lui tenir tête."
L["If the walls start whispering, {name}, don't answer. It only encourages them."] = "Ici, les murs ont des oreilles, {name}. S'ils chuchotent, ne répondez pas."
L["Touch nothing that glows, pull nothing that clicks, {name}. Wear this."] = "Ne touchez rien qui brille, ne tirez rien qui fait clic, {name}. Portez ceci."
L["Stick together in here, {name}. Echoes carry, and so do grudges."] = "Restons groupés ici, {name}. L'écho porte loin, les rancunes aussi."
L["Flags, towers, graveyards, {name}. Whatever we're fighting over, take this."] = "Drapeaux, tours, cimetières, {name}. Quel que soit l'enjeu, prenez ceci."
L["Win or lose, {name}, nobody will say you went in unprepared."] = "Victoire ou défaite, {name}, nul ne dira que vous étiez mal préparé."
L["The graveyard's just over there, {name}. Let's both not visit it."] = "Le cimetière est juste là, {name}. Évitons tous les deux d'y faire un tour."
L["Honour's on the line, {name}. So is the flag. Mostly the flag."] = "L'honneur est en jeu, {name}. Le drapeau aussi. Surtout le drapeau."
L["Stay with the group, {name}. Lone heroes end up in the other side's songs."] = "Restez groupés, {name}. Les héros solitaires finissent dans les chansons d'en face."
L["Our banner looks better with you under it, {name}. Stand tall."] = "Notre bannière est plus belle avec vous dessous, {name}. Redressez-vous."
L["Keep your head down and your colours up, {name}."] = "Gardez la tête basse et les couleurs hautes, {name}."
L["Hold the line, {name}. The songs are always about the ones who stood."] = "Tenez bon, {name}. Les chansons parlent toujours de ceux qui ont tenu."
L["The spirit healer knows my face by now, {name}. Let's keep yours a stranger."] = "Le gardien des esprits me connaît par cœur, {name}. Restez un inconnu pour lui."
L["Drums are for courage, {name}. This is for everything else."] = "Les tambours donnent du courage, {name}. Ceci s'occupe du reste."
L["The quartermaster counts marks, {name}. I count friends. You're on my list."] = "L'intendant compte les marques, {name}. Moi, je compte sur mes amis. Vous en êtes."
L["Fight for the banner, {name}, but come back for the singing. Mine's dreadful."] = "Battez-vous pour la bannière, {name}, mais revenez pour les chants. Je chante faux."
L["Early bird, {name}? Here's something better than a worm."] = "Debout tôt, {name} ? L'avenir vous appartient. Et ceci aussi."
L["Good morning, {name}. Consider this your first cup of something strong."] = "Bien le bonjour, {name}. Votre première tasse de quelque chose de corsé."
L["Early start, {name}. The day hasn't had a chance to go wrong yet."] = "Départ matinal, {name}. La journée n'a pas encore eu le temps de mal tourner."
L["Not even lunch yet, {name}, and you're already better prepared than I am."] = "Il n'est même pas midi, {name}, et vous êtes déjà mieux préparé que moi."
L["Morning, {name}. Somewhere, the monsters are still yawning."] = "Bonjour, {name}. Quelque part, les monstres bâillent encore."
L["A fresh day and a fresh {buff}, {name}. Let's not waste either."] = "Un jour neuf, {buff} de frais, {name}. Ne gâchons ni l'un ni l'autre."
L["Up with the sun, {name}? Show-off. Here; the sun doesn't get one."] = "Levé avec le soleil, {name} ? Vous lui faites de l'ombre. Lui n'aura rien."
L["Rise and shine, {name}. Well, rise. The shining can wait till after breakfast."] = "Debout et radieux, {name}. Enfin, debout. Radieux, ce sera après le petit-déjeuner."
L["Dawn, {name}. Everything's golden and nobody's shouted yet. Let's enjoy it."] = "L'aube, {name}. Tout est doré et personne n'a encore crié. Profitons-en."
L["Too early for heroics, {name}? Nonsense. Heroics go best before lunch."] = "Trop tôt pour l'héroïsme, {name} ? Allons ! Les exploits se font à jeun."
L["The birds are singing, {name}. They haven't seen what's out there yet."] = "Les oiseaux chantent, {name}. Ils n'ont pas encore vu ce qui rôde dehors."
L["Morning, {name}. Here's the first good deed of the day. It's all downhill now."] = "Bonjour, {name}. Ma première bonne action du jour. Ensuite, ça va se gâter."
L["Still yawning, {name}? This works faster than tea."] = "Vous bâillez, {name} ? Ceci réveille mieux que le café."
L["Early, {name}. The dawn patrol looks at us like we've lost our minds."] = "Si tôt, {name}. La patrouille de l'aube nous regarde comme des fous."
L["Out this late, {name}? The night is hungrier than the day. Take this."] = "Dehors si tard, {name} ? La nuit a plus faim que le jour. Prenez ceci."
L["Past bedtime, {name}. The sensible folk are asleep, which leaves us."] = "Passé l'heure du coucher, {name}. Les gens sensés dorment ; reste nous."
L["Can't sleep either, {name}? Then let's be well-protected insomniacs."] = "Pas sommeil non plus, {name} ? Alors soyons des insomniaques bien protégés."
L["Mind the dark, {name}. Not everything out there is as friendly as I am."] = "Méfiez-vous du noir, {name}. Dehors, tout n'est pas aussi aimable que moi."
L["It's late, {name}. This should keep you going till the sun remembers us."] = "Il est tard, {name}. De quoi tenir jusqu'à ce que le soleil se souvienne de nous."
L["Only the owls and us awake, {name}, and the owls get no {buff}."] = "Debout : nous et les chouettes, {name}. Et les chouettes n'ont pas droit à {buff}."
L["The inns have locked up, {name}. This is the only thing still being served."] = "Les auberges sont fermées, {name}. Ceci, c'est la dernière tournée."
L["It's the hour for ghost stories, {name}. Take this, in case one is true."] = "L'heure des histoires de fantômes, {name}. Ceci, au cas où l'une serait vraie."
L["Candles low, stars high, {name}. A good hour for small kindnesses."] = "Bougies basses, étoiles hautes, {name}. L'heure des petites attentions."
L["Quiet hour, {name}. Every creak sounds like an ambush. Most of them aren't."] = "Tout est calme, {name}. Chaque craquement sent l'embuscade. Presque aucun ne l'est."
L["This late, {name}, even the guards are talking to themselves."] = "À cette heure, {name}, même les gardes parlent tout seuls."
L["This is the hour things climb out of graves, {name}. Take this; walk briskly."] = "C'est l'heure où les choses sortent des tombes, {name}. Prenez ceci ; pressez le pas."
L["Tomorrow you'll wonder why you stayed up, {name}. This is one good reason."] = "Demain, vous vous demanderez pourquoi veiller, {name}. Voici une bonne raison."
L["Takes one to know one, {name}. Takes one to do it properly, too."] = "Qui se ressemble s'assemble, {name}. Et s'entraide mieux, aussi."
L["From one of our trade to another, {name}. No need to check my work."] = "Entre gens du métier, {name}. Inutile de vérifier mon travail."
L["Professional courtesy, {name}. We don't charge each other."] = "Courtoisie professionnelle, {name}. Entre collègues, on ne se fait pas payer."
L["Two of a kind, {name}. Between us we could write the manual."] = "Nous sommes du même bois, {name}. À nous deux, on pourrait écrire le manuel."
L["Don't look so surprised, {name}. Same trainer, I expect."] = "Ne faites pas cette tête, {name}. Même entraîneur, sûrement."
L["I'd critique your technique, {name}, but mine looks exactly the same."] = "Je critiquerais bien votre technique, {name}, mais la mienne est exactement la même."
L["Don't tell the others, {name}, but ours really is the finest calling."] = "Ne le dites pas aux autres, {name}, mais notre vocation est vraiment la plus belle."
L["Look at us, {name}. Two experts, making it look easy. It isn't, is it?"] = "Regardez-nous, {name}. Deux experts, et ça a l'air facile. Ça ne l'est pas, hein ?"
L["Between colleagues, {name}: I also have no idea how half of it works."] = "Entre collègues, {name} : moi aussi, la moitié du métier m'échappe."
L["Same trade, {name}, so you know exactly how hard that was. Let's say very."] = "Même métier, {name}, donc vous savez à quel point c'était dur. Disons : très."
L["If anyone asks, {name}, we trained each other."] = "Si on demande, {name}, on s'est formés l'un l'autre."
L["Calling to calling, {name}. We should compare notes. Mine are mostly doodles."] = "Entre confrères, {name}, comparons nos notes. Moi, j'ai surtout des gribouillis."
L["Colleague, {name}. We should found a society. Dues, minutes, a very small hat."] = "Fondons une amicale, {name}. Cotisations, procès-verbaux et un tout petit chapeau."
L["We'd be twins, {name}, if I were a touch better-looking."] = "On serait jumeaux, {name}, si j'étais un peu plus beau."
L["I'd shout some encouragement, {name}, but you do that far better."] = "Je vous crierais bien des encouragements, {name}, mais vous le faites bien mieux."
L["Charge in as usual, {name}. I'll simply feel better about it now."] = "Chargez comme d'habitude, {name}. Ça me rassurera un peu plus, voilà tout."
L["For the one who goes in first, {name}. Somebody has to, and it's never me."] = "Pour celui qui passe en premier, {name}. Il en faut bien un, et ce n'est jamais moi."
L["You take the hits so the rest of us don't, {name}. It's the least I can do."] = "Vous prenez les coups à notre place, {name}. C'est bien le moins que je puisse faire."
L["Go on, {name}, charge. I'll be right behind you. Quite a long way behind."] = "Allez-y, {name}, chargez. Je serai juste derrière vous. Assez loin derrière."
L["For the one who fixes every problem by hitting it, {name}. It usually works."] = "Pour qui règle chaque problème en tapant dessus, {name}. Et ça marche, en général."
L["I'd shake your hand, {name}, but both of yours are holding something sharp."] = "Je vous serrerais la main, {name}, mais les vôtres tiennent chacune une lame."
L["A little help for a lot of armour, {name}. I hope it fits under there."] = "Petite aide, grosse armure, {name}. J'espère qu'il reste de la place dessous."
L["You'll charge something enormous soon, {name}. I'm just helping it lose."] = "Vous chargerez bientôt quelque chose d'énorme, {name}. Je l'aide juste à perdre."
L["Save the bubble for later, {name}. This one's from me."] = "Gardez votre bulle pour plus tard, {name}. Ceci vient de moi."
L["You bless everyone else all day, {name}. Here's one going the other way."] = "Vous bénissez les autres à longueur de journée, {name}. Pour une fois, l'inverse."
L["The Light already likes you, {name}. Consider this a second opinion."] = "La Lumière vous apprécie déjà, {name}. Voyez ceci comme un deuxième avis."
L["Even the Light's own champion needs a hand now and then, {name}."] = "Même le champion de la Lumière a besoin d'un coup de main, parfois, {name}."
L["I'd ask for a blessing back, {name}, but then we'd be here all day."] = "Je vous demanderais bien une bénédiction, {name}, mais on n'en finirait plus."
L["For the one who carries a hammer and a conscience, {name}. Heavy load."] = "Pour qui porte un marteau et une conscience, {name}. Lourd fardeau."
L["Don't thank the Light for this one, {name}. It had the day off. This was me."] = "Ne remerciez pas la Lumière, {name}. Elle était de repos. C'était moi."
L["No need to kneel, {name}. I know it's a habit."] = "Ne vous agenouillez pas, {name}. Je sais, l'habitude."
L["One for you, {name}, and a pat on the head for your companion."] = "Ceci pour vous, {name}, et une caresse sur la tête pour votre compagnon."
L["You watch everyone's back from range, {name}. I've got yours."] = "Vous couvrez nos arrières à distance, {name}. Moi, je couvre les vôtres."
L["Hunter's Mark for them, {buff} for you, {name}. Much nicer."] = "Marque du chasseur pour eux, {buff} pour vous, {name}. Bien plus sympathique."
L["Aim true, {name}. And if it charges you anyway, run towards the rest of us."] = "Visez juste, {name}. Et si ça vous charge quand même, courez vers nous."
L["Your pet was looking at me hopefully, {name}. This is for you; tell it sorry."] = "Votre familier me regardait plein d'espoir, {name}. C'est pour vous ; dites-lui pardon."
L["Nothing for the pet this time, {name}. It's already had three of my sandwiches."] = "Rien pour le familier cette fois, {name}. Il a déjà mangé trois de mes sandwichs."
L["I'd have brought arrows, {name}, but I never know which kind you like."] = "J'aurais bien pris des flèches, {name}, mais lesquelles aimez-vous ?"
L["You can track anything, {name}, but you never saw this one coming."] = "Vous pistez tout, {name}, mais celui-là, vous ne l'avez pas vu venir."
L["For the one I never see coming, {name}. Meant as the highest praise."] = "Pour celui que je ne vois jamais arriver, {name}. C'est un immense compliment."
L["Quick, {name}, before you vanish again."] = "Vite, {name}, avant votre prochaine Disparition."
L["Poison on the blades, {buff} on you. Very thorough, {name}."] = "Du poison sur les lames, {buff} sur vous. Travail soigné, {name}."
L["I'd slip it in your pocket, {name}, but you'd notice. You always notice."] = "Je vous le glisserais bien en poche, {name}, mais vous voyez toujours tout."
L["For the one who opens every locked box, {name}. This one comes unlocked."] = "Pour qui crochète tous les coffrets, {name}. Celui-ci s'ouvre tout seul."
L["Nobody sees you coming, {name}. Now it's even worse news when they do."] = "Personne ne vous voit venir, {name}. Et quand on vous voit, c'est pire encore."
L["Take this, {name}. Very discreet. It even walks quietly."] = "Prenez ceci, {name}. Très discret. Il marche même à pas de loup."
L["I'd have wrapped it, {name}, but you'd only pick the knot."] = "Je l'aurais emballé, {name}, mais vous auriez crocheté le nœud."
L["Keep this one, {name}. You don't even have to steal it."] = "Gardez-le, {name}. Vous n'avez même pas à le voler."
L["For once, {name}, somebody's looking after the priest."] = "Pour une fois, {name}, quelqu'un s'occupe du prêtre."
L["Save your prayers for the rest of us, {name}. This one's already answered."] = "Gardez vos prières pour nous autres, {name}. Celle-ci est déjà exaucée."
L["Light or Shadow, {name}, I don't ask which. This suits both."] = "Lumière ou Ombre, {name}, je ne demande pas. Ceci convient aux deux."
L["Sit down after this fight, {name}. That's an order, from a grateful patient."] = "Asseyez-vous après ce combat, {name}. C'est un ordre, d'un patient reconnaissant."
L["You keep us all standing, {name}. Here's a little of it coming back."] = "Vous nous gardez tous debout, {name}. En voici un peu en retour."
L["You've knelt beside all of us, {name}. Stand tall a minute."] = "Vous vous agenouillez auprès de tous, {name}. Redressez-vous un peu."
L["Something that needed no prayer, {name}. You've said plenty of those today."] = "Ceci n'a coûté aucune prière, {name}. Vous en avez assez dit aujourd'hui."
L["No voice in your head comes with this one, {name}. Refreshing, isn't it?"] = "Pas de voix dans la tête avec celui-là, {name}. Reposant, non ?"
L["The Ebon Blade asks no favours, {name}. I'm giving one anyway."] = "La Lame d'ébène ne demande rien, {name}. Je vous fais une faveur quand même."
L["A little warmth, {name}. I know you don't feel the cold. It's the thought."] = "Un peu de chaleur, {name}. Vous ignorez le froid, je sais. C'est le geste qui compte."
L["You came back from the dead, {name}. The least I can do is help you stay back."] = "Vous revenez de chez les morts, {name}. Je vous aide à ne pas y retourner."
L["Runes, plague and frost, {name}. Take this too; it completes the set."] = "Runes, peste et givre, {name}. Prenez ceci aussi, ça complète la panoplie."
L["A skeletal horse and a sword that talks back, {name}. Here's something normal."] = "Un cheval squelettique et une lame qui répond, {name}. Tenez, du normal, pour changer."
L["No need to drag me over on a chain, {name}. I was coming anyway."] = "Inutile de me tirer par la chaîne, {name}. J'arrivais de toute façon."
L["Welcome back to the land of the living, {name}. Well, its general direction."] = "Bon retour parmi les vivants, {name}. Enfin, dans les parages."
L["The elements look after you, {name}, but they don't make house calls."] = "Les éléments veillent sur vous, {name}, mais ils ne se déplacent pas à domicile."
L["Tell the spirits I said hello, {name}. They never write back."] = "Saluez les esprits de ma part, {name}. Ils ne répondent jamais à mes lettres."
L["Plant a totem in my honour, {name}. A small one. I'm modest."] = "Plantez un totem en mon honneur, {name}. Un petit. Je suis modeste."
L["Earth, fire, water, air and me, {name}. Admittedly the least of the five."] = "Terre, feu, eau, air, et moi, {name}. Certes, le moindre des cinq."
L["Totems up already, {name}? Then this goes next to them. Don't plant it."] = "Vos totems sont déjà posés, {name} ? Alors ceci va à côté. Ne le plantez pas."
L["The wind would have brought you this, {name}, but it's flighty. I'm reliable."] = "Le vent vous aurait apporté ceci, {name}, mais il est volage. Moi, je suis fiable."
L["Tell the earth I said thanks, {name}. It's done so much for my feet."] = "Remerciez la terre pour moi, {name}. Elle m'a toujours soutenu."
L["The spirits said you'd earned this, {name}. I didn't ask; they volunteered."] = "Selon les esprits, vous le méritez, {name}. Je n'ai rien demandé ; ils ont insisté."
L["A gift for a mage, {name}? Like bringing water to... well, you."] = "Un cadeau pour un mage, {name} ? Comme apporter de l'eau à... enfin, vous."
L["You solve most problems with sheep, {name}. This covers the rest."] = "Vous réglez presque tout avec des moutons, {name}. Ceci couvre le reste."
L["You could teleport out of any trouble, {name}. This is for the trouble first."] = "Vous pourriez vous téléporter hors de tout pétrin, {name}. Ceci, c'est pour avant."
L["For the clever one, {name}. Please don't thank me by making me a sheep."] = "Pour l'esprit brillant, {name}. Ne me remerciez pas en me changeant en mouton."
L["Blink wherever you like, {name}. This comes too."] = "Transférez-vous où bon vous semble, {name}. Ceci vous suivra."
L["Stand a little back from the fire you're about to start, {name}. Here."] = "Reculez un peu du feu que vous allez allumer, {name}. Tenez."
L["You keep us all fed and watered, {name}. Your turn to be looked after."] = "Vous nous nourrissez et nous abreuvez tous, {name}. À votre tour d'être choyé."
L["Portal fees are steep, {name}. Call this a down payment on my next one."] = "Les portails coûtent cher, {name}. Voyez ceci comme un acompte sur le prochain."
L["Entirely demon-free, {name}. I checked."] = "Garanti sans démon, {name}. J'ai vérifié."
L["Your imp may be jealous, {name}. Tell it there's plenty to go round."] = "Votre diablotin sera peut-être jaloux, {name}. Dites-lui qu'il y en a pour tous."
L["No contract, no fine print, {name}. Just a gift."] = "Pas de contrat, pas de petits caractères, {name}. Juste un cadeau."
L["For the one who hands out healthstones, {name}. Nobody ever thanks you."] = "Pour qui distribue les pierres de soins, {name}. Personne ne vous en remercie jamais."
L["Here, {name}. Summon the rest of us later and we'll call it even."] = "Tenez, {name}. Invoquez-nous plus tard et on sera quittes."
L["Your voidwalker can stop hovering, {name}. I mean well."] = "Votre marcheur du Vide peut cesser de rôder, {name}. Je viens en ami."
L["Your felhunter eats magic, {name}. Keep it off this one; it's for you."] = "Votre chasseur corrompu dévore la magie, {name}. Pas celle-ci, c'est la vôtre."
L["Keep your imp downwind, {name}, and we'll call it even."] = "Gardez votre diablotin sous le vent, {name}, et on sera quittes."
L["Carrying a bag of souls all day, {name}? Your shoulders must need this."] = "Un sac d'âmes sur le dos toute la journée, {name} ? Vos épaules en ont besoin."
L["Roll wherever you like, {name}. This rolls with you."] = "Roulez où bon vous semble, {name}. Ceci roule avec vous."
L["Brew first or fight first, {name}? Either way, take this."] = "Breuvage ou bagarre d'abord, {name} ? Dans tous les cas, prenez ceci."
L["Inner peace for you, {name}, and outer peace too, as long as this lasts."] = "La paix intérieure pour vous, {name}, et la paix extérieure aussi, tant que ça dure."
L["Chi flows better with a little help, {name}. Or so a monk once told me."] = "Le chi circule mieux avec un peu d'aide, {name}. C'est ce qu'un moine m'a dit."
L["Kick, flip, roll, {name}. I'll just stand here and do this bit."] = "Coup de pied, salto, roulade, {name}. Moi, je reste là et je fais juste ça."
L["Teach me to flip without spilling my drink, {name}, and we're even."] = "Apprenez-moi le salto sans renverser ma chope, {name}, et on sera quittes."
L["Tea, meditation and this, {name}. The three pillars of a good day."] = "Thé, méditation et ceci, {name}. Les trois piliers d'une bonne journée."
L["Tell the bear this is for them too, {name}."] = "Dites à l'ours que c'est pour lui aussi, {name}."
L["Hold still, {name}. I've never once managed to catch you as a cheetah."] = "Ne bougez pas, {name}. Je n'ai jamais réussi à vous attraper en guépard."
L["Nature looks after you already, {name}. Today she sent me to help."] = "La nature veille déjà sur vous, {name}. Aujourd'hui, elle m'envoie en renfort."
L["Whatever shape you're in next, {name}, this goes with you."] = "Quelle que soit votre prochaine forme, {name}, ceci vous suit."
L["For the forest's friend, {name}. Give my regards to the trees."] = "Pour l'ami de la forêt, {name}. Mes amitiés aux arbres."
L["It's the least we can do for somebody who is also a bear, {name}."] = "C'est bien le moins pour quelqu'un qui est aussi un ours, {name}."
L["I'd hand it to the cat, {name}, but it would only knock it off the table."] = "Je le donnerais bien au félin, {name}, mais il le ferait tomber de la table."
L["Say hello to your moonkin form for me, {name}. It always looks so startled."] = "Saluez votre forme de sélénien pour moi, {name}. Elle a toujours l'air si ahurie."
L["You were not prepared, {name}. Now you are."] = "Vous n'étiez pas prêt, {name}. Maintenant, si."
L["Ten thousand years in a cell, {name}. You've earned a small kindness."] = "Dix mille ans dans une cellule, {name}. Vous méritez une petite gentillesse."
L["You gave up so much to fight the Legion, {name}. Here's a little back."] = "Vous avez tant sacrifié pour combattre la Légion, {name}. En voici un peu en retour."
L["For the one who leaps first, {name}. Do land somewhere friendly."] = "Pour celui qui saute en premier, {name}. Atterrissez en terrain ami, surtout."
L["Fel and fury, {name}, and now a little kindness. It'll balance out."] = "Gangrène et fureur, {name}, et maintenant un peu de gentillesse. Ça va s'équilibrer."
L["I'd ask if you saw this coming, {name}, but you see everything."] = "Je vous demanderais si vous l'avez vu venir, {name}, mais vous voyez tout."
L["You can see souls, {name}. Mine's the one being generous."] = "Vous voyez les âmes, {name}. La mienne, c'est celle qui donne."
L["Illidan never let anyone help him, {name}. You're wiser than your teacher."] = "Illidan refusait toute aide, {name}. L'élève dépasse le maître."
L["A demon inside and a Legion outside, {name}. Here's one thing on your side."] = "Un démon au-dedans, une Légion au-dehors, {name}. Voici au moins un allié."
L["For you, {name}. Please don't breathe on it."] = "Pour vous, {name}. Évitez de souffler dessus, s'il vous plaît."
L["A little help for a dragon, {name}. I'll be telling my grandchildren."] = "Un coup de main à un dragon, {name}. Je le raconterai à mes petits-enfants."
L["The Aspects sent you out into the world, {name}. I'm making it friendlier."] = "Les Aspects vous ont envoyé dans le monde, {name}. Je le rends plus accueillant."
L["Take to the skies after this, {name}. I'll wave from down here."] = "Envolez-vous après ça, {name}. Je vous ferai signe d'en bas."
L["A dragon on our side, {name}. I've never felt safer being generous."] = "Un dragon dans notre camp, {name}. Jamais la générosité ne m'a paru aussi sûre."
L["A gift for a dragon, {name}. Normally folk bring gold and hope to leave again."] = "Un cadeau à un dragon, {name}. D'habitude, c'est de l'or, et on espère repartir."
L["For the one who could fly me to the next town, {name}. Not asking. Hinting."] = "Pour qui pourrait me déposer en ville, {name}. Je ne demande rien. J'insinue."
L["I've met a few dragons, {name}. You're the first I didn't run from."] = "J'ai croisé des dragons, {name}. Vous êtes le premier que je n'ai pas fui."
L["For the world's youngest ancient, {name}."] = "Pour le plus jeune ancien du monde, {name}."
L["{buff} for a mage, {name}. Like lending a library a book."] = "{buff} pour un mage, {name}. Comme prêter un livre à une bibliothèque."
L["Mage to mage, {name}: I won't ask you for water if you won't ask me."] = "Entre mages, {name} : je ne vous demande pas d'eau si vous ne m'en demandez pas."
L["Two mages, {name}. Between us we can portal anywhere and still be late."] = "Deux mages, {name}. Des portails partout, et pourtant toujours en retard."
L["A mage for a mage, {name}. The Kirin Tor would call this peer review."] = "D'un mage à un mage, {name}. Le Kirin Tor appellerait ça une évaluation par les pairs."
L["A mage enchanting a mage, {name}. We'll both pretend we needed it."] = "Un mage enchante un mage, {name}. Enchanté ! Faisons comme si c'était utile."
L["Neither of us will admit which spells we still read off the page, {name}."] = "Aucun de nous n'avouera quels sorts il lit encore dans le grimoire, {name}."
L["One mage is a scholar, {name}. Two is an argument. Here's my opening point."] = "Un mage, c'est un érudit, {name}. Deux, c'est un débat. Voici mon premier argument."
L["We both know this spell backwards, {name}. Luckily I cast it forwards."] = "On connaît ce sort dans tous les sens, {name}. Moi, je le lance dans le bon."
L["More mana for you, {name}. Try not to spend it all on one fireball."] = "Plus de mana pour vous, {name}. Évitez de tout dépenser en une Boule de feu."
L["Priest to priest, {name}: who blesses the blessers? Today, me."] = "De prêtre à prêtre, {name} : qui bénit ceux qui bénissent ? Aujourd'hui, moi."
L["Between us priests, {name}, we'll both pretend the tank listens."] = "Entre prêtres, {name}, faisons tous deux semblant que le tank écoute."
L["A priest looking after a priest, {name}. It feels almost forbidden."] = "Un prêtre qui prend soin d'un prêtre, {name}. Ça semble presque interdit."
L["Two priests, {name}. Twice the praying and half the panic."] = "Deux prêtres, {name}. Deux fois plus de prières, deux fois moins de panique."
L["Two priests, {name}. If it goes wrong, we're the last ones standing. Kneeling."] = "Deux prêtres, {name}. Si ça tourne mal, nous serons les derniers debout. À genoux."
L["Your prayers can take a break, {name}. Mine are covering the shift."] = "Vos prières peuvent faire une pause, {name}. Les miennes assurent la relève."
L["I'd preach to you, {name}, but you've heard it. You've probably given it."] = "Vous faire un sermon, {name}, serait prêcher un converti. Voire le prêcheur."
L["Same vows and same sore knees, {name}. Here's something for yours."] = "Mêmes vœux, mêmes genoux endoloris, {name}. Ceci est pour les vôtres."
L["If I fall, {name}, you know the words. If you fall, so do I. Let's neither."] = "Si je tombe, {name}, vous connaissez les paroles. Et inversement. Évitons."
L["Two druids, {name}. The Cenarion Circle would call this a quorum."] = "Deux druides, {name}. Le Cercle cénarien appellerait ça un quorum."
L["Druid to druid, {name}: bear or cat, I'd know you by the leaves in your hair."] = "Entre druides, {name} : ours ou félin, je vous reconnais aux feuilles dans vos cheveux."
L["From one shapeshifter to another, {name}: this one fits every shape."] = "D'un métamorphe à un autre, {name} : celui-ci va à toutes les formes."
L["No handshake, {name}. Two druids, and neither of us has the right shape for it."] = "Pas de poignée de main, {name}. Deux druides, et aucun de nous n'a la bonne forme."
L["Between us, {name}, we've a shape for every problem. Mostly bears."] = "À nous deux, {name}, une forme pour chaque problème. Surtout des ours."
L["Fellow druid, {name}? Then you know the trees told me you were coming."] = "Druide aussi, {name} ? Alors vous savez que les arbres m'ont prévenu."
L["If you see me as a cat later, {name}, pretend you don't know me. Dignity."] = "Si vous me croisez en félin plus tard, {name}, ignorez-moi. Question de dignité."
L["Paladin to paladin, {name}: I won't mention the bubble if you don't."] = "Entre paladins, {name} : je ne parle pas de la bulle si vous n'en parlez pas."
L["A blessing for a paladin, {name}. Now we're both insufferably radiant."] = "Bénir un paladin, {name}. Nous voilà tous deux insupportablement radieux."
L["Two paladins, {name}. Somewhere, a priest is quietly relieved."] = "Deux paladins, {name}. Quelque part, un prêtre pousse un soupir de soulagement."
L["One of us should be humble about this, {name}. Neither of us will be."] = "L'un de nous devrait rester humble, {name}. Aucun de nous ne le sera."
L["Same oath, different polish, {name}. Yours is shinier; I noticed."] = "Même serment, autre cirage, {name}. Le vôtre brille plus ; j'ai remarqué."
L["Between us, {name}, we could light a cathedral. Or a small, very holy room."] = "À nous deux, {name}, on éclairerait une cathédrale. Ou un petit placard très saint."
L["Two suits of plate, {name}. Nobody will hear us sneak up. Nobody ever does."] = "Deux armures de plaques, {name}. Discrétion assurée. Comme toujours."
L["Your libram and mine agree on this one, {name}. Rare, that."] = "Votre libram et le mien s'accordent là-dessus, {name}. C'est rare."
L["Warlock to warlock, {name}: keep your imp away from mine. They gossip."] = "Entre démonistes, {name} : éloignez votre diablotin du mien. Ils cancanent."
L["Fellow warlock, {name}? Then you know this one's actually harmless. Honestly."] = "Démoniste vous aussi, {name} ? Alors vous savez que celui-ci est inoffensif. Vraiment."
L["Two warlocks, {name}. Let's not compare soul shards in public."] = "Deux démonistes, {name}. Ne comparons pas nos fragments d'âme en public."
L["Between us, {name}, the demons do all the work. This bit I do myself."] = "Entre nous, {name}, les démons font tout le travail. Ça, je le fais moi-même."
L["Another warlock, {name}. Let's be polite; I've seen what you summon."] = "Un autre démoniste, {name}. Restons polis ; j'ai vu ce que vous invoquez."
L["A spell from one warlock to another, {name}. Check it for curses. I would."] = "D'un démoniste à l'autre, {name}. Cherchez les malédictions. Moi, je le ferais."
L["Fellow warlock, {name}. The only one who won't ask where this came from."] = "Un confrère démoniste, {name}. Le seul qui ne demandera pas d'où ça vient."
L["Two warlocks, one kind deed, {name}. The Burning Legion must be livid."] = "Deux démonistes, une bonne action, {name}. La Légion ardente doit fulminer."
L["I'd summon you a drink, {name}, but we both know how summoning goes."] = "Je vous invoquerais un verre, {name}, mais on sait ce qui sort des invocations."
L["Two warriors, {name}. Somewhere, a healer just sighed."] = "Deux guerriers, {name}. Quelque part, un soigneur vient de soupirer."
L["Warrior to warrior, {name}: first into the fight buys the drinks. I'm buying."] = "Entre guerriers, {name} : le premier au combat paie la tournée. Je paie."
L["Shout for shout, {name}. We'll deafen the whole place together."] = "Cri pour cri, {name}. Ensemble, on va rendre tout le monde sourd."
L["No plan, {name}? Perfect. We'll get along."] = "Pas de plan, {name} ? Parfait. On va bien s'entendre."
L["Warriors, {name}: the only folk who think shouting is a spell. We're right."] = "Les guerriers, {name} : les seuls à croire qu'un cri est un sort. Et on a raison."
L["One warrior to another, {name}: whoever's hit first gets angriest. Lucky them."] = "Entre guerriers, {name} : le premier touché enrage le plus. Tant mieux pour lui."
L["You know this one, {name}. You've probably shouted it at me already."] = "Vous connaissez celui-là, {name}. Vous me l'avez sûrement déjà hurlé."
L["Our trainer would be proud, {name}. He'd shout it, but he'd be proud."] = "Notre entraîneur serait fier, {name}. Il le hurlerait, mais il serait fier."
L["Fellow warrior? Then you know the blacksmith's first name too, {name}."] = "Guerrier vous aussi ? Alors vous aussi, vous tutoyez le forgeron, {name}."
L["No mana to fill, {name}. It'll just stand about being clever, like me."] = "Pas de mana à remplir, {name}. Ça restera là à faire le malin, comme moi."
L["Intellect on a warrior, {name}. The Kirin Tor would call it research."] = "Intelligence pour un guerrier, {name} ? Le Kirin Tor parlerait de recherche."
L["I only know the one spell for friends, {name}. Rage or mana, you're getting it."] = "Je ne connais qu'un sort pour les amis, {name}. Rage ou mana, vous l'aurez."
L["Your rage doesn't need this, {name}, but I'd feel rude walking past you."] = "Votre rage n'en a pas besoin, {name}, mais passer sans rien dire serait impoli."
L["No mana, I know, {name}. Use it on locks. They're only puzzles with opinions."] = "Pas de mana, je sais, {name}. Pour les serrures, alors : des énigmes têtues."
L["It's meant for mana, {name}. You'll find a use. Rogues always find a use."] = "C'est pour le mana, {name}. Un voleur trouve toujours un usage à tout."
L["Energy, not mana, I know, {name}. Call it a very clever lockpick."] = "L'énergie, pas le mana, je sais, {name}. Disons : un rossignol très futé."
L["Aye, {name}, ye only had to ask. Hold still now!"] = "Pour sûr, {name}, suffisait d'demander. Bougez plus !"
L["Here, {name}, a wee somethin' to keep ye on yer feet."] = "Tenez, {name}, un p'tit quelque chose pour vous garder d'aplomb."
L["My thanks, {name}. Allow me to return the kindness."] = "Merci, {name}. Permettez-moi de vous rendre la politesse."
L["Of course, {name}. Stand fast a moment."] = "Bien sûr, {name}. Ne bougez pas un instant."
L["The road ahead is long, {name}. Take this with you."] = "La route est longue, {name}. Emportez ceci."
L["Ishnu-alah, {name}. Your kindness is returned."] = "Ishnu-alah, {name}. Votre bonté vous est rendue."
L["Elune-adore, {name}. Walk softly beneath the stars."] = "Elune-adore, {name}. Marchez d'un pas léger sous les étoiles."
L["The Light rewards kindness, {name}, and so shall I."] = "La Lumière récompense la bonté, {name}, et moi aussi."
L["Of course, {name}. May the Naaru guide your steps."] = "Bien sûr, {name}. Que les naaru guident vos pas."
L["The Light is with you, {name}. Go in peace."] = "La Lumière est avec vous, {name}. Allez en paix."
L["Much obliged, {name}. Gilneas never forgets a kindness."] = "Je vous suis redevable, {name}. Gilnéas n'oublie jamais un bienfait."
L["Lok'tar ogar, {name}! Take this into battle."] = "Lok'tar ogar, {name} ! Emportez ça au combat."
L["The Earth Mother sees your kindness, {name}. I return it."] = "La Terre-Mère voit votre bonté, {name}. Je vous la rends."
L["Of course, {name}. Stand tall and be at peace."] = "Bien sûr, {name}. Tenez-vous droit et soyez en paix."
L["Walk with the Earth Mother, {name}."] = "Marchez avec la Terre-Mère, {name}."
L["Sure ting, {name}. Hold still now."] = "Bien sûr, {name}. Bougez plus, là."
L["Da loa be watchin' over ya, {name}."] = "Les loa, ils veillent sur vous, {name}."
L["Such courtesy does you credit, {name}. Anar'alah belore."] = "Tant de courtoisie vous honore, {name}. Anar'alah belore."
L["Anar'alah belore, {name}. May the sun guide you."] = "Anar'alah belore, {name}. Que le soleil vous guide."
L["Your generosity is noted, {name}. Suramar remembers its friends."] = "Votre générosité est notée, {name}. Suramar n'oublie pas ses amis."
L["Thank you, {name}! The caravan always repays a kindness."] = "Merci, {name} ! La caravane rend toujours un bienfait."
L["Every traveller needs something for the road, {name}."] = "Tout voyageur a besoin de quoi tenir la route, {name}."
L["Of course, {name}. Patience, and it is done."] = "Bien sûr, {name}. Un peu de patience, et c'est fait."
L["Take this, {name}. Even a dragon needs allies."] = "Prenez ceci, {name}. Même un dragon a besoin d'alliés."
L["Thank you, {name}. The Alliance looks after its own."] = "Merci, {name}. L'Alliance veille sur les siens."
L["Of course, {name}. Allies help each other."] = "Naturellement, {name}. Entre alliés, on s'entraide."
L["For the Alliance, {name}! Stay strong out there."] = "Pour l'Alliance, {name} ! Tenez bon, là-dehors."
L["Strength and honour, {name}. Your kindness is repaid."] = "Force et honneur, {name}. Votre geste vous est rendu."
L["Consider it done, {name}. For the Horde."] = "Considérez que c'est fait, {name}. Pour la Horde."
L["For the Horde, {name}! Go with strength."] = "Pour la Horde, {name} ! Allez, et frappez fort."
L["Thank you, {name}. Good hearts are found everywhere."] = "Merci, {name}. Il y a de bons cœurs partout."
L["Gladly, {name}, whatever banner you fly."] = "Avec plaisir, {name}, quelle que soit votre bannière."
L["Friends can come from any side, {name}."] = "On trouve des amis dans tous les camps, {name}."
L["Safe travels, {name}. Take some {buff} with you."] = "Bon voyage, {name}. Emportez {buff} avec vous."
