L["|cffffd100Snoozed until %s.|r The prompt is unlocked, so it stays up to be dragged, casting nothing, until you lock it."] = "|cffffd100En pause jusqu'à %s.|r Le panneau est déverrouillé : il reste donc affiché pour que vous puissiez le déplacer, sans rien lancer, jusqu'à ce que vous le verrouilliez."
L["|cffffd100Snoozed until %s.|r No prompt until then, though who buffs you is still noticed."] = "|cffffd100En pause jusqu'à %s.|r Pas de panneau d'ici là, mais les joueurs qui vous buffent sont toujours repérés."
L["Hide the prompt for a while without turning Manners off."] = "Masquer le panneau un moment sans désactiver Manners."
L["Snooze %s"] = "Pause de %s"
L["Who buffed you, whether you returned it, and who you buffed first."] = "Qui vous a buffé, si vous avez rendu la politesse, et qui vous avez buffé spontanément."
L["Minimap and chat"] = "Minicarte et discussion"
L["Show minimap button"] = "Afficher le bouton de la minicarte"
L["Manners stays in the addon compartment under the minimap either way."] = "Manners reste de toute façon dans le menu des addons (sous la minicarte)."
L["Without it, open these settings with %s or Options > AddOns."] = "Sans lui, ouvrez ces paramètres avec %s ou via Options > AddOns."
L["A line when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed."] = "Une ligne quand quelqu'un vous buffe, quand une faveur est comptée comme rendue, et quand un clic échoue, est passé, ou laisse une faveur encore due."
L["Only you see these; they show whether a buff was missed or someone could not be reached."] = "Vous seul les voyez ; elles indiquent si une amélioration a été manquée ou si quelqu'un était hors d'atteinte."
L["Automatic (whatever they are missing)"] = "Automatique (ce qui lui manque)"
L["%s |cff808080(not learned)|r"] = "%s |cff808080(non appris)|r"
L["%s |cff808080(mana users only)|r"] = "%s |cff808080(classes à mana uniquement)|r"
L["%s |cff808080(your group only)|r"] = "%s |cff808080(votre groupe uniquement)|r"
L["This character has nothing it can cast on another player."] = "Ce personnage n'a rien à lancer sur un autre joueur."
L["You have not learned any of these yet, so nobody will be offered anything."] = "Vous n'avez encore appris aucun de ces sorts, donc rien ne sera proposé à personne."
L["Automatic never offers %s -- nobody standing in a city wants it -- so nobody will be offered anything."] = "Le mode Automatique ne propose jamais le sort %s -- personne n'en a besoin en ville -- donc rien ne sera proposé à personne."
L["Pick it in Buff to offer if you want it given out anyway."] = "Choisissez-le dans « Amélioration à proposer » si vous voulez quand même le distribuer."
L["Every spell you have learned is switched off, so nothing is offered until you switch one back on or learn one of the others."] = "Tous les sorts que vous avez appris sont désactivés, donc rien n'est proposé tant que vous n'en réactivez pas un ou n'apprenez pas l'un des autres."
L["Every spell below is switched off, so the prompt will never appear."] = "Tous les sorts ci-dessous sont désactivés, donc le panneau n'apparaîtra jamais."
L["Your blessings replace one another, so Automatic gives only the first of %s that suits them. |cffffd100Always offer|r does not check what they carry, so it can replace one of yours."] = "Vos bénédictions se remplacent l'une l'autre, donc le mode Automatique ne donne que la première parmi %s qui convient au joueur. |cffffd100Toujours proposer|r ne vérifie pas ce qu'il porte, et peut donc remplacer l'une des vôtres."
L["Your blessings replace one another, so Automatic gives only the first of %s that suits them. Where the game hides which blessing somebody carries, it can replace one of yours."] = "Vos bénédictions se remplacent l'une l'autre, donc le mode Automatique ne donne que la première parmi %s qui convient au joueur. Quand le jeu cache quelle bénédiction porte un joueur, elle peut remplacer l'une des vôtres."
L["Your blessings replace one another, so Automatic gives only the first of %s that suits them. Anybody already carrying one of yours is left alone."] = "Vos bénédictions se remplacent l'une l'autre, donc le mode Automatique ne donne que la première parmi %s qui convient au joueur. Quiconque porte déjà l'une des vôtres est laissé tranquille."
L["Automatic may offer, in this order: %s. Each person gets the first one they are missing."] = "Le mode Automatique peut proposer, dans cet ordre : %s. Chaque joueur reçoit le premier sort qui lui manque."
L["When the game hides what someone has, it tries the next one each time."] = "Quand le jeu cache ce qu'un joueur possède, le mode Automatique essaie le suivant à chaque fois."
L["Only |cffffffff%s|r is offered, to everybody, whatever else they are missing. The per-spell switches come back with Automatic."] = "Seul le sort |cffffffff%s|r est proposé, à tout le monde, quoi qu'il leur manque d'autre. Les options par sort reviennent avec le mode Automatique."
L["You picked %s in Buff to offer, but have not learned it, so nothing is offered."] = "Vous avez choisi le sort %s dans « Amélioration à proposer », mais vous ne l'avez pas appris, donc rien n'est proposé."
L["Learn it or set Buff to offer back to Automatic."] = "Apprenez-le ou remettez « Amélioration à proposer » sur Automatique."
L["Untick to never offer this buff."] = "Décochez pour ne jamais proposer cette amélioration."
L["Automatic (only while I'm the tank)"] = "Automatique (seulement si je suis tank)"
L["Automatic"] = "Automatique"
L["Automatic (%s, the one you had up last)"] = "Automatique (%s, comme la dernière fois)"
L["Automatic (%s, in a dungeon or raid)"] = "Automatique (%s, en donjon ou en raid)"
L["Automatic (%s, outside dungeons and raids)"] = "Automatique (%s, hors donjons et raids)"
L["Automatic (%s, the best you can use now)"] = "Automatique (%s, le meilleur utilisable maintenant)"
L["Automatic (%s, until you have put one up)"] = "Automatique (%s, tant que vous n'avez rien lancé)"
L["Automatic reminds you only while your group role is tank; Always reminds you whenever it is not up."] = "Le mode Automatique ne vous rappelle de la lancer que si votre rôle de groupe est tank ; le mode Toujours, dès qu'elle n'est pas active."
L["Reminds you when nothing is on the weapon in your main hand and a scroll in your bags fits it. Automatic takes the one you used last, else the best you can use."] = "Vous le rappelle quand l'arme de votre main droite ne porte rien et qu'un parchemin de vos sacs lui convient. Le mode Automatique choisit celui que vous avez utilisé en dernier, sinon le meilleur que vous pouvez utiliser."
L["Reminds you when no familiar is with you and a scroll for one is in your bags. Automatic takes the one you used last, else the best your level allows."] = "Vous le rappelle quand aucun familier ne vous accompagne et qu'un parchemin de familier se trouve dans vos sacs. Le mode Automatique choisit celui que vous avez utilisé en dernier, sinon le meilleur que votre niveau permet."
L["Reminds you when none of these is up. Automatic takes the one you had up last."] = "Vous rappelle de lancer l'une de ces améliorations quand aucune n'est active. Le mode Automatique choisit celle que vous aviez en dernier."
L["Until you have had one up: %s in a dungeon or raid, %s elsewhere."] = "Tant que vous n'avez rien lancé : %s en donjon ou en raid, %s ailleurs."
L["Don't remind me"] = "Ne pas me le rappeler"
L["Always"] = "Toujours"
L["Reminds you when it is not up."] = "Vous rappelle de la lancer quand elle n'est pas active."
L["%s: the game does not say how many you carry."] = "%s : le jeu n'indique pas combien vous en avez."
L["%s: %d in your bags"] = "%s : %d dans vos sacs"
L["You have not learned a group version of your buffs yet."] = "Vous n'avez encore appris aucune version de groupe de vos améliorations."
L["What to cast"] = "Sort à lancer"
L["Buff to offer"] = "Amélioration à proposer"
L["You offer %s."] = "Vous proposez %s."
L["%s is not offered to players without mana, such as warriors and rogues."] = "Le sort %s n'est pas proposé aux joueurs sans mana, comme les guerriers et les voleurs."
L["%s are not offered to players without mana, such as warriors and rogues."] = "Les sorts %s ne sont pas proposés aux joueurs sans mana, comme les guerriers et les voleurs."
L["Nothing is ticked here, so the prompt will never appear."] = "Rien n'est coché ici, donc le panneau n'apparaîtra jamais."
L["People who buff me"] = "Ceux qui me buffent"
L["Offer a buff back to anyone who buffs you. Yours reaches only your own party (in a raid, your subgroup), so someone outside it is offered once they join."] = "Propose de rendre la politesse à quiconque vous buffe. Vos améliorations n'atteignent que votre propre groupe (en raid, votre sous-groupe), donc un joueur extérieur est proposé dès qu'il le rejoint."
L["Offer a buff back to anyone who buffs you. Yours reaches only your group, so someone outside it is offered once they join."] = "Propose de rendre la politesse à quiconque vous buffe. Vos améliorations n'atteignent que votre groupe, donc un joueur extérieur est proposé dès qu'il le rejoint."
L["Offer a buff back to anyone who buffs you, in your group or not."] = "Propose de rendre la politesse à quiconque vous buffe, qu'il soit dans votre groupe ou non."
L["My party and raid"] = "Mon groupe et mon raid"
L["Passers-by (players near me, not in my group)"] = "Passants (joueurs proches, hors de mon groupe)"
L["Seen through nameplates, your target, focus and mouseover."] = "Repérés via les barres d'info, votre cible, votre focalisation et l'unité sous votre curseur."
L["Everything you can offer is cast on yourself and reaches only your party, so there is nothing for passers-by."] = "Tout ce que vous pouvez proposer se lance sur vous et n'atteint que votre groupe, donc il n'y a rien pour les passants."
L["Passers-by within"] = "Distance des passants"
L["Only passers-by are measured, and only roughly: the game gives no exact distance."] = "Seuls les passants sont mesurés, et seulement approximativement : le jeu ne donne pas de distance exacte."
L["Only in cities and inns"] = "Seulement en ville et dans les auberges"
L["Out in the world, passers-by are left alone; your group and people who buff you are offered anywhere."] = "Ailleurs dans le monde, les passants sont laissés tranquilles ; votre groupe et ceux qui vous buffent sont proposés partout."
L["For a minute, offer your buff to someone who asks for it (\"fort pls\"); off by default because chat is guesswork."] = "Pendant une minute, propose votre amélioration à qui la demande (« fort stp ») ; désactivé par défaut, car interpréter la discussion reste approximatif."
L["Offer your own buffs to you when one is not up: the ones below. They are cast on you, your target is handed back, and nothing is said."] = "Vous propose vos propres améliorations quand l'une d'elles n'est pas active : celles ci-dessous. Elles sont lancées sur vous, votre cible est rétablie et rien n'est dit."
L["Offer your own buffs to you too, when one is not up: the ones below, and the buff you give others. They are cast on you, your target is handed back, and nothing is said."] = "Vous propose aussi vos propres améliorations quand l'une d'elles n'est pas active : celles ci-dessous, et celle que vous donnez aux autres. Elles sont lancées sur vous, votre cible est rétablie et rien n'est dit."
L["Offer your own buff to you too, when you are missing it or, with top-ups on, it is running low. It is cast on you, your target is handed back, and nothing is said."] = "Vous propose aussi votre propre amélioration quand elle vous manque ou, avec les rafraîchissements activés, quand elle s'épuise. Elle est lancée sur vous, votre cible est rétablie et rien n'est dit."
L["Off: nothing is offered to you while the game calls you resting, in a city or an inn."] = "Désactivé : rien ne vous est proposé tant que le jeu vous indique au repos, en ville ou dans une auberge."
L["My group and raid"] = "Mon groupe et mon raid"
L["Use group buffs"] = "Utiliser les améliorations de groupe"
L["When this many need it"] = "Nombre de joueurs qui en ont besoin"
L["Raid groups I buff"] = "Groupes de raid que je buffe"
L["In a raid, only these groups are offered your buff; people who buff you or ask are offered anyway."] = "En raid, votre amélioration n'est proposée qu'à ces groupes ; ceux qui vous buffent ou vous la demandent sont proposés quand même."
L["Who comes first"] = "Qui passe en premier"
L["My target first"] = "Ma cible en premier"
L["Your target goes ahead of everyone when the game can see they lack the buff."] = "Votre cible passe avant tout le monde quand le jeu peut voir qu'il lui manque l'amélioration."
L["Greyed out while |cffffd100Always offer|r is chosen on %s: nothing is read then."] = "Grisé tant que |cffffd100Toujours proposer|r est choisi dans l'onglet %s : rien n'est alors vérifié."
L["Friends and guildmates first"] = "Amis et membres de guilde en premier"
L["Only changes the order; nobody is added or left out."] = "Ne change que l'ordre ; personne n'est ajouté ni écarté."
L["My group first at a ready check"] = "Mon groupe en premier lors d'un appel"
L["From a ready check until the pull, group members missing your buff go first."] = "D'un appel jusqu'au pull, les membres du groupe à qui manque votre amélioration passent en premier."
L["Group members just revived first"] = "Membres du groupe tout juste ressuscités en premier"
L["For two minutes after someone is brought back, they go first if they lack your buff."] = "Pendant deux minutes après avoir été ramené à la vie, un joueur passe en premier s'il n'a pas votre amélioration."
L["Skip players below level"] = "Ignorer les joueurs de niveau inférieur à"
L["Someone known only by name is offered anyway."] = "Un joueur connu seulement par son nom est proposé quand même."
L["Skip players out of range"] = "Ignorer les joueurs hors de portée"
L["If the game cannot tell the range they are still offered."] = "Si le jeu ne peut pas déterminer la portée, le joueur est quand même proposé."
L["Skip players flagged for PvP"] = "Ignorer les joueurs marqués JcJ"
L["Buffing somebody flagged for PvP flags you too. Ignored while you are flagged yourself, as in a battleground, but not while your own flag is running out."] = "Buffer un joueur marqué JcJ vous marque aussi. Cette option est ignorée tant que vous êtes vous-même marqué, comme sur un champ de bataille, mais pas pendant que votre propre marquage arrive à expiration."
L["Skip my own class when they can cast it too"] = "Ignorer ma propre classe quand elle peut le lancer aussi"
L["Somebody of your class can give themselves your buff, so they are left out -- unless they are too low a level for the rank you cast, and then they still get yours. People who buffed you, asked or you targeted are always offered."] = "Quelqu'un de votre classe peut se donner votre amélioration lui-même, il est donc ignoré -- sauf si son niveau est trop bas pour le rang que vous lancez : il reçoit alors le vôtre. Ceux qui vous ont buffé, qui l'ont demandé ou que vous ciblez sont toujours proposés."
L["Nobody is on the list. Shift-right-click the prompt to add the person it shows, or type a name below."] = "Personne n'est sur la liste. Faites un Maj-clic droit sur le panneau pour ajouter la personne affichée, ou tapez un nom ci-dessous."
L["One person is on the list. They are never offered anything as a passer-by or as a member of your group."] = "Une personne est sur la liste. Rien ne lui est jamais proposé, ni comme passant ni comme membre de votre groupe."
L["%d people are on the list. They are never offered anything as passers-by or as members of your group."] = "%d personnes sont sur la liste. Rien ne leur est jamais proposé, ni comme passants ni comme membres de votre groupe."
L["Somebody on it who buffs you is still offered the favour back. Shift-right-click them on the prompt to let that favour go."] = "Si quelqu'un de la liste vous buffe, il vous est quand même proposé de lui rendre la politesse. Faites un Maj-clic droit sur le panneau quand il y est affiché pour abandonner cette faveur."
L["Add a name"] = "Ajouter un nom"
L["Type it as the prompt shows it and press Enter."] = "Tapez-le tel que le panneau l'affiche et appuyez sur Entrée."
L["Pick a name"] = "Choisir un nom"
L["Remove from list"] = "Retirer de la liste"
L["Clear the list"] = "Vider la liste"
L["Take everybody off the never-offer list?"] = "Retirer tout le monde de la liste d'exclusion ?"
L["Already buffed"] = "Déjà buffé"
L["If they already have it"] = "S'il l'a déjà"
L["Your own buffs are offered when none is up; with Offer a top-up when it runs low, also when one is running out (never an aura or an aspect)."] = "Vos propres améliorations sont proposées quand aucune n'est active ; avec « Proposer un rafraîchissement quand elle s'épuise », aussi quand l'une d'elles s'épuise (jamais une aura ni un aspect)."
L["Someone who buffed you is always offered a buff back; Diagnostics shows which buffs Manners can see on others."] = "On vous propose toujours de rendre la politesse à qui vous a buffé ; l'onglet Diagnostic montre quelles améliorations Manners peut voir sur les autres."
L["Skip them (default)"] = "Les ignorer (par défaut)"
L["Offer a top-up when it runs low"] = "Proposer un rafraîchissement quand elle s'épuise"
L["Always offer (costs a lot of mana)"] = "Toujours proposer (coûte beaucoup de mana)"
L["Top up when less than this is left (minutes)"] = "Rafraîchir quand il en reste moins de (minutes)"
L["Someone whose time left cannot be read is not offered a top-up, unless they buffed you."] = "Aucun rafraîchissement n'est proposé à un joueur dont le temps restant est illisible, sauf s'il vous a buffé."
L["Everyone you offer to is offered again and again, even with a fresh buff."] = "Chaque joueur est proposé encore et encore, même avec une amélioration toute récente."
L["%s does nothing in this mode."] = "%s n'a aucun effet dans ce mode."
L["Hold back"] = "Restrictions"
L["Casting would dismount you; it is always hidden while dead, on a flight path or in a vehicle."] = "Lancer un sort vous ferait descendre de monture ; le panneau est toujours masqué quand vous êtes mort, pendant un trajet aérien ou dans un véhicule."
L["Below this, only your own buff and people who buffed you or asked are offered."] = "En dessous, seuls votre propre amélioration et ceux qui vous ont buffé ou vous l'ont demandé sont proposés."
L["Below this, only people who buffed you or asked are offered."] = "En dessous, seuls ceux qui vous ont buffé ou vous l'ont demandé sont proposés."
L["Off: buffs are offered at any mana."] = "Désactivé : les améliorations sont proposées quel que soit votre mana."
L["Below %d%% only favours, requests and your own buff are offered; the rest come back at %d%%."] = "Sous %d %%, seules les faveurs, les demandes et votre propre amélioration sont proposées ; le reste revient à %d %%."
L["Below %d%% only favours and requests are offered; the rest come back at %d%%."] = "Sous %d %%, seules les faveurs et les demandes sont proposées ; le reste revient à %d %%."
L["Fantasy (general)"] = "Fantasy (générique)"
L["loaded the %s lines."] = "série « %s » chargée."
L["In combat: changes here apply once the fight ends."] = "En combat : les modifications faites ici s'appliqueront à la fin du combat."
L["Thanks and speech"] = "Remerciements et paroles"
L["Everyone near you sees it; never in combat or instances, and at most once per person every five minutes."] = "Tous les joueurs proches le voient ; jamais en combat ni en instance, et au plus une fois par personne toutes les cinq minutes."
L["Say a line when I buff someone"] = "Dire une phrase quand je buffe quelqu'un"
L["Where to say it"] = "Où la dire"
L["Whisper them sends it only to the person you buff."] = "« Lui chuchoter » ne l'envoie qu'à la personne que vous buffez."
L["Say"] = "Dire"
L["Whisper them"] = "Lui chuchoter"
L["Emote"] = "Emote"
L["Party"] = "Groupe"
L["Raid"] = "Raid"
L["Yell"] = "Crier"
L["Only when I buff someone back"] = "Seulement quand je rends la politesse"
L["Off, you also speak when you buff someone first."] = "Désactivé, vous parlez aussi quand vous buffez quelqu'un spontanément."
L["Tick Say a line to choose what you say."] = "Cochez « Dire une phrase » pour choisir ce que vous dites."
L["Lines"] = "Phrases"
L["Line set"] = "Série de phrases"
L["Replaces the lines below."] = "Remplace les phrases ci-dessous."
L["Replace everything in the box below with the %s lines?"] = "Remplacer tout le contenu du champ ci-dessous par la série « %s » ?"
L["One line is picked at random. Placeholders: {name} their name, {buff} the spell."] = "Une phrase est tirée au hasard. Balises : {name} son nom, {buff} le sort."
L["A line too long for a macro is skipped; Try a few shows what would go out."] = "Une phrase trop longue pour une macro est ignorée ; « Essayer quelques phrases » montre ce qui partirait."
L["In character picks one of its %d lines when you click, to fit your race, faction, class and the moment. The box below shows only a few examples; editing it turns In character off."] = "« Selon le personnage » choisit une de ses %d phrases au moment du clic, adaptée à votre race, votre faction, votre classe et au moment. Le champ ci-dessous n'en montre que quelques exemples ; le modifier le désactive."
L["Your lines (one per line)"] = "Vos phrases (une par ligne)"
L["Editing these turns In character off and uses only your lines. Continue?"] = "Les modifier désactive « Selon le personnage » et n'utilise plus que vos phrases. Continuer ?"
L["Go back to In character"] = "Revenir à « Selon le personnage »"
L["Try a few lines"] = "Essayer quelques phrases"
L["Prints sample lines in your chat; only you see them."] = "Affiche des exemples de phrases dans votre discussion ; vous seul les voyez."
L["Somebody"] = "Quelqu'un"
L["A line goes out when you click, even if the cast then fails out of range or line of sight."] = "La ligne part au moment du clic, même si le sort échoue ensuite, hors de portée ou hors du champ de vision."
L["In combat: changes here show once the fight ends."] = "En combat : les modifications faites ici s'afficheront à la fin du combat."
L["Lock position"] = "Verrouiller la position"
L["Unlock to drag the prompt; it will not cast until you lock it again."] = "Déverrouillez pour déplacer le panneau ; il ne lancera rien avant d'être reverrouillé."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- switch it on first."] = "déverrouillé, mais l'addon est |cffff8080désactivé|r, donc il n'y a aucun panneau à faire glisser -- activez-le d'abord."
L["Where it sits"] = "Emplacement"
L["Pick Above the action bars to put it back where it started."] = "Choisissez « Au-dessus des barres d'action » pour remettre le panneau à sa place d'origine."
L["Dragging the prompt afterwards sets this to Where I dragged it."] = "Déplacer ensuite le panneau fait passer ce choix sur « Là où je l'ai déplacé »."
L["Above the action bars (default)"] = "Au-dessus des barres d'action (par défaut)"
L["Where I dragged it"] = "Là où je l'ai déplacé"
L["Size"] = "Taille"
L["Scale"] = "Échelle"
L["Opacity"] = "Opacité"
L["Width"] = "Largeur"
L["Height"] = "Hauteur"
L["Style"] = "Style"
L["Panel style"] = "Style du panneau"
L["Panel colour"] = "Couleur du fond"
L["Colour marker by reason"] = "Colorer le marqueur selon la raison"
L["Pale yellow for your own target, orange for a favour owed, deep pink for somebody who asked, sky blue for your group, violet for passers-by -- the order they are offered in."] = "Jaune pâle pour votre propre cible, orange pour une faveur due, rose vif pour quelqu'un qui l'a demandé, bleu ciel pour votre groupe, violet pour les passants -- l'ordre dans lequel ils sont proposés."
L["Pale blue for your own target, amber for a favour owed, pink for somebody who asked, deeper blue for your group, grey for passers-by -- the order they are offered in."] = "Bleu pâle pour votre propre cible, ambre pour une faveur due, rose pour quelqu'un qui l'a demandé, bleu plus soutenu pour votre groupe, gris pour les passants -- l'ordre dans lequel ils sont proposés."
L["A colour that shows why this person is on the prompt."] = "Une couleur qui indique pourquoi ce joueur est sur le panneau."
L["Reason colours"] = "Couleurs de raison"
L["The colour-blind set keeps the reasons apart for red-green colour blindness, in colours that differ in lightness too."] = "Les couleurs adaptées aux daltoniens distinguent les raisons en cas de daltonisme rouge-vert, avec des couleurs qui diffèrent aussi par la luminosité."
L["Standard"] = "Standard"
L["Colour-blind friendly"] = "Adaptées aux daltoniens"
L["Marker colour"] = "Couleur du marqueur"
L["Used when Colour marker by reason is off."] = "Utilisée quand « Colorer le marqueur selon la raison » est désactivé."
L["Colour marker"] = "Marqueur coloré"
L["Framed panels have no stripe."] = "Le style Encadré n'a pas de bande."
L["Ring around the icon"] = "Anneau autour de l'icône"
L["Stripe on the left edge"] = "Bande sur le bord gauche"
L["Both"] = "Les deux"
L["None"] = "Aucun"
